(window.CERTDATA = window.CERTDATA || {})["data-engineer-associate"] = {"meta":{"id":"data-engineer-associate","title":"Data Engineer Associate","level":"Associate","color":"#4f46e5","examMinutes":90,"examSize":45,"lang":"pt","lessonRoot":"data-engineer-associate-ptbr/pt-br/certifications/data-engineer-associate","questionCount":235,"lessonCount":30,"banks":[{"id":"praticas","label":"Questões práticas","kind":"practice","count":145},{"id":"simulado-1","label":"Simulado 1","kind":"mock","count":45},{"id":"simulado-2","label":"Simulado 2","kind":"mock","count":45}],"domains":[{"id":"databricks-intelligence-platform","name":"Plataforma Databricks","nameEn":"Databricks Intelligence Platform","weight":6,"official":true,"count":27},{"id":"data-ingestion-and-loading","name":"Ingestão e Carga de Dados","nameEn":"Data Ingestion and Loading","weight":21,"official":true,"count":42},{"id":"data-transformation-and-modeling","name":"Transformação e Modelagem","nameEn":"Data Transformation and Modeling","weight":22,"official":true,"count":55},{"id":"working-with-lakeflow-jobs","name":"Lakeflow Jobs","nameEn":"Working with Lakeflow Jobs","weight":16,"official":true,"count":29},{"id":"implementing-cicd","name":"CI/CD","nameEn":"Implementing CI/CD","weight":10,"official":true,"count":25},{"id":"troubleshooting-monitoring-and-optimization","name":"Troubleshooting, Monitoramento e Otimização","nameEn":"Troubleshooting, Monitoring, and Optimization","weight":10,"official":true,"count":26},{"id":"governance-and-security","name":"Governança e Segurança","nameEn":"Governance and Security","weight":15,"official":true,"count":31}],"officialWeights":true},"questions":[{"id":"01-databricks-intelligence-platform-q001","bank":"praticas","n":1,"domain":"databricks-intelligence-platform","title":"Lakehouse as a Unified Source of Truth","difficulty":"medium","question":"A leader in data organization is frustrated because the reports from the data analysis team differ from those of the data engineering team. How might a data lakehouse resolve this issue?","choices":{"A":"Both teams would utilize the same source of truth for their tasks","B":"Each team would maintain separate copies of data optimized for their specific workloads","C":"The data lakehouse would automatically reconcile differences between team reports","D":"A dedicated ETL pipeline would synchronize data between team-specific databases"},"answer":"A","short":"Both teams would utilize the same source of truth for their tasks.","explanation":"A data lakehouse provides a single, unified platform where all teams access the same underlying data, eliminating discrepancies caused by siloed data systems or separate copies of data maintained by different teams.","lesson":"01-databricks-intelligence-platform/01-lakehouse-architecture","related":null},{"id":"01-databricks-intelligence-platform-q002","bank":"praticas","n":2,"domain":"databricks-intelligence-platform","title":"Control Plane Components","difficulty":"easy","question":"Which option is entirely hosted within the control plane of the classic Databricks architecture?","choices":{"A":"Worker nodes and executor processes","B":"The Databricks web application","C":"Customer-managed cloud storage buckets","D":"Driver nodes and cluster compute resources"},"answer":"B","short":"The Databricks web application.","explanation":"The control plane hosts the Databricks web UI, REST APIs, notebook server, and cluster manager — all infrastructure managed by Databricks. Worker nodes and driver nodes reside in the customer's data plane (their cloud account).","lesson":"01-databricks-intelligence-platform/01-lakehouse-architecture","related":null},{"id":"01-databricks-intelligence-platform-q003","bank":"praticas","n":3,"domain":"databricks-intelligence-platform","title":"Delta Lake Advantage for Workloads","difficulty":"easy","question":"Which of the following advantages associated with the Databricks Lakehouse Platform is offered by Delta Lake?","choices":{"A":"The ability to run SQL queries without requiring a compute cluster","B":"Automatic migration of legacy Hive tables to cloud-native formats","C":"The ability to support both batch and streaming workloads","D":"Built-in machine learning model training on raw data files"},"answer":"C","short":"The ability to support both batch and streaming workloads.","explanation":"Delta Lake's transaction log and Structured Streaming integration allow the same Delta tables to be read and written by both batch jobs and streaming pipelines, eliminating the need for separate storage systems for each workload type.","lesson":"01-databricks-intelligence-platform/04-delta-lake-fundamentals","related":null},{"id":"01-databricks-intelligence-platform-q004","bank":"praticas","n":4,"domain":"databricks-intelligence-platform","title":"Delta Table Storage Organization","difficulty":"easy","question":"What describes how a Delta table is organized for storage?","choices":{"A":"Delta tables are stored as CSV files with a separate JSON manifest tracking schema changes","B":"Delta tables are stored as a single monolithic binary file containing all rows and metadata","C":"Delta tables are stored exclusively in the Databricks control plane with pointers to cloud storage","D":"Delta tables are stored in a collection of files that contain data, history, metadata, and other attributes"},"answer":"D","short":"Delta tables are stored in a collection of files that contain data, history, metadata, and other attributes.","explanation":"Data is stored in Parquet files, and the `_delta_log` directory contains JSON transaction log files and checkpoint files that track all changes, schema, and table properties.","lesson":"01-databricks-intelligence-platform/04-delta-lake-fundamentals","related":null},{"id":"01-databricks-intelligence-platform-q005","bank":"praticas","n":5,"domain":"databricks-intelligence-platform","title":"VACUUM and Time Travel","difficulty":"medium","question":"A data engineer discovered an error while updating a table daily and needs to use Delta time travel to revert the table to a version from three days ago. However, when they try to access the older version, the data files are absent. What explains the absence of the data files?","choices":{"A":"The VACUUM command was run on the table","B":"The OPTIMIZE command was run, which compacted and removed older file versions","C":"The table was converted from Parquet to Delta, erasing its version history","D":"The Delta transaction log automatically purges entries older than 24 hours"},"answer":"A","short":"The VACUUM command was run on the table.","explanation":"`VACUUM` permanently deletes data files that are outside the retention threshold (default 7 days). Once vacuumed, older versions cannot be restored via time travel because the underlying Parquet files no longer exist.","lesson":"01-databricks-intelligence-platform/05-time-travel-versioning","related":null},{"id":"01-databricks-intelligence-platform-q006","bank":"praticas","n":6,"domain":"databricks-intelligence-platform","title":"Data Quality Feature of a Lakehouse","difficulty":"easy","question":"Which feature of a data lakehouse enhances data quality compared to a traditional data lake?","choices":{"A":"Native support for unstructured binary file formats","B":"A data lakehouse supports ACID-compliant transactions","C":"Automatic data replication across multiple cloud regions","D":"Built-in data visualization and dashboarding tools"},"answer":"B","short":"A data lakehouse supports ACID-compliant transactions.","explanation":"Traditional data lakes lack transactional guarantees, which can lead to partial writes, inconsistent reads, and data corruption. ACID transactions in Delta Lake ensure atomicity, consistency, isolation, and durability for all operations.","lesson":"01-databricks-intelligence-platform/01-lakehouse-architecture","related":null},{"id":"01-databricks-intelligence-platform-q007","bank":"praticas","n":7,"domain":"databricks-intelligence-platform","title":"Gold vs Silver Table Relationship","difficulty":"easy","question":"What best explains the connection between Gold tables and Silver tables?","choices":{"A":"Gold tables store raw data while Silver tables store transformed data","B":"Gold tables are temporary views derived from permanent Silver tables","C":"Gold tables are more likely to contain aggregations than Silver tables","D":"Gold tables and Silver tables always share the same schema and row count"},"answer":"C","short":"Gold tables are more likely to contain aggregations than Silver tables.","explanation":"Gold tables represent business-level aggregates and metrics built for consumption in dashboards and reports. Silver tables contain cleaned and enriched data, but are typically at row-level granularity without the summarizations found in Gold.","lesson":"01-databricks-intelligence-platform/01-lakehouse-architecture","related":null},{"id":"01-databricks-intelligence-platform-q008","bank":"praticas","n":8,"domain":"databricks-intelligence-platform","title":"Bronze vs Raw Data Relationship","difficulty":"easy","question":"What characterizes the connection between Bronze tables and raw data?","choices":{"A":"Bronze tables contain only validated and schema-enforced records from source systems","B":"Bronze tables are external tables pointing directly to raw source files without any transformation","C":"Bronze tables store aggregated summaries of raw data for downstream consumption","D":"Bronze tables contain raw data with a schema applied"},"answer":"D","short":"Bronze tables contain raw data with a schema applied.","explanation":"Bronze is the first layer in the medallion architecture. Data is ingested from source systems with minimal transformation, but is captured in a structured Delta table format with metadata columns added (e.g., ingestion timestamp, source file).","lesson":"01-databricks-intelligence-platform/01-lakehouse-architecture","related":null},{"id":"01-databricks-intelligence-platform-q009","bank":"praticas","n":9,"domain":"databricks-intelligence-platform","title":"Open-Source Technology Advantage","difficulty":"easy","question":"What is one advantage of the Databricks Lakehouse Platform utilizing open-source technologies?","choices":{"A":"Avoiding vendor lock-in","B":"Eliminating the need for cloud infrastructure providers","C":"Guaranteeing backward compatibility with all legacy data systems","D":"Providing free unlimited compute resources for open-source users"},"answer":"A","short":"Avoiding vendor lock-in.","explanation":"By building on open standards and formats — Delta Lake (open format), Apache Spark, MLflow — organizations retain the ability to move data and workloads across clouds and platforms without being tied to proprietary, closed formats.","lesson":"01-databricks-intelligence-platform/01-lakehouse-architecture","related":null},{"id":"01-databricks-intelligence-platform-q010","bank":"praticas","n":10,"domain":"databricks-intelligence-platform","title":"Delta Lake Underlying File Format","difficulty":"easy","question":"Which file formats are primarily used to store data from Delta Lake tables?","choices":{"A":"Avro","B":"Parquet","C":"CSV","D":"ORC"},"answer":"B","short":"Parquet.","explanation":"Delta Lake stores all data in Parquet files, an open columnar format that provides efficient compression and predicate pushdown. The `_delta_log` directory stores transaction metadata as JSON and Parquet checkpoint files, but data itself is always Parquet.","lesson":"01-databricks-intelligence-platform/04-delta-lake-fundamentals","related":null},{"id":"01-databricks-intelligence-platform-q011","bank":"praticas","n":11,"domain":"databricks-intelligence-platform","title":"Customer Cloud Account Contents","difficulty":"easy","question":"What is stored in the cloud account of the Databricks customer?","choices":{"A":"The Databricks web application and REST APIs","B":"Cluster management metadata and job configurations","C":"Data","D":"Notebook source code and revision history"},"answer":"C","short":"Data.","explanation":"The customer's cloud account (AWS S3, Azure ADLS, GCP GCS) stores the actual data files. Databricks infrastructure — including the web application, cluster management metadata, repos, and notebooks — is managed in the Databricks-controlled plane, not the customer's account.","lesson":"01-databricks-intelligence-platform/02-databricks-workspace","related":null},{"id":"01-databricks-intelligence-platform-q012","bank":"praticas","n":12,"domain":"databricks-intelligence-platform","title":"Streamlining Data Architectures","difficulty":"medium","question":"What methods can help streamline and integrate distinct data architectures tailored for particular applications?","choices":{"A":"Building custom ETL pipelines between each pair of data systems","B":"Deploying separate data warehouses for each business unit","C":"Using a message queue to synchronize data between independent databases","D":"A data lakehouse"},"answer":"D","short":"A data lakehouse.","explanation":"The lakehouse architecture unifies the flexibility of a data lake (support for unstructured data, low-cost storage, ML workloads) with the reliability and governance of a data warehouse (ACID transactions, SQL support, schema enforcement) into a single platform.","lesson":"01-databricks-intelligence-platform/01-lakehouse-architecture","related":null},{"id":"01-databricks-intelligence-platform-q013","bank":"praticas","n":13,"domain":"databricks-intelligence-platform","title":"When to Use Cluster Pools","difficulty":"medium","question":"When would a data team use cluster pools?","choices":{"A":"When an automated report needs to be refreshed as quickly as possible","B":"When clusters need to share data between concurrent jobs","C":"When reducing cloud storage costs for intermediate data is the priority","D":"When enforcing uniform cluster configurations across all team members"},"answer":"A","short":"When an automated report needs to be refreshed as quickly as possible.","explanation":"Cluster pools maintain a set of pre-warmed, idle VM instances that can be assigned to clusters immediately on startup. This eliminates the VM provisioning delay (which can take several minutes), reducing cluster startup time to seconds for time-sensitive jobs.","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"01-databricks-intelligence-platform-q014","bank":"praticas","n":14,"domain":"databricks-intelligence-platform","title":"SQL Warehouse Scaling for Concurrent Queries","difficulty":"medium","question":"A data analysis team's Databricks SQL queries perform poorly when multiple members execute small queries simultaneously on an always-on SQL warehouse. All queries use the same endpoint. What strategy improves performance?","choices":{"A":"Switch from a Pro to a Classic SQL warehouse type","B":"Increase the maximum bound of the SQL warehouse's scaling range","C":"Increase the size (T-shirt size) of each individual cluster in the endpoint","D":"Enable query result caching on the SQL warehouse"},"answer":"B","short":"Increase the maximum bound of the SQL warehouse's scaling range.","explanation":"A SQL warehouse (warehouse) can auto-scale by adding more clusters when concurrent query load increases. Raising the maximum cluster count allows the endpoint to serve more parallel queries simultaneously, reducing wait times during peak concurrent usage.","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"01-databricks-intelligence-platform-q015","bank":"praticas","n":15,"domain":"databricks-intelligence-platform","title":"Reducing SQL Warehouse Cost on a Daily Dashboard","difficulty":"medium","question":"A data engineer sets a Databricks SQL dashboard to refresh daily and wants the related SQL warehouse to run only when needed. What strategy reduces the overall running time of the SQL warehouse?","choices":{"A":"Downgrade the SQL warehouse to a smaller cluster size","B":"Configure the SQL warehouse to start only during business hours","C":"Turn on the Auto Stop feature for the SQL warehouse","D":"Switch the dashboard to use a shared all-purpose cluster instead"},"answer":"C","short":"Turn on the Auto Stop feature for the SQL warehouse.","explanation":"Auto Stop automatically terminates the SQL warehouse after a configurable idle period. After the dashboard refresh completes, the endpoint shuts down automatically — avoiding continuous compute charges during the long idle period between daily refreshes.","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"01-databricks-intelligence-platform-q016","bank":"praticas","n":16,"domain":"databricks-intelligence-platform","title":"Faster Cluster Startup for Nightly Jobs","difficulty":"easy","question":"A data engineer manages a nightly job with several tasks that run slowly due to long cluster startup times. What action improves cluster startup time?","choices":{"A":"Increase the driver node memory allocation","B":"Switch to a single-node cluster to avoid worker provisioning","C":"Enable autoscaling with a higher maximum worker count","D":"Use clusters from a cluster pool"},"answer":"D","short":"Use clusters from a cluster pool.","explanation":"Cluster pools pre-provision and maintain idle instances that are immediately available for cluster creation. Tasks using pool-backed clusters skip the VM provisioning step, reducing startup from several minutes to a few seconds.","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"01-databricks-intelligence-platform-q017","bank":"praticas","n":17,"domain":"databricks-intelligence-platform","title":"Minimizing SQL Warehouse Runtime on an Hourly Dashboard","difficulty":"medium","question":"A data engineer has an hourly Databricks SQL dashboard whose underlying data is managed by an automated Databricks Job. How can they minimize the total running time of the SQL warehouse during the dashboard's hourly refresh?","choices":{"A":"Turn on the Auto Stop feature for the SQL warehouse","B":"Use a shared all-purpose cluster instead of a SQL warehouse","C":"Pre-compute dashboard results in the Databricks Job and cache them","D":"Reduce the SQL warehouse cluster size to the smallest available"},"answer":"A","short":"Turn on the Auto Stop feature for the SQL warehouse.","explanation":"Auto Stop shuts down the SQL warehouse after a defined idle period following the last query. Since the dashboard only needs the endpoint during the brief refresh window each hour, Auto Stop ensures the endpoint is off for the remaining idle time between refreshes.","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"01-databricks-intelligence-platform-q018","bank":"praticas","n":18,"domain":"databricks-intelligence-platform","title":"When to Use a Single-Node Cluster","difficulty":"medium","question":"What scenario would prompt a data engineer to use a single-node cluster?","choices":{"A":"When running a distributed join across tables with billions of rows","B":"When working interactively with a small amount of data","C":"When deploying a production Lakeflow Declarative Pipelines pipeline with multiple streaming sources","D":"When maximizing parallelism for a large-scale ETL workload"},"answer":"B","short":"When working interactively with a small amount of data.","explanation":"Single-node clusters run both the driver and executor on the same machine, making them suitable for development, exploratory data analysis on small datasets, and libraries that do not support distributed execution (e.g., some scikit-learn workflows). They are not appropriate for large-scale production jobs.","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"01-databricks-intelligence-platform-q019","bank":"praticas","n":19,"domain":"databricks-intelligence-platform","title":"Using SQL in a Python Notebook Cell","difficulty":"easy","question":"A data engineer is working in a Python notebook on Databricks but needs to use SQL for one specific cell. They prefer that all other cells remain Python. How can they incorporate SQL into only that cell?","choices":{"A":"Change the notebook's default language to SQL and then switch back","B":"Wrap the SQL query in `spark.sql()` and assign it to a variable","C":"Add `%sql` to the first line of the cell","D":"Import the `sql` module and call `sql.execute()`"},"answer":"C","short":"Add `%sql` to the first line of the cell.","explanation":"Databricks magic commands (`%sql`, `%python`, `%scala`, `%r`) override the cell language for that individual cell only. All other cells continue using the notebook's default language. This allows mixing languages within a single notebook without changing the global setting.","lesson":"01-databricks-intelligence-platform/02-databricks-workspace","related":null},{"id":"01-databricks-intelligence-platform-q020","bank":"praticas","n":20,"domain":"databricks-intelligence-platform","title":"Compute for Concurrent Ad Hoc SQL *(2026 blueprint)*","difficulty":"medium","question":"Throughout the day, dozens of business analysts run short, ad hoc SQL queries against curated Gold tables. The team wants fast startup, good performance as concurrency rises, and no paying for a large cluster that sits idle overnight. Which compute should they use?","choices":{"A":"An all-purpose cluster with a fixed 20 workers, shared by all analysts","B":"A single-node cluster per analyst","C":"A jobs compute cluster created for each query","D":"A serverless SQL warehouse with autoscaling (maximum clusters raised) and auto stop"},"answer":"D","short":"A serverless SQL warehouse with autoscaling (maximum clusters raised) and auto stop.","explanation":"Serverless SQL warehouses start in about 2–6 seconds, scale out by adding clusters as queries queue, and auto stop after idle time (10 minutes by default). A fixed all-purpose cluster pays for peak capacity all day. Jobs compute exists only for scheduled job runs. Single-node clusters don't share capacity or scale for concurrency ([SQL warehouse types](https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-types)).","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"01-databricks-intelligence-platform-q021","bank":"praticas","n":21,"domain":"databricks-intelligence-platform","title":"Characteristics of Serverless Compute *(2026 blueprint)*","difficulty":"easy","question":"Which statement about serverless compute for notebooks and jobs is correct?","choices":{"A":"Serverless workloads always run on the latest runtime version, and compute is managed by Databricks","B":"Serverless compute supports setting any Spark configuration and custom init scripts","C":"You choose the Databricks Runtime version and instance types for each serverless job","D":"Serverless compute is available only in workspaces that use the legacy Hive metastore"},"answer":"A","short":"Serverless workloads always run on the latest runtime version, and compute is managed by Databricks.","explanation":"Serverless is versionless and Databricks-managed, so you don't pick runtimes or instance types. Only a short list of Spark properties can be set (for example `spark.sql.shuffle.partitions`), and dependencies are managed with environments. Workspaces without Unity Catalog must upgrade before they can use serverless ([Connect to serverless compute](https://docs.databricks.com/aws/en/compute/serverless/), [Spark configuration](https://docs.databricks.com/aws/en/spark/conf)).","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"02-data-ingestion-and-loading-q001","bank":"praticas","n":22,"domain":"data-ingestion-and-loading","title":"JDBC Format for SQLite","difficulty":"easy","question":"A data engineer needs to create a table in Databricks using data from the organization's SQLite database. They set up a JDBC connection. Which format string correctly identifies the JDBC data source?","choices":{"A":"`\"sqlite\"`","B":"`\"jdbc\"`","C":"`\"database\"`","D":"`\"odbc\"`"},"answer":"B","short":"`\"jdbc\"`","explanation":"This is the format string used with Spark's DataFrameReader to connect to any JDBC-compatible database (including SQLite, MySQL, PostgreSQL). It is specified as `.format(\"jdbc\")` in the DataFrameReader chain, followed by `.option()` calls for the connection URL, driver, and table name.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q002","bank":"praticas","n":23,"domain":"data-ingestion-and-loading","title":"Parquet Advantage Over CSV","difficulty":"medium","question":"What advantage does creating an external table using Parquet have over CSV in a `CREATE TABLE AS SELECT` statement?","choices":{"A":"Parquet files are human-readable and can be edited with a text editor","B":"Parquet files support row-level locking for concurrent writes","C":"Parquet files have a well-defined schema","D":"Parquet files are smaller because they use row-based compression"},"answer":"C","short":"Parquet files have a well-defined schema.","explanation":"Unlike CSV (a schema-less text format requiring manual type inference), Parquet embeds column names and data types directly in the file metadata. This enables schema enforcement, efficient columnar reads, and predicate pushdown without a separate schema definition.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q003","bank":"praticas","n":24,"domain":"data-ingestion-and-loading","title":"COPY INTO Idempotency","difficulty":"medium","question":"Every day, a data engineer runs a command to transfer the previous day's sales data into a `transactions` table. Today, after running the command, the record count remains unchanged. Why were no new records copied?","choices":{"A":"The table's schema rejected the incoming data due to a type mismatch","B":"The transaction log was full and could not accept new entries","C":"The COPY INTO command only works with streaming sources, not batch files","D":"The previous day's file has already been copied into the table"},"answer":"D","short":"The previous day's file has already been copied into the table.","explanation":"`COPY INTO` is idempotent — it maintains an internal record of which files have already been loaded. On subsequent runs, it automatically skips previously processed files, preventing duplicate ingestion. This makes it safe to rerun without creating duplicates.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q004","bank":"praticas","n":25,"domain":"data-ingestion-and-loading","title":"Spark Offset Tracking Methods","difficulty":"easy","question":"To reliably monitor the precise progress of processing and manage failures through restarting or reprocessing, which two methods does Spark use to log the offset range of the data processed in each trigger?","choices":{"A":"Checkpointing and Write-ahead Logs (WAL)","B":"Transaction logs and Delta Lake versioning","C":"Spark event logs and executor heartbeats","D":"Watermarking and session windows"},"answer":"A","short":"Checkpointing and Write-ahead Logs (WAL).","explanation":"The checkpoint saves the streaming query's progress (including offsets) to a durable location in cloud storage, while the WAL records each trigger's offset range before the batch is processed. Together, they enable exactly-once semantics and recovery after cluster failure.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q005","bank":"praticas","n":26,"domain":"data-ingestion-and-loading","title":"Auto Loader Underlying Technology","difficulty":"easy","question":"Which tool does Auto Loader use to incrementally process data?","choices":{"A":"Apache Kafka consumer groups","B":"Spark Structured Streaming","C":"COPY INTO with file tracking","D":"Delta Lake Change Data Feed"},"answer":"B","short":"Spark Structured Streaming.","explanation":"Auto Loader is built on top of Structured Streaming and uses it to incrementally discover and ingest new files as they arrive in cloud storage. It maintains a checkpoint to ensure exactly-once processing and scales automatically with file volume.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q006","bank":"praticas","n":27,"domain":"data-ingestion-and-loading","title":"Micro-Batch Trigger Every 5 Seconds","difficulty":"medium","question":"A data engineer sets up a Structured Streaming job to read from a table, process the data, and subsequently write it to a new table in real-time. The code block is shown below:\n\n```python\n(spark.table(\"sales\")\n  .withColumn(\"avg_price\", col(\"sales\") / col(\"units\"))\n  .writeStream\n  .option(\"checkpointLocation\", checkpointPath)\n  .outputMode(\"append\")\n  ._____\n  .table(\"new_sales\"))\n```\n\nIf the data engineer aims to run a micro-batch query that processes data every 5 seconds, which line of code should be used to complete the blank?","choices":{"A":"`.trigger(interval=\"5 seconds\")`","B":"`.trigger(continuous=\"5 seconds\")`","C":"`.trigger(processingTime=\"5 seconds\")`","D":"`.trigger(microBatch=\"5 seconds\")`"},"answer":"C","short":"`.trigger(processingTime=\"5 seconds\")`","explanation":"This fixed-interval trigger causes Spark to kick off a new micro-batch every 5 seconds, processing all data that arrived since the last batch. If processing takes longer than the interval, the next batch starts immediately after completion.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q007","bank":"praticas","n":28,"domain":"data-ingestion-and-loading","title":"Auto Loader for New File Detection","difficulty":"medium","question":"A data engineer's source system produces files in a shared directory that accumulate over time. The engineer must recognize which files are new since the last pipeline execution and ingest only those during each run. Which tool addresses this?","choices":{"A":"COPY INTO with manual file listing","B":"Spark batch read with timestamp filtering","C":"Delta Lake MERGE with file metadata","D":"Auto Loader"},"answer":"D","short":"Auto Loader.","explanation":"Auto Loader uses file notification (cloud storage events) or directory listing to detect new files incrementally. It maintains a checkpoint recording which files have been processed, so only unprocessed files are ingested on each pipeline run — without requiring manual file tracking.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q008","bank":"praticas","n":29,"domain":"data-ingestion-and-loading","title":"Writing to a Path vs a Table","difficulty":"medium","question":"What is wrong with the following code?\n\n```python\ndf = spark.read.json(\"data/\")\ndf.write.save(\"output\", format=\"delta\")\n```","choices":{"A":"The code saves files to a path but does not register the output as a named Delta table in the metastore","B":"The `spark.read.json()` method cannot be used with Delta format output","C":"The `.save()` method requires a checkpoint location for Delta format writes","D":"The code is missing a schema definition, which is required for JSON reads"},"answer":"A","short":"The code saves files to a path but does not register the output as a named Delta table in the metastore. To create a queryable Delta table accessible via SQL, use `.write.format(\"delta\").saveAsTable(\"table_name\")` instead.","explanation":"> ⚠️ *This answer was generated by AI — verify against official Databricks documentation.*","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q009","bank":"praticas","n":30,"domain":"data-ingestion-and-loading","title":"CREATE TABLE from CSV Keyword","difficulty":"easy","question":"A data engineer needs to create a table in Databricks using data from a CSV file. They run a `CREATE TABLE` command that already specifies the CSV path and format in the statement body. Which additional line of code completes the blank?","choices":{"A":"`USING DELTA`","B":"No additional line is needed","C":"`FORMAT_OPTIONS('header' = 'true')`","D":"`STORED AS TEXTFILE`"},"answer":"B","short":"No additional line is needed.","explanation":"When a `CREATE TABLE` statement already contains `USING CSV LOCATION '/path/to/csv'`, the format and location are fully specified within the command body itself. No extra keyword is required to complete the statement.\n\n> ⚠️ *This answer was generated by AI — verify against official Databricks documentation.*","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q010","bank":"praticas","n":31,"domain":"data-ingestion-and-loading","title":"Process All Available Data Trigger","difficulty":"medium","question":"A data engineer sets up a Structured Streaming job to read from a table and write results to a new table. The code block is shown below:\n\n```python\n(spark.table(\"transactions\")\n  .withColumn(\"total\", col(\"price\") * col(\"qty\"))\n  .writeStream\n  .option(\"checkpointLocation\", checkpointPath)\n  .outputMode(\"append\")\n  ._____\n  .table(\"transactions_gold\"))\n```\n\nIf the data engineer intends for the query to process all available data across as many batches as needed and then stop, which line of code should be used to complete the blank?","choices":{"A":"`.trigger(once=True)`","B":"`.trigger(processingTime=\"0 seconds\")`","C":"`.trigger(availableNow=True)`","D":"`.trigger(continuous=\"1 second\")`"},"answer":"C","short":"`.trigger(availableNow=True)`","explanation":"This trigger processes all data that has arrived since the last checkpoint across one or more micro-batches, then shuts down automatically. It combines the efficiency of micro-batching (processing incrementally) with the convenience of a batch job (terminates when done).","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q011","bank":"praticas","n":32,"domain":"data-ingestion-and-loading","title":"Auto Loader JSON String Inference","difficulty":"medium","question":"A data engineer creates a pipeline to ingest JSON data via Auto Loader with no type inference or schema hints specified. After examining the data, all columns in the target table are of string type, even for fields containing only float or boolean values. Why does Auto Loader infer all columns as string type?","choices":{"A":"Auto Loader defaults to string type to prevent data loss during schema evolution","B":"The checkpoint metadata overrides column types to string for safety","C":"The Delta table's schema enforcement converts all incoming types to strings","D":"JSON data is a text-based format"},"answer":"D","short":"JSON data is a text-based format.","explanation":"Without enabling schema inference (`cloudFiles.inferColumnTypes = true`), Auto Loader reads all JSON field values as strings by default. JSON itself does not enforce strict data types at the format level, so without explicit type hints, the safest default is to represent all values as strings.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q012","bank":"praticas","n":33,"domain":"data-ingestion-and-loading","title":"Auto Loader Compatible Workloads","difficulty":"easy","question":"What type of workloads are consistently compatible with Auto Loader?","choices":{"A":"Both streaming and batch workloads","B":"Only batch workloads with scheduled triggers","C":"Only streaming workloads with continuous triggers","D":"Only interactive notebook workloads"},"answer":"A","short":"Both streaming and batch workloads.","explanation":"Auto Loader natively supports Structured Streaming for continuous incremental ingestion. It also supports triggered batch execution using `.trigger(availableNow=True)` to process all new files at once and then stop. This flexibility makes it suitable for both real-time and scheduled batch pipelines.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q013","bank":"praticas","n":34,"domain":"data-ingestion-and-loading","title":"spark.read to spark.readStream","difficulty":"easy","question":"A data engineer utilizes this code block within a batch ingestion pipeline to read from a Delta table:\n\n```python\ndf = (spark.read\n      .format(\"delta\")\n      .schema(schema)\n      .load(\"/delta/transactions\"))\n```\n\nWhat single change must be made for this code block to work correctly when the `transactions` table acts as a streaming source?","choices":{"A":"Replace `.format(\"delta\")` with `.format(\"deltaStream\")`","B":"Replace `spark.read` with `spark.readStream`","C":"Add `.option(\"streaming\", \"true\")` to the reader chain","D":"Replace `.load(\"/delta/transactions\")` with `.stream(\"/delta/transactions\")`"},"answer":"B","short":"Replace `spark.read` with `spark.readStream`.","explanation":"This single change converts the static batch read into an incremental streaming read that consumes new records appended to the Delta table since the last checkpoint. All subsequent transformations on the resulting DataFrame remain unchanged.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q014","bank":"praticas","n":35,"domain":"data-ingestion-and-loading","title":"Streaming DataFrame Write API Error","difficulty":"medium","question":"Why will the following code fail?\n\n```python\ndf = spark.readStream.format(\"delta\").load(\"dbfs:/delta/events\")\ndf.write.csv(\"output\")\n```","choices":{"A":"A checkpoint location must be specified before calling `.write`","B":"The `.csv(\"output\")` method is not supported for Delta format reads","C":"`df.write` must be `df.writeStream`","D":"The `readStream` API cannot read from Delta format tables"},"answer":"C","short":"`df.write` must be `df.writeStream`.","explanation":"A streaming DataFrame created with `readStream` must be written using the `writeStream` API. Using the batch `.write` API on a streaming DataFrame raises an `AnalysisException: Queries with streaming sources must be executed with writeStream.start()`.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q015","bank":"praticas","n":36,"domain":"data-ingestion-and-loading","title":"Missing Checkpoint in Streaming Write","difficulty":"medium","question":"What is missing from this streaming write?\n\n```python\ndf.writeStream.format(\"delta\").start(\"output\")\n```","choices":{"A":"An output mode specification (append, complete, or update)","B":"A schema definition for the output Delta table","C":"A trigger interval for micro-batch processing","D":"A checkpoint location is missing"},"answer":"D","short":"A checkpoint location is missing.","explanation":"Structured Streaming requires `.option(\"checkpointLocation\", \"/path/to/checkpoint\")` to track query progress and enable fault-tolerance. Without a checkpoint, the query cannot recover from failures or track which data has been processed, and Spark will raise an error on startup.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q016","bank":"praticas","n":37,"domain":"data-ingestion-and-loading","title":"Ingesting a SaaS Source With Least Overhead *(2026 blueprint)*","difficulty":"easy","question":"Sales leadership wants Salesforce accounts and opportunities in Unity Catalog, refreshed hourly. The data team has no capacity to write or maintain custom API code. Which approach fits best?","choices":{"A":"The Lakeflow Connect managed Salesforce connector with an hourly schedule","B":"A notebook that calls the Salesforce REST API, scheduled hourly with Lakeflow Jobs","C":"Auto Loader reading Salesforce export files from a volume","D":"A JDBC read of the Salesforce database every hour"},"answer":"A","short":"The Lakeflow Connect managed Salesforce connector with an hourly schedule.","explanation":"Managed connectors are fully managed ingestion pipelines for popular SaaS apps and databases. They run on serverless compute, write to UC streaming tables, ingest incrementally, and Lakeflow Connect creates a job for each schedule. Databricks recommends starting with the most managed layer. Custom REST code adds maintenance, and Auto Loader needs files that someone else would have to export ([Lakeflow Connect](https://docs.databricks.com/aws/en/ingestion/overview)).","lesson":"02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect","related":null},{"id":"02-data-ingestion-and-loading-q017","bank":"praticas","n":38,"domain":"data-ingestion-and-loading","title":"Components of a Managed Database Connector *(2026 blueprint)*","difficulty":"medium","question":"A team configures a Lakeflow Connect managed connector to replicate a SQL Server database with change data capture. Which component exists only for database connectors, and runs continuously to stage changes?","choices":{"A":"The Unity Catalog connection","B":"The ingestion gateway","C":"The destination streaming tables","D":"The Lakeflow Jobs schedule"},"answer":"B","short":"The ingestion gateway.","explanation":"Database connectors include \"an ingestion gateway and staging storage to support continuous change capture\". The gateway runs as a continuous task in its own job. Every managed connector uses a UC **connection** (credentials), an **ingestion pipeline**, and **streaming tables** as destinations ([connector concepts](https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/)).","lesson":"02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect","related":null},{"id":"02-data-ingestion-and-loading-q018","bank":"praticas","n":39,"domain":"data-ingestion-and-loading","title":"Standard vs Managed Connectors *(2026 blueprint)*","difficulty":"medium","question":"Which source is a typical case for a Lakeflow Connect **standard** (customizable) connector rather than a managed connector?","choices":{"A":"Workday reports for an HR dashboard","B":"HubSpot CRM objects","C":"Events from an Apache Kafka topic that need custom parsing in Structured Streaming","D":"A MySQL database replicated with CDC"},"answer":"C","short":"Events from an Apache Kafka topic that need custom parsing in Structured Streaming.","explanation":"Standard connectors are the customizable SQL and Spark ingestion paths for cloud object storage (Auto Loader, `read_files`), message buses (Kafka, Kinesis, Pub/Sub), and SFTP. Managed connectors cover SaaS apps (Workday, HubSpot, Salesforce) and databases (MySQL, PostgreSQL, SQL Server) with no ingestion code ([Ingest with SQL and Spark APIs](https://docs.databricks.com/aws/en/ingestion/)).","lesson":"02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect","related":null},{"id":"02-data-ingestion-and-loading-q019","bank":"praticas","n":40,"domain":"data-ingestion-and-loading","title":"Auto Loader Schema Evolution Without Failures *(2026 blueprint)*","difficulty":"hard","question":"An Auto Loader stream lands vendor JSON in a Bronze table whose schema downstream teams depend on. New fields occasionally appear. The stream must never stop because of them, the table schema must not change, and the unexpected values must be kept for review. Which setting meets this?","choices":{"A":"`cloudFiles.schemaEvolutionMode = \"addNewColumns\"`","B":"`cloudFiles.inferColumnTypes = \"true\"`","C":"`cloudFiles.schemaEvolutionMode = \"failOnNewColumns\"`","D":"`cloudFiles.schemaEvolutionMode = \"rescue\"`"},"answer":"D","short":"`cloudFiles.schemaEvolutionMode = \"rescue\"`.","explanation":"In `rescue` mode the schema never evolves and the stream doesn't fail. New columns are written to the `_rescued_data` column. `addNewColumns` evolves the schema and stops the stream with `UnknownFieldException` until it's restarted. `failOnNewColumns` stops until someone fixes the schema. `inferColumnTypes` only affects type inference ([schema inference and evolution](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema)).","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q020","bank":"praticas","n":41,"domain":"data-ingestion-and-loading","title":"Auto Loader File Discovery Mode *(2026 blueprint)*","difficulty":"medium","question":"An Auto Loader stream reads a Unity Catalog external location that receives hundreds of thousands of files per day. Directory listing has become slow. What does Databricks recommend?","choices":{"A":"Switch to file notification mode with file events enabled on the external location","B":"Enable `cloudFiles.useIncrementalListing`","C":"Reduce `cloudFiles.maxFilesPerTrigger` to 10","D":"Replace Auto Loader with a scheduled `spark.read` of the whole directory"},"answer":"A","short":"Switch to file notification mode with file events enabled on the external location.","explanation":"Directory listing is the default mode. Databricks recommends file notification mode with **file events** for most workloads, as it's more performant and scalable, and needs no extra permissions once file events are enabled on the external location (DBR 14.3 LTS+). `cloudFiles.useIncrementalListing` is deprecated. You can switch modes across restarts and keep exactly-once processing ([file detection modes](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/file-detection-modes)).","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q021","bank":"praticas","n":42,"domain":"data-ingestion-and-loading","title":"Forcing a COPY INTO Reload *(2026 blueprint)*","difficulty":"medium","question":"After fixing a parsing bug, a data engineer truncates a Bronze table and re-runs the same `COPY INTO` statement. Zero rows are loaded. What explains this, and how should they reload the files?","choices":{"A":"`COPY INTO` caches query results. Run `REFRESH TABLE` first","B":"`COPY INTO` is idempotent and skips files it already loaded. Add `COPY_OPTIONS ('force' = 'true')`","C":"The files were deleted by `COPY INTO` after the first load. Re-upload them","D":"`COPY INTO` only loads files newer than the table's last `OPTIMIZE`"},"answer":"B","short":"`COPY INTO` is idempotent and skips files it already loaded. Add `COPY_OPTIONS ('force' = 'true')`.","explanation":"\"Files in the source location that have already been loaded are skipped\", and truncating the target doesn't reset that tracking. `'force' = 'true'` disables idempotency, so the files load again ([COPY INTO reference](https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into)).","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"02-data-ingestion-and-loading-q022","bank":"praticas","n":43,"domain":"data-ingestion-and-loading","title":"Parallelizing a JDBC Read *(2026 blueprint)*","difficulty":"medium","question":"A notebook reads a 300-million-row PostgreSQL table with `spark.read.format(\"jdbc\")`, and the read runs for hours while most cluster cores sit idle. What change parallelizes the read?","choices":{"A":"Set `fetchSize` to 1","B":"Call `.repartition(64)` after `.load()`","C":"Add `partitionColumn`, `lowerBound`, `upperBound`, and `numPartitions` on an indexed numeric column","D":"Increase `spark.sql.shuffle.partitions`"},"answer":"C","short":"Add `partitionColumn`, `lowerBound`, `upperBound`, and `numPartitions` on an indexed numeric column.","explanation":"A JDBC read uses one thread by default. The partitioning options split the read into parallel range queries. Repartitioning after `load()` only redistributes data that was already read serially. Shuffle partitions don't affect the read ([Query databases using JDBC](https://docs.databricks.com/aws/en/connect/external-systems/jdbc)).","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q023","bank":"praticas","n":44,"domain":"data-ingestion-and-loading","title":"Landing REST API Data *(2026 blueprint)*","difficulty":"medium","question":"A vendor exposes order data only through a REST API. The team wants an immutable raw copy for replay, schema-drift handling, and a nightly schedule. Which design fits?","choices":{"A":"Store the API token in the notebook and write directly to DBFS root","B":"Call the API from a notebook and `collect()` the results into a pandas DataFrame on the driver","C":"Create a Lakehouse Federation connection that queries the REST API in place","D":"Call the API from a notebook, write the raw JSON responses to a Unity Catalog volume, ingest them with Auto Loader, and schedule both tasks in one Lakeflow Job"},"answer":"D","short":"Call the API from a notebook, write the raw JSON responses to a Unity Catalog volume, ingest them with Auto Loader, and schedule both tasks in one Lakeflow Job.","explanation":"Landing raw files in a governed volume keeps a replayable copy, and Auto Loader handles incremental loading and schema evolution. Lakeflow Jobs schedules and retries the tasks. The token belongs in Databricks secrets (`dbutils.secrets.get`). DBFS root is deprecated for data ([What is DBFS?](https://docs.databricks.com/aws/en/dbfs/)).","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"02-data-ingestion-and-loading-q024","bank":"praticas","n":45,"domain":"data-ingestion-and-loading","title":"Querying Nested JSON Strings *(2026 blueprint)*","difficulty":"easy","question":"A Bronze column `raw` holds JSON strings such as `{\"customer\": {\"id\": 42}, \"total\": \"19.99\"}`. Which Databricks SQL expression returns the customer ID?","choices":{"A":"`raw:customer.id`","B":"`raw.customer.id`","C":"`get_json(raw, 'customer', 'id')`","D":"`raw['customer']['id']::json`"},"answer":"A","short":"`raw:customer.id`.","explanation":"For JSON **strings**, Databricks SQL uses `<column>:<path>`, with dot notation or brackets for nested fields and `::` for casting (for example `raw:total::double`). Dot notation without the colon works on **struct** columns, not on strings ([Query JSON strings](https://docs.databricks.com/aws/en/semi-structured/json)). For new semi-structured data, Databricks recommends the `VARIANT` type over JSON strings.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"03-data-transformation-and-modeling-q001","bank":"praticas","n":46,"domain":"data-transformation-and-modeling","title":"DELETE Syntax","difficulty":"easy","question":"Which code block will delete rows from the Delta table `my_table` where the `age` column value exceeds 25?","choices":{"A":"`REMOVE FROM my_table WHERE age > 25;`","B":"`DELETE FROM my_table WHERE age > 25;`","C":"`DROP ROWS FROM my_table WHERE age > 25;`","D":"`TRUNCATE my_table WHERE age > 25;`"},"answer":"B","short":"`DELETE FROM my_table WHERE age > 25;`","explanation":"This standard SQL DML syntax works directly on Delta tables. Delta Lake supports full DML operations including DELETE, UPDATE, and MERGE with ACID guarantees, so the deleted rows are tracked in the transaction log and are recoverable via time travel.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":"01-databricks-intelligence-platform/04-delta-lake-fundamentals"},{"id":"03-data-transformation-and-modeling-q002","bank":"praticas","n":47,"domain":"data-transformation-and-modeling","title":"PySpark Table Access","difficulty":"easy","question":"A data analyst has developed a Delta table `sales` that the entire data analysis team uses. The data engineering team prefers Python. Which command can the engineering team use to access `sales` data in PySpark?","choices":{"A":"`spark.read.delta(\"sales\")`","B":"`spark.load(\"sales\")`","C":"`spark.table(\"sales\")`","D":"`spark.sql.table(\"sales\")`"},"answer":"C","short":"`spark.table(\"sales\")`","explanation":"This loads the registered Delta table into a PySpark DataFrame, allowing the engineering team to use Python and Spark transformations on the same data the analyst queries with SQL. The table is accessible because it is registered in the shared metastore.","lesson":"03-data-transformation-and-modeling/02-dataframe-operations","related":null},{"id":"03-data-transformation-and-modeling-q003","bank":"praticas","n":48,"domain":"data-transformation-and-modeling","title":"Indicating PII in Table Metadata","difficulty":"medium","question":"A data engineer intends to create a new table listing customers residing in France and wants to indicate the table contains PII. The incomplete SQL is shown below:\n\n```sql\nCREATE TABLE customerInFrance\n_____ AS\nSELECT id\n      ,firstName\n      ,lastName\nFROM customerLocations\nWHERE country = 'FRANCE';\n```\n\nWhich line of code correctly fills in the blank to add a table property indicating PII?","choices":{"A":"`METADATA ('contains_pii' = 'true')`","B":"`COMMENT 'contains_pii = true'`","C":"`OPTIONS ('contains_pii' = 'true')`","D":"`TBLPROPERTIES ('contains_pii' = 'true')`"},"answer":"D","short":"`TBLPROPERTIES ('contains_pii' = 'true')`","explanation":"`TBLPROPERTIES` adds structured key-value metadata directly to the table definition — these are the actual \"table properties\" in Databricks SQL. `COMMENT` adds a human-readable description but is not a table property. Using `TBLPROPERTIES` to tag sensitivity classifications (e.g., PII, data classification) is the standard approach for policy-driven metadata in Databricks.","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":"07-governance-and-security/04-row-filters-column-masks-abac"},{"id":"03-data-transformation-and-modeling-q004","bank":"praticas","n":49,"domain":"data-transformation-and-modeling","title":"Array Functions for Nested JSON","difficulty":"easy","question":"What benefits do the array functions from Spark SQL offer?","choices":{"A":"The ability to work with complex, nested data ingested from JSON files","B":"The ability to convert JSON files into Parquet format without code","C":"The ability to enforce strict schemas on semi-structured data at write time","D":"The ability to automatically flatten all nested structures into separate tables"},"answer":"A","short":"The ability to work with complex, nested data ingested from JSON files.","explanation":"Functions like `explode`, `array_contains`, `transform`, and `filter` allow operations directly on nested array structures without flattening the entire schema first, making them essential for processing hierarchical JSON data at scale.","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"03-data-transformation-and-modeling-q005","bank":"praticas","n":50,"domain":"data-transformation-and-modeling","title":"MERGE to Prevent Duplicates","difficulty":"easy","question":"What commands can be utilized to insert data into a Delta table while preventing duplicate records?","choices":{"A":"`INSERT DISTINCT`","B":"`MERGE`","C":"`COPY INTO`","D":"`UPSERT`"},"answer":"B","short":"`MERGE`.","explanation":"The `MERGE INTO` statement matches source records against a target table on a key condition and conditionally inserts, updates, or skips records. This is the standard upsert pattern in Delta Lake for ensuring no duplicate rows are added.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"03-data-transformation-and-modeling-q006","bank":"praticas","n":51,"domain":"data-transformation-and-modeling","title":"UNION for Unique Records","difficulty":"medium","question":"A data engineering team maintains `march_transactions` (all March retail transactions) and `april_transactions` (all April retail transactions) with no overlapping records. What command creates a new table `all_transactions` containing all unique records from both?","choices":{"A":"`CREATE TABLE all_transactions AS SELECT * FROM march_transactions INTERSECT SELECT * FROM april_transactions;`","B":"`CREATE TABLE all_transactions AS SELECT * FROM march_transactions UNION ALL SELECT * FROM april_transactions;`","C":"`CREATE TABLE all_transactions AS SELECT * FROM march_transactions UNION SELECT * FROM april_transactions;`","D":"`CREATE TABLE all_transactions AS SELECT * FROM march_transactions JOIN april_transactions;`"},"answer":"C","short":"```sql\nCREATE TABLE all_transactions AS\nSELECT * FROM march_transactions\nUNION\nSELECT * FROM april_transactions;\n```","explanation":"`UNION` (without `ALL`) removes duplicate rows across the combined result. Since the two tables share no overlapping records, all rows from both tables are included exactly once in the output.","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"03-data-transformation-and-modeling-q007","bank":"praticas","n":52,"domain":"data-transformation-and-modeling","title":"Python Multi-Condition Control Flow","difficulty":"medium","question":"A data engineer intends to run the last block of a Python program only if `day_of_week` is set to 1 and `review_period` is `True`. The incomplete code block is shown below:\n\n```python\nday_of_week = get_day_of_week()\nreview_period = check_review_period()\n\n_____\n    run_final_block()\n```\n\nWhat control flow statement should be used to complete the blank?","choices":{"A":"`if day_of_week is 1 and review_period is True:`","B":"`if day_of_week = 1 and review_period == \"True\":`","C":"`if day_of_week == 1 or review_period:`","D":"`if day_of_week == 1 and review_period:`"},"answer":"D","short":"`if day_of_week == 1 and review_period:`","explanation":"In Python, `==` performs equality comparison (not assignment). A boolean variable is truthy when referenced directly — wrapping it in quotes (`\"True\"`) would compare against the string literal, not the boolean value. Using a single `=` would cause a `SyntaxError`.","lesson":"03-data-transformation-and-modeling/02-dataframe-operations","related":null},{"id":"03-data-transformation-and-modeling-q008","bank":"praticas","n":53,"domain":"data-transformation-and-modeling","title":"Persistent Cross-Session Data Entity","difficulty":"medium","question":"A data engineer needs a data entity built from several tables that must be accessible to other data engineers in their sessions and stored in a physical location. Which data entity should be created?","choices":{"A":"A table (Delta or Spark SQL table)","B":"A temporary view","C":"A global temporary view","D":"A Common Table Expression (CTE)"},"answer":"A","short":"A table (Delta or Spark SQL table).","explanation":"Tables persist data physically at a storage location and are registered in the metastore, making them accessible across all sessions and users. Unlike temporary views (session-scoped) or views (no physical storage), tables outlive any individual session.","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"03-data-transformation-and-modeling-q009","bank":"praticas","n":54,"domain":"data-transformation-and-modeling","title":"INSERT INTO a Delta Table","difficulty":"easy","question":"A data engineer needs to add a new record `('a1', 6, 9.4)` to the existing Delta table `my_table`. Which SQL command accomplishes this?","choices":{"A":"`ADD ROW my_table VALUES ('a1', 6, 9.4);`","B":"`INSERT INTO my_table VALUES ('a1', 6, 9.4);`","C":"`APPEND INTO my_table VALUES ('a1', 6, 9.4);`","D":"`MERGE INTO my_table VALUES ('a1', 6, 9.4);`"},"answer":"B","short":"`INSERT INTO my_table VALUES ('a1', 6, 9.4);`","explanation":"`INSERT INTO ... VALUES` appends new rows to an existing Delta table without modifying existing records. Delta Lake records this as a new transaction in the log, making it reversible via time travel.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"03-data-transformation-and-modeling-q010","bank":"praticas","n":55,"domain":"data-transformation-and-modeling","title":"CREATE OR REPLACE TABLE","difficulty":"easy","question":"A data architect needs to create an empty Delta table in a specified format, regardless of whether a table with that name already exists. Which SQL DDL approach accomplishes this?","choices":{"A":"`DROP TABLE IF EXISTS table_name; CREATE TABLE table_name (...)`","B":"`CREATE TABLE IF NOT EXISTS table_name (...)`","C":"`CREATE OR REPLACE TABLE table_name (...column definitions...)`","D":"`ALTER TABLE table_name REPLACE COLUMNS (...)`"},"answer":"C","short":"`CREATE OR REPLACE TABLE table_name (...column definitions...)`","explanation":"This atomically drops and recreates the table if it exists, or creates it new if it does not. It avoids errors from pre-existing tables and ensures the table always reflects the latest schema definition.","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"03-data-transformation-and-modeling-q011","bank":"praticas","n":56,"domain":"data-transformation-and-modeling","title":"PIVOT for Wide Format","difficulty":"easy","question":"Which SQL keyword can transform a table from long format to wide format?","choices":{"A":"`UNPIVOT`","B":"`LATERAL VIEW`","C":"`TRANSPOSE`","D":"`PIVOT`"},"answer":"D","short":"`PIVOT`.","explanation":"The `PIVOT` clause rotates distinct row values into column headers, converting a tall/long table (one row per category) into a wide/crosstab format (one column per category). This is commonly used to reshape metrics data for reporting dashboards.","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"03-data-transformation-and-modeling-q012","bank":"praticas","n":57,"domain":"data-transformation-and-modeling","title":"Temporary View for Single-Session Use","difficulty":"medium","question":"A data engineer needs a relational object from two tables that will not be used by other engineers in different sessions. To minimize storage expenses, physical data should not be duplicated. Which relational object should be created?","choices":{"A":"A temporary view","B":"A managed Delta table","C":"An external table","D":"A materialized view"},"answer":"A","short":"A temporary view.","explanation":"Temporary views exist only for the current Spark session, are not accessible to other users, and store no physical data — they are just a named query definition. This avoids both storage costs and data duplication while enabling SQL-based access within the session.","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"03-data-transformation-and-modeling-q013","bank":"praticas","n":58,"domain":"data-transformation-and-modeling","title":"PySpark SQL Query Execution","difficulty":"easy","question":"A data analyst has created a query that operates on a Delta table. They seek assistance from the data engineering team to perform a set of tests to verify that the data returned by the query is accurate and clean. However, the data engineering team utilizes Python for their tests instead of SQL. Which operations can the data engineering team use in PySpark to execute the query and process the results?","choices":{"A":"`spark.query(\"SELECT ...\")`","B":"`spark.sql(\"SELECT ...\")`","C":"`spark.execute(\"SELECT ...\")`","D":"`spark.run(\"SELECT ...\")`"},"answer":"B","short":"`spark.sql(\"SELECT ...\")`","explanation":"`spark.sql()` accepts a SQL query string and executes it, returning the results as a PySpark DataFrame. `spark.table(\"table_name\")` loads an entire table as a DataFrame but does not execute a specific SQL query — it is not the correct tool when the goal is to run a particular SQL statement.","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"03-data-transformation-and-modeling-q014","bank":"praticas","n":59,"domain":"data-transformation-and-modeling","title":"count_if for NULL Values","difficulty":"medium","question":"Which command shows the count of null values in the `member_id` column?","choices":{"A":"`SELECT count(member_id) FROM my_table WHERE member_id IS NULL;`","B":"`SELECT sum(CASE WHEN member_id IS NULL THEN 0 ELSE 1 END) FROM my_table;`","C":"`SELECT count_if(member_id IS NULL) FROM my_table;`","D":"`SELECT count(NULL) FROM my_table;`"},"answer":"C","short":"`SELECT count_if(member_id IS NULL) FROM my_table;`","explanation":"`count_if` counts rows that satisfy the given boolean condition. `IS NULL` evaluates to true for null values. Standard `count(member_id)` would exclude nulls, returning the opposite of what is needed.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"03-data-transformation-and-modeling-q015","bank":"praticas","n":60,"domain":"data-transformation-and-modeling","title":"FILTER Higher-Order Function","difficulty":"medium","question":"A data engineer needs to implement custom logic for the `employees` array column in the `stores` table to find employees with more than 5 years of experience. The result should be a new column `exp_employees` containing only matching employees for each row. The incomplete SQL query is shown below:\n\n```sql\nSELECT store_id,\n       _____ AS exp_employees\nFROM stores\n```\n\nWhich code correctly completes the blank using the FILTER higher-order function?","choices":{"A":"`TRANSFORM(employees, i -> i.years_exp > 5)`","B":"`ARRAY_FILTER(employees, i -> i.years_exp > 5)`","C":"`SELECT_FROM_ARRAY(employees, years_exp > 5)`","D":"`FILTER(employees, i -> i.years_exp > 5)`"},"answer":"D","short":"`FILTER(employees, i -> i.years_exp > 5)`","explanation":"The `FILTER` higher-order function applies a lambda predicate to each element of an array column, returning a new array containing only elements where the condition is true. The arrow syntax (`->`) defines the anonymous function.","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"03-data-transformation-and-modeling-q016","bank":"praticas","n":61,"domain":"data-transformation-and-modeling","title":"Python Variable in SQL Query","difficulty":"easy","question":"A data engineer has a Python variable `table_name` and wants to execute a SQL query using it in PySpark. The incomplete code block is shown below:\n\n```python\ntable_name = \"sales\"\nresult = _____(f\"SELECT * FROM {table_name}\")\n```\n\nWhich method completes the blank?","choices":{"A":"`spark.sql`","B":"`spark.read`","C":"`spark.query`","D":"`spark.execute`"},"answer":"A","short":"`spark.sql(f\"SELECT * FROM {table_name}\")`","explanation":"`spark.sql()` accepts a SQL string, and Python f-strings embed variables directly into the query using `{variable_name}` syntax. This is the standard way to dynamically reference table names or other values from Python variables in SQL queries.","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"03-data-transformation-and-modeling-q017","bank":"praticas","n":62,"domain":"data-transformation-and-modeling","title":"Python Function Definition","difficulty":"easy","question":"A data engineer new to Python needs a function that adds two integers and returns their sum. Which code block is correct?","choices":{"A":"`function add_integers(x, y): return x + y`","B":"`def add_integers(x, y): return x + y`","C":"`def add_integers(x, y): yield x + y`","D":"`def add_integers(x, y): print(x + y)`"},"answer":"B","short":"```python\ndef add_integers(x, y):\n    return x + y\n```","explanation":"In Python, `def` defines a function and `return` outputs the result. Using `print` instead of `return` would output to the console but the function would return `None`, making it unusable in further computation. Using `function` (JavaScript syntax) would cause a `SyntaxError`.","lesson":"03-data-transformation-and-modeling/02-dataframe-operations","related":null},{"id":"03-data-transformation-and-modeling-q018","bank":"praticas","n":63,"domain":"data-transformation-and-modeling","title":"MERGE INTO vs INSERT INTO","difficulty":"medium","question":"When should a data engineer prefer the `MERGE INTO` command over the `INSERT INTO` command?","choices":{"A":"When the target table needs to be completely overwritten with new data","B":"When inserting data from a streaming source into a batch table","C":"When the target table cannot contain duplicate records","D":"When the source and target tables have different schemas"},"answer":"C","short":"When the target table cannot contain duplicate records.","explanation":"`MERGE INTO` matches source records against existing rows on a key condition and conditionally inserts, updates, or skips records. `INSERT INTO` always appends all rows regardless of existing data, which would create duplicates if records already exist.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"03-data-transformation-and-modeling-q019","bank":"praticas","n":64,"domain":"data-transformation-and-modeling","title":"GROUP BY Ordinal Referencing an Aggregate","difficulty":"medium","question":"What is wrong with the following SQL query?\n\n```sql\nSELECT name, count(*) FROM people GROUP BY 2\n```","choices":{"A":"The `count(*)` function requires an alias to be used with `GROUP BY`","B":"The query is missing a `HAVING` clause to filter the aggregated results","C":"`GROUP BY` using a numeric ordinal position is never valid in Spark SQL","D":"`GROUP BY 2` refers to `count(*)`, an aggregate expression, which can't be a grouping key"},"answer":"D","short":"`GROUP BY 2` refers to `count(*)`, an aggregate expression, which can't be a grouping key.","explanation":"Databricks SQL does allow grouping by column position (for example `GROUP BY 1` here would group by `name`). But \"if a positional reference resolves to an aggregate expression, Databricks raises GROUP_BY_POS_AGGREGATE\". Use `GROUP BY 1` or `GROUP BY name` ([GROUP BY clause](https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-qry-select-groupby)).","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"03-data-transformation-and-modeling-q020","bank":"praticas","n":65,"domain":"data-transformation-and-modeling","title":"Tool for Automated Data Quality Monitoring","difficulty":"easy","question":"During data ingestion, a data engineer observes that source data quality is declining. They want to automate the process of monitoring the quality level. Which tool addresses this?","choices":{"A":"Lakeflow Declarative Pipelines (formerly DLT)","B":"Databricks SQL Alerts with scheduled queries","C":"Apache Airflow with custom validation DAGs","D":"Great Expectations library integrated with Spark"},"answer":"A","short":"Lakeflow Declarative Pipelines (formerly DLT).","explanation":"Lakeflow Declarative Pipelines provides built-in data quality monitoring through expectations — declarative constraints that automatically track pass/fail metrics, record violations in the event log, and optionally drop or quarantine bad records. Quality statistics are visible per-table in the pipeline UI.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"03-data-transformation-and-modeling-q021","bank":"praticas","n":66,"domain":"data-transformation-and-modeling","title":"Lakeflow Declarative Pipelines Continuous Pipeline Behavior","difficulty":"hard","question":"A Lakeflow Declarative Pipelines pipeline has two streaming tables and three materialized views. It runs in Production mode with Continuous Pipeline Mode. What outcome should be expected after clicking Start if there is unprocessed data and all definitions are correct?","choices":{"A":"Only the two streaming datasets are updated continuously; the three materialized views are updated once and then stop","B":"All datasets are updated at set intervals until the pipeline is shut down. Compute resources are deployed for the update and terminated when the pipeline is stopped","C":"All five datasets are updated once, and then the pipeline shuts down automatically to conserve resources","D":"The pipeline fails because streaming and materialized view datasets cannot coexist in Continuous mode"},"answer":"B","short":"All datasets are updated at set intervals until the pipeline is shut down. Compute resources are deployed for the update and terminated when the pipeline is stopped.","explanation":"In Continuous mode, the pipeline runs indefinitely — processing streaming tables as new data arrives and periodically refreshing materialized views. It does not shut down automatically; resources are released only when the pipeline is manually stopped.","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":null},{"id":"03-data-transformation-and-modeling-q022","bank":"praticas","n":67,"domain":"data-transformation-and-modeling","title":"Lakeflow Declarative Pipelines DROP Expectation Behavior","difficulty":"medium","question":"A dataset established through Lakeflow Declarative Pipelines has an expectations clause with `ON VIOLATION DROP ROW`. What should occur when processing a batch of data that includes entries violating these constraints?","choices":{"A":"Violating records are written to a separate quarantine table for manual review","B":"The entire batch is rejected and the pipeline enters a failed state","C":"Records that violate the expectation are dropped from the target dataset and recorded as invalid in the event log","D":"The pipeline pauses and waits for manual approval before continuing"},"answer":"C","short":"Records that violate the expectation are dropped from the target dataset and recorded as invalid in the event log.","explanation":"The pipeline continues running. Dropped record counts and violation metrics are tracked in the Lakeflow Declarative Pipelines event log and displayed per-table in the pipeline UI under data quality statistics. The `FAIL UPDATE` variant would stop the pipeline instead.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"03-data-transformation-and-modeling-q023","bank":"praticas","n":68,"domain":"data-transformation-and-modeling","title":"CREATE STREAMING TABLE vs CREATE MATERIALIZED VIEW","difficulty":"medium","question":"In a Lakeflow Declarative Pipelines SQL definition, when should `CREATE OR REFRESH STREAMING TABLE` be used instead of `CREATE OR REFRESH MATERIALIZED VIEW`?","choices":{"A":"When the table needs to support both read and write operations simultaneously","B":"When the table must be accessible from multiple workspaces","C":"When the table requires ACID transaction support","D":"When data needs to be processed incrementally"},"answer":"D","short":"When data needs to be processed incrementally.","explanation":"A streaming table reads append-oriented sources (Auto Loader, Kafka, `STREAM(...)` of another table) and processes only records that arrived since the last update. A materialized view stores a query result and refreshes it, incrementally when possible, otherwise by recomputing. Legacy syntax used `CREATE STREAMING LIVE TABLE` (now a streaming table) and `CREATE LIVE TABLE` (now a materialized view).","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":null},{"id":"03-data-transformation-and-modeling-q024","bank":"praticas","n":69,"domain":"data-transformation-and-modeling","title":"Silver to Gold Streaming Query","difficulty":"medium","question":"Which type of Structured Streaming query represents the transition from a Silver table to a Gold table?","choices":{"A":"A query that reads from a Silver streaming table and applies aggregations — such as `groupBy()` with `sum()`, `count()`, or `avg()` — to produce summary metrics written to a Gold table","B":"A query that deduplicates and cleanses Bronze data before writing to a Silver table","C":"A query that reads raw data from cloud storage and applies schema enforcement before writing to a Silver table","D":"A query that replicates Silver data to an external data warehouse for reporting"},"answer":"A","short":"A query that reads from a Silver streaming table and applies aggregations — such as `groupBy()` with `sum()`, `count()`, or `avg()` — to produce summary metrics written to a Gold table.","explanation":"Gold tables typically contain business-level aggregates. Transforming cleaned Silver data into aggregated Gold data is the defining characteristic of the Silver-to-Gold transition in medallion architecture.\n\n> ⚠️ *This answer was generated by AI — verify against official Databricks documentation.*","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":"01-databricks-intelligence-platform/01-lakehouse-architecture"},{"id":"03-data-transformation-and-modeling-q025","bank":"praticas","n":70,"domain":"data-transformation-and-modeling","title":"Identifying Which Lakeflow Declarative Pipelines Table Drops Records","difficulty":"medium","question":"A data engineer manages three tables in a Lakeflow Declarative Pipelines pipeline with expectations set to eliminate invalid records. They observe that data is being discarded at some stage. How can they identify which specific table is dropping the records?","choices":{"A":"Query the Delta transaction log of each table to find DELETE operations","B":"Navigate to the Lakeflow Declarative Pipelines pipeline page, click on each table, and view the data quality statistics","C":"Run DESCRIBE HISTORY on each table to check for dropped record counts","D":"Add explicit logging statements to each table's transformation code"},"answer":"B","short":"Navigate to the Lakeflow Declarative Pipelines pipeline page, click on each table, and view the data quality statistics.","explanation":"The Lakeflow Declarative Pipelines pipeline UI shows per-table expectation metrics, including the number of records that passed, failed, or were dropped for each defined constraint. This makes it straightforward to pinpoint which table's expectation is causing record drops.","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"03-data-transformation-and-modeling-q026","bank":"praticas","n":71,"domain":"data-transformation-and-modeling","title":"Lakeflow Declarative Pipelines Pipeline Minimum Requirement","difficulty":"easy","question":"What needs to be specified when creating a new Lakeflow Declarative Pipelines pipeline?","choices":{"A":"A target database and storage location","B":"A cluster policy and node type configuration","C":"At least one source code file or notebook that defines the datasets","D":"An explicit schedule or cron expression"},"answer":"C","short":"At least one source code file or notebook that defines the datasets.","explanation":"A pipeline must reference source code (notebooks or files) containing the dataset definitions, such as `CREATE OR REFRESH STREAMING TABLE` / `CREATE OR REFRESH MATERIALIZED VIEW` statements or `@dp.table` / `@dp.materialized_view` functions. Other settings — storage location, target database, cluster configuration — are optional and can use defaults.","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":null},{"id":"03-data-transformation-and-modeling-q027","bank":"praticas","n":72,"domain":"data-transformation-and-modeling","title":"STREAM() Function in Lakeflow Declarative Pipelines","difficulty":"medium","question":"A data engineer joins an ongoing project and notices a `STREAM()` function wrapping a table reference in a Lakeflow Declarative Pipelines SQL query. What explains its inclusion?","choices":{"A":"The `STREAM()` function applies watermarking to handle late-arriving data","B":"The `STREAM()` function enables parallel reads from the table across multiple clusters","C":"It converts a batch table into a temporary streaming source for the current query only","D":"The referenced dataset is read as a streaming source (for example, a streaming table)"},"answer":"D","short":"The referenced dataset is read as a streaming source (for example, a streaming table).","explanation":"In Lakeflow Declarative Pipelines, `STREAM(table_name)` indicates that the table should be read as a streaming source — consuming only new records incrementally rather than reprocessing the full table. It is required when the source is a streaming table and the consuming dataset needs to process it incrementally.","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":null},{"id":"03-data-transformation-and-modeling-q028","bank":"praticas","n":73,"domain":"data-transformation-and-modeling","title":"Lakeflow Declarative Pipelines Migration Changes","difficulty":"medium","question":"A data engineer (Python, bronze/silver) and a data analyst (SQL, gold) collaborate on a medallion pipeline with a streaming source. They plan to migrate to Lakeflow Declarative Pipelines. What changes are necessary?","choices":{"A":"No changes are required","B":"The SQL code must be rewritten in Python because Lakeflow Declarative Pipelines only supports Python definitions","C":"The streaming source must be converted to a batch source before migrating to Lakeflow Declarative Pipelines","D":"The Python code must be rewritten in SQL because Lakeflow Declarative Pipelines only supports SQL definitions"},"answer":"A","short":"No changes are required.","explanation":"Lakeflow Declarative Pipelines natively supports both Python and SQL within the same pipeline. It supports the medallion architecture (Bronze/Silver/Gold layers) and handles streaming sources directly. The existing language mix and multi-hop architecture can migrate to Lakeflow Declarative Pipelines without modification to the underlying logic.","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":null},{"id":"03-data-transformation-and-modeling-q029","bank":"praticas","n":74,"domain":"data-transformation-and-modeling","title":"Persist to Memory and Disk","difficulty":"medium","question":"Which Spark method persists data to both memory and disk when memory is insufficient?","choices":{"A":"`cache()` with `StorageLevel.MEMORY_ONLY`","B":"`persist()` with `StorageLevel.MEMORY_AND_DISK`","C":"`checkpoint()` with eager evaluation","D":"`broadcast()` with local storage fallback"},"answer":"B","short":"`persist()` with `StorageLevel.MEMORY_AND_DISK`.","explanation":"`persist()` allows specifying a `StorageLevel` such as `MEMORY_AND_DISK`, which stores partitions in memory and spills excess to disk when memory is exhausted. `cache()` is a shortcut for `persist(StorageLevel.MEMORY_ONLY)` and does not spill to disk automatically.","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables"},{"id":"03-data-transformation-and-modeling-q030","bank":"praticas","n":75,"domain":"data-transformation-and-modeling","title":"Broadcast Join for a Small Dimension *(2026 blueprint)*","difficulty":"medium","question":"A 2 TB `sales` DataFrame is joined to a 15 MB `stores` DataFrame on `store_id`. The Spark UI shows a `SortMergeJoin` with a large shuffle of `sales`. Which change avoids shuffling the large side?","choices":{"A":"`sales.repartition(1).join(stores, \"store_id\")`","B":"`sales.crossJoin(stores).filter(\"sales.store_id = stores.store_id\")`","C":"`sales.join(broadcast(stores), \"store_id\")`","D":"Lower `spark.sql.shuffle.partitions` to 10"},"answer":"C","short":"`sales.join(broadcast(stores), \"store_id\")`.","explanation":"`broadcast()` marks the small DataFrame for a broadcast join, which copies it to every executor so `sales` isn't shuffled. Its size (15 MB) is above the default `spark.sql.autoBroadcastJoinThreshold` of 10 MB, which is why Spark didn't broadcast it automatically. A cross join multiplies rows. One partition removes parallelism. Fewer shuffle partitions don't remove the shuffle ([SQL performance tuning](https://spark.apache.org/docs/latest/sql-performance-tuning.html)).","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"03-data-transformation-and-modeling-q031","bank":"praticas","n":76,"domain":"data-transformation-and-modeling","title":"union vs unionByName *(2026 blueprint)*","difficulty":"medium","question":"Two DataFrames hold the same columns in a different order: `df_a(id, name, city)` and `df_b(city, id, name)`. Which call combines them, keeping duplicate rows and matching columns correctly?","choices":{"A":"`df_a.union(df_b)`","B":"`df_a.join(df_b, \"id\", \"outer\")`","C":"`df_a.union(df_b).distinct()`","D":"`df_a.unionByName(df_b)`"},"answer":"D","short":"`df_a.unionByName(df_b)`.","explanation":"`union` resolves columns **by position**, so it would put `city` values into `id`. `unionByName` resolves them **by name**. Both keep duplicates, which is SQL `UNION ALL` semantics. Add `.distinct()` for SQL `UNION` behaviour. `allowMissingColumns=True` fills columns missing from one side with nulls ([PySpark unionByName](https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.unionByName.html)).","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"03-data-transformation-and-modeling-q032","bank":"praticas","n":77,"domain":"data-transformation-and-modeling","title":"Splitting and Exploding Columns *(2026 blueprint)*","difficulty":"medium","question":"A Silver table has a `tags` string column such as `\"red,large,sale\"`. Analysts need one row per tag. Which PySpark expression produces it?","choices":{"A":"`df.withColumn(\"tag\", F.explode(F.split(\"tags\", \",\")))`","B":"`df.withColumn(\"tag\", F.split(\"tags\", \",\"))`","C":"`df.withColumn(\"tag\", F.flatten(\"tags\"))`","D":"`df.groupBy(\"tags\").agg(F.collect_list(\"tags\"))`"},"answer":"A","short":"`df.withColumn(\"tag\", F.explode(F.split(\"tags\", \",\")))`.","explanation":"`split` turns the string into an array using a (regular expression) pattern. `explode` then emits one row per array element. `split` alone leaves one row with an array. `flatten` works on arrays of arrays, and `collect_list` does the opposite of what's needed ([PySpark split](https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.functions.split.html)).","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"03-data-transformation-and-modeling-q033","bank":"praticas","n":78,"domain":"data-transformation-and-modeling","title":"Fast Distinct Counts on Huge Tables *(2026 blueprint)*","difficulty":"easy","question":"A dashboard shows the number of distinct visitors per day over billions of events. An exact `COUNT(DISTINCT visitor_id)` is too slow, and a small error is acceptable. Which function fits?","choices":{"A":"`count_if(visitor_id IS NOT NULL)`","B":"`approx_count_distinct(visitor_id)`","C":"`sum(DISTINCT visitor_id)`","D":"`collect_set(visitor_id)`"},"answer":"B","short":"`approx_count_distinct(visitor_id)`.","explanation":"`approx_count_distinct` estimates the number of distinct values with HyperLogLog++. Its default maximum relative standard deviation is 5 %, and the `relativeSD` argument can tighten it. `collect_set` would build huge arrays, and the other options compute something else ([approx_count_distinct](https://docs.databricks.com/aws/en/sql/language-manual/functions/approx_count_distinct)).","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"03-data-transformation-and-modeling-q034","bank":"praticas","n":79,"domain":"data-transformation-and-modeling","title":"Shuffle Partitions vs Default Parallelism *(2026 blueprint)*","difficulty":"medium","question":"A DataFrame `groupBy` on 40 MB of data runs 200 tiny tasks after the shuffle on classic compute. An engineer wants to tune the post-shuffle partition count and then re-measure. Which setting controls it?","choices":{"A":"`spark.default.parallelism`","B":"`spark.executor.memory`","C":"`spark.sql.shuffle.partitions`","D":"`spark.sql.autoBroadcastJoinThreshold`"},"answer":"C","short":"`spark.sql.shuffle.partitions`.","explanation":"It sets the number of partitions used when shuffling data for joins or aggregations in the DataFrame and SQL engine (default 200). On Databricks, setting it to `auto` lets Spark size it from the plan and the data. `spark.default.parallelism` applies to RDD operations, memory settings size the JVMs, and the broadcast threshold controls join strategy ([AQE](https://docs.databricks.com/aws/en/optimizations/aqe), [Spark SQL tuning](https://spark.apache.org/docs/latest/sql-performance-tuning.html)).","lesson":"03-data-transformation-and-modeling/07-spark-tuning-parameters","related":null},{"id":"03-data-transformation-and-modeling-q035","bank":"praticas","n":80,"domain":"data-transformation-and-modeling","title":"Choosing a Gold Object for a Busy Dashboard *(2026 blueprint)*","difficulty":"medium","question":"Two hundred users open a dashboard each morning that aggregates revenue by region from a large Silver table. Hourly freshness is acceptable. The team wants fast reads and doesn't want to maintain refresh code. Which Unity Catalog object should back the dashboard?","choices":{"A":"A standard view over the Silver table","B":"A streaming table that appends Silver rows","C":"A temporary view created by the dashboard query","D":"A materialized view refreshed on a schedule"},"answer":"D","short":"A materialized view refreshed on a schedule.","explanation":"A materialized view stores precomputed results and refreshes them (incrementally when possible) on a schedule or when upstream data changes, so reads are cheap. A view recomputes the aggregation on every query. Temporary views are session-scoped. Streaming tables append new rows and don't recompute an aggregate ([standalone materialized views](https://docs.databricks.com/aws/en/views/materialized)).","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":null},{"id":"04-working-with-lakeflow-jobs-q001","bank":"praticas","n":81,"domain":"working-with-lakeflow-jobs","title":"Adding an Upstream Task to an Existing Job","difficulty":"medium","question":"A data engineer executes a single-task job each morning. Upon discovering an upstream data issue, they must add a new notebook to run before the original task. What is the correct approach to set up this new upstream task?","choices":{"A":"Create a new task in the existing Job, and then add the original task as a dependency of the new task","B":"Create a separate Job for the new notebook and schedule it to run 30 minutes before the original Job","C":"Clone the existing Job and add the new notebook as a second task in the clone","D":"Replace the original task's notebook with a wrapper notebook that runs both notebooks sequentially"},"answer":"A","short":"Create a new task in the existing Job, and then add the original task as a dependency of the new task.","explanation":"In Databricks Jobs, task dependencies are defined by specifying which tasks a given task \"depends on.\" To insert an upstream step, the new task should have no dependencies (runs first), and the original task should be configured to depend on the new task (runs after).","lesson":"04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks","related":null},{"id":"04-working-with-lakeflow-jobs-q002","bank":"praticas","n":82,"domain":"working-with-lakeflow-jobs","title":"Limiting Query Refresh Schedule Duration","difficulty":"medium","question":"An engineering manager wants a query to refresh every minute for the first week after a project launch, with no compute costs after that week. What strategy ensures the query stops refreshing and generating costs beyond week one?","choices":{"A":"Set the SQL warehouse to auto-stop after one week of total runtime","B":"Set the query's refresh schedule to end on a specific date in the query scheduler","C":"Manually cancel the refresh schedule at the end of the week","D":"Create a Databricks Job to disable the query refresh after seven days"},"answer":"B","short":"Set the query's refresh schedule to end on a specific date in the query scheduler.","explanation":"Databricks SQL query schedulers support an optional end date/time, allowing the refresh to automatically stop once the date is reached. No manual intervention is needed after the initial setup.","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"04-working-with-lakeflow-jobs-q003","bank":"praticas","n":83,"domain":"working-with-lakeflow-jobs","title":"Programmatic Job Schedule Representation","difficulty":"medium","question":"A data engineer manages a complex job schedule and wants to represent and submit it to other jobs programmatically rather than manually selecting values in the Databricks scheduling form. Which tool enables this?","choices":{"A":"Declarative Automation Bundles (formerly Databricks Asset Bundles) YAML configuration","B":"Apache Airflow DAG definitions","C":"Cron syntax","D":"JSON job templates via the Databricks CLI"},"answer":"C","short":"Cron syntax.","explanation":"Databricks Jobs support quartz cron expressions for scheduling. Cron strings are compact, human-readable, and can be programmatically constructed and submitted via the Jobs API or embedded in Declarative Automation Bundles (formerly Databricks Asset Bundles) YAML configuration files.","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"04-working-with-lakeflow-jobs-q004","bank":"praticas","n":84,"domain":"working-with-lakeflow-jobs","title":"Scheduling a Daily SQL Query Refresh","difficulty":"easy","question":"An engineering manager reviews a query daily but currently reruns it manually and waits for results. What strategy guarantees the query results are refreshed daily automatically?","choices":{"A":"Use a Lakeflow Declarative Pipelines pipeline with a daily trigger to refresh the query","B":"Create a Databricks Job that runs the query notebook on a daily cron schedule","C":"Set up an Apache Airflow DAG to trigger the query execution daily","D":"Schedule the query to refresh every 1 day from the query's page in Databricks SQL"},"answer":"D","short":"Schedule the query to refresh every 1 day from the query's page in Databricks SQL.","explanation":"Databricks SQL provides a built-in scheduler accessible directly from the query editor. Setting a recurring daily refresh interval ensures results are always up-to-date without manual intervention or external orchestration tools.","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"04-working-with-lakeflow-jobs-q005","bank":"praticas","n":85,"domain":"working-with-lakeflow-jobs","title":"When to Use \"Depends On\" for a Job Task","difficulty":"easy","question":"In what situations should a data engineer choose a task in the \"Depends On\" field when creating a new Databricks Job task?","choices":{"A":"When another task needs to successfully complete before the new task begins","B":"When the new task should only run if a previous task has completed successfully","C":"When the new task processes data from a different database than other tasks","D":"When the new task needs to run on a different cluster than other tasks"},"answer":"A","short":"When another task needs to successfully complete before the new task begins.","explanation":"The \"Depends On\" field establishes execution order in a Databricks Job DAG. The new task will only start after all specified upstream tasks have completed successfully. With the default Run if condition (*All succeeded*), if a dependency fails the downstream task doesn't run and is marked `Upstream failed`.","lesson":"04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks","related":null},{"id":"04-working-with-lakeflow-jobs-q006","bank":"praticas","n":86,"domain":"working-with-lakeflow-jobs","title":"Branching on New Data *(2026 blueprint)*","difficulty":"medium","question":"An ingestion task publishes the number of rows it loaded as a task value. The transformation tasks should run only when that number is greater than zero. Which Lakeflow Jobs feature implements this?","choices":{"A":"A For each task over the task value","B":"An If/else condition task comparing `{{tasks.ingest.values.rows_loaded}} > 0`, with transformations depending on its `true` outcome","C":"A retry policy on the transformation task","D":"Setting max concurrent runs to 0 when no data arrives"},"answer":"B","short":"An If/else condition task comparing `{{tasks.ingest.values.rows_loaded}} > 0`, with transformations depending on its `true` outcome.","explanation":"The If/else task evaluates a boolean expression on two operands (task values, job parameters, literals). Downstream tasks depend on its `(true)` or `(false)` outcome. `>` performs a numeric comparison ([If/else task](https://docs.databricks.com/aws/en/jobs/if-else)).","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"04-working-with-lakeflow-jobs-q007","bank":"praticas","n":87,"domain":"working-with-lakeflow-jobs","title":"Looping Over Tables *(2026 blueprint)*","difficulty":"medium","question":"The same load notebook must run for 30 source tables, at most five at a time, without defining 30 tasks. Which configuration meets this?","choices":{"A":"A single notebook task with `max_retries` set to 30","B":"Thirty notebook tasks with no dependencies","C":"A For each task with the table list as input, the notebook as the nested task, and concurrency set to 5","D":"A Run Job task pointing at itself"},"answer":"C","short":"A For each task with the table list as input, the notebook as the nested task, and concurrency set to 5.","explanation":"For each runs one nested task once per input element, passing `{{input}}` (or `{{input.<key>}}`). Concurrency defaults to 1, and the nested task can't itself be a For each ([For each task](https://docs.databricks.com/aws/en/jobs/for-each)).","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"04-working-with-lakeflow-jobs-q008","bank":"praticas","n":88,"domain":"working-with-lakeflow-jobs","title":"Retrying Transient Failures *(2026 blueprint)*","difficulty":"easy","question":"A task that calls an external API fails a few times a week with transient network errors, and succeeds when re-run minutes later. What is the built-in way to handle this?","choices":{"A":"Increase the task timeout","B":"Add an If/else task after it","C":"Set the job's max concurrent runs to 2","D":"Configure a retry policy on the task, with a retry interval"},"answer":"D","short":"Configure a retry policy on the task, with a retry interval.","explanation":"Task-level retries automatically re-run a failed task after the configured interval. A timeout limits how long one attempt may run, and when both are set the timeout applies to each retry. Concurrency and branching don't retry anything ([Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task)).","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"04-working-with-lakeflow-jobs-q009","bank":"praticas","n":89,"domain":"working-with-lakeflow-jobs","title":"Cleanup That Always Runs *(2026 blueprint)*","difficulty":"medium","question":"A job's final task drops temporary staging tables. It must run whether the upstream transform succeeds or fails. Which Run if condition should it use?","choices":{"A":"All done","B":"At least one succeeded","C":"All succeeded","D":"All failed"},"answer":"A","short":"All done.","explanation":"*All done* runs the task after all dependencies finish, whatever their status. The default, *All succeeded*, would mark the task `Upstream failed` and skip it when the transform fails. *All failed* runs it only after failures ([Configure task dependencies](https://docs.databricks.com/aws/en/jobs/conditional-tasks)).","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"04-working-with-lakeflow-jobs-q010","bank":"praticas","n":90,"domain":"working-with-lakeflow-jobs","title":"Processing Files Soon After Unpredictable Drops *(2026 blueprint)*","difficulty":"medium","question":"A partner uploads JSON files to a Unity Catalog external location at unpredictable times: sometimes several an hour, sometimes nothing for a day. Each drop should be processed shortly after it lands, without empty runs or idle compute. Which trigger should the Lakeflow Job use?","choices":{"A":"Scheduled trigger every 5 minutes","B":"File arrival trigger on the external location","C":"Continuous trigger","D":"Manual trigger by an operator"},"answer":"B","short":"File arrival trigger on the external location.","explanation":"A file arrival trigger monitors a UC external location or volume and starts a run only when new files appear. *Wait after last change* can batch bursts into one run. Polling schedules start runs that find nothing, and continuous triggers keep compute running ([file arrival triggers](https://docs.databricks.com/aws/en/jobs/file-arrival-triggers)).","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"04-working-with-lakeflow-jobs-q011","bank":"praticas","n":91,"domain":"working-with-lakeflow-jobs","title":"Running When Upstream Tables Change *(2026 blueprint)*","difficulty":"medium","question":"A Gold build job must run after **both** `main.silver.orders` and `main.silver.customers` are updated. Those tables are maintained by two other teams' jobs, which run at varying times. Which trigger configuration fits?","choices":{"A":"A scheduled trigger at 06:00","B":"A table update trigger on both tables with \"Any table is updated\"","C":"A table update trigger on both tables with \"All tables are updated\"","D":"A file arrival trigger on the tables' storage paths"},"answer":"C","short":"A table update trigger on both tables with \"All tables are updated\".","explanation":"Table update triggers start a run when monitored UC tables change. With multiple tables, *Trigger when* can be set to **All tables are updated** or **Any table is updated**. The job's Run as principal needs `SELECT` on the tables. File arrival triggers can't target managed table locations ([table update triggers](https://docs.databricks.com/aws/en/jobs/trigger-table-update)).","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"04-working-with-lakeflow-jobs-q012","bank":"praticas","n":92,"domain":"working-with-lakeflow-jobs","title":"Time-Based vs Data-Driven Triggers *(2026 blueprint)*","difficulty":"easy","question":"A regulatory report must be published at exactly 07:00 every weekday, using whatever data has arrived by then. Which trigger fits best?","choices":{"A":"Continuous trigger","B":"File arrival trigger","C":"Table update trigger","D":"Scheduled trigger with Quartz cron `0 0 7 ? * MON-FRI`"},"answer":"D","short":"Scheduled trigger with Quartz cron `0 0 7 ? * MON-FRI`.","explanation":"When the deadline, not data availability, decides when work runs, a time-based schedule is right. Quartz cron puts seconds first, and `?` goes in day-of-month when day-of-week is constrained. Data-driven triggers fit when work should follow data arrival ([schedules and triggers](https://docs.databricks.com/aws/en/jobs/triggers)).","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"04-working-with-lakeflow-jobs-q013","bank":"praticas","n":93,"domain":"working-with-lakeflow-jobs","title":"Configuring a Dashboard Task *(2026 blueprint)*","difficulty":"easy","question":"After a pipeline task refreshes Gold tables, an AI/BI dashboard must be refreshed in the same job. Which task configuration achieves this?","choices":{"A":"A Dashboards task that depends on the pipeline task and uses a SQL warehouse","B":"A notebook task that calls `display()` on the Gold tables","C":"A For each task over the dashboard's widgets","D":"A second job with a scheduled trigger 30 minutes later"},"answer":"A","short":"A Dashboards task that depends on the pipeline task and uses a SQL warehouse.","explanation":"Lakeflow Jobs has native task types for notebooks, SQL, dashboards, and pipelines. Making the Dashboards task depend on the pipeline task guarantees the order inside one DAG. A separate job on a fixed delay can run before the data is ready ([Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task)).","lesson":"04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks","related":null},{"id":"04-working-with-lakeflow-jobs-q014","bank":"praticas","n":94,"domain":"working-with-lakeflow-jobs","title":"Passing a Value Between Tasks *(2026 blueprint)*","difficulty":"medium","question":"Task `ingest` computes the latest order date. Task `report` needs that value. Which code sets it in `ingest`?","choices":{"A":"`dbutils.widgets.text(\"max_date\", value)`","B":"`dbutils.jobs.taskValues.set(key=\"max_date\", value=value)`","C":"`spark.conf.set(\"max_date\", value)`","D":"`dbutils.notebook.exit(value)` in every task"},"answer":"B","short":"`dbutils.jobs.taskValues.set(key=\"max_date\", value=value)`.","explanation":"Task values pass small, JSON-serializable results (up to 48 KiB) between tasks. Downstream tasks read them with `dbutils.jobs.taskValues.get(taskKey=\"ingest\", key=\"max_date\")` or, preferably, the reference `{{tasks.ingest.values.max_date}}` in parameters ([task values](https://docs.databricks.com/aws/en/jobs/task-values)).","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"04-working-with-lakeflow-jobs-q015","bank":"praticas","n":95,"domain":"working-with-lakeflow-jobs","title":"Reading Quartz Cron *(2026 blueprint)*","difficulty":"easy","question":"A Lakeflow Job schedule uses the Quartz expression `0 30 2 * * ?`. When does it run?","choices":{"A":"Every 30 minutes past 2 o'clock, every hour","B":"At 00:30 on the 2nd of every month","C":"At 02:30:00 every day","D":"Every 2 minutes at second 30"},"answer":"C","short":"At 02:30:00 every day.","explanation":"Quartz fields are seconds, minutes, hours, day-of-month, month, day-of-week, and an optional year. So `0 30 2 * * ?` means second 0, minute 30, hour 2, every day of every month, with no specific day-of-week ([Quartz CronTrigger tutorial](https://www.quartz-scheduler.org/documentation/quartz-2.3.0/tutorials/crontrigger.html)).","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"05-implementing-cicd-q001","bank":"praticas","n":96,"domain":"implementing-cicd","title":"Where Pull Requests Are Created","difficulty":"easy","question":"A data engineer works on a feature branch in a Databricks Git folder. Which step of their workflow is performed in the Git provider (for example GitHub) rather than in the Databricks Git dialog?","choices":{"A":"Committing and pushing changes","B":"Creating the feature branch","C":"Pulling a teammate's latest changes","D":"Creating and merging the pull request into the default branch"},"answer":"D","short":"Creating and merging the pull request into the default branch.","explanation":"Git folders handle branch creation, switching, Commit & Push, pull, merge, rebase, and conflict resolution in the workspace UI. The docs say to \"use your Git provider's interface to create a pull request and merge it into the default branch\", where reviews and branch protections apply ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"05-implementing-cicd-q002","bank":"praticas","n":97,"domain":"implementing-cicd","title":"Benefit of Git Folders Over Notebook Versioning","difficulty":"medium","question":"A data engineer must decide between the built-in versioning of Databricks Notebooks and Databricks Git folders. What is one benefit of using Git folders (formerly Repos) instead?","choices":{"A":"Databricks Git folders support the use of multiple branches","B":"Git folders eliminate the need for a Git provider by hosting repositories internally","C":"Git folders provide a visual diff tool for comparing notebook cell outputs","D":"Git folders automatically back up notebooks to cloud storage every 5 minutes"},"answer":"A","short":"Databricks Git folders support the use of multiple branches.","explanation":"Built-in notebook versioning provides only a linear history of auto-saved snapshots. Git folders integrate fully with Git, enabling feature branches, pull requests, code reviews, and collaborative development workflows — essential for team-based software engineering practices.","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"05-implementing-cicd-q003","bank":"praticas","n":98,"domain":"implementing-cicd","title":"Syncing a Git Folder With Remote Changes","difficulty":"easy","question":"A data engineer's colleague has pushed updates to the central Git repository. The data engineer needs to sync their Databricks Git folder with these changes. Which Git operation accomplishes this?","choices":{"A":"Clone","B":"Pull","C":"Rebase","D":"Fetch"},"answer":"B","short":"Pull.","explanation":"A `git pull` fetches changes from the remote repository and merges them into the current local branch. In a Databricks Git folder, this is the **Pull** action in the Git dialog (pull also clears notebook state), keeping the local copy synchronized with the latest upstream changes.","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"05-implementing-cicd-q004","bank":"praticas","n":99,"domain":"implementing-cicd","title":"Committing From a Git Folder *(2026 blueprint)*","difficulty":"easy","question":"A data engineer has edited two notebooks in a Databricks Git folder on branch `feature/dedup`. How do they get the changes to the remote repository from the workspace UI?","choices":{"A":"Export the notebooks as DBC files and upload them to the Git provider","B":"Run `databricks bundle deploy`","C":"Open the Git dialog, select the changes, enter a commit message, and click Commit & Push","D":"Click Pull, which pushes local changes automatically"},"answer":"C","short":"Open the Git dialog, select the changes, enter a commit message, and click Commit & Push.","explanation":"In Git folders, the UI \"commits and pushes in a single action\", and a commit message is required. Pull brings remote changes **in**. Bundle deploy pushes to a workspace, not to Git ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"05-implementing-cicd-q005","bank":"praticas","n":100,"domain":"implementing-cicd","title":"Creating a Feature Branch *(2026 blueprint)*","difficulty":"easy","question":"Before starting new work, an engineer wants a separate branch based on `main` in their Git folder. What should they do?","choices":{"A":"Rename the `main` branch in the Git dialog","B":"Clone the repository again into a new workspace folder","C":"Ask an admin to create the branch with the Repos API","D":"Use the Git dialog's Create Branch option, name the branch, and choose `main` as the base"},"answer":"D","short":"Use the Git dialog's Create Branch option, name the branch, and choose `main` as the base.","explanation":"Git folders create and switch branches from the Git dialog. Switching branches can carry uncommitted changes over. It can also delete workspace assets that don't exist on the target branch, and recreate them with new IDs when you switch back ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"05-implementing-cicd-q006","bank":"praticas","n":101,"domain":"implementing-cicd","title":"Reset in a Git Folder *(2026 blueprint)*","difficulty":"hard","question":"An engineer clicks **Reset** on a branch in a Git folder. What is the effect?","choices":{"A":"It is equivalent to `git reset --hard` plus `git push --force`, so committed and uncommitted changes are lost locally and on the remote branch","B":"Only uncommitted local changes are discarded","C":"The branch is restored from notebook revision history","D":"The Git folder is unlinked from the remote repository"},"answer":"A","short":"It is equivalent to `git reset --hard` plus `git push --force`, so committed and uncommitted changes are lost locally and on the remote branch.","explanation":"The docs warn: \"When you reset, you lose all uncommitted and committed changes in both the local and remote version of the branch.\" Use it only when you really want to discard work ([Git operations in Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"05-implementing-cicd-q007","bank":"praticas","n":102,"domain":"implementing-cicd","title":"Keeping a Secret Out of the Bundle *(2026 blueprint)*","difficulty":"medium","question":"A Declarative Automation Bundle deploys a job that needs a database password. The password must not appear in `databricks.yml`, in notebooks, or in Git. The CI system stores it as a secret. How should the bundle receive it at deploy time?","choices":{"A":"Put the password in the variable's `default`","B":"Declare a bundle variable with no default, and have CI export `BUNDLE_VAR_<variable_name>` from its secret store","C":"Store it in a `passwords.txt` file in the bundle root","D":"Hard-code it with `spark.conf.set` in the notebook"},"answer":"B","short":"Declare a bundle variable with no default, and have CI export `BUNDLE_VAR_<variable_name>` from its secret store.","explanation":"Bundle variables can be set from `BUNDLE_VAR_`-prefixed environment variables, so the value never enters source control. Runtime credentials can also be read in code with `dbutils.secrets.get` ([bundle variables](https://docs.databricks.com/aws/en/dev-tools/bundles/variables)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q008","bank":"praticas","n":103,"domain":"implementing-cicd","title":"Bundle Variable Precedence *(2026 blueprint)*","difficulty":"hard","question":"A bundle declares `catalog` with `default: dev`. The `prod` target sets `variables: {catalog: prod}`. In CI, the environment has `BUNDLE_VAR_catalog=staging`, and the command is `databricks bundle deploy -t prod --var=\"catalog=prod_v2\"`. Which value is used?","choices":{"A":"`dev`","B":"`prod`","C":"`prod_v2`","D":"`staging`"},"answer":"C","short":"`prod_v2`.","explanation":"The CLI uses the first source that provides a value, in this order: the `--var` option, then `BUNDLE_VAR_` environment variables, then `variable-overrides.json`, then target `variables`, then the declaration's `default` ([bundle variables](https://docs.databricks.com/aws/en/dev-tools/bundles/variables)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q009","bank":"praticas","n":104,"domain":"implementing-cicd","title":"Promoting One Codebase Across Environments *(2026 blueprint)*","difficulty":"medium","question":"A team wants the same job definition deployed to dev, test, and prod workspaces, each writing to a different Unity Catalog catalog. What is the bundle-native approach?","choices":{"A":"Copy `resources/job.yml` into three folders, one per environment","B":"Edit the job in each workspace UI after deployment","C":"Create three Git repositories","D":"Define `dev`, `test`, and `prod` targets with their own workspace hosts, and override a `catalog` variable per target"},"answer":"D","short":"Define `dev`, `test`, and `prod` targets with their own workspace hosts, and override a `catalog` variable per target.","explanation":"Targets override top-level settings (workspace, `run_as`, variables, resource settings) per environment, so one set of resource YAML is promoted with `databricks bundle deploy -t <target>`. Manual UI edits drift from source control, and the next deploy can overwrite them ([Declarative Automation Bundles](https://docs.databricks.com/aws/en/dev-tools/bundles/)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q010","bank":"praticas","n":105,"domain":"implementing-cicd","title":"Development Mode Behaviour *(2026 blueprint)*","difficulty":"medium","question":"An engineer deploys a bundle with `-t dev`, where the target has `mode: development`. The deployed job never runs on its daily schedule. Why?","choices":{"A":"Development mode pauses schedules and triggers on deployed resources, and prefixes resource names with `[dev <user>]`","B":"Development mode deletes schedules from the YAML","C":"Development mode requires a service principal","D":"The `dev` target always deploys to a read-only workspace"},"answer":"A","short":"Development mode pauses schedules and triggers on deployed resources, and prefixes resource names with `[dev <user>]`.","explanation":"`mode: development` also marks pipelines as `development: true` and allows concurrent runs, so engineers can iterate safely. Run the job manually with `databricks bundle run`, or deploy to a production-mode target for scheduled runs ([deployment modes](https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q011","bank":"praticas","n":106,"domain":"implementing-cicd","title":"Production Mode Safeguards *(2026 blueprint)*","difficulty":"medium","question":"Which behaviour is part of `mode: production` for a bundle target?","choices":{"A":"It pauses all schedules after deployment","B":"It validates the configured Git branch and that `run_as` and permissions are specified (a service principal is recommended), and it disallows cluster overrides","C":"It prefixes every resource name with the deployer's user name","D":"It skips YAML validation for faster deploys"},"answer":"B","short":"It validates the configured Git branch and that `run_as` and permissions are specified (a service principal is recommended), and it disallows cluster overrides.","explanation":"Production mode also checks that pipelines are `development: false` and that paths aren't overridden to a specific user. The branch check can be overridden with `--force` ([deployment modes](https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q012","bank":"praticas","n":107,"domain":"implementing-cicd","title":"Validating Before Deploying *(2026 blueprint)*","difficulty":"easy","question":"In a CI pipeline, which Databricks CLI command checks that the bundle configuration is syntactically correct before anything is deployed?","choices":{"A":"`databricks bundle sync`","B":"`databricks bundle destroy`","C":"`databricks bundle validate`","D":"`databricks jobs list`"},"answer":"C","short":"`databricks bundle validate`.","explanation":"`validate` checks the bundle configuration. `deploy -t <target>` deploys it, `run` runs a job or pipeline, `plan` shows the deployment plan, and `destroy` deletes previously deployed resources ([bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q013","bank":"praticas","n":108,"domain":"implementing-cicd","title":"Running a Bundle Job From CI *(2026 blueprint)*","difficulty":"easy","question":"After `databricks bundle deploy -t test`, the CI pipeline must start the bundle's `orders_job` in the test environment and wait for the result. Which command does this?","choices":{"A":"`databricks bundle init orders_job`","B":"`databricks bundle deploy orders_job --run`","C":"`databricks bundle summary -t test`","D":"`databricks bundle run orders_job -t test`"},"answer":"D","short":"`databricks bundle run orders_job -t test`.","explanation":"`bundle run` runs \"a job, pipeline, app, or script\" defined in the bundle, against the selected target. `summary` lists the bundle's identity and deployed resources, and `init` creates a bundle from a template ([bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q014","bank":"praticas","n":109,"domain":"implementing-cicd","title":"Bringing an Existing Job Under a Bundle *(2026 blueprint)*","difficulty":"hard","question":"A job was built by hand in the UI. The team wants it managed by their bundle without recreating it from scratch. Which CLI commands help?","choices":{"A":"`databricks bundle generate` to produce YAML for the existing job, then `databricks bundle deployment bind` to link the bundle resource to it","B":"`databricks bundle destroy`, then recreate it in the UI","C":"`databricks bundle sync`, which copies the workspace job into Git","D":"`databricks bundle validate --import`"},"answer":"A","short":"`databricks bundle generate` to produce YAML for the existing job, then `databricks bundle deployment bind` to link the bundle resource to it.","explanation":"`generate` creates bundle configuration for a resource that already exists in the workspace. `deployment bind` links a bundle-defined resource to the existing remote resource, so later deploys update it instead of creating a duplicate. `sync` is a one-way copy of local files to the workspace ([bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"05-implementing-cicd-q015","bank":"praticas","n":110,"domain":"implementing-cicd","title":"What a Bundle Packages *(2026 blueprint)*","difficulty":"easy","question":"Which set of assets can a Declarative Automation Bundle define and deploy together?","choices":{"A":"Only notebooks","B":"Lakeflow Jobs, Lakeflow (Declarative) Pipelines, and other workspace assets such as dashboards, alongside their source code","C":"Only Unity Catalog grants","D":"Only cluster policies"},"answer":"B","short":"Lakeflow Jobs, Lakeflow (Declarative) Pipelines, and other workspace assets such as dashboards, alongside their source code.","explanation":"A bundle is YAML configuration (`databricks.yml` plus included resource files) and the code it references, versioned in Git and deployed per target. Newer CLI versions also support resources such as Genie Agents and Lakebase projects ([bundles release notes](https://docs.databricks.com/aws/en/release-notes/dev-tools/bundles)).","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q001","bank":"praticas","n":111,"domain":"troubleshooting-monitoring-and-optimization","title":"OPTIMIZE for File Compaction","difficulty":"easy","question":"A data engineer has discovered that the data files related to a Delta table are quite small. They aim to merge these small files into larger ones to enhance performance. Which keywords can be utilized to compact the small files?","choices":{"A":"VACUUM","B":"COMPACT","C":"OPTIMIZE","D":"DEFRAGMENT"},"answer":"C","short":"`OPTIMIZE`.","explanation":"The `OPTIMIZE` command compacts small files in a Delta table into larger ones, improving read performance by reducing the number of files that need to be scanned. This is different from `VACUUM`, which removes old data files no longer referenced by the transaction log.","lesson":"06-troubleshooting-monitoring-and-optimization/03-delta-optimization","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q002","bank":"praticas","n":112,"domain":"troubleshooting-monitoring-and-optimization","title":"Webhook Alert for NULL Count","difficulty":"medium","question":"A data engineer uses a Databricks SQL dashboard to monitor data quality. When the count of NULL values in a query result reaches 100, the entire team should be alerted via a messaging webhook. What method accomplishes this?","choices":{"A":"Configure a SQL warehouse event hook that triggers on query result thresholds","B":"Add a conditional formatting rule to the dashboard visualization that sends a webhook","C":"Create a Databricks Job that polls the query results and calls the webhook via Python","D":"Set up an Alert with a new webhook alert destination"},"answer":"D","short":"Set up an Alert with a new webhook alert destination.","explanation":"Databricks SQL Alerts monitor query results against a threshold condition and trigger notifications when the condition is met. Webhook destinations allow alerts to be sent to external messaging services (Slack, Microsoft Teams, PagerDuty) in real-time.","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q003","bank":"praticas","n":113,"domain":"troubleshooting-monitoring-and-optimization","title":"Diagnosing a Slow Job Task","difficulty":"medium","question":"A single Job executes two notebooks as distinct tasks. One notebook is performing slowly during the current Job run. What method can a tech lead use to diagnose the cause?","choices":{"A":"Navigate to the Runs tab in the Jobs UI and click on the active run to review the processing notebook","B":"Check the Databricks SQL query history for slow-running queries","C":"Review the cluster event log for resource allocation errors","D":"Open the Lakeflow Declarative Pipelines pipeline UI to inspect per-table processing metrics"},"answer":"A","short":"Navigate to the Runs tab in the Jobs UI and click on the active run to review the processing notebook.","explanation":"Clicking into the active run opens a live view of the notebook execution, including links to the Spark UI for the current task. This allows inspection of active stages, task metrics, shuffle data, and memory usage to identify performance bottlenecks.","lesson":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q004","bank":"praticas","n":114,"domain":"troubleshooting-monitoring-and-optimization","title":"Job Failure Email Notification","difficulty":"easy","question":"What approach should be taken to email the owner of a Databricks Job if it fails?","choices":{"A":"Write a try/except block in the notebook that sends an email on failure","B":"Set up an Alert in the Job's notification settings (Job page)","C":"Configure an external monitoring tool to watch the Jobs API for failure status","D":"Create a downstream task that runs only on failure and sends the email"},"answer":"B","short":"Set up an Alert in the Job's notification settings (Job page).","explanation":"Databricks Jobs support email notifications for job events (failure, success, or start). The job owner's email address is added directly from the Job's \"Notifications\" section, requiring no custom code or external alerting systems.","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q005","bank":"praticas","n":115,"domain":"troubleshooting-monitoring-and-optimization","title":"Webhook Alert for Zero-Sales Stores","difficulty":"medium","question":"A data engineer tracks store-level records where sales equal zero. When this count exceeds zero, the entire team should be notified via a messaging webhook. What approach accomplishes this?","choices":{"A":"Configure a Lakeflow Declarative Pipelines expectation that triggers a webhook when zero-sales records appear","B":"Build a custom Python script that polls the query results and posts to the webhook","C":"Set up an Alert with a new webhook alert destination","D":"Add a dashboard filter that highlights zero-sales stores and emails the team"},"answer":"C","short":"Set up an Alert with a new webhook alert destination.","explanation":"Configure the alert condition on the query result (value > 0) and point the destination to the team's webhook URL. Databricks SQL Alerts evaluate the query result on each refresh and trigger the webhook notification when the threshold condition is met.","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q006","bank":"praticas","n":116,"domain":"troubleshooting-monitoring-and-optimization","title":"Spotting a Duration Regression *(2026 blueprint)*","difficulty":"easy","question":"Stakeholders say a daily Lakeflow Job \"feels slower lately\". Where can the engineer compare recent run durations with the historical baseline, task by task?","choices":{"A":"The workspace admin settings","B":"The cluster's Environment tab in the Spark UI","C":"`DESCRIBE HISTORY` on the output table","D":"The job's Runs tab matrix view"},"answer":"D","short":"The job's Runs tab matrix view.","explanation":"The matrix view shows one column per run, with a Run total duration row and a row per task. Bar height reflects duration, so a growing bar exposes the regression and the task responsible. History is kept for 60 days. Use `system.lakeflow` tables for longer trends ([Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor)).","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q007","bank":"praticas","n":117,"domain":"troubleshooting-monitoring-and-optimization","title":"Finding the Upstream Blocker *(2026 blueprint)*","difficulty":"medium","question":"A job run failed. In the Graph view, three downstream tasks show **Upstream failed** and one task shows **Failed**. Where should the engineer start investigating?","choices":{"A":"The Failed task. The Upstream failed tasks didn't run because their dependency failed","B":"The three Upstream failed tasks, because they're the most numerous","C":"The cluster event log of the last task in the DAG","D":"The job's schedule"},"answer":"A","short":"The Failed task. The Upstream failed tasks didn't run because their dependency failed.","explanation":"With the default Run if (*All succeeded*), a task whose dependency fails is marked `Upstream failed`. The DAG graph shows where the failure started. Fix that task, then use **Repair run** to re-run it and its dependents ([Configure task dependencies](https://docs.databricks.com/aws/en/jobs/conditional-tasks)).","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q008","bank":"praticas","n":118,"domain":"troubleshooting-monitoring-and-optimization","title":"Succeeded With Failures *(2026 blueprint)*","difficulty":"medium","question":"A job run shows the status **Succeeded with failures**. What does that mean?","choices":{"A":"Every task failed, but the job was retried successfully","B":"Some tasks failed, but all leaf tasks (tasks with no downstream dependencies) succeeded","C":"The run succeeded, but notifications failed to send","D":"The run timed out after producing output"},"answer":"B","short":"Some tasks failed, but all leaf tasks (tasks with no downstream dependencies) succeeded.","explanation":"A run's outcome is determined by its leaf tasks. For example, a failed optional branch with no downstream dependents can leave the run \"Succeeded with failures\" ([Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor)).","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q009","bank":"praticas","n":119,"domain":"troubleshooting-monitoring-and-optimization","title":"Fixing a Timed Out Task *(2026 blueprint)*","difficulty":"easy","question":"A task failed with status **Timed Out** after 45 minutes. With today's data volume it needs about 60 minutes. What should the engineer change so future runs complete?","choices":{"A":"The compute's auto termination setting","B":"The job's max concurrent runs","C":"The task's timeout, raised above 60 minutes with headroom","D":"The upstream dependency's Run if condition"},"answer":"C","short":"The task's timeout, raised above 60 minutes with headroom.","explanation":"If a task doesn't finish within its configured timeout, its status is set to Timed Out. With retries configured, the timeout applies to each attempt. The run-duration *warning* threshold only raises an alert, and the other settings don't control the timeout ([Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task)).","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q010","bank":"praticas","n":120,"domain":"troubleshooting-monitoring-and-optimization","title":"Skewed Aggregation With AQE Enabled *(2026 blueprint)*","difficulty":"hard","question":"A batch job does a `groupBy(\"customer_id\")` aggregation. In the Spark UI, most tasks in the longest stage finish in seconds, but one runs for 12 minutes. Its shuffle read is about 10× the median. AQE is enabled with default settings. Which change most directly reduces the runtime?","choices":{"A":"Add more workers to the cluster","B":"Reduce `spark.sql.shuffle.partitions`","C":"Rely on AQE skew-join handling to split the partition","D":"Salt the aggregation key, then aggregate the partial results in a second pass"},"answer":"D","short":"Salt the aggregation key, then aggregate the partial results in a second pass.","explanation":"One hot key overloads a single task. AQE splits skewed partitions only in sort-merge and shuffle-hash **joins**, not in `groupBy` aggregations. More workers leave the giant task on one core, and fewer shuffle partitions make partitions bigger. Salting spreads the hot key across many tasks ([Skew and spill](https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/long-spark-stage-page), [AQE](https://docs.databricks.com/aws/en/optimizations/aqe)).","lesson":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q011","bank":"praticas","n":121,"domain":"troubleshooting-monitoring-and-optimization","title":"Diagnosing Disk Spill *(2026 blueprint)*","difficulty":"medium","question":"A join stage shows large **Spill (Disk)** values and high peak execution memory, with no single straggler task. Which change addresses the cause?","choices":{"A":"Set `spark.sql.shuffle.partitions` to `auto` (or more partitions), or use workers with more memory","B":"Disable AQE","C":"Increase `spark.default.parallelism` only","D":"Run `VACUUM` on the input tables"},"answer":"A","short":"Set `spark.sql.shuffle.partitions` to `auto` (or more partitions), or use workers with more memory.","explanation":"Spill happens when Spark runs low on execution memory during shuffles, joins, sorts, or aggregations. Smaller partitions, less data held per task, or more executor memory reduce it. `spark.default.parallelism` affects RDDs. `VACUUM` doesn't touch execution memory ([Skew and spill](https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/long-spark-stage-page)).","lesson":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q012","bank":"praticas","n":122,"domain":"troubleshooting-monitoring-and-optimization","title":"Liquid Clustering Keys *(2026 blueprint)*","difficulty":"medium","question":"A team's Delta table uses Liquid Clustering on `event_date`. Query patterns change, and most queries now filter on `customer_id`. What should they do?","choices":{"A":"Rewrite the table with `PARTITIONED BY (customer_id)`","B":"Run `ALTER TABLE t CLUSTER BY (customer_id)`, then run `OPTIMIZE` (use `OPTIMIZE ... FULL` to recluster existing data)","C":"Run `OPTIMIZE t ZORDER BY (customer_id)`","D":"Drop and recreate the table, because clustering keys can't change"},"answer":"B","short":"Run `ALTER TABLE t CLUSTER BY (customer_id)`, then run `OPTIMIZE` (use `OPTIMIZE ... FULL` to recluster existing data).","explanation":"Clustering keys can change at any time without an immediate rewrite. Later `OPTIMIZE` runs and writes use the new keys, and `OPTIMIZE FULL` reclusters all existing data. Clustering isn't compatible with partitioning or `ZORDER` ([liquid clustering](https://docs.databricks.com/aws/en/delta/clustering)).","lesson":"06-troubleshooting-monitoring-and-optimization/04-liquid-clustering-and-predictive-optimization","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q013","bank":"praticas","n":123,"domain":"troubleshooting-monitoring-and-optimization","title":"Automatic Liquid Clustering *(2026 blueprint)*","difficulty":"medium","question":"A team wants Databricks to choose and evolve clustering keys from actual query patterns. What do they need?","choices":{"A":"Partitioning by every filter column","B":"`ZORDER BY AUTO` in a nightly `OPTIMIZE` job","C":"`CLUSTER BY AUTO` on a Unity Catalog managed table with predictive optimization enabled","D":"A Spark configuration that enables auto clustering on external tables"},"answer":"C","short":"`CLUSTER BY AUTO` on a Unity Catalog managed table with predictive optimization enabled.","explanation":"Automatic liquid clustering \"requires predictive optimization\" for key selection and clustering operations. Predictive optimization runs only on UC managed tables ([liquid clustering](https://docs.databricks.com/aws/en/delta/clustering), [predictive optimization](https://docs.databricks.com/aws/en/optimizations/predictive-optimization)).","lesson":"06-troubleshooting-monitoring-and-optimization/04-liquid-clustering-and-predictive-optimization","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q014","bank":"praticas","n":124,"domain":"troubleshooting-monitoring-and-optimization","title":"What Predictive Optimization Does *(2026 blueprint)*","difficulty":"easy","question":"Which statement about predictive optimization is correct?","choices":{"A":"It runs `OPTIMIZE ... ZORDER BY` on all partitioned tables","B":"It tunes Spark configurations for every notebook session","C":"It applies to external tables and tables received through sharing","D":"It runs `OPTIMIZE`, `VACUUM`, and `ANALYZE` automatically on Unity Catalog managed tables"},"answer":"D","short":"It runs `OPTIMIZE`, `VACUUM`, and `ANALYZE` automatically on Unity Catalog managed tables.","explanation":"Predictive optimization runs on serverless jobs compute, applies only to UC managed tables, doesn't run `ZORDER`, and can be enabled, disabled, or inherited per catalog, schema, or table. Its history is in `system.storage.predictive_optimization_operations_history` ([predictive optimization](https://docs.databricks.com/aws/en/optimizations/predictive-optimization)).","lesson":"06-troubleshooting-monitoring-and-optimization/03-delta-optimization","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q015","bank":"praticas","n":125,"domain":"troubleshooting-monitoring-and-optimization","title":"Cluster Fails to Start *(2026 blueprint)*","difficulty":"medium","question":"A classic job cluster terminates during startup with `INIT_SCRIPT_FAILURE`. What should the engineer check first?","choices":{"A":"The init script logs, to find why the cluster-scoped script failed (path, permissions, or a failing command)","B":"The Spark UI Stages tab","C":"The job's max concurrent runs","D":"The Delta transaction log of the output table"},"answer":"A","short":"The init script logs, to find why the cluster-scoped script failed (path, permissions, or a failing command).","explanation":"`INIT_SCRIPT_FAILURE` means a cluster-scoped init script couldn't load or exited non-zero. The Spark UI doesn't exist yet because Spark never started. Other startup codes point to cloud capacity, quota, or subnet issues ([termination error codes](https://docs.databricks.com/aws/en/compute/troubleshooting/cluster-error-codes)).","lesson":"06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q016","bank":"praticas","n":126,"domain":"troubleshooting-monitoring-and-optimization","title":"Library Conflict on Shared Compute *(2026 blueprint)*","difficulty":"medium","question":"Two notebooks on the same all-purpose cluster need different versions of a Python library. A compute-scoped install of one version breaks the other notebook. What is the recommended fix?","choices":{"A":"Install both versions as compute-scoped libraries","B":"Install each version with notebook-scoped `%pip install pkg==x.y` in the notebook that needs it","C":"Install the library with a global init script","D":"Copy the library files to DBFS root"},"answer":"B","short":"Install each version with notebook-scoped `%pip install pkg==x.y` in the notebook that needs it.","explanation":"Notebook-scoped libraries take precedence over compute-scoped libraries, which take precedence over Runtime built-ins, and they apply only to that notebook session. Databricks doesn't recommend installing libraries with init scripts, and DBFS library storage is deprecated ([Install libraries](https://docs.databricks.com/aws/en/libraries/)).","lesson":"06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q017","bank":"praticas","n":127,"domain":"troubleshooting-monitoring-and-optimization","title":"Driver Out of Memory *(2026 blueprint)*","difficulty":"medium","question":"A notebook crashes with a driver `OutOfMemoryError` on `pdf = spark.table(\"events\").toPandas()`, where `events` has 300 million rows. Adding workers didn't help. What is the right fix?","choices":{"A":"Increase `spark.sql.shuffle.partitions`","B":"Add even more workers","C":"Aggregate or filter in Spark and collect only the small result (or write results to a table)","D":"Enable autoscaling on the cluster"},"answer":"C","short":"Aggregate or filter in Spark and collect only the small result (or write results to a table).","explanation":"`toPandas()` and `collect()` pull every row into driver memory. Workers add executor capacity, not driver memory. Raising `spark.driver.memory` at compute level is a last resort. The real fix is to keep large data distributed ([Spark configuration: driver memory](https://spark.apache.org/docs/latest/configuration.html)).","lesson":"06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting","related":null},{"id":"06-troubleshooting-monitoring-and-optimization-q018","bank":"praticas","n":128,"domain":"troubleshooting-monitoring-and-optimization","title":"Job Failure Rate Across the Workspace *(2026 blueprint)*","difficulty":"medium","question":"A platform team wants a weekly dashboard of failure rates for every Lakeflow Job over the past 90 days. Which source fits best?","choices":{"A":"The driver logs of the last run","B":"Each job's matrix view, screenshotted weekly","C":"`DESCRIBE HISTORY` on each job's output tables","D":"The `system.lakeflow.job_run_timeline` system table"},"answer":"D","short":"The `system.lakeflow.job_run_timeline` system table.","explanation":"Job run system tables record runs and their result states across the account and can be queried with SQL for dashboards. The UI keeps run history for 60 days, and system tables aren't meant for real-time alerting ([System tables](https://docs.databricks.com/aws/en/admin/system-tables/), [Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor)).","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"07-governance-and-security-q001","bank":"praticas","n":129,"domain":"governance-and-security","title":"External Table Data Retention After DROP","difficulty":"medium","question":"A data engineer drops `my_table` with `DROP TABLE IF EXISTS my_table`. The object no longer appears in `SHOW TABLES`, but the data files still exist on the filesystem. What explains this?","choices":{"A":"The table was an external table","B":"The table had active streaming readers that prevented file deletion","C":"The DROP command failed silently due to insufficient permissions","D":"The VACUUM command needs to be run separately to remove data files"},"answer":"A","short":"The table was an external table.","explanation":"When an external table is dropped, Databricks removes only the metadata entry from the metastore. The underlying data files are stored at a user-defined location and are not managed by Databricks, so they remain intact after the table is dropped.","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"07-governance-and-security-q002","bank":"praticas","n":130,"domain":"governance-and-security","title":"Default Schema Location in the Legacy Hive Metastore","difficulty":"easy","question":"In a workspace still using the legacy `hive_metastore` catalog, a data engineer has established a new database with this command:\n\n```sql\nCREATE DATABASE IF NOT EXISTS customer360;\n```\n\nWhere will the `customer360` database be situated?","choices":{"A":"`dbfs:/user/hive/warehouse/`","B":"`dbfs:/user/hive/warehouse/customer360.db`","C":"`dbfs:/databricks/databases/customer360/`","D":"`dbfs:/mnt/default/customer360.db`"},"answer":"B","short":"`dbfs:/user/hive/warehouse/customer360.db`","explanation":"When a database is created without specifying a `LOCATION`, Databricks stores it in the default Hive warehouse directory at `dbfs:/user/hive/warehouse/`. A subdirectory named `<database_name>.db` is automatically created for it. Specifying only `dbfs:/user/hive/warehouse` (without the `.db` suffix) is incorrect — that is the parent warehouse directory, not the database's own location.","lesson":"07-governance-and-security/01-unity-catalog-basics","related":null},{"id":"07-governance-and-security-q003","bank":"praticas","n":131,"domain":"governance-and-security","title":"DESCRIBE DATABASE Location","difficulty":"easy","question":"Which command retrieves the location of the `customer360` database?","choices":{"A":"`SHOW DATABASE LOCATION customer360;`","B":"`SELECT location FROM information_schema.databases WHERE name = 'customer360';`","C":"`DESCRIBE DATABASE customer360;`","D":"`LIST DATABASE customer360;`"},"answer":"C","short":"`DESCRIBE DATABASE customer360;`","explanation":"This command returns database metadata including the storage location path, owner, comment, and custom properties. It is the standard way to inspect database-level information in Spark SQL and Databricks.","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"07-governance-and-security-q004","bank":"praticas","n":132,"domain":"governance-and-security","title":"Managed Table File Deletion After DROP","difficulty":"medium","question":"A data engineer drops `my_table` and observes that both data files and metadata files are deleted from the filesystem. What explains the complete deletion?","choices":{"A":"The VACUUM command was automatically triggered after the DROP","B":"The table was stored in a temporary storage location","C":"The table had a retention policy set to zero days","D":"The table was a managed table"},"answer":"D","short":"The table was a managed table.","explanation":"When a managed (internal) table is dropped, Databricks deletes both the metastore entry and the underlying data files, because Databricks controls the full lifecycle of managed table data. This is the opposite behavior from external tables. In Unity Catalog, a dropped managed table can be recovered with `UNDROP TABLE` for 7 days by default, and the data files are deleted after that recovery period.","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"07-governance-and-security-q005","bank":"praticas","n":133,"domain":"governance-and-security","title":"Table Ownership Transfer","difficulty":"medium","question":"A data engineer has left the organization and no longer has access. The team must transfer ownership of the engineer's Unity Catalog tables to the new lead data engineer. Who can perform this transfer?","choices":{"A":"A metastore admin, or the owner of the tables' parent schema (or a user with MANAGE on the tables)","B":"Any user with SELECT privilege on the tables","C":"The new lead data engineer, by running `ALTER TABLE ... OWNER TO` on their own","D":"Any member of the data team with MODIFY privilege"},"answer":"A","short":"A metastore admin, or the owner of the tables' parent schema (or a user with MANAGE on the tables).","explanation":"In Unity Catalog, ownership can be transferred by the current owner, a metastore admin, the owner of the container (the schema for a table), or a user with the `MANAGE` privilege on the object. `SELECT` and `MODIFY` don't allow it. Use `ALTER TABLE ... OWNER TO <principal>` or the Owner field in Catalog Explorer ([Manage privileges](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/)).","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"07-governance-and-security-q006","bank":"praticas","n":134,"domain":"governance-and-security","title":"GRANT ALL PRIVILEGES on a Database","difficulty":"easy","question":"A new data engineering team needs full privileges on the `customers` database to manage the project effectively. Which command grants all permissions?","choices":{"A":"`GRANT FULL ACCESS ON DATABASE customers TO team;`","B":"`GRANT ALL PRIVILEGES ON DATABASE customers TO team;`","C":"`GRANT READ, WRITE, ADMIN ON DATABASE customers TO team;`","D":"`GRANT MANAGE ON DATABASE customers TO team;`"},"answer":"B","short":"`GRANT ALL PRIVILEGES ON DATABASE customers TO team;`","explanation":"`DATABASE` is a synonym for `SCHEMA`. `ALL PRIVILEGES` grants every applicable privilege on the schema and its objects. In Unity Catalog it does **not** include `MANAGE` (or `EXTERNAL USE SCHEMA` / `EXTERNAL USE LOCATION` / `READ METADATA`), so it isn't the same as ownership.","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"07-governance-and-security-q007","bank":"praticas","n":135,"domain":"governance-and-security","title":"Discovering Tables Without Reading Data","difficulty":"medium","question":"A newly formed data engineering team needs to discover which tables exist in the Unity Catalog catalog `customers` and view their metadata, without being able to read any data yet. Which grant fits best?","choices":{"A":"`GRANT SELECT ON CATALOG customers TO team;`","B":"`GRANT ALL PRIVILEGES ON CATALOG customers TO team;`","C":"`GRANT BROWSE ON CATALOG customers TO team;`","D":"`GRANT USAGE ON DATABASE customers TO team;`"},"answer":"C","short":"`GRANT BROWSE ON CATALOG customers TO team;`","explanation":"`BROWSE` lets users discover objects and view metadata without usage privileges, and Databricks recommends granting it on catalogs. `SELECT` and `ALL PRIVILEGES` would expose data. `USAGE` is a legacy Hive metastore privilege. In Unity Catalog the usage privileges are `USE CATALOG` / `USE SCHEMA`, and they don't grant data access on their own ([UC privileges reference](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)).","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"07-governance-and-security-q008","bank":"praticas","n":136,"domain":"governance-and-security","title":"Where to Check Table Permissions","difficulty":"easy","question":"A data engineer needs to use a Delta table but is unsure whether they have the necessary permissions. Where can they check their table permissions?","choices":{"A":"The Databricks Admin Console under User Management","B":"The SQL warehouse's access control list","C":"The cluster configuration page under Security settings","D":"Catalog Explorer"},"answer":"D","short":"Catalog Explorer.","explanation":"The Catalog Explorer in Databricks provides a dedicated \"Permissions\" tab for each table, listing which users and groups have access and what privilege levels are granted. It is the primary interface for inspecting and managing object-level permissions.","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"07-governance-and-security-q009","bank":"praticas","n":137,"domain":"governance-and-security","title":"Identifying a Table Owner","difficulty":"easy","question":"A data engineer requires access to `new_table` but does not know who owns it. What method can be used to identify the owner?","choices":{"A":"Review the Owner field in the table's page in Catalog Explorer","B":"Check the cluster logs for the user who last wrote to the table","C":"Query the `information_schema.tables` view for the table's creator","D":"Run `SHOW GRANT ON TABLE new_table` to list all privilege holders"},"answer":"A","short":"Review the Owner field in the table's page in Catalog Explorer.","explanation":"Catalog Explorer displays the table owner in the table details panel. Any user with workspace access can view this field without needing special permissions, making it the standard way to identify who to contact for permission requests.","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"07-governance-and-security-q010","bank":"praticas","n":138,"domain":"governance-and-security","title":"Undoing an External-to-Managed Conversion *(2026 blueprint)*","difficulty":"hard","question":"A data engineer converted an external table to a Unity Catalog managed table with `ALTER TABLE ... SET MANAGED`. Two days later, the team must undo it. What should they run?","choices":{"A":"`RESTORE TABLE ... TO VERSION AS OF` the version before the conversion","B":"`ALTER TABLE ... UNSET MANAGED`","C":"Drop the table and recreate it as external, because rollback isn't supported","D":"`ALTER TABLE ... SET EXTERNAL`"},"answer":"B","short":"`ALTER TABLE ... UNSET MANAGED`.","explanation":"Rollback is supported within **14 days** of conversion. `UNSET MANAGED` points the table metadata back to the original external location and preserves writes made after conversion. Streams must be restarted, and Databricks deletes the managed copy seven days after rollback. `RESTORE` restores data versions, not the table type ([Convert to managed tables](https://docs.databricks.com/aws/en/tables/convert-external-managed)).","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"07-governance-and-security-q011","bank":"praticas","n":139,"domain":"governance-and-security","title":"Converting an External Table to Managed *(2026 blueprint)*","difficulty":"medium","question":"Which command converts an existing Unity Catalog external Delta table to a managed table while keeping its name, permissions, and history?","choices":{"A":"`CREATE OR REPLACE TABLE t AS SELECT * FROM t`","B":"`CONVERT TO DELTA t`","C":"`ALTER TABLE t SET MANAGED` on Databricks Runtime 17.3 LTS+ or serverless","D":"`ALTER TABLE t SET LOCATION NULL`"},"answer":"C","short":"`ALTER TABLE t SET MANAGED` on Databricks Runtime 17.3 LTS+ or serverless.","explanation":"The conversion copies data and the transaction log to managed storage, then switches metadata, with only brief writer downtime. It keeps the name, settings, permissions, views, and history. You must own the table, and existing streams must be restarted afterwards ([Convert to managed tables](https://docs.databricks.com/aws/en/tables/convert-external-managed)).","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"07-governance-and-security-q012","bank":"praticas","n":140,"domain":"governance-and-security","title":"Recovering a Dropped Managed Table *(2026 blueprint)*","difficulty":"easy","question":"A Unity Catalog managed table was dropped by mistake yesterday. What can the team do?","choices":{"A":"Nothing, because managed-table data is deleted immediately","B":"Recreate it with `CREATE TABLE ... LOCATION` pointing at the old path","C":"Run `RESTORE TABLE` on the dropped name","D":"Run `UNDROP TABLE` within the recovery period (7 days by default)"},"answer":"D","short":"Run `UNDROP TABLE` within the recovery period (7 days by default).","explanation":"Dropped managed tables can be recovered with `UNDROP TABLE` for 7 days by default, and the data files are deleted when the recovery period expires. Dropping an external table removes only metadata, and its files stay in cloud storage ([UC managed tables](https://docs.databricks.com/aws/en/tables/managed)).","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"07-governance-and-security-q013","bank":"praticas","n":141,"domain":"governance-and-security","title":"DENY in Unity Catalog *(2026 blueprint)*","difficulty":"hard","question":"An admin runs `DENY SELECT ON TABLE prod.gold.revenue TO contractors` in a Unity Catalog catalog, and the statement fails. Which statement is correct?","choices":{"A":"The classic `DENY` statement applies only to the legacy `hive_metastore` catalog. In Unity Catalog, remove access by revoking (or not granting) `SELECT`, and use filters, masks, or ABAC for partial access","B":"The syntax is wrong. It should be `DENY SELECT TO contractors ON prod.gold.revenue`","C":"`DENY` works only on schemas, not tables","D":"`DENY` requires a metastore admin, and a workspace admin can't run it"},"answer":"A","short":"The classic `DENY` statement applies only to the legacy `hive_metastore` catalog. In Unity Catalog, remove access by revoking (or not granting) `SELECT`, and use filters, masks, or ABAC for partial access.","explanation":"The DENY reference states it \"is not supported by Unity Catalog\". Unity Catalog's deny mechanism is the ABAC DENY policy (Beta), which currently denies only `MANAGE ACCESS CONTROL` ([DENY](https://docs.databricks.com/aws/en/sql/language-manual/security-deny), [ABAC DENY policies](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/deny-policies)).","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"07-governance-and-security-q014","bank":"praticas","n":142,"domain":"governance-and-security","title":"Minimum Privileges for One Table *(2026 blueprint)*","difficulty":"medium","question":"The `auditors` group must query only `prod.finance.ledger`, not the other tables in `prod.finance`. Which grants are required?","choices":{"A":"`SELECT` on the table only","B":"`USE CATALOG` on `prod`, `USE SCHEMA` on `prod.finance`, and `SELECT` on `prod.finance.ledger`","C":"`SELECT` on schema `prod.finance`","D":"`ALL PRIVILEGES` on catalog `prod`"},"answer":"B","short":"`USE CATALOG` on `prod`, `USE SCHEMA` on `prod.finance`, and `SELECT` on `prod.finance.ledger`.","explanation":"The usage privileges are required to reach objects inside a catalog or schema, but they don't grant data access by themselves. A schema-level `SELECT` would be inherited by every current and future table in the schema, which is too broad here ([UC privileges](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)).","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"07-governance-and-security-q015","bank":"praticas","n":143,"domain":"governance-and-security","title":"Masking a Column by Group *(2026 blueprint)*","difficulty":"medium","question":"Only members of `finance_team` may see full values in `credit_card_number`. Everyone else should see a masked value, and everyone queries the same table. What should be implemented?","choices":{"A":"`DENY SELECT` on the column for everyone except `finance_team`","B":"A separate copy of the table per group","C":"A column mask function using `is_account_group_member('finance_team')`, attached with `ALTER TABLE ... ALTER COLUMN credit_card_number SET MASK`","D":"Cloud IAM permissions on the column"},"answer":"C","short":"A column mask function using `is_account_group_member('finance_team')`, attached with `ALTER TABLE ... ALTER COLUMN credit_card_number SET MASK`.","explanation":"A column mask is a SQL UDF that receives the value and returns either the original or a masked value, evaluated per query. Its return type must match the column type. Copies drift, and `DENY` isn't a Unity Catalog column-level mechanism ([row filters and column masks](https://docs.databricks.com/aws/en/tables/row-and-column-filters)).","lesson":"07-governance-and-security/04-row-filters-column-masks-abac","related":null},{"id":"07-governance-and-security-q016","bank":"praticas","n":144,"domain":"governance-and-security","title":"Row-Level Security *(2026 blueprint)*","difficulty":"medium","question":"Regional sales managers must see only the rows of `main.silver.orders` for their own region. Which implementation fits?","choices":{"A":"`REVOKE SELECT` from all managers","B":"A column mask on `region`","C":"Partition the table by region and grant `SELECT` per partition","D":"A row filter UDF returning `BOOLEAN` that checks group membership against `region`, attached with `ALTER TABLE main.silver.orders SET ROW FILTER fn ON (region)`"},"answer":"D","short":"A row filter UDF returning `BOOLEAN` that checks group membership against `region`, attached with `ALTER TABLE main.silver.orders SET ROW FILTER fn ON (region)`.","explanation":"Rows for which the row filter returns `FALSE` are excluded from results. Masks change column values, not row visibility, and Unity Catalog doesn't grant privileges per partition ([row filters and column masks](https://docs.databricks.com/aws/en/tables/row-and-column-filters)).","lesson":"07-governance-and-security/04-row-filters-column-masks-abac","related":null},{"id":"07-governance-and-security-q017","bank":"praticas","n":145,"domain":"governance-and-security","title":"Masking PII Across Many Tables *(2026 blueprint)*","difficulty":"hard","question":"A privacy team must mask every email column in all tables of the `main.silver` schema, including tables created later. Table owners must not be able to remove the masking. What should they use?","choices":{"A":"A Unity Catalog ABAC column mask policy on the schema, matching columns tagged with a governed tag such as `pii = email`","B":"A column mask set separately on each table by its owner","C":"A dynamic view per table","D":"An ABAC DENY policy on `SELECT`"},"answer":"A","short":"A Unity Catalog ABAC column mask policy on the schema, matching columns tagged with a governed tag such as `pii = email`.","explanation":"ABAC policies (`CREATE POLICY ... COLUMN MASK ... FOR TABLES MATCH COLUMNS has_tag_value('pii','email')`) attach at catalog, schema, or table level and apply automatically to objects with matching governed tags. Because higher-level admins define them, table owners can't override or remove them. DENY policies currently deny only `MANAGE ACCESS CONTROL` ([ABAC](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/), [ABAC policies](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/policies)).","lesson":"07-governance-and-security/04-row-filters-column-masks-abac","related":null},{"id":"data-engineer-associate-mock-1-q001","bank":"simulado-1","n":1,"domain":"databricks-intelligence-platform","title":"A data engineering team is evaluating whether to migrate their existing data warehouse…","difficulty":"medium","question":"A data engineering team is evaluating whether to migrate their existing data warehouse to a Databricks Lakehouse. The primary concern is maintaining ACID guarantees for concurrent reads and writes on large tables. Which Databricks technology directly addresses this requirement?","choices":{"A":"Apache Parquet file format with schema enforcement","B":"Unity Catalog with row-level security","C":"Databricks SQL Serverless warehouses","D":"Delta Lake with transaction log (`_delta_log`)"},"answer":"D","short":"Delta Lake provides ACID transactions through its transaction log (`_delta_log`), which records every operation as an atomic commit. This enables concurrent readers and writers without data corruption. Parquet alone has no transaction support, Serverless warehouses are a compute option, and Unity Catalog handles governance — not storage-level ACID.","explanation":"","lesson":"01-databricks-intelligence-platform/04-delta-lake-fundamentals","related":null},{"id":"data-engineer-associate-mock-1-q002","bank":"simulado-1","n":2,"domain":"databricks-intelligence-platform","title":"An engineer is setting up a new Databricks workspace and needs to run interactive…","difficulty":"medium","question":"An engineer is setting up a new Databricks workspace and needs to run interactive notebooks for development while also running scheduled production jobs. Which cluster type should they use for each workload?","choices":{"A":"All-purpose clusters for both — they are more flexible","B":"Job clusters for both — they are cheaper and auto-terminate","C":"All-purpose clusters for interactive notebooks; job clusters for scheduled production jobs","D":"SQL warehouses for notebooks; job clusters for scheduled jobs"},"answer":"C","short":"All-purpose clusters support interactive, multi-user notebook sessions and persist between runs. Job clusters are created specifically for a single job run and terminate automatically upon completion, making them more cost-effective for production pipelines. SQL warehouses are optimized for SQL queries, not general notebook workloads.","explanation":"","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"data-engineer-associate-mock-1-q003","bank":"simulado-1","n":3,"domain":"databricks-intelligence-platform","title":"A data engineer needs to query data as it existed 7 days ago from a Delta table named…","difficulty":"medium","question":"A data engineer needs to query data as it existed 7 days ago from a Delta table named `transactions`. Which command correctly retrieves this historical snapshot?","choices":{"A":"`SELECT * FROM transactions WHERE _commit_timestamp >= date_sub(current_date(), 7)`","B":"`SELECT * FROM transactions VERSION AS OF 7`","C":"`SELECT * FROM transactions TIMESTAMP AS OF date_sub(current_date(), 7)`","D":"`RESTORE TABLE transactions TO TIMESTAMP AS OF date_sub(current_date(), 7)`"},"answer":"C","short":"Delta Lake time travel using `TIMESTAMP AS OF` queries the table state at a specific point in time. `VERSION AS OF 7` queries version number 7 (the 8th commit), not 7 days ago. `RESTORE TABLE` permanently restores the table to a previous state rather than just reading it. `_commit_timestamp` is not a valid time travel filter syntax.","explanation":"","lesson":"01-databricks-intelligence-platform/05-time-travel-versioning","related":null},{"id":"data-engineer-associate-mock-1-q004","bank":"simulado-1","n":4,"domain":"data-ingestion-and-loading","title":"A SQL analyst runs this statement every morning: On Tuesday a vendor re-uploads…","difficulty":"medium","question":"A SQL analyst runs this statement every morning:\n\n```sql\nCOPY INTO main.bronze.orders\nFROM '/Volumes/main/raw/landing/orders'\nFILEFORMAT = CSV\nFORMAT_OPTIONS ('header' = 'true');\n```\n\nOn Tuesday a vendor re-uploads Monday's file, `orders_0901.csv`, with corrected values under the same name. Tuesday's run loads 0 rows. What explains this, and how can the analyst load the corrected file?","choices":{"A":"`COPY INTO` is idempotent and skips files it has already loaded, even if they were modified. Re-run it with `FILES = ('orders_0901.csv')` and `COPY_OPTIONS ('force' = 'true')`","B":"`COPY INTO` only reads files written after the table's latest commit. Run `OPTIMIZE` on the table first","C":"The corrected file failed schema validation. Add `VALIDATE ALL` to load it","D":"`COPY INTO` needs a checkpoint location to track files. Add one with `COPY_OPTIONS`"},"answer":"A","short":"`COPY INTO` is retriable and idempotent: files in the source location that were already loaded are skipped on later runs, even if they changed after loading.","explanation":"Setting `'force' = 'true'` turns idempotency off and reloads files whether or not they were loaded before. Listing just that file with `FILES` keeps the reload from duplicating every other file. `VALIDATE` only checks data without loading it, so it can't load anything. A checkpoint location belongs to Auto Loader and Structured Streaming, not `COPY INTO`, which tracks loaded files internally.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"data-engineer-associate-mock-1-q005","bank":"simulado-1","n":5,"domain":"data-ingestion-and-loading","title":"A data engineer configures Auto Loader to ingest CSV files from an S3 bucket. The…","difficulty":"medium","question":"A data engineer configures Auto Loader to ingest CSV files from an S3 bucket. The pipeline runs every hour. What happens if 5 new files arrive between runs?","choices":{"A":"Auto Loader automatically detects and processes all 5 new files in the next trigger","B":"Only the first file is processed; subsequent files are queued for the next run","C":"Auto Loader processes files only when triggered manually","D":"Auto Loader fails if more than 1 file arrives between runs"},"answer":"A","short":"Auto Loader uses cloud storage notifications or directory listing combined with a checkpoint to track which files have been processed. On the next trigger, it automatically detects all new, unprocessed files and ingests them. This checkpointing mechanism ensures exactly-once processing without manual intervention or file tracking.","explanation":"","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"data-engineer-associate-mock-1-q006","bank":"simulado-1","n":6,"domain":"data-ingestion-and-loading","title":"A team must ingest Salesforce objects into Unity Catalog tables incrementally, with as…","difficulty":"easy","question":"A team must ingest Salesforce objects into Unity Catalog tables incrementally, with as little custom code as possible. Which option does Databricks recommend?","choices":{"A":"A notebook that calls the Salesforce REST API, scheduled with Lakeflow Jobs","B":"Auto Loader pointed at the Salesforce instance URL","C":"A Lakeflow Connect managed connector, which creates an ingestion pipeline that writes streaming tables","D":"A Lakehouse Federation foreign catalog, queried by every downstream job"},"answer":"C","short":"SaaS applications such as Salesforce map to a Lakeflow Connect **managed connector**: no code, incremental, serverless, and governed by Unity Catalog.","explanation":"Databricks recommends starting with the most managed layer and moving down only when it can't meet the requirement. A hand-written REST notebook is the fallback for sources without a connector. Auto Loader reads files in cloud storage, not a SaaS API. Federation queries a source in place without ingesting it, and the requirement here is to land the data in Unity Catalog tables.","lesson":"02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect","related":null},{"id":"data-engineer-associate-mock-1-q007","bank":"simulado-1","n":7,"domain":"data-ingestion-and-loading","title":"A streaming job reads from a Kafka topic and writes to a Delta table. The engineer…","difficulty":"medium","question":"A streaming job reads from a Kafka topic and writes to a Delta table. The engineer wants the job to process all currently available data and then stop automatically. Which trigger type should they configure?","choices":{"A":"`trigger(processingTime=\"0 seconds\")` for continuous mode","B":"`trigger(availableNow=True)` to process all available data then stop","C":"`trigger(continuous=\"10 seconds\")` for low-latency micro-batch processing","D":"No trigger configuration — streaming jobs stop automatically when the source is empty"},"answer":"B","short":"`trigger(availableNow=True)` (Spark 3.3+) or `trigger(once=True)` processes all currently available data in the stream source and then terminates the query. This is ideal for scheduled batch-style streaming jobs. `processingTime=\"0 seconds\"` runs as fast as possible but never stops. Streaming jobs do not stop automatically without explicit trigger configuration.","explanation":"","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"data-engineer-associate-mock-1-q008","bank":"simulado-1","n":8,"domain":"data-ingestion-and-loading","title":"A notebook reads a 200-million-row PostgreSQL table with spark.read.format(\"jdbc\"),…","difficulty":"medium","question":"A notebook reads a 200-million-row PostgreSQL table with `spark.read.format(\"jdbc\")`, setting only `url`, `dbtable`, `user`, and `password`. The Spark UI shows the read running as a single task while the other cores sit idle. Which change parallelizes the read?","choices":{"A":"Raise `fetchSize` to 1,000,000 rows","B":"Call `.repartition(64)` right after `.load()`","C":"Switch from `spark.read` to `spark.readStream`","D":"Set `partitionColumn` (an indexed numeric column), `lowerBound`, `upperBound`, and `numPartitions`"},"answer":"D","short":"A JDBC read uses one thread by default. `partitionColumn`, `lowerBound`, `upperBound`, and `numPartitions` split the key range into parallel queries against the database.","explanation":"`fetchSize` only sets how many rows come back per network round trip, and a very large value can cause out-of-memory errors. `repartition` runs after the single-threaded read has finished, so the read itself stays serial. The JDBC source isn't a streaming source, so `readStream` doesn't help.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"data-engineer-associate-mock-1-q009","bank":"simulado-1","n":9,"domain":"data-ingestion-and-loading","title":"A data engineer notices that a Delta streaming job fails with StreamingQueryException:…","difficulty":"hard","question":"A data engineer notices that a Delta streaming job fails with `StreamingQueryException: Detected a data update in the source table`. What caused this error?","choices":{"A":"The source Delta table had `OPTIMIZE` run on it while the stream was reading","B":"The source Delta table had rows `UPDATE`d or `DELETE`d, which is not supported by default streaming reads","C":"The streaming job ran out of memory due to large state size","D":"The checkpoint directory was deleted, causing the stream to restart"},"answer":"B","short":"By default, Delta streaming reads assume an append-only source. If the source table has `UPDATE`, `DELETE`, or `MERGE` operations on existing rows, the stream throws this exception. To handle such sources, use `.option(\"skipChangeCommits\", \"true\")` (recommended on DBR 12.2 LTS+; it replaces the legacy `ignoreChanges`), or switch to Change Data Feed for CDC-aware streaming.","explanation":"","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"data-engineer-associate-mock-1-q010","bank":"simulado-1","n":10,"domain":"data-ingestion-and-loading","title":"An Auto Loader stream feeds a Bronze table whose schema downstream teams rely on, so…","difficulty":"medium","question":"An Auto Loader stream feeds a Bronze table whose schema downstream teams rely on, so it must not change. The vendor sometimes adds new JSON fields. The stream must keep running when that happens, and the unexpected values must not be lost. Which `cloudFiles.schemaEvolutionMode` fits?","choices":{"A":"`addNewColumns`","B":"`failOnNewColumns`","C":"`none`, with no rescued data column configured","D":"`rescue`"},"answer":"D","short":"In `rescue` mode the schema never evolves and the stream doesn't fail. Values for unknown columns go into the `_rescued_data` column, so nothing is lost.","explanation":"`addNewColumns` changes the schema, and it stops the stream with `UnknownFieldException` before picking up the new column on restart. `failOnNewColumns` stops the stream and keeps it failed until someone updates the schema. `none` ignores new columns, and without a rescued data column their values are dropped.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"data-engineer-associate-mock-1-q011","bank":"simulado-1","n":11,"domain":"data-ingestion-and-loading","title":"A business user sends a data engineer a 40 MB CSV file. The engineer wants it in Unity…","difficulty":"easy","question":"A business user sends a data engineer a 40 MB CSV file. The engineer wants it in Unity Catalog quickly, with no code, as a governed file that other teams can later load with `read_files` or `COPY INTO`. Which path fits?","choices":{"A":"**New → Add or upload data → Upload files to a volume**, which needs `WRITE VOLUME` on the target volume","B":"Mount a cloud storage bucket to DBFS and copy the file there","C":"Configure a Lakeflow Connect managed connector for the file","D":"Publish the file to a Kafka topic and read it with Structured Streaming"},"answer":"A","short":"The **Add or upload data** UI can upload local files into a Unity Catalog volume (`/Volumes/<catalog>/<schema>/<volume>/...`). It needs `WRITE VOLUME` on the volume and `USE CATALOG` and `USE SCHEMA` on its parents, and UI uploads accept up to 5 GB per file. Once the file is in a volume, `read_files`, `COPY INTO`, or Auto Loader can load it.","explanation":"DBFS mounts are deprecated in favor of Unity Catalog volumes and external locations. Managed connectors are for SaaS applications and databases. A Kafka topic is a streaming source for events, not a way to land one file.","lesson":"02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect","related":null},{"id":"data-engineer-associate-mock-1-q012","bank":"simulado-1","n":12,"domain":"data-ingestion-and-loading","title":"A Bronze table has a STRING column named raw that holds JSON documents such as…","difficulty":"medium","question":"A Bronze table has a `STRING` column named `raw` that holds JSON documents such as `{\"customer\": {\"id\": 42}, \"line_items\": [{\"sku\": \"A1\"}, {\"sku\": \"B7\"}]}`. Which Databricks SQL expression returns the first item's SKU (`A1`)?","choices":{"A":"`raw:line_items[0].sku`","B":"`raw.line_items[0].sku`","C":"`raw:line_items[1].sku`","D":"`explode(raw.line_items)`"},"answer":"A","short":"When a column holds JSON **strings**, Databricks SQL extracts fields with the `:` path syntax, and array indexes are 0-based, so `raw:line_items[0].sku` returns `A1`.","explanation":"Dot notation works on `STRUCT` columns, not on a plain string. Index `[1]` returns the second element (`B7`). `explode` turns an array into rows and can't run on a string field reference like this. For new tables, Databricks recommends the `VARIANT` type over JSON strings.","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":"03-data-transformation-and-modeling/04-advanced-transformations"},{"id":"data-engineer-associate-mock-1-q013","bank":"simulado-1","n":13,"domain":"data-transformation-and-modeling","title":"A data engineer runs the following SQL command. What is the result?","difficulty":"easy","question":"A data engineer runs the following SQL command. What is the result?\n\n```sql\nCREATE OR REPLACE TABLE sales_summary AS\nSELECT region, SUM(amount) AS total_sales\nFROM transactions\nGROUP BY region;\n```","choices":{"A":"Creates a new table only if it does not already exist","B":"Creates a temporary view of the aggregated results","C":"Appends aggregated results to the existing table","D":"Creates a new table or replaces the entire table if it already exists"},"answer":"D","short":"`CREATE OR REPLACE TABLE ... AS SELECT` (CRAS) creates a new table with the query results. If a table with that name already exists, it is completely replaced (dropped and recreated). Use `CREATE TABLE IF NOT EXISTS` to skip creation when the table exists, or `INSERT INTO` to append rows.","explanation":"","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"data-engineer-associate-mock-1-q014","bank":"simulado-1","n":14,"domain":"data-transformation-and-modeling","title":"A Databricks SQL query must return all rows from the orders table and only the…","difficulty":"easy","question":"A Databricks SQL query must return all rows from the `orders` table and only the matching rows from the `customers` table. Which JOIN type accomplishes this?","choices":{"A":"INNER JOIN","B":"RIGHT JOIN","C":"LEFT JOIN","D":"CROSS JOIN"},"answer":"C","short":"A LEFT JOIN returns all rows from the left table (`orders`) and matched rows from the right table (`customers`). Unmatched rows from `customers` appear as NULL. INNER JOIN returns only matched rows from both tables. RIGHT JOIN returns all rows from `customers` and matched rows from `orders` — the inverse of what is needed.","explanation":"","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"data-engineer-associate-mock-1-q015","bank":"simulado-1","n":15,"domain":"data-transformation-and-modeling","title":"A data engineer needs to find the top 3 highest-selling products within each product…","difficulty":"medium","question":"A data engineer needs to find the top 3 highest-selling products within each product category. Which SQL feature is most appropriate?","choices":{"A":"GROUP BY with HAVING clause","B":"Correlated subquery with LIMIT","C":"Window function with `RANK() OVER (PARTITION BY category ORDER BY sales DESC)`","D":"PIVOT table with category as columns"},"answer":"C","short":"Window functions with `RANK()` or `ROW_NUMBER()` partitioned by category and ordered by sales descending assign a rank to each product within its category. Filtering `WHERE rank <= 3` returns the top 3 per category. `GROUP BY` with `HAVING` can't retrieve individual rows within groups. Subqueries with `LIMIT` don't partition by category.","explanation":"","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"data-engineer-associate-mock-1-q016","bank":"simulado-1","n":16,"domain":"data-transformation-and-modeling","title":"A data engineer needs to apply a custom Python function to a column in a large Spark…","difficulty":"medium","question":"A data engineer needs to apply a custom Python function to a column in a large Spark DataFrame. The function uses a third-party library not available as a built-in Spark function. What is the recommended approach?","choices":{"A":"Use `df.apply()` to apply the function row by row","B":"Register the function as a Spark UDF with `spark.udf.register()` or `udf()`","C":"Export the DataFrame to Pandas, apply the function, then convert back","D":"Use `df.withColumn()` with a Python lambda directly without registration"},"answer":"B","short":"Spark UDFs (User-Defined Functions) allow custom Python logic to be applied to DataFrame columns in a distributed manner. They must be registered before use. Exporting to Pandas loses distributed processing and will fail on large datasets. `withColumn()` with a lambda doesn't work — Spark columns require Spark expressions or registered UDFs.","explanation":"","lesson":"03-data-transformation-and-modeling/02-dataframe-operations","related":null},{"id":"data-engineer-associate-mock-1-q017","bank":"simulado-1","n":17,"domain":"data-transformation-and-modeling","title":"A data engineer uses explode() on a column containing arrays. What does this function do?","difficulty":"easy","question":"A data engineer uses `explode()` on a column containing arrays. What does this function do?","choices":{"A":"Converts an array column into multiple rows, one row per array element","B":"Removes all NULL values from array columns","C":"Flattens nested structs into separate columns","D":"Converts an array column into a string by joining elements"},"answer":"A","short":"`explode()` takes an array (or map) column and generates one new row per element, duplicating all other column values. This is the standard way to \"unnest\" array data in Spark. `flatten()` flattens nested arrays. Struct flattening uses `col(\"field.*\")`. `array_join()` converts an array to a string.","explanation":"","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"data-engineer-associate-mock-1-q018","bank":"simulado-1","n":18,"domain":"data-transformation-and-modeling","title":"A data engineer needs to combine two DataFrames that have the same schema, keeping all…","difficulty":"easy","question":"A data engineer needs to combine two DataFrames that have the same schema, keeping all rows from both including duplicates. Which operation should they use?","choices":{"A":"`df1.join(df2, how=\"full\")`","B":"`df1.union(df2)`","C":"`df1.intersect(df2)`","D":"`df1.merge(df2)`"},"answer":"B","short":"`union()` appends all rows from `df2` to `df1`, preserving duplicates. It requires both DataFrames to have the same schema (same column count and order). `join()` combines rows based on a key condition. `intersect()` returns only rows present in both DataFrames. Spark DataFrames don't have a `merge()` method.","explanation":"","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"data-engineer-associate-mock-1-q019","bank":"simulado-1","n":19,"domain":"data-transformation-and-modeling","title":"A data engineer needs to pivot sales data so that each product category becomes a…","difficulty":"easy","question":"A data engineer needs to pivot sales data so that each product category becomes a separate column showing total sales. Which SQL keyword accomplishes this?","choices":{"A":"UNPIVOT","B":"CROSSTAB","C":"PIVOT","D":"TRANSPOSE"},"answer":"C","short":"`PIVOT` in Databricks SQL rotates rows into columns. You specify the pivot column (categories) and the aggregation (SUM of sales). `UNPIVOT` does the reverse — converts columns to rows. `CROSSTAB` is not a standard SQL keyword in Databricks. `TRANSPOSE` is not a SQL operation.","explanation":"","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"data-engineer-associate-mock-1-q020","bank":"simulado-1","n":20,"domain":"data-transformation-and-modeling","title":"A data engineer needs to upsert records into a Delta table: update existing customer…","difficulty":"medium","question":"A data engineer needs to upsert records into a Delta table: update existing customer records when `customer_id` matches, and insert new records when there is no match. Which clause correctly completes the MERGE statement?\n\n```sql\nMERGE INTO customers AS target\nUSING updates AS source\nON target.customer_id = source.customer_id\nWHEN MATCHED THEN\n  UPDATE SET target.name = source.name, target.email = source.email\nWHEN NOT MATCHED THEN\n  ___________\n```","choices":{"A":"`INSERT VALUES (source.customer_id, source.name, source.email)`","B":"`INSERT INTO customers SELECT * FROM source`","C":"`INSERT (customer_id, name, email) VALUES (source.customer_id, source.name, source.email)`","D":"`INSERT * FROM source`"},"answer":"C","short":"The correct MERGE `WHEN NOT MATCHED` syntax is `INSERT (column_list) VALUES (source.column_list)`. The column list explicitly names the target columns, and the VALUES clause provides the source values. Option A is missing the column list. Options B and D are not valid MERGE syntax.","explanation":"","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"data-engineer-associate-mock-1-q021","bank":"simulado-1","n":21,"domain":"data-transformation-and-modeling","title":"A data engineer uses the medallion architecture. Which layer is responsible for…","difficulty":"easy","question":"A data engineer uses the medallion architecture. Which layer is responsible for enforcing data quality rules, deduplication, and applying business logic transformations?","choices":{"A":"Bronze layer — stores raw, unmodified ingested data","B":"Silver layer — stores cleaned, filtered, and enriched data with quality checks applied","C":"Gold layer — stores aggregate KPIs and metrics for reporting","D":"The medallion architecture has no dedicated quality enforcement layer"},"answer":"B","short":"The Silver layer is where data quality enforcement, deduplication, schema normalization, and business logic transformations occur. Bronze stores raw data as-is for auditability and reprocessing. Gold stores aggregated, business-ready data optimized for analytics and BI reporting.","explanation":"","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"data-engineer-associate-mock-1-q022","bank":"simulado-1","n":22,"domain":"data-transformation-and-modeling","title":"A DLT pipeline has an EXPECT constraint: EXPECT (amount > 0) ON VIOLATION DROP ROW. A…","difficulty":"medium","question":"A DLT pipeline has an `EXPECT` constraint: `EXPECT (amount > 0) ON VIOLATION DROP ROW`. A batch of 1,000 records arrives and 50 have `amount <= 0`. What happens?","choices":{"A":"The entire batch fails and no records are written","B":"All 1,000 records are written, and the 50 violating records are flagged in the event log","C":"The 50 violating records are dropped and 950 valid records are written to the table","D":"The pipeline pauses and waits for manual intervention to resolve the violations"},"answer":"C","short":"`ON VIOLATION DROP ROW` instructs DLT to discard rows that fail the expectation and continue processing valid rows. Violation counts are tracked in the DLT event log. `ON VIOLATION FAIL UPDATE` would fail the pipeline on any violation. `ON VIOLATION WARN` (the default with no modifier) writes all rows but logs violations without dropping any.","explanation":"","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"data-engineer-associate-mock-1-q023","bank":"simulado-1","n":23,"domain":"working-with-lakeflow-jobs","title":"A data engineer needs to run a notebook that performs interactive EDA (exploratory…","difficulty":"medium","question":"A data engineer needs to run a notebook that performs interactive EDA (exploratory data analysis) with visualizations, then automatically hand off to a scheduled production pipeline. Which Databricks features best match these two phases respectively?","choices":{"A":"All-purpose cluster for EDA; DLT pipeline for production","B":"Job cluster for EDA; all-purpose cluster for production","C":"SQL warehouse for EDA; serverless compute for production","D":"All-purpose cluster for EDA; job cluster with Lakeflow Jobs for production"},"answer":"D","short":"All-purpose clusters support interactive notebook sessions ideal for EDA with visualizations and iterative development. Lakeflow Jobs with job clusters provide automated, scheduled, cost-efficient execution for production pipelines. Job clusters terminate after the job completes, reducing cost. SQL warehouses are optimized for SQL queries, not general notebook EDA.","explanation":"","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":"01-databricks-intelligence-platform/03-compute-clusters"},{"id":"data-engineer-associate-mock-1-q024","bank":"simulado-1","n":24,"domain":"working-with-lakeflow-jobs","title":"A partner drops files into a Unity Catalog volume at unpredictable times, from zero to…","difficulty":"medium","question":"A partner drops files into a Unity Catalog volume at unpredictable times, from zero to several drops a day. The team wants each drop processed within minutes and doesn't want runs that find no new data. Which Lakeflow Jobs trigger fits best?","choices":{"A":"A scheduled trigger that runs every 5 minutes","B":"A continuous trigger","C":"A file arrival trigger on the volume, with Auto Loader in the job to process only the new files","D":"A table update trigger on the Bronze table that the job writes to"},"answer":"C","short":"A file arrival trigger monitors a Unity Catalog external location or volume and starts a run when new files land. It checks for new files about every minute, on a best-effort basis. Inside the job, Auto Loader processes exactly the new files.","explanation":"A 5-minute schedule starts many runs that find no data. A continuous trigger keeps a run active all the time. A table update trigger fires when a monitored table changes, but here the Bronze table is the job's own output, so it can't tell the job that new files have arrived.","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"data-engineer-associate-mock-1-q025","bank":"simulado-1","n":25,"domain":"working-with-lakeflow-jobs","title":"A data engineer is designing a Lakeflow Job with three tasks: ingest → transform →…","difficulty":"medium","question":"A data engineer is designing a Lakeflow Job with three tasks: `ingest → transform → report`. The `report` task must only run if `transform` succeeds. How should task dependencies be configured?","choices":{"A":"Use a single-task job with all logic in one notebook to avoid dependency issues","B":"Set `transform` and `report` to run in parallel to reduce total execution time","C":"Use separate jobs for each task and chain them with external orchestration","D":"Configure `transform` as a dependency of `report` using the `depends_on` task setting"},"answer":"D","short":"Lakeflow Jobs supports multi-task jobs with explicit task dependencies via `depends_on`. When `transform` fails, downstream tasks (`report`) don't run and are marked `Upstream failed` (default Run if: *All succeeded*). Running tasks in parallel would not enforce the required sequential dependency. Separate jobs with external orchestration adds unnecessary complexity.","explanation":"","lesson":"04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks","related":null},{"id":"data-engineer-associate-mock-1-q026","bank":"simulado-1","n":26,"domain":"working-with-lakeflow-jobs","title":"A Lakeflow Job must run the same load_table notebook for 40 source tables, passing a…","difficulty":"medium","question":"A Lakeflow Job must run the same `load_table` notebook for 40 source tables, passing a different table name each time, with up to 5 loads running at once. What is the documented way to build this?","choices":{"A":"Add 40 notebook tasks, one per table, each with a hard-coded table name","B":"Add an If/else condition task that checks the table name","C":"Add a Run Job task that triggers the job again for each table","D":"Add a For each task over a JSON array of table names, with the notebook as its nested task and concurrency set to 5"},"answer":"D","short":"The **For each** task runs one nested task once per element of an input array. Each iteration reads its value with `{{input}}` (or `{{input.<key>}}` for objects), and **concurrency** sets how many iterations run in parallel. It defaults to 1.","explanation":"Forty copied tasks work, but every change has to be repeated 40 times. If/else branches on a condition. It doesn't loop. A Run Job task triggers another job as a step, which isn't a loop over inputs.","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"data-engineer-associate-mock-1-q027","bank":"simulado-1","n":27,"domain":"working-with-lakeflow-jobs","title":"A production job fails intermittently due to transient cloud API errors. What built-in…","difficulty":"medium","question":"A production job fails intermittently due to transient cloud API errors. What built-in Lakeflow Jobs feature can automatically retry failed tasks without manual intervention?","choices":{"A":"Task timeout configuration — the task retries when it exceeds the timeout","B":"Per-task retry policy with configurable maximum retries and retry interval","C":"Workflow-level SLA notifications that page the on-call engineer","D":"Databricks auto-recovers all failed tasks by default with no configuration needed"},"answer":"B","short":"Lakeflow Jobs allows configuring a retry policy per task, specifying the maximum number of retry attempts and the interval between retries. This handles transient failures automatically. Timeout configuration controls how long a task runs before being killed, not whether it retries. Auto-recovery is not enabled by default.","explanation":"","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"data-engineer-associate-mock-1-q028","bank":"simulado-1","n":28,"domain":"working-with-lakeflow-jobs","title":"The last task of a job, cleanup, drops staging tables. It depends on the transform…","difficulty":"medium","question":"The last task of a job, `cleanup`, drops staging tables. It depends on the `transform` task and uses the default dependency settings. Whenever `transform` fails, `cleanup` is skipped and marked `Upstream failed`. Which setting makes `cleanup` run whatever happens upstream?","choices":{"A":"Set `cleanup`'s **Run if** condition to **All done**","B":"Add a retry policy to `transform`","C":"Set `cleanup`'s **Run if** condition to **At least one succeeded**","D":"Raise the timeout on `cleanup`"},"answer":"A","short":"**All done** runs a task once all its dependencies have finished, whatever their outcome, which is the documented choice for cleanup tasks. The default, **All succeeded**, marks the task `Upstream failed` when a dependency fails.","explanation":"**At least one succeeded** still skips `cleanup` here, because its only dependency failed. Retries make `transform` more likely to succeed, but `cleanup` is still skipped if every attempt fails. A timeout limits how long a task runs. It doesn't decide whether the task starts.","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"data-engineer-associate-mock-1-q029","bank":"simulado-1","n":29,"domain":"working-with-lakeflow-jobs","title":"A data engineer configures a Lakeflow Job with a schedule of 0 0 8 ? (Quartz cron…","difficulty":"medium","question":"A data engineer configures a Lakeflow Job with a schedule of `0 0 8 * * ?` (Quartz cron format). When does this job run?","choices":{"A":"Every 8 minutes","B":"Every hour at minute 8","C":"At 8:00 AM every day","D":"At 8:00 AM on the 8th of every month"},"answer":"C","short":"In Quartz cron format, fields are: second minute hour day-of-month month day-of-week. So `0 0 8 * * ?` means second=0, minute=0, hour=8, every day, every month. This fires at exactly 8:00:00 AM daily. `0 8 * * * ?` would run every hour at minute 8. `0 0 0 8 * ?` would run at midnight on the 8th of each month.","explanation":"","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"data-engineer-associate-mock-1-q030","bank":"simulado-1","n":30,"domain":"implementing-cicd","title":"An engineer deploys a bundle with databricks bundle deploy -t dev. The dev target sets…","difficulty":"easy","question":"An engineer deploys a bundle with `databricks bundle deploy -t dev`. The `dev` target sets `mode: development`. The deployed job has a daily schedule in its YAML, but the schedule never fires. Why?","choices":{"A":"Development mode pauses schedules and triggers on deployed resources","B":"Bundles can't deploy job schedules. Schedules must be added in the Jobs UI","C":"Scheduled jobs deployed from a bundle must run as a service principal","D":"The schedule fires only after the bundle is also deployed to the `prod` target"},"answer":"A","short":"`mode: development` pauses schedules and triggers on the resources it deploys. It also prefixes their names with `[dev <user>]`, so personal copies don't run on their own or clash with shared ones.","explanation":"Run the job with `databricks bundle run`, or unpause it explicitly in dev. Bundles do deploy schedules (`schedule.quartz_cron_expression` in the job YAML), and in `mode: production` they stay active. A service principal is recommended for production deployments, but it isn't why a dev schedule is paused.","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"data-engineer-associate-mock-1-q031","bank":"simulado-1","n":31,"domain":"implementing-cicd","title":"An engineer has committed and pushed the branch feature/orders-dedup from a Databricks…","difficulty":"easy","question":"An engineer has committed and pushed the branch `feature/orders-dedup` from a Databricks Git folder. The team requires a review before any change is merged into `main`. Where is the pull request opened, reviewed, and merged?","choices":{"A":"In the Git folder, with **Merge** from the Git dialog's kebab menu","B":"In the notebook's revision history","C":"By running `databricks bundle deploy -t prod`","D":"In the Git provider's interface, such as GitHub, GitLab, or Azure DevOps"},"answer":"D","short":"Git folders handle branches, commits, pushes, and pulls in the workspace. The Databricks docs say to use your Git provider's interface to create a pull request and merge it into the default branch, where branch protection and reviews are enforced.","explanation":"Merging locally from the Git dialog skips the review the team requires. Notebook revision history has no branches or pull requests. Deploying a bundle releases code. It doesn't review or merge it.","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"data-engineer-associate-mock-1-q032","bank":"simulado-1","n":32,"domain":"implementing-cicd","title":"A bundle needs a source database password at deploy time. A reviewer finds the…","difficulty":"medium","question":"A bundle needs a source database password at deploy time. A reviewer finds the password set as the `default` of a variable in `databricks.yml`. What is the recommended fix?","choices":{"A":"Base64-encode the password before saving it as the default","B":"Move the password under `targets.prod.variables` so it only applies to production","C":"Store the password in a notebook widget's default value instead","D":"Remove the default, rotate the password, and have the CI runner export `BUNDLE_VAR_db_password` from its secret store"},"answer":"D","short":"Secrets never belong in bundle YAML or notebooks, because both are committed to Git. Declare the variable with no default and let CI supply it as the `BUNDLE_VAR_<name>` environment variable from its secret store, so the value never touches the repository. A password that was committed should also be rotated.","explanation":"Base64 is an encoding, not encryption. A target-level value and a widget default are both still in Git. At run time, notebooks can read credentials with `dbutils.secrets.get`.","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"data-engineer-associate-mock-1-q033","bank":"simulado-1","n":33,"domain":"implementing-cicd","title":"A team's GitHub Actions workflow should fail a pull request check when the bundle…","difficulty":"medium","question":"A team's GitHub Actions workflow should fail a pull request check when the bundle configuration is malformed, without deploying anything. Which command should the workflow run?","choices":{"A":"`databricks bundle validate`","B":"`databricks bundle summary`","C":"`databricks bundle destroy`","D":"`databricks bundle generate`"},"answer":"A","short":"`databricks bundle validate` checks that the bundle configuration files are syntactically correct, which makes it the standard first step of a CI pipeline before `deploy -t <target>`.","explanation":"`summary` lists the bundle's identity and already deployed resources. `destroy` deletes previously deployed jobs, pipelines, and artifacts. `generate` writes bundle YAML for a resource that already exists in the workspace.","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"data-engineer-associate-mock-1-q034","bank":"simulado-1","n":34,"domain":"implementing-cicd","title":"Two engineers work on the same feature branch, each in their own Git folder. Engineer…","difficulty":"medium","question":"Two engineers work on the same feature branch, each in their own Git folder. Engineer B has pushed new commits. Engineer A has no local changes and wants B's commits in their Git folder. Which Git folder operation should A use?","choices":{"A":"**Pull**","B":"**Reset**","C":"**Rebase**","D":"**Commit & Push**"},"answer":"A","short":"**Pull** updates the Git folder's notebooks and files to the remote version. It also clears notebook state, so cells need to be re-run.","explanation":"**Reset** is the equivalent of `git reset --hard` plus `git push --force`, and it discards both uncommitted and committed changes on the local and the remote branch. **Rebase** ends with a force push that rewrites history for collaborators. **Commit & Push** sends local changes to the remote, and there aren't any here.","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"data-engineer-associate-mock-1-q035","bank":"simulado-1","n":35,"domain":"troubleshooting-monitoring-and-optimization","title":"A data engineer writes a SQL query joining three large tables. The query is slow and…","difficulty":"hard","question":"A data engineer writes a SQL query joining three large tables. The query is slow and the Spark UI shows excessive shuffle volume. Which optimization should they apply first?","choices":{"A":"Increase the number of shuffle partitions with `spark.sql.shuffle.partitions`","B":"Use broadcast join hints for small dimension tables: `/*+ BROADCAST(dim) */`","C":"Convert all joins to CROSS JOINs for performance","D":"Add more worker nodes to the cluster"},"answer":"B","short":"If one or more tables are small enough to fit in memory (~200MB or less), a broadcast join eliminates the shuffle entirely by sending the small table to every executor. This is the most impactful optimization for join-heavy queries. Increasing shuffle partitions only changes partition count, not the total shuffle volume. Adding nodes doesn't eliminate the shuffle.","explanation":"","lesson":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables","related":"03-data-transformation-and-modeling/03-joins-aggregations"},{"id":"data-engineer-associate-mock-1-q036","bank":"simulado-1","n":36,"domain":"troubleshooting-monitoring-and-optimization","title":"A Delta table has accumulated many small Parquet files over several months of…","difficulty":"easy","question":"A Delta table has accumulated many small Parquet files over several months of streaming ingestion. A data engineer runs `OPTIMIZE` on the table. What is the primary effect?","choices":{"A":"Rewrites small Parquet files into larger, more efficient files to improve read performance","B":"Deletes files marked for deletion by previous VACUUM operations","C":"Recalculates column statistics and updates the transaction log","D":"Converts the table from Parquet format to a different columnar format"},"answer":"A","short":"`OPTIMIZE` compacts small files into larger files (typically targeting 1GB) to reduce the overhead of reading many small files and improve scan efficiency. It does not delete files — `VACUUM` handles that. Statistics updates are a secondary benefit. Delta Lake always uses Parquet as its underlying storage format.","explanation":"","lesson":"06-troubleshooting-monitoring-and-optimization/03-delta-optimization","related":null},{"id":"data-engineer-associate-mock-1-q037","bank":"simulado-1","n":37,"domain":"troubleshooting-monitoring-and-optimization","title":"A data engineer runs VACUUM transactions RETAIN 168 HOURS. What is the effect on time…","difficulty":"medium","question":"A data engineer runs `VACUUM transactions RETAIN 168 HOURS`. What is the effect on time travel capabilities?","choices":{"A":"No effect — VACUUM only removes duplicated data, not historical versions","B":"Historical data files older than 168 hours (7 days) are permanently deleted and time travel to those versions is no longer possible","C":"Delta Lake automatically creates a backup before running VACUUM","D":"VACUUM retains exactly 168 versions of the table, not based on time"},"answer":"B","short":"`VACUUM` removes data files no longer referenced by the transaction log that are older than the retention period. Once vacuumed, time travel queries to those older versions fail because the underlying Parquet files are deleted. The default retention is 7 days (168 hours). Delta Lake does not automatically create backups before VACUUM.","explanation":"","lesson":"06-troubleshooting-monitoring-and-optimization/03-delta-optimization","related":null},{"id":"data-engineer-associate-mock-1-q038","bank":"simulado-1","n":38,"domain":"troubleshooting-monitoring-and-optimization","title":"A data engineer wants to Z-ORDER a Delta table by the customer_id column to improve…","difficulty":"medium","question":"A data engineer wants to Z-ORDER a Delta table by the `customer_id` column to improve query performance. When does Z-ORDER provide the most benefit?","choices":{"A":"When queries always perform full table scans without any filters","B":"Z-ORDER provides no benefit on Delta tables; use partitioning for all performance needs","C":"When the table has fewer than 10 files and is already compact","D":"When queries frequently filter on `customer_id`, enabling Delta's data skipping to skip entire files"},"answer":"D","short":"Z-ORDER co-locates related values within the same set of files, enabling Delta Lake's data skipping to skip entire files that don't contain queried `customer_id` values. This is most beneficial for high-cardinality columns frequently used in `WHERE` clauses. If queries always scan the full table, or the table is very small, Z-ORDER provides no benefit.","explanation":"","lesson":"06-troubleshooting-monitoring-and-optimization/03-delta-optimization","related":null},{"id":"data-engineer-associate-mock-1-q039","bank":"simulado-1","n":39,"domain":"governance-and-security","title":"An analyst needs to access data stored in an external S3 bucket from a Databricks…","difficulty":"medium","question":"An analyst needs to access data stored in an external S3 bucket from a Databricks cluster without hardcoding credentials in notebooks. Which approach is most appropriate?","choices":{"A":"Store credentials in a notebook cell marked as hidden","B":"Use Databricks Secrets with `dbutils.secrets.get()` to retrieve credentials at runtime","C":"Export credentials as environment variables in the cluster init script","D":"Pass credentials as job parameters in the Lakeflow Jobs UI"},"answer":"B","short":"Databricks Secrets provides a secure vault for storing sensitive values. `dbutils.secrets.get()` retrieves them at runtime and the values are never shown in logs or notebook output. Hardcoding in notebooks or init scripts exposes credentials in version control and logs. Job parameters are visible in the UI and logs.","explanation":"","lesson":"07-governance-and-security/02-managed-and-external-tables","related":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion"},{"id":"data-engineer-associate-mock-1-q040","bank":"simulado-1","n":40,"domain":"governance-and-security","title":"Members of the emea_sales group must see only the EMEA rows of main.silver.orders, and…","difficulty":"medium","question":"Members of the `emea_sales` group must see only the EMEA rows of `main.silver.orders`, and members of `admins` must see every row. Which Unity Catalog implementation fits?","choices":{"A":"A SQL UDF that returns `BOOLEAN` using `is_account_group_member()`, attached with `ALTER TABLE main.silver.orders SET ROW FILTER <function> ON (region)`","B":"A column mask on the `region` column that returns `NULL` for non-EMEA values","C":"`DENY SELECT ON TABLE main.silver.orders TO emea_sales`","D":"A separate copy of the table for each region, with `SELECT` granted per group"},"answer":"A","short":"A **row filter** is a SQL UDF that returns `BOOLEAN` for each row. For example, `is_account_group_member('admins') OR (is_account_group_member('emea_sales') AND region = 'EMEA')`, attached with `SET ROW FILTER ... ON (region)`. Unity Catalog applies it to every query on the table.","explanation":"A column mask changes the values in a column but returns every row. The classic `DENY` statement works only on the legacy Hive metastore, and it would hide the whole table anyway. Per-region copies duplicate data and drift out of sync.","lesson":"07-governance-and-security/04-row-filters-column-masks-abac","related":null},{"id":"data-engineer-associate-mock-1-q041","bank":"simulado-1","n":41,"domain":"governance-and-security","title":"A data engineer needs to grant a user access to query a specific table in Unity…","difficulty":"hard","question":"A data engineer needs to grant a user access to query a specific table in Unity Catalog without giving access to the entire schema. What is the minimum set of privileges required?","choices":{"A":"`GRANT SELECT ON TABLE catalog.schema.table TO user` only","B":"`GRANT SELECT ON SCHEMA catalog.schema TO user` only","C":"`USE CATALOG` on the catalog + `USE SCHEMA` on the schema + `SELECT` on the table","D":"`GRANT ALL PRIVILEGES ON TABLE catalog.schema.table TO user`"},"answer":"C","short":"Unity Catalog uses hierarchical privilege inheritance. To query a table, a user needs: `USE CATALOG` on the parent catalog, `USE SCHEMA` on the parent schema, and `SELECT` on the specific table. Without the `USE` privileges at each level, the user cannot navigate to the table even if `SELECT` is granted on the table itself. Granting `ALL PRIVILEGES` is overly permissive.","explanation":"","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"data-engineer-associate-mock-1-q042","bank":"simulado-1","n":42,"domain":"governance-and-security","title":"A team registered the external Delta table main.bronze.vendor_feed over an existing…","difficulty":"medium","question":"A team registered the external Delta table `main.bronze.vendor_feed` over an existing cloud storage path. Nothing writes to that path directly any more, and the team now wants Unity Catalog to own the table's storage, without changing its name, permissions, or history. Ten days after the change, they may still need to undo it. Which approach fits?","choices":{"A":"Drop the external table and re-create it as a managed table with `CREATE TABLE ... AS SELECT`","B":"Run `RESTORE TABLE main.bronze.vendor_feed TO VERSION AS OF 0`, which restores the table as managed","C":"Run `DEEP CLONE` into a new managed table and swap the names","D":"Run `ALTER TABLE main.bronze.vendor_feed SET MANAGED`, and roll back with `ALTER TABLE ... UNSET MANAGED` within 14 days if needed"},"answer":"D","short":"`ALTER TABLE ... SET MANAGED` converts an external Delta table to a managed table in place. It keeps the name, settings, permissions, views, and table history, and needs Databricks Runtime 17.3 LTS+ or serverless and ownership of the table. `UNSET MANAGED` points the table back to its original external location, and it is available for 14 days after the conversion.","explanation":"Dropping and re-creating, or cloning and swapping names, produces a new table that loses its grants and history. `RESTORE` restores data versions, not the table type. Existing read and write streams fail after the conversion and need a restart.","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"data-engineer-associate-mock-1-q043","bank":"simulado-1","n":43,"domain":"governance-and-security","title":"In a Unity Catalog-enabled workspace, an engineer runs DENY SELECT ON TABLE…","difficulty":"hard","question":"In a Unity Catalog-enabled workspace, an engineer runs `DENY SELECT ON TABLE prod.gold.revenue TO contractors`, and the statement fails. Contractors must not read the table. What is the correct approach?","choices":{"A":"Run the same `DENY` statement as the table owner, because `DENY` requires ownership","B":"`REVOKE SELECT ON TABLE prod.gold.revenue FROM contractors` (and from any groups that give them access), or don't grant it at all","C":"Apply the `DENY` at the catalog level instead, so it is inherited by the table","D":"Run `ALTER TABLE prod.gold.revenue SET DENY SELECT FOR contractors`"},"answer":"B","short":"The classic `DENY` statement is a legacy Hive metastore feature. In Unity Catalog, read access comes from `SELECT` granted on the table or inherited from a parent catalog or schema, directly or through a group, so you remove access with `REVOKE`, including from the groups the contractors belong to, or by never granting it. Partial access is handled with row filters, column masks, or ABAC policies.","explanation":"Unity Catalog's only deny mechanism is the ABAC DENY policy (Beta), which currently covers just `MANAGE ACCESS CONTROL`, not `SELECT`. `SET DENY` is not valid syntax.","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"data-engineer-associate-mock-1-q044","bank":"simulado-1","n":44,"domain":"governance-and-security","title":"A data engineering team creates Unity Catalog external tables pointing to existing…","difficulty":"hard","question":"A data engineering team creates Unity Catalog external tables pointing to existing data in S3. Which Unity Catalog objects must be configured, and in what order?","choices":{"A":"Storage Credential only — it automatically creates External Locations for referenced paths","B":"External Location only — it includes embedded credential configuration","C":"Catalog first, then Schema, then External Location","D":"Storage Credential first (defines the IAM identity), then External Location (maps the cloud path to the credential)"},"answer":"D","short":"Configuring external storage access in Unity Catalog requires two objects in order: (1) a **Storage Credential** that holds the IAM role or service principal identity with cloud storage permissions, and (2) an **External Location** that maps a specific cloud storage path (e.g., `s3://bucket/prefix`) to that credential. External tables can then reference paths within registered External Locations.","explanation":"","lesson":"07-governance-and-security/01-unity-catalog-basics","related":null},{"id":"data-engineer-associate-mock-1-q045","bank":"simulado-1","n":45,"domain":"governance-and-security","title":"A data engineer wants to audit who accessed a specific Unity Catalog table and when.…","difficulty":"medium","question":"A data engineer wants to audit who accessed a specific Unity Catalog table and when. Which Databricks feature provides this capability?","choices":{"A":"Delta Lake transaction log (`_delta_log`) — records all read and write operations","B":"Databricks system tables (`system.access.audit`) — captures access events including table reads","C":"Unity Catalog lineage graph — shows data flow but not individual user access events","D":"Spark UI history server — stores query history with user attribution"},"answer":"B","short":"Databricks system tables include audit logs in `system.access.audit` that record who accessed what resources and when. The Delta transaction log records write operations (inserts, updates, deletes) but not reads. Lineage shows data flow between datasets. The Spark UI history tracks queries but is not designed for security auditing and has limited retention.","explanation":"","lesson":"07-governance-and-security/01-unity-catalog-basics","related":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables"},{"id":"data-engineer-associate-mock-2-q001","bank":"simulado-2","n":1,"domain":"databricks-intelligence-platform","title":"An analyst notices that a Databricks SQL warehouse is taking 3 minutes to run the…","difficulty":"medium","question":"An analyst notices that a Databricks SQL warehouse is taking 3 minutes to run the first query of the day but subsequent queries run in seconds. What is the most likely cause?","choices":{"A":"The warehouse has a cold start delay because the compute nodes were terminated during the idle period","B":"The warehouse is running out of memory after the first query","C":"The first query always runs as a dry run without caching","D":"The SQL optimizer is recomputing all table statistics for the first query"},"answer":"A","short":"SQL warehouses auto-stop after an idle period (defaults: 10 minutes for serverless, 45 minutes for pro and classic) to save cost. When a new query arrives, a stopped pro or classic warehouse must start again, which takes about 4 minutes. Serverless SQL warehouses start in about 2–6 seconds. Subsequent queries run fast because the cluster is already running.","explanation":"","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"data-engineer-associate-mock-2-q002","bank":"simulado-2","n":2,"domain":"databricks-intelligence-platform","title":"A data engineer accidentally ran DELETE FROM customers WHERE 1=1 which deleted all…","difficulty":"medium","question":"A data engineer accidentally ran `DELETE FROM customers WHERE 1=1` which deleted all rows. The table is named `customers` in Delta format. How can they recover the data?","choices":{"A":"`INSERT INTO customers SELECT * FROM customers VERSION AS OF previous_version`","B":"`RESTORE TABLE customers TO VERSION AS OF previous_version`","C":"Contact Databricks Support — deleted data cannot be recovered from Delta tables","D":"Rerun the original data ingestion pipeline to recreate the data"},"answer":"B","short":"`RESTORE TABLE ... TO VERSION AS OF` (or `TIMESTAMP AS OF`) is the correct command to restore a Delta table to a previous version. It is an atomic operation that restores the table by re-referencing the old data files. This works as long as `VACUUM` has not deleted the files for that version. Option A creates a new table rather than restoring in-place.","explanation":"","lesson":"01-databricks-intelligence-platform/05-time-travel-versioning","related":null},{"id":"data-engineer-associate-mock-2-q003","bank":"simulado-2","n":3,"domain":"databricks-intelligence-platform","title":"A team runs a nightly ETL notebook on a shared all-purpose cluster that stays up all…","difficulty":"medium","question":"A team runs a nightly ETL notebook on a shared all-purpose cluster that stays up all day. Nobody watches the run, and the notebook needs no R, GPU, or custom init script. The team wants to cut cost and follow Databricks guidance for unattended production work. Which compute should the scheduled job use?","choices":{"A":"The same all-purpose cluster, with auto termination turned off so it is always ready","B":"A Pro SQL warehouse sized to the notebook's data volume","C":"A single-node all-purpose cluster dedicated to the job","D":"Serverless compute for jobs, or a jobs compute cluster that is created for each run and terminated afterwards"},"answer":"D","short":"For a nightly ETL notebook with no one watching, Databricks points to **serverless jobs** or **jobs compute**. Jobs compute is created for the run and terminated at the end, so you pay only while it runs, at the separate jobs price. Serverless bills DBUs for the work done with idle time minimized.","explanation":"All-purpose compute is meant for interactive use and keeps billing while idle until auto termination, so turning auto termination off makes the cost worse. A SQL warehouse runs SQL for BI and ad hoc queries, not a general notebook job. Single-node compute suits small data and single-machine libraries, and it is still all-purpose compute.","lesson":"01-databricks-intelligence-platform/03-compute-clusters","related":null},{"id":"data-engineer-associate-mock-2-q004","bank":"simulado-2","n":4,"domain":"data-ingestion-and-loading","title":"A data engineer must choose between COPY INTO and Auto Loader for ingesting files from…","difficulty":"medium","question":"A data engineer must choose between COPY INTO and Auto Loader for ingesting files from cloud storage. Which statement correctly describes when to use each?","choices":{"A":"COPY INTO is for structured files; Auto Loader is for unstructured files","B":"Auto Loader is deprecated; COPY INTO is the only recommended approach","C":"COPY INTO is idempotent and suits smaller, known file sets; Auto Loader suits continuous, large-scale ingestion with automatic file tracking","D":"Both are equivalent — the choice is purely based on personal preference"},"answer":"C","short":"COPY INTO is a SQL command that idempotently loads files into a Delta table (skipping already-loaded files) — suitable for smaller or periodic batch loads from a known set of files. Auto Loader uses checkpointing and cloud notifications to efficiently handle millions of files continuously at scale, making it the recommended approach for streaming ingestion pipelines.","explanation":"","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"data-engineer-associate-mock-2-q005","bank":"simulado-2","n":5,"domain":"data-ingestion-and-loading","title":"An Auto Loader stream ingests JSON files with cloudFiles.schemaLocation set and no…","difficulty":"easy","question":"An Auto Loader stream ingests JSON files with `cloudFiles.schemaLocation` set and no other schema options. Every column in the Bronze table, including `amount` and `event_ts`, ends up as `STRING`. What explains this?","choices":{"A":"For JSON, CSV, and XML, Auto Loader infers columns as strings unless `cloudFiles.inferColumnTypes` is `true` or `cloudFiles.schemaHints` sets the types","B":"Auto Loader always writes `STRING` columns to Bronze tables, and types are applied only in Silver","C":"The schema location is corrupt, so Auto Loader fell back to strings","D":"JSON files can't carry numeric or timestamp values, so strings are the only option"},"answer":"A","short":"When Auto Loader infers a schema for JSON, CSV, or XML, it reads every column as a string by default. Setting `cloudFiles.inferColumnTypes` to `true` infers real types, and `cloudFiles.schemaHints` (SQL DDL such as `amount DECIMAL(10,2)`) overrides or adds specific types.","explanation":"Avro and Parquet carry their types in the files, so they don't need this option. Nothing forces Bronze columns to be strings, and the behavior here is the documented default, not a fallback after an error.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"data-engineer-associate-mock-2-q006","bank":"simulado-2","n":6,"domain":"data-ingestion-and-loading","title":"A data engineer writes df = spark.read.format(\"delta\").load(\"/path/to/table\"). What is…","difficulty":"medium","question":"A data engineer writes `df = spark.read.format(\"delta\").load(\"/path/to/table\")`. What is the difference if they use `spark.readStream` instead of `spark.read`?","choices":{"A":"`readStream` reads the entire table into memory at once; `read` reads in chunks","B":"`readStream` automatically converts the Delta table to a Kafka stream","C":"There is no difference — both return identical DataFrames","D":"`readStream` returns a streaming DataFrame that only processes new files/rows added since the last checkpoint"},"answer":"D","short":"`spark.readStream.format(\"delta\").load(path)` creates a streaming DataFrame that treats the Delta table as a streaming source. It processes only new data (rows appended after the checkpoint) in each micro-batch. `spark.read` returns a static (batch) DataFrame representing the full table at the time of reading. The two APIs have fundamentally different execution semantics.","explanation":"","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"data-engineer-associate-mock-2-q007","bank":"simulado-2","n":7,"domain":"data-ingestion-and-loading","title":"A data engineer configures Auto Loader with cloudFiles.schemaEvolutionMode =…","difficulty":"medium","question":"A data engineer configures Auto Loader with `cloudFiles.schemaEvolutionMode = \"addNewColumns\"`. A new column appears in incoming JSON files. What happens?","choices":{"A":"The stream fails and can't restart until the schema is manually updated","B":"The new column is silently ignored and not written to the Delta table","C":"The stream stops with an `UnknownFieldException` after recording the new column. When restarted, it adds the column to the schema and continues","D":"Auto Loader quarantines files with new columns for manual review"},"answer":"C","short":"With `addNewColumns` (the default when no schema is provided), Auto Loader stops the stream with `UnknownFieldException`, saves the evolved schema, and picks up the new column on restart. That's why Databricks recommends running these streams in Lakeflow Jobs with retries. `failOnNewColumns` is the mode that stays failed until the schema is fixed, and `rescue` puts unexpected columns into `_rescued_data` ([schema evolution](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema)).","explanation":"","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"data-engineer-associate-mock-2-q008","bank":"simulado-2","n":8,"domain":"data-ingestion-and-loading","title":"A data engineer sets a watermark on a streaming query: withWatermark(\"event_time\", \"10…","difficulty":"hard","question":"A data engineer sets a watermark on a streaming query: `withWatermark(\"event_time\", \"10 minutes\")`. What is the purpose of this watermark?","choices":{"A":"Defines the maximum tolerated lateness for event-time-based aggregations, allowing late data up to 10 minutes after the window closes","B":"Ensures that data older than 10 minutes is deleted from the Delta table","C":"Buffers all incoming data for exactly 10 minutes before writing to the sink","D":"Limits the streaming query to process at most 10 minutes of historical data"},"answer":"A","short":"Watermarks in Spark Structured Streaming define how late data can arrive and still be included in aggregations. A 10-minute watermark means data with an event_time up to 10 minutes behind the current watermark is included; older data is dropped. This allows Spark to bound the state size by eventually discarding old windows.","explanation":"","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":"03-data-transformation-and-modeling/04-advanced-transformations"},{"id":"data-engineer-associate-mock-2-q009","bank":"simulado-2","n":9,"domain":"data-ingestion-and-loading","title":"An Auto Loader stream reads a landing directory that holds millions of files. Each…","difficulty":"medium","question":"An Auto Loader stream reads a landing directory that holds millions of files. Each micro-batch spends most of its time listing the directory. Which change does Databricks recommend for most workloads?","choices":{"A":"Set `cloudFiles.useIncrementalListing` to `true`","B":"Raise `cloudFiles.maxFilesPerTrigger` to 100,000","C":"Replace Auto Loader with a scheduled `COPY INTO`","D":"Use file notification mode with file events enabled on the Unity Catalog external location"},"answer":"D","short":"Directory listing, the default mode, lists the input directory on every micro-batch, which gets slow as the directory grows. Databricks recommends **file notification with file events**, enabled on the Unity Catalog external location, as more performant and scalable. You can switch modes across stream restarts and keep exactly-once processing.","explanation":"`cloudFiles.useIncrementalListing` is deprecated. `maxFilesPerTrigger` caps how many files each micro-batch takes, but discovery still has to list the directory. `COPY INTO` is meant for modest, known file sets, not millions of files.","lesson":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","related":null},{"id":"data-engineer-associate-mock-2-q010","bank":"simulado-2","n":10,"domain":"data-ingestion-and-loading","title":"A data engineer compares two streaming trigger settings: trigger(processingTime=\"1…","difficulty":"medium","question":"A data engineer compares two streaming trigger settings: `trigger(processingTime=\"1 minute\")` and `trigger(availableNow=True)`. Which scenario is best suited for each?","choices":{"A":"`processingTime` for one-time batch runs; `availableNow` for continuous low-latency streams","B":"`processingTime` for continuous micro-batch streaming on a 1-minute interval; `availableNow` for scheduled jobs that process all pending data then stop","C":"Both are equivalent — the difference is only in the polling interval","D":"`processingTime` is deprecated; use `availableNow` for all streaming jobs"},"answer":"B","short":"`trigger(processingTime=\"1 minute\")` runs micro-batches on a fixed 1-minute interval indefinitely — suitable for continuous, near-real-time streaming. `trigger(availableNow=True)` processes all currently available data and terminates — suitable for scheduled pipeline runs where a streaming source needs batch-style processing. Neither is deprecated.","explanation":"","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":null},{"id":"data-engineer-associate-mock-2-q011","bank":"simulado-2","n":11,"domain":"data-ingestion-and-loading","title":"A data engineer has a CSV directory and wants to convert it to a managed Delta table…","difficulty":"medium","question":"A data engineer has a CSV directory and wants to convert it to a managed Delta table in Unity Catalog. Which approach creates a properly managed Delta table?","choices":{"A":"`CONVERT TO DELTA parquet.'/path/to/csv/'` — converts any format to Delta","B":"Delta tables can only be created from Parquet format; CSV must first be converted to Parquet","C":"`ALTER TABLE csv_table SET TYPE DELTA`","D":"`CREATE TABLE catalog.schema.table USING DELTA AS SELECT * FROM csv.'/path/'`"},"answer":"D","short":"`CREATE TABLE ... USING DELTA AS SELECT * FROM csv.'/path/'` reads the CSV files and creates a new managed Delta table with the query results. `CONVERT TO DELTA` works only on Parquet-formatted directories (not CSV). `ALTER TABLE SET TYPE` is not valid Databricks SQL syntax. Delta tables can be created from any format via CTAS.","explanation":"","lesson":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","related":"03-data-transformation-and-modeling/01-spark-sql-fundamentals"},{"id":"data-engineer-associate-mock-2-q012","bank":"simulado-2","n":12,"domain":"data-ingestion-and-loading","title":"A team sets up a Lakeflow Connect managed connector for continuous change data capture…","difficulty":"medium","question":"A team sets up a Lakeflow Connect managed connector for continuous change data capture from SQL Server. Which component runs continuously in its own job and stages the change data before it is written to the destination?","choices":{"A":"The Unity Catalog connection","B":"The destination streaming tables","C":"The ingestion gateway","D":"The ingestion pipeline"},"answer":"C","short":"Database connectors add an **ingestion gateway**. It runs as a continuous task in its own job and stages change data for continuous change capture.","explanation":"The **connection** is a Unity Catalog securable that stores the source's authentication details. The **ingestion pipeline** reads the staged changes and writes them to the destination, and the destination tables are **streaming tables** in the catalog and schema you pick.","lesson":"02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect","related":null},{"id":"data-engineer-associate-mock-2-q013","bank":"simulado-2","n":13,"domain":"data-transformation-and-modeling","title":"A data engineer needs to replace all data in a partition of a Delta table with new…","difficulty":"medium","question":"A data engineer needs to replace all data in a partition of a Delta table with new data, without affecting other partitions. Which SQL command accomplishes this?","choices":{"A":"`DELETE FROM table WHERE partition_col = 'value'` followed by `INSERT INTO`","B":"`INSERT OVERWRITE table PARTITION (partition_col = 'value') SELECT ...`","C":"`TRUNCATE TABLE table` then `INSERT INTO table SELECT ...`","D":"`CREATE OR REPLACE TABLE table AS SELECT ...`"},"answer":"B","short":"`INSERT OVERWRITE ... PARTITION (...)` replaces data in the specified partition atomically while leaving other partitions untouched. `TRUNCATE TABLE` removes all data from all partitions. `CREATE OR REPLACE TABLE` replaces the entire table. The `DELETE` + `INSERT` approach works but is not atomic — `INSERT OVERWRITE` is preferred for partition replacement.","explanation":"","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"data-engineer-associate-mock-2-q014","bank":"simulado-2","n":14,"domain":"data-transformation-and-modeling","title":"A data engineer has a column price stored as STRING type and needs to cast it to…","difficulty":"easy","question":"A data engineer has a column `price` stored as `STRING` type and needs to cast it to `DOUBLE` for calculations. Which SQL expression correctly performs this conversion?","choices":{"A":"`CONVERT(price, DOUBLE)`","B":"`price::DOUBLE`","C":"`CAST(price AS DOUBLE)`","D":"`TO_DOUBLE(price)`"},"answer":"C","short":"`CAST(column AS type)` is the standard SQL syntax for type conversion in Databricks SQL and Spark SQL. Databricks also supports the shorthand `column::type` (PostgreSQL-style). `CONVERT()` is valid in some SQL dialects but not Databricks SQL. `TO_DOUBLE()` is not a Databricks function.","explanation":"","lesson":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","related":null},{"id":"data-engineer-associate-mock-2-q015","bank":"simulado-2","n":15,"domain":"data-transformation-and-modeling","title":"A data engineer writes SELECT FROM orders WHERE discount IS NOT NULL AND discount !=…","difficulty":"medium","question":"A data engineer writes `SELECT * FROM orders WHERE discount IS NOT NULL AND discount != 0`. A row with `discount = NULL` — will it be returned?","choices":{"A":"Yes — `IS NOT NULL` matches NULL values","B":"Yes — `discount != 0` returns all non-zero values including NULL","C":"No — `IS NOT NULL` excludes NULL values; rows with NULL discount are filtered out","D":"A SQL error occurs because you cannot compare NULL with `!=`"},"answer":"C","short":"`IS NOT NULL` filters out rows where the column contains NULL. Since both conditions are joined with `AND`, a row with `NULL` discount fails the `IS NOT NULL` check and is excluded. In SQL, `NULL != 0` evaluates to NULL (not TRUE), so NULL values are also excluded by the `!=` comparison — but `IS NOT NULL` already removes them first.","explanation":"","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"data-engineer-associate-mock-2-q016","bank":"simulado-2","n":16,"domain":"data-transformation-and-modeling","title":"A data engineer writes Delta table data using…","difficulty":"medium","question":"A data engineer writes Delta table data using `df.write.format(\"delta\").mode(\"append\").save(path)`. What happens if the path already contains a Delta table with a different schema?","choices":{"A":"The write succeeds and merges the schemas automatically","B":"The new data is silently dropped and the existing table is unchanged","C":"The existing table is overwritten with the new schema","D":"The write fails with a `AnalysisException` due to schema mismatch unless `mergeSchema` is enabled"},"answer":"D","short":"Delta Lake enforces schema consistency by default. Appending data with a different schema throws an `AnalysisException`. To allow schema evolution during appends, enable `.option(\"mergeSchema\", \"true\")` which adds new columns from the source. Overwriting behavior requires `.mode(\"overwrite\")`, not `\"append\"`.","explanation":"","lesson":"03-data-transformation-and-modeling/02-dataframe-operations","related":"01-databricks-intelligence-platform/04-delta-lake-fundamentals"},{"id":"data-engineer-associate-mock-2-q017","bank":"simulado-2","n":17,"domain":"data-transformation-and-modeling","title":"A data engineer queries a table with millions of rows and needs to know the count of…","difficulty":"easy","question":"A data engineer queries a table with millions of rows and needs to know the count of distinct values in a column. Which function returns this?","choices":{"A":"`COUNT(DISTINCT column)`","B":"`COUNT(column)`","C":"`SUM(DISTINCT column)`","D":"`APPROX_COUNT_DISTINCT(column)`"},"answer":"A","short":"`COUNT(DISTINCT column)` returns the exact number of distinct non-NULL values in the column. `COUNT(column)` counts non-NULL rows including duplicates. `SUM(DISTINCT column)` sums distinct numeric values, not counts. `APPROX_COUNT_DISTINCT()` uses HyperLogLog for an approximate count — faster for very large datasets but not exact.","explanation":"","lesson":"03-data-transformation-and-modeling/03-joins-aggregations","related":null},{"id":"data-engineer-associate-mock-2-q018","bank":"simulado-2","n":18,"domain":"data-transformation-and-modeling","title":"A data engineer uses collect_list() and collect_set() in a GROUP BY aggregation. What…","difficulty":"medium","question":"A data engineer uses `collect_list()` and `collect_set()` in a GROUP BY aggregation. What is the difference between these two functions?","choices":{"A":"`collect_list` returns a sorted array; `collect_set` returns an unsorted array","B":"`collect_list` preserves duplicates in the array; `collect_set` returns only distinct values","C":"`collect_set` works on numeric types only; `collect_list` works on any type","D":"Both functions are identical — the names are aliases for the same behavior"},"answer":"B","short":"`collect_list(col)` aggregates all values into an array including duplicates, preserving order. `collect_set(col)` aggregates into an array of unique values, with no guaranteed ordering. Use `collect_list` when duplicates and order matter; use `collect_set` when you only need distinct values.","explanation":"","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"data-engineer-associate-mock-2-q019","bank":"simulado-2","n":19,"domain":"data-transformation-and-modeling","title":"A data engineer receives a DataFrame with a column containing nested arrays of arrays…","difficulty":"medium","question":"A data engineer receives a DataFrame with a column containing nested arrays of arrays (e.g., `[[1,2],[3,4]]`). Which function flattens this into a single-level array (e.g., `[1,2,3,4]`)?","choices":{"A":"`explode()`","B":"`transform()`","C":"`array_join()`","D":"`flatten()`"},"answer":"D","short":"`flatten(array_of_arrays)` converts a nested array (array of arrays) into a single flat array by concatenating the inner arrays. `explode()` creates one row per element — it doesn't flatten, it unnests. `array_join()` converts an array to a string. `transform()` applies a lambda to each element, producing an array of the same depth.","explanation":"","lesson":"03-data-transformation-and-modeling/04-advanced-transformations","related":null},{"id":"data-engineer-associate-mock-2-q020","bank":"simulado-2","n":20,"domain":"data-transformation-and-modeling","title":"A data engineer needs to delete records from a Delta table where a customer opted out,…","difficulty":"hard","question":"A data engineer needs to delete records from a Delta table where a customer opted out, and also update other customers' status in the same operation. Which SQL command handles both in a single atomic operation?","choices":{"A":"Run `DELETE` and `UPDATE` as separate transactions in sequence","B":"`TRUNCATE TABLE customers` then reinsert only the retained records","C":"`MERGE INTO customers USING opt_outs ON ... WHEN MATCHED AND condition THEN DELETE WHEN MATCHED AND other_condition THEN UPDATE SET ...`","D":"Use a Python loop to delete and update records one by one"},"answer":"C","short":"Delta Lake's `MERGE` statement supports multiple `WHEN MATCHED` clauses with different conditions — one can trigger `DELETE` and another can trigger `UPDATE SET`. This executes atomically in a single pass over the data. Running `DELETE` and `UPDATE` as separate transactions is correct but not atomic as a combined unit. `TRUNCATE` and reinsert is expensive and error-prone.","explanation":"","lesson":"03-data-transformation-and-modeling/02-dataframe-operations","related":"04-working-with-lakeflow-jobs/03-control-flow"},{"id":"data-engineer-associate-mock-2-q021","bank":"simulado-2","n":21,"domain":"data-transformation-and-modeling","title":"A DLT pipeline runs a full refresh. How does a full refresh differ from a standard…","difficulty":"medium","question":"A DLT pipeline runs a full refresh. How does a full refresh differ from a standard pipeline update?","choices":{"A":"A full refresh only processes files added in the last 24 hours","B":"A full refresh truncates all materialized tables and recomputes them from scratch using all source data","C":"A full refresh updates only the tables with failed expectations from the previous run","D":"A full refresh is identical to a standard update — the terminology is interchangeable"},"answer":"B","short":"A full refresh in Delta Live Tables drops all data in the pipeline's materialized tables and recomputes everything from the original sources. This is useful after fixing pipeline logic or recovering from data corruption. A standard update (incremental) processes only new data since the last checkpoint. Full refreshes are more expensive since they reprocess all historical data.","explanation":"","lesson":"03-data-transformation-and-modeling/06-gold-layer-objects","related":null},{"id":"data-engineer-associate-mock-2-q022","bank":"simulado-2","n":22,"domain":"data-transformation-and-modeling","title":"A DLT pipeline has an EXPECT constraint with no ON VIOLATION modifier. A record fails…","difficulty":"medium","question":"A DLT pipeline has an `EXPECT` constraint with no `ON VIOLATION` modifier. A record fails the constraint. What is the default behavior?","choices":{"A":"The pipeline fails and stops processing","B":"The violating record is dropped silently","C":"The violating record is written to the output table and the violation is logged in the event log as a warning","D":"The violating record is written to a quarantine table for review"},"answer":"C","short":"The default behavior of `EXPECT` without an `ON VIOLATION` modifier is `WARN` — all records (including violating ones) are written to the output table, and the number of violations is tracked in the DLT event log as metrics. To drop records, use `ON VIOLATION DROP ROW`. To fail the pipeline, use `ON VIOLATION FAIL UPDATE`.","explanation":"","lesson":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","related":null},{"id":"data-engineer-associate-mock-2-q023","bank":"simulado-2","n":23,"domain":"working-with-lakeflow-jobs","title":"A data engineer uses dbutils.widgets.text(\"start_date\", \"2024-01-01\") in a notebook.…","difficulty":"medium","question":"A data engineer uses `dbutils.widgets.text(\"start_date\", \"2024-01-01\")` in a notebook. What is the purpose of this widget?","choices":{"A":"Displays a text message at the top of the notebook output","B":"Logs the value `\"2024-01-01\"` to the Databricks audit trail","C":"Creates a permanent database variable that persists across cluster restarts","D":"Creates a parameterized input that can be overridden when running the notebook as a job"},"answer":"D","short":"`dbutils.widgets` creates interactive input controls (text boxes, dropdowns, etc.) in the notebook UI. When the notebook is run as a Lakeflow Job, the widget value can be overridden via job parameters or the `notebookParams` API. This makes notebooks parameterizable and reusable across different date ranges or environments.","explanation":"","lesson":"04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks","related":"01-databricks-intelligence-platform/02-databricks-workspace"},{"id":"data-engineer-associate-mock-2-q024","bank":"simulado-2","n":24,"domain":"working-with-lakeflow-jobs","title":"In a Lakeflow Job, the ingest task publishes the number of new rows with…","difficulty":"medium","question":"In a Lakeflow Job, the `ingest` task publishes the number of new rows with `dbutils.jobs.taskValues.set(key=\"rows_loaded\", value=rows)`. The `transform` task should run only when `rows_loaded` is greater than 0, and a `notify_no_data` task should run otherwise. How should the job be built?","choices":{"A":"Add an If/else condition task after `ingest` that compares `{{tasks.ingest.values.rows_loaded}}` `>` `0`. Make `transform` depend on its `(true)` outcome and `notify_no_data` on its `(false)` outcome","B":"Make both tasks depend on `ingest`, and have `transform` exit early in code when no rows were loaded","C":"Use a For each task over `rows_loaded`","D":"Set `notify_no_data`'s **Run if** to **At least one failed**, and make `ingest` fail when no rows are loaded"},"answer":"A","short":"The **If/else condition** task branches a job on a boolean expression. Operands can be literals, job parameters, or task values such as `{{tasks.ingest.values.rows_loaded}}`, and downstream tasks depend on its `(true)` or `(false)` outcome. `>` compares numbers, while `==` and `!=` compare strings.","explanation":"An early exit in code still starts `transform` and hides the branch from the job graph. For each loops over an array of inputs. It doesn't branch. Making a task fail on purpose to drive control flow turns a normal empty day into a failed run.","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"data-engineer-associate-mock-2-q025","bank":"simulado-2","n":25,"domain":"working-with-lakeflow-jobs","title":"A data engineer uses dbutils.notebook.run(\"./child_notebook\", timeout_seconds=300,…","difficulty":"medium","question":"A data engineer uses `dbutils.notebook.run(\"./child_notebook\", timeout_seconds=300, arguments={\"date\": \"2024-01-15\"})`. What does this accomplish?","choices":{"A":"Runs the child notebook synchronously in the current cluster, passing the date argument as a widget value","B":"Runs the child notebook asynchronously in a separate Databricks job","C":"Schedules the child notebook to run at the specified timeout in 300 seconds","D":"Creates a permanent link between the parent and child notebook that runs on every commit"},"answer":"A","short":"`dbutils.notebook.run()` executes another notebook synchronously on the current cluster with a timeout. The `arguments` dictionary sets widget values in the child notebook. It blocks until the child completes or times out. Unlike `%run`, the child notebook runs in an isolated scope and its variables are not imported into the parent.","explanation":"","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":"01-databricks-intelligence-platform/02-databricks-workspace"},{"id":"data-engineer-associate-mock-2-q026","bank":"simulado-2","n":26,"domain":"working-with-lakeflow-jobs","title":"A data engineer uses task values to pass a dynamically computed date from Task A to…","difficulty":"medium","question":"A data engineer uses task values to pass a dynamically computed date from Task A to Task B in a multi-task Lakeflow Job. Which `dbutils` functions are used to set and retrieve the value?","choices":{"A":"`dbutils.jobs.set(\"key\", value)` in Task A; `dbutils.jobs.get(\"key\")` in Task B","B":"`dbutils.jobs.taskValues.set(key=\"key\", value=value)` in Task A; `dbutils.jobs.taskValues.get(taskKey=\"task_a\", key=\"key\")` in Task B","C":"`dbutils.widgets.set(\"key\", value)` in Task A; `dbutils.widgets.get(\"key\")` in Task B","D":"Write the value to DBFS in Task A; read from DBFS in Task B"},"answer":"B","short":"`dbutils.jobs.taskValues.set(key=..., value=...)` publishes a value from the current task. Downstream tasks read it with `dbutils.jobs.taskValues.get(taskKey=..., key=...)`, or reference it as `{{tasks.<task>.values.<key>}}` ([task values](https://docs.databricks.com/aws/en/jobs/task-values)). Widgets are for parameterizing notebooks, not passing values between tasks. DBFS would work but is an anti-pattern compared to the built-in task values API.","explanation":"","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"data-engineer-associate-mock-2-q027","bank":"simulado-2","n":27,"domain":"working-with-lakeflow-jobs","title":"A Gold job reads main.silver.orders, which Team A refreshes, and…","difficulty":"medium","question":"A Gold job reads `main.silver.orders`, which Team A refreshes, and `main.silver.customers`, which Team B refreshes. Both teams finish at different, unpredictable times. The Gold job should run once both tables have been refreshed, with no polling. Which trigger fits?","choices":{"A":"A scheduled trigger at 06:00 every day","B":"A table update trigger on both tables with **Any table is updated**","C":"A file arrival trigger on the Silver schema's storage location","D":"A table update trigger on both tables with **All tables are updated**"},"answer":"D","short":"A **table update trigger** starts a run when monitored Unity Catalog tables change, with no compute running in between. When it monitors several tables, **All tables are updated** waits until every one of them has changed, which suits a job that needs every input fresh.","explanation":"**Any table is updated** would start after the first team finishes, with the other input still stale. A fixed 06:00 schedule can run before either team is done. File arrival triggers watch for new files in a volume or external location, not table refreshes. The job's **Run as** principal needs `SELECT` on each table, plus `USE CATALOG` and `USE SCHEMA`, or the trigger can't evaluate.","lesson":"04-working-with-lakeflow-jobs/02-scheduling-triggers","related":null},{"id":"data-engineer-associate-mock-2-q028","bank":"simulado-2","n":28,"domain":"working-with-lakeflow-jobs","title":"A production Lakeflow Job runs a task that occasionally takes much longer than usual…","difficulty":"medium","question":"A production Lakeflow Job runs a task that occasionally takes much longer than usual due to data volume spikes. To prevent the job from running indefinitely, which configuration should the engineer set?","choices":{"A":"Retry policy with maximum retries set to 1","B":"Task timeout — the maximum time in seconds a task is allowed to run before it is cancelled","C":"Cluster autotermination minutes on the job cluster","D":"Maximum concurrent runs set to 1"},"answer":"B","short":"Task timeout defines the maximum wall-clock time a task is allowed to run before Databricks automatically cancels it and marks the task as failed. This prevents runaway jobs from consuming resources indefinitely. Retry policy controls what happens after failure. Autotermination applies to idle clusters, not running tasks. Max concurrent runs controls parallel job instances.","explanation":"","lesson":"04-working-with-lakeflow-jobs/03-control-flow","related":null},{"id":"data-engineer-associate-mock-2-q029","bank":"simulado-2","n":29,"domain":"working-with-lakeflow-jobs","title":"A Lakeflow Job multi-task job has tasks A → B → C (sequential dependency). Task B…","difficulty":"medium","question":"A Lakeflow Job multi-task job has tasks A → B → C (sequential dependency). Task B fails. What is the default behavior for Task C?","choices":{"A":"Task C runs anyway, using the last successful output from Task B","B":"Task C doesn't run and is marked `Upstream failed` because its dependency failed","C":"Task C waits indefinitely for Task B to be manually retried","D":"The entire job reruns from Task A automatically"},"answer":"B","short":"When an upstream task fails in a Lakeflow Job, downstream tasks with the default Run if condition (*All succeeded*) are marked `Upstream failed`. Databricks does not run dependent tasks if their dependencies failed. If the job has retry configured, the failed task is retried first. Task C is not retried or rerun automatically.","explanation":"","lesson":"04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks","related":null},{"id":"data-engineer-associate-mock-2-q030","bank":"simulado-2","n":30,"domain":"implementing-cicd","title":"A data engineer wants to version control notebooks using Git and collaborate with…","difficulty":"easy","question":"A data engineer wants to version control notebooks using Git and collaborate with teammates via pull requests. Which Databricks feature supports this workflow?","choices":{"A":"Databricks Archives — export notebooks to ZIP format for external storage","B":"Lakeflow Jobs — tracks job run history as a proxy for code versions","C":"Databricks File System — stores notebook files in DBFS with version history","D":"Databricks Git folders (formerly Repos) — connects workspace folders to a remote Git repository"},"answer":"D","short":"Databricks Git folders (formerly Repos) integrates workspace folders directly with remote Git repositories (GitHub, GitLab, Azure DevOps, etc.). Engineers can commit, push, pull, create branches, and collaborate via pull requests without leaving the Databricks interface. DBFS does not provide version control. Workflows tracks job runs, not code changes.","explanation":"","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"data-engineer-associate-mock-2-q031","bank":"simulado-2","n":31,"domain":"implementing-cicd","title":"A bundle declares the variable catalog with default: dev, and the prod target sets…","difficulty":"hard","question":"A bundle declares the variable `catalog` with `default: dev`, and the `prod` target sets `variables.catalog: prod`. The CI runner exports `BUNDLE_VAR_catalog=staging` and then runs `databricks bundle deploy -t prod` with no `--var` option. Which value does `${var.catalog}` resolve to?","choices":{"A":"`staging`","B":"`prod`","C":"`dev`","D":"The deploy fails because the variable is defined in two places"},"answer":"A","short":"Bundle variables are resolved at deploy time, in this order of precedence: the `--var` CLI option, then the `BUNDLE_VAR_<name>` environment variable, then `.databricks/bundle/<target>/variable-overrides.json`, then the value under the target, and last the top-level `default`.","explanation":"No `--var` was passed, so the environment variable wins over the target-level `prod` value. This is a common reason a target's value seems to be ignored. Defining a value in several places is normal, and precedence decides which one is used.","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"data-engineer-associate-mock-2-q032","bank":"simulado-2","n":32,"domain":"implementing-cicd","title":"A CI step runs databricks bundle deploy with no -t option. The bundle defines dev,…","difficulty":"easy","question":"A CI step runs `databricks bundle deploy` with no `-t` option. The bundle defines `dev`, `test`, and `prod` targets, and the code ends up in the dev workspace instead of prod. Why?","choices":{"A":"Without `-t`, the bundle deploys to the target marked `default: true`","B":"Without `-t`, the bundle deploys to every target in alphabetical order","C":"`databricks bundle deploy` always deploys to dev, and prod requires `databricks bundle run`","D":"The CI runner's service principal can access only the dev workspace"},"answer":"A","short":"When no target is given, the CLI uses the target marked `default: true`, which is usually `dev`. CI pipelines should always pass `-t <target>` explicitly.","explanation":"A deploy goes to one target, not to all of them. `deploy` works for any target, and `run` starts a deployed job, pipeline, app, or script. Nothing in the scenario points to a permission problem: the deploy succeeded, just to the wrong target.","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"data-engineer-associate-mock-2-q033","bank":"simulado-2","n":33,"domain":"implementing-cicd","title":"Which behavior applies to a bundle target set to mode: production?","difficulty":"medium","question":"Which behavior applies to a bundle target set to `mode: production`?","choices":{"A":"Resource names get a `[dev <user>]` prefix, and schedules and triggers are paused","B":"Clusters can be overridden with `--cluster-id` so production runs can reuse a developer's cluster","C":"Validations check `run_as` and permissions, reject cluster overrides, and require the Git branch to match the target's configured branch","D":"The deployment lock is disabled so several pipelines can deploy at once"},"answer":"C","short":"`mode: production` adds safety checks: it validates `run_as`, `permissions`, and that paths aren't user-specific, doesn't allow a `cluster_id` override, and requires the Git branch to match the target's configured branch (`--force` overrides that check). A service principal is the recommended identity.","explanation":"The name prefix, paused schedules, and allowed cluster overrides all belong to `mode: development`. The deployment lock is enabled in production mode and disabled in development mode.","lesson":"05-implementing-cicd/02-declarative-automation-bundles","related":null},{"id":"data-engineer-associate-mock-2-q034","bank":"simulado-2","n":34,"domain":"implementing-cicd","title":"A production Lakeflow Job points at a notebook inside an engineer's personal Git…","difficulty":"medium","question":"A production Lakeflow Job points at a notebook inside an engineer's personal Git folder. After the engineer switches to a branch that doesn't contain the notebook and then switches back, the job fails because the notebook now has a new ID. What is the recommended practice?","choices":{"A":"Pin the job to the notebook's old URL","B":"Forbid branch switching in that Git folder","C":"Have every engineer share one Git folder for production","D":"Have CI deploy a bundle from the merged `main` branch to the production workspace, run as a service principal"},"answer":"D","short":"Switching branches can delete workspace assets that the new branch doesn't contain. Switching back recreates them with new IDs and URLs, so any job that points at a personal Git folder is fragile.","explanation":"Production jobs should run from a bundle that CI deploys from the merged branch, using a service principal. The old URL no longer exists. Blocking branch switches defeats the purpose of Git folders, and the docs advise against sharing one Git folder between people.","lesson":"05-implementing-cicd/01-git-folders","related":null},{"id":"data-engineer-associate-mock-2-q035","bank":"simulado-2","n":35,"domain":"troubleshooting-monitoring-and-optimization","title":"A data engineer examines the Spark UI after a job completes and sees one task taking…","difficulty":"hard","question":"A data engineer examines the Spark UI after a job completes and sees one task taking 10× longer than all other tasks. What does this indicate?","choices":{"A":"The cluster ran out of memory and had to spill to disk","B":"The Photon engine failed to accelerate that specific task","C":"A data skew problem — one partition contains significantly more data than others","D":"Network latency caused a delay in fetching data from cloud storage"},"answer":"C","short":"A single slow task (stragglers) in the Spark UI typically indicates data skew — one partition has significantly more rows than others, causing one executor to do disproportionately more work. Solutions include salting keys, using `skewHint`, or repartitioning. Memory spill shows in the Spark UI as shuffle spill metrics, not as a single slow task.","explanation":"","lesson":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables","related":null},{"id":"data-engineer-associate-mock-2-q036","bank":"simulado-2","n":36,"domain":"troubleshooting-monitoring-and-optimization","title":"A data engineer runs OPTIMIZE transactions ZORDER BY (customer_id, transaction_date).…","difficulty":"hard","question":"A data engineer runs `OPTIMIZE transactions ZORDER BY (customer_id, transaction_date)`. How does Z-ORDER with multiple columns differ from Z-ORDER with a single column?","choices":{"A":"Z-ORDER with multiple columns is invalid — only one column is allowed","B":"Z-ORDER with multiple columns co-locates data that shares similar values across all specified columns, optimizing queries filtering on any combination of those columns","C":"Z-ORDER applies the first column's ordering first; the second column only applies within ties","D":"Each column is independently Z-ORDERed in separate file groups"},"answer":"B","short":"Z-ORDER with multiple columns uses a space-filling curve to interleave the sort dimensions, co-locating rows that are similar in all specified columns simultaneously. This enables data skipping for queries filtering on `customer_id`, `transaction_date`, or both together. Option C describes a lexicographic sort, which is not how Z-ORDER works.","explanation":"","lesson":"06-troubleshooting-monitoring-and-optimization/03-delta-optimization","related":null},{"id":"data-engineer-associate-mock-2-q037","bank":"simulado-2","n":37,"domain":"troubleshooting-monitoring-and-optimization","title":"A data engineer wants to receive an email when a Lakeflow Job fails. Where is this…","difficulty":"easy","question":"A data engineer wants to receive an email when a Lakeflow Job fails. Where is this configured?","choices":{"A":"In the cluster configuration under \"Termination Notifications\"","B":"In the Databricks workspace admin settings under \"Global Notifications\"","C":"Through a separate alerting notebook that monitors job status via the Jobs API","D":"In the job's \"Notifications\" settings, where email addresses can be added for failure, success, or start events"},"answer":"D","short":"Lakeflow Jobs has a built-in \"Notifications\" section in the job configuration where you can specify email addresses to notify on job start, job success, job failure, and task failure events. This is configured per-job, not globally. A separate monitoring notebook is an alternative but unnecessary when built-in notifications are available.","explanation":"","lesson":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","related":null},{"id":"data-engineer-associate-mock-2-q038","bank":"simulado-2","n":38,"domain":"troubleshooting-monitoring-and-optimization","title":"A report notebook runs pdf = spark.table(\"main.silver.events\").toPandas() on a…","difficulty":"hard","question":"A report notebook runs `pdf = spark.table(\"main.silver.events\").toPandas()` on a 200-million-row table. The run fails with `java.lang.OutOfMemoryError` on the driver, and the notebook detaches. The engineer doubles the number of workers, and the error comes back. What is the right fix?","choices":{"A":"Double the number of workers again, until the cluster has enough total memory","B":"Keep the data distributed: aggregate or filter in Spark and collect only the small result (or write the output to a table), raising `spark.driver.memory` only if still needed","C":"Raise `spark.sql.shuffle.partitions` so each partition is smaller","D":"Enable autoscaling so Databricks adds workers when memory runs low"},"answer":"B","short":"A driver OOM usually comes from pulling data to the driver with `collect()` or `toPandas()`. Workers don't add driver memory, so more workers or autoscaling can't fix it. Aggregate in Spark first, for example `groupBy(\"event_type\").count().toPandas()`, or write results to a table and use `display()` or `limit()`.","explanation":"More shuffle partitions help executor OOM and spill from oversized partitions, not a driver that is holding the whole table. Raising `spark.driver.memory` at the compute level is a last resort when the result really must live on the driver.","lesson":"06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting","related":null},{"id":"data-engineer-associate-mock-2-q039","bank":"simulado-2","n":39,"domain":"governance-and-security","title":"A data engineer needs to store a small reference file that will be accessed by Spark…","difficulty":"easy","question":"A data engineer needs to store a small reference file that will be accessed by Spark jobs in a Databricks workspace. The file must be governed by Unity Catalog and accessible from any Unity Catalog-enabled compute without mount configuration. Which storage location is most appropriate?","choices":{"A":"Cloud object storage (S3/ADLS) with manual mount configuration per cluster","B":"DBFS root, which is mounted on every cluster automatically","C":"Local disk of the driver node — fastest access for small files","D":"A Unity Catalog volume, referenced by a path such as `/Volumes/main/ref/files/lookup.csv`"},"answer":"D","short":"Unity Catalog volumes govern non-tabular files with UC privileges (`READ VOLUME` / `WRITE VOLUME`) and are reachable from UC-enabled compute through `/Volumes/...` paths. DBFS root and mounts are deprecated, and Databricks recommends UC volumes, external locations, or workspace files instead ([What is DBFS?](https://docs.databricks.com/aws/en/dbfs/)). Local driver disk is ephemeral and not shared with other nodes.","explanation":"","lesson":"07-governance-and-security/01-unity-catalog-basics","related":null},{"id":"data-engineer-associate-mock-2-q040","bank":"simulado-2","n":40,"domain":"governance-and-security","title":"A company migrates from an existing Hive metastore to Unity Catalog. What is the key…","difficulty":"medium","question":"A company migrates from an existing Hive metastore to Unity Catalog. What is the key advantage of Unity Catalog over the workspace-level Hive metastore?","choices":{"A":"Unity Catalog provides centralized governance, fine-grained access control, and data lineage across multiple workspaces","B":"Unity Catalog stores data in a different file format for better performance","C":"Unity Catalog eliminates the need for any access control configuration","D":"Unity Catalog is faster because it uses an in-memory metadata cache"},"answer":"A","short":"Unity Catalog provides a centralized governance layer that spans multiple Databricks workspaces and accounts. It offers fine-grained table, column, and row-level security, automated data lineage tracking, and audit logs — none of which are available in the per-workspace Hive metastore. The metastore stores metadata; performance depends on the underlying data files.","explanation":"","lesson":"07-governance-and-security/01-unity-catalog-basics","related":null},{"id":"data-engineer-associate-mock-2-q041","bank":"simulado-2","n":41,"domain":"governance-and-security","title":"A data engineer creates a new Delta table in Unity Catalog using CREATE TABLE…","difficulty":"easy","question":"A data engineer creates a new Delta table in Unity Catalog using `CREATE TABLE catalog.schema.table`. Who automatically becomes the table owner?","choices":{"A":"The workspace admin who configured Unity Catalog","B":"The metastore admin","C":"The user who created the table (the current session's identity)","D":"Ownership is not assigned until explicitly set with `ALTER TABLE ... OWNER TO`"},"answer":"C","short":"In Unity Catalog, the user who creates an object (table, schema, catalog) automatically becomes its owner. Owners have full control over the object, including the ability to grant privileges to others and transfer ownership. Ownership can be transferred using `ALTER TABLE ... OWNER TO new_owner`.","explanation":"","lesson":"07-governance-and-security/03-access-control-permissions","related":null},{"id":"data-engineer-associate-mock-2-q042","bank":"simulado-2","n":42,"domain":"governance-and-security","title":"A data engineer needs to restrict certain users from seeing the full value of a ssn…","difficulty":"medium","question":"A data engineer needs to restrict certain users from seeing the full value of a `ssn` (social security number) column, showing only the last 4 digits instead. Which Unity Catalog feature implements this?","choices":{"A":"Row-level security policy with a `WHERE` clause filter","B":"Column masking policy that replaces the column value with a masked version based on user identity","C":"Dynamic view with `CASE WHEN current_user() = 'admin' THEN ssn ELSE NULL END`","D":"Remove the column from the table and create a separate table for privileged users"},"answer":"B","short":"Unity Catalog column masking policies apply a transformation function to a column's value based on the requesting user's identity or group membership. For example, showing only `'***-**-' || RIGHT(ssn, 4)` to non-privileged users while showing the full value to authorized users. Dynamic views (option C) also work but require maintaining a separate view object. Column masking is the purpose-built Unity Catalog feature.","explanation":"","lesson":"07-governance-and-security/04-row-filters-column-masks-abac","related":null},{"id":"data-engineer-associate-mock-2-q043","bank":"simulado-2","n":43,"domain":"governance-and-security","title":"Hundreds of tables across the schema main.silver have email columns tagged with the…","difficulty":"hard","question":"Hundreds of tables across the schema `main.silver` have email columns tagged with the governed tag `pii = email`, and new tables are added every week. The governance team wants every tagged email column masked for the `analysts` group, now and in future tables, using one definition that table owners can't remove. What should they create?","choices":{"A":"An ABAC policy created with `CREATE POLICY ... ON SCHEMA main.silver COLUMN MASK <function> TO analysts FOR TABLES MATCH COLUMNS has_tag_value('pii', 'email')`","B":"A dynamic view over each table that hides the email column","C":"A column mask on each email column, applied with `ALTER TABLE ... ALTER COLUMN ... SET MASK`","D":"A row filter on each table that returns `FALSE` for the `analysts` group"},"answer":"A","short":"**ABAC policies** evaluate governed tags. One policy attached to a catalog or schema masks every matching column in current and future tables, and because higher-level admins define it, table owners can't override or remove it. ABAC needs Databricks Runtime 16.4+ or serverless compute.","explanation":"Per-column masks and dynamic views have to be repeated for every new table, and owners can change them. A row filter removes whole rows instead of masking a column.","lesson":"07-governance-and-security/04-row-filters-column-masks-abac","related":null},{"id":"data-engineer-associate-mock-2-q044","bank":"simulado-2","n":44,"domain":"governance-and-security","title":"A data engineer creates an external table in Unity Catalog pointing to an S3 path.…","difficulty":"medium","question":"A data engineer creates an external table in Unity Catalog pointing to an S3 path. What happens to the underlying data files when the table is dropped with `DROP TABLE`?","choices":{"A":"The data files are deleted along with the table metadata","B":"The data files are moved to a Unity Catalog-managed trash location for 30 days","C":"The data files are retained in cloud storage; only the table metadata (catalog registration) is removed","D":"`DROP TABLE` fails on external tables — you must use `DROP EXTERNAL TABLE`"},"answer":"C","short":"External tables in Unity Catalog (and Databricks in general) only store metadata — the table definition pointing to an external cloud storage location. When dropped, only the metadata registration is removed. The underlying data files in S3 or ADLS are untouched. This is the key difference from managed tables, where dropping the table also deletes the data files.","explanation":"","lesson":"07-governance-and-security/02-managed-and-external-tables","related":null},{"id":"data-engineer-associate-mock-2-q045","bank":"simulado-2","n":45,"domain":"governance-and-security","title":"A data engineer queries SELECT FROM system.access.audit LIMIT 100 and sees events with…","difficulty":"medium","question":"A data engineer queries `SELECT * FROM system.access.audit LIMIT 100` and sees events with `actionName = 'getTable'`. What do these events represent?","choices":{"A":"Metadata queries where a user read the table's schema or properties","B":"Full table scans where all rows were returned to the user","C":"Table creation events logged when a new table is registered","D":"Failed access attempts where permission was denied"},"answer":"A","short":"In Databricks audit logs, `getTable` action events are recorded when a user reads a table's metadata (schema, properties, statistics) — this includes actions like `DESCRIBE TABLE` or when a BI tool queries the catalog for table info. Full data reads are logged as `commandSubmit`/`commandFinish` events. Permission denials are recorded as separate audit events with error details.","explanation":"","lesson":"07-governance-and-security/03-access-control-permissions","related":null}],"lessons":[{"id":"01-databricks-intelligence-platform/01-lakehouse-architecture","folder":"01-databricks-intelligence-platform","group":"modulo","order":1,"isIndex":false,"title":"Arquitetura Lakehouse","md":"# Arquitetura Lakehouse\n\n## Visão geral\n\nO Databricks Lakehouse combina o melhor dos data warehouses e dos data lakes, permitindo analytics, IA e aplicações em tempo real sobre todos os seus dados. Na prova, este é o Domínio 1 (Databricks Intelligence Platform): os componentes centrais, ou seja, a arquitetura, o Delta Lake e o Unity Catalog.\n\n> [!abstract] Resumo\n>\n> - Um lakehouse mantém uma única cópia dos dados em formatos abertos no object storage da nuvem e adiciona confiabilidade de nível warehouse com o Delta Lake\n> - Camadas medallion: Bronze (bruto, como foi ingerido), Silver (limpo e padronizado), Gold (agregados de negócio para BI e analytics)\n> - O Unity Catalog adiciona controle de acesso centralizado, linhagem e auditoria entre workspaces\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: entender os componentes centrais da plataforma (arquitetura, Delta Lake, Unity Catalog)\n> - Por que uma única cópia governada dos dados dá a IA e BI uma única fonte da verdade, com rollback (time travel) e trilhas de auditoria\n> - Em qual camada medallion uma transformação ou tabela se encaixa\n\n---\n\n## Arquitetura Lakehouse\n\n```mermaid\nflowchart LR\n    subgraph DataLake[\"Data Lake\"]\n        S1[\"Fontes de dados brutos\"]\n        S2[\"Logs históricos\"]\n        S3[\"Dados de streaming\"]\n    end\n\n    subgraph Medallion[\"Camadas Medallion\"]\n        B[\"Bronze<br/>(Bruto)\"]\n        S[\"Silver<br/>(Limpo)\"]\n        G[\"Gold<br/>(Analytics)\"]\n    end\n\n    subgraph Governance[\"Governança\"]\n        UC[\"Unity Catalog\"]\n        Policy[\"Controle de acesso\"]\n        Audit[\"Auditoria\"]\n    end\n\n    subgraph Compute[\"Engines de Compute\"]\n        SQL[\"SQL Engine\"]\n        Analytics[\"Analytics\"]\n        ML[\"ML/IA\"]\n    end\n\n    S1 --> B\n    S2 --> B\n    S3 --> B\n    B --> S\n    S --> G\n    G --> SQL\n    G --> Analytics\n    G --> ML\n    UC --> Governance\n    Policy --> Governance\n    Audit --> Governance\n```\n\n## Data Warehouse vs Data Lake vs Lakehouse\n\n| Aspecto | Data Warehouse | Data Lake | Lakehouse |\n|--------|---|---|---|\n| **Formato dos dados** | Apenas estruturado | Qualquer formato | Estruturado + não estruturado |\n| **Custo** | Alto | Baixo | Baixo |\n| **Velocidade** | Consultas muito rápidas | Consultas mais lentas | Consultas rápidas |\n| **Governança** | Forte | Fraca | Forte |\n| **Flexibilidade** | Schema fixo | Flexível | Ambos |\n| **Casos de uso** | BI, Analytics | Data science, ML | Todos |\n\n## Conceitos-chave do Lakehouse\n\n### **Transações ACID**\n\n- Garantem confiabilidade e consistência dos dados\n- Suportam leituras e escritas concorrentes\n- Permitem rollback e recuperação\n- Embutidas no formato Delta Lake\n\n### **Schema Enforcement e Schema Evolution**\n\n```python\n# Schema enforcement impede dados ruins\n\n(df.write\n    .mode(\"append\")\n    .saveAsTable(\"main.silver.orders\"))   # falha se o schema do df não bater\n\n# Schema evolution permite mudanças controladas\n\n(df.write\n    .mode(\"append\")\n    .option(\"mergeSchema\", \"true\")\n    .saveAsTable(\"main.silver.orders\"))   # adiciona as novas colunas do df\n```\n\n### **Versionamento de dados e Time Travel**\n\n- Acesse versões históricas dos dados\n- Consulte os dados \"as of\" (como estavam em) um timestamp específico\n- Sem git: os snapshots funcionam como controle de versão\n\n```python\n# Consulta com time travel\n\n(spark.read\n    .option(\"versionAsOf\", 0)\n    .table(\"main.silver.orders\"))\n\n# Ou por timestamp\n\n(spark.read\n    .option(\"timestampAsOf\", \"2025-01-15\")\n    .table(\"main.silver.orders\"))\n```\n\n### **Linhagem de dados e logs de auditoria**\n\n- Rastreiam mudanças nos dados ao longo do tempo\n- Quem modificou os dados e quando\n- Atendem requisitos de compliance\n- Viabilizam a governança de dados\n\n## A base: Delta Lake\n\nO Delta Lake é o storage engine open source que dá suporte ao Lakehouse:\n\n- **Compliance ACID**: controle de concorrência multiversão (MVCC)\n- **Formato**: arquivos Parquet + transaction log\n- **Confiabilidade**: trata incompatibilidades de schema e corrupção de dados\n- **Performance**: suporte nativo a DELETE, UPDATE e MERGE\n\n```python\n# Criar uma tabela Delta\n\ndf.write.mode(\"overwrite\").saveAsTable(\"main.bronze.my_table\")   # Delta é o formato padrão\n\n# Ou converter Parquet existente\n\nfrom delta.tables import DeltaTable\nDeltaTable.convertToDelta(spark, \"parquet.`/path/to/data`\")\n```\n\n## Arquitetura Medallion (Bronze/Silver/Gold)\n\nUm padrão de boas práticas para organizar os dados:\n\n```mermaid\nflowchart TB\n    Raw[\"Fontes de dados brutos\"]\n\n    subgraph Bronze[\"🥉 Camada Bronze\"]\n        B1[\"Ingestão bruta\"]\n        B2[\"Transformação mínima\"]\n        B3[\"Append-only\"]\n    end\n\n    subgraph Silver[\"🥈 Camada Silver\"]\n        S1[\"Limpo e deduplicado\"]\n        S2[\"Schema garantido\"]\n        S3[\"Regras de negócio aplicadas\"]\n    end\n\n    subgraph Gold[\"🥇 Camada Gold\"]\n        G1[\"Agregados de negócio\"]\n        G2[\"Tabelas de dimensão\"]\n        G3[\"Otimizado para BI/ML\"]\n    end\n\n    BI[\"Ferramentas de BI e Dashboards\"]\n    ML[\"Modelos de ML\"]\n\n    Raw --> Bronze\n    Bronze --> Silver\n    Silver --> Gold\n    Gold --> BI\n    Gold --> ML\n```\n\n### Camada Bronze\n\n- **Propósito**: ingestão bruta a partir dos sistemas de origem\n- **Schema**: igual ao da origem (pode ser não estruturado)\n- **Retenção**: transformação mínima, mantém todos os dados brutos\n- **Qualidade**: pode conter duplicatas, nulos e erros\n- **Caso de uso**: preservar os dados originais para trilhas de auditoria\n\n### Camada Silver\n\n- **Propósito**: hub analítico limpo e deduplicado\n- **Schema**: padronizado e garantido (enforced)\n- **Retenção**: remove duplicatas, trata nulos\n- **Qualidade**: segue as regras de negócio\n- **Caso de uso**: juntar sistemas de origem, identificar dimensões\n\n### Camada Gold\n\n- **Propósito**: agregados prontos para o negócio, para BI/ML\n- **Schema**: otimizado para casos de uso específicos\n- **Retenção**: apenas o necessário para analytics\n- **Qualidade**: totalmente validada, alta confiança\n- **Caso de uso**: alimentar dashboards e features de ML\n\n## Onde cada camada vive no Databricks\n\n| Camada | Localização típica no Unity Catalog | Formato | Acesso |\n|-------|---------|--------|--------|\n| **Bronze** | Tabelas `main.bronze.*` (arquivos brutos em um volume UC como `/Volumes/main/raw/landing/`) | Delta | Engenheiros de dados |\n| **Silver** | `main.silver.*` | Delta | Engenheiros de dados, analistas |\n| **Gold** | Tabelas, views e materialized views `main.gold.*` | Delta | Analistas, ferramentas de BI, ML |\n\nMuitas equipes usam um catálogo por ambiente (`dev`, `prod`) e um schema por camada. Outras usam um catálogo por camada. De qualquer forma, as camadas são securables do UC, não caminhos de mount do DBFS. Os mounts do DBFS estão depreciados em favor de volumes e external locations do Unity Catalog ([What is DBFS?](https://docs.databricks.com/aws/en/dbfs/)).\n\n## Unity Catalog para governança\n\nO Unity Catalog fornece uma solução de governança unificada:\n\n- **Catalogs**: contêineres parecidos com bancos de dados para organizar tabelas\n- **Schemas**: namespaces dentro dos catálogos\n- **Tables/Volumes**: objetos de dados com controle de acesso granular\n- **Segurança granular**: row filters, column masks e políticas ABAC (veja o [Domínio 7](../07-governance-and-security/04-row-filters-column-masks-abac.md))\n\n```python\n# Namespace de três níveis\n\nspark.sql(\"SELECT * FROM main.default.my_table\")\n\n#                        ^    ^       ^\n#                  catalog schema  table\n\n```\n\n## Casos de uso\n\n1. **Analytics em tempo real**: dados em streaming pelas camadas medallion, consultados imediatamente\n2. **Machine Learning**: conjuntos de features reprodutíveis na camada Gold, time travel para versionar dados\n3. **Data Warehousing**: substituir o EDW tradicional com menor custo e mais flexibilidade\n4. **Compliance**: trilhas de auditoria em todas as mudanças, mascaramento por coluna\n5. **Compartilhamento de dados**: compartilhamento externo seguro sem duplicar dados\n\n## Problemas e erros comuns\n\n### Formatos de dados conflitantes\n\n**Cenário:** consultas falham ao misturar arquivos Parquet, CSV e JSON no mesmo diretório.\n\n**Correção:** converta todos os dados brutos para Delta cedo no pipeline medallion (camada Bronze) para que as camadas seguintes sempre leiam um formato consistente.\n\n### Cache de metadados desatualizado\n\n**Cenário:** dados recém-escritos não aparecem nas consultas.\n\n**Correção:** rode `REFRESH TABLE <table_name>` ou use Delta Lake (que gerencia os metadados automaticamente) em vez de tabelas Parquet/CSV puras.\n\n## Dicas para a prova\n\n- Saiba as três camadas da arquitetura Medallion (Bronze, Silver, Gold) e o propósito de cada uma\n- Entenda a diferença entre data warehouse, data lake e lakehouse — principalmente quanto a suporte ACID e flexibilidade de schema\n- Lembre que Delta Lake = Parquet + transaction log; isso habilita ACID, time travel e operações DML\n- Saiba identificar o namespace de três níveis do Unity Catalog: `catalog.schema.table`\n\n## Pontos-chave\n\n- **O lakehouse combina**: transações ACID e governança forte de um data warehouse com o baixo custo e a flexibilidade de schema de um data lake\n- **Delta Lake**: a base do Lakehouse — arquivos Parquet mais um transaction log; habilita ACID, time travel e MERGE/UPDATE/DELETE\n- **Camadas medallion**: Bronze (ingestão bruta, append-only) → Silver (limpo, deduplicado, schema garantido) → Gold (agregados de negócio, prontos para BI/ML)\n- **Schema enforcement**: comportamento padrão; impede escritas de dados ruins. Habilite evolução com `.option(\"mergeSchema\", \"true\")`\n- **Time travel**: consulte por versão (`versionAsOf`) ou timestamp (`timestampAsOf`) — sem ferramenta externa\n- **Namespace do Unity Catalog**: três níveis — `catalog.schema.table`; oferece segurança por coluna, linhagem e auditoria\n- **ACID via MVCC**: o controle de concorrência multiversão permite leitores e escritores concorrentes sem locks\n\n## Tópicos relacionados\n\n- [Fundamentos do Delta Lake](04-delta-lake-fundamentals.md)\n- [Unity Catalog básico](../07-governance-and-security/01-unity-catalog-basics.md)\n\n## Documentação oficial\n\n- [What is a data lakehouse?](https://docs.databricks.com/aws/en/lakehouse/)\n- [What is Delta Lake?](https://docs.databricks.com/aws/en/delta/)\n- [What is Unity Catalog?](https://docs.databricks.com/aws/en/data-governance/unity-catalog/)\n\n---\n\n**[↑ Voltar para Databricks Intelligence Platform](README.md) | [Próximo: Databricks Workspace →](02-databricks-workspace.md)**\n"},{"id":"01-databricks-intelligence-platform/02-databricks-workspace","folder":"01-databricks-intelligence-platform","group":"modulo","order":2,"isIndex":false,"title":"Databricks Workspace","md":"# Databricks Workspace\n\n## Visão geral\n\nO workspace do Databricks é o ambiente colaborativo para desenvolver, testar e implantar soluções de engenharia de dados. Ele oferece ferramentas unificadas para desenvolvimento em SQL, Python, R e Scala.\n\n> [!abstract] Resumo\n>\n> - O workspace reúne notebooks, arquivos, Git folders, jobs e objetos de dados em uma única interface no navegador\n> - Magic commands (`%sql`, `%python`, `%md`, `%run`, `%pip`) mudam a linguagem ou o comportamento de uma única célula\n> - `dbutils.widgets` parametrizam notebooks para que os Lakeflow Jobs possam passar valores\n\n> [!tip] O que a prova cobra\n>\n> - Apoia a habilidade de componentes centrais do Domínio 1: workspace, notebooks e colaboração\n> - Misturar linguagens em um notebook, e `%run` vs `dbutils.notebook.run()`\n> - A integração com Git (Git folders) é cobrada no Domínio 5. Veja [Git Folders](../05-implementing-cicd/01-git-folders.md)\n\n---\n\n## Arquitetura do Workspace\n\n```mermaid\nflowchart TB\n    subgraph Workspace[\"Databricks Workspace\"]\n        subgraph Home[\"Diretório Home\"]\n            NB1[\"Meu Notebook 1\"]\n            NB2[\"Meu Notebook 2\"]\n        end\n\n        subgraph Shared[\"Pasta Shared\"]\n            NB3[\"Notebook da equipe\"]\n            NB4[\"Dashboard\"]\n        end\n\n        subgraph GitFolders[\"Git folders\"]\n            GIT[\"Integração Git\"]\n            VCS[\"Controle de versão\"]\n        end\n\n        subgraph Clusters[\"Clusters\"]\n            C1[\"Cluster Dev\"]\n            C2[\"Cluster Prod\"]\n        end\n    end\n```\n\n## Organização do Workspace\n\n### Estrutura de diretórios\n\n| Caminho | Propósito | Acesso |\n|------|---------|--------|\n| `/Users/{email}/` | Diretório pessoal (home) | Só você |\n| `/Shared/` | Pasta acessível pela equipe | Todos os usuários do workspace |\n| Git folder (antigo Repo) | Uma pasta do workspace ligada a um repositório Git remoto | Usuários com acesso à pasta |\n\n### Boas práticas\n\n```text\nWorkspace Root/\n├── /Shared/\n│   ├── /datasets/               # Referências de dados compartilhadas\n│   ├── /dashboards/             # Dashboards de BI\n│   ├── /team-notebooks/         # Notebooks colaborativos\n│   └── /production-jobs/        # Definições de jobs\n├── /Shared/git/\n│   └── /data-platform/          # Git folder (antigo Repo) com código de pipeline\n└── /Users/\n    └── {seu-email}/\n        ├── /dev/                # Desenvolvimento pessoal\n        ├── /experiments/        # Análises ad hoc\n        └── /dashboards/         # Dashboards pessoais\n```\n\n## Notebooks\n\nNotebooks são a principal ferramenta de desenvolvimento no Databricks.\n\n### Recursos dos notebooks\n\n- **Múltiplas linguagens**: SQL, Python, R e Scala no mesmo notebook\n- **Magic commands**: controlam o comportamento do notebook\n- **Colaborativo**: edição multiusuário em tempo real\n- **Histórico de versões**: snapshots automáticos de revisões do notebook\n- **Publicação**: compartilhar como HTML ou embutir dashboards\n\n### Magic commands de linguagem\n\n```markdown\n%python  # Muda para Python\n%sql     # Muda para SQL\n%r       # Muda para R\n%scala   # Muda para Scala\n%md      # Formatação Markdown\n%sh      # Comandos de shell\n```\n\n### Recursos-chave dos notebooks\n\n```python\n# Exibir saída formatada\n\ndisplay(df)  # Melhor que df.show()\n\n# Widgets do Databricks para dashboards interativos\n\ndbutils.widgets.text(\"param_name\", \"default_value\")\ndbutils.widgets.dropdown(\"env\", \"dev\", [\"dev\", \"prod\"])\n\n# Ler parâmetros no código\n\nenv = dbutils.widgets.get(\"env\")\n\n# Operações de sistema de arquivos\n\ndbutils.fs.ls(\"/Volumes/main/raw/landing/\")  # Listar arquivos em um volume UC\ndbutils.fs.mv(\"/path/src\", \"/path/dst\")  # Mover arquivos\ndbutils.fs.cp(\"/path/src\", \"/path/dst\", True)  # Copiar recursivamente\n```\n\n## Git Folders (antigo Repos)\n\n**Databricks Git folders** (antigo Databricks Repos) são pastas do workspace ligadas a um repositório Git remoto. Funcionam como um cliente Git visual para criar branches, fazer commit e push, pull, merge e resolver conflitos pela interface do workspace. A prova cobra esse fluxo no **Domínio 5 — Implementing CI/CD**. Veja [Git Folders](../05-implementing-cicd/01-git-folders.md) para o fluxo completo branch → commit & push → pull request.\n\n### Estratégia de branches para engenharia de dados\n\n```text\nmain (produção)\n├── dev\n│   ├── feature/new-pipeline\n│   └── feature/optimization\n├── staging\n└── hotfix/urgent-fix\n```\n\n## Clusters\n\nClusters fornecem o compute para executar notebooks e jobs.\n\n### Tipos de cluster\n\n| Tipo | Caso de uso | Duração |\n|------|----------|----------|\n| **All-Purpose** | Desenvolvimento interativo | Horas a dias |\n| **Jobs** | Batch/streaming automatizado | Minutos a horas |\n| **SQL Warehouse** | Consultas SQL e ferramentas de BI | Sempre ligado |\n\n### Personal Compute (cluster de usuário único)\n\n```text\n# Inicialização mais rápida para uso pessoal\n\nConfiguração:\n- Um único nó worker\n- Bibliotecas pré-instaladas\n- Não compartilhado com ninguém\n```\n\n### Cluster compartilhado\n\n```text\n# Para colaboração em equipe\n\nConfiguração:\n- Vários workers\n- Bibliotecas compartilhadas\n- Audit logging habilitado\n```\n\n## Recursos de colaboração\n\n### Colaboração em tempo real\n\n```text\nAlice abre o notebook → Bob abre o mesmo notebook\n→ Ambos veem as posições do cursor\n→ Edições aparecem em tempo real\n→ Mudanças compatíveis são mescladas automaticamente\n```\n\n### Comentários e discussão\n\n```markdown\n<!-- Comentários inline nas células -->\nClique na célula → ícone de Comentários → Adicionar comentário\n@mencione membros da equipe para notificá-los\nResolva os comentários quando tratados\n```\n\n### Compartilhamento de notebooks\n\n- **Somente leitura**: link para acesso de leitura\n- **Permissão de edição**: concede direito de edição\n- **Compartilhamento de pasta**: herança de permissões\n\n## Administração e segurança\n\n### Controle de acesso\n\n```text\nAdmins podem controlar:\n- Gestão de usuários e grupos\n- Recursos do workspace (notebooks, clusters, jobs)\n- Acesso a dados via UC (Unity Catalog)\n- Conectividade externa\n```\n\n### Autenticação multifator (MFA)\n\n```text\nAdmin console → Security\n→ Exigir MFA para todos os usuários\n→ Suporte a provisionamento SCIM\n```\n\n### Logs de auditoria\n\n```text\nWorkspace Admin Console → Audit log\nRegistra:\n- Quem acessou o quê, e quando\n- Atividades de login/logout\n- Criação/exclusão de recursos\n- Mudanças de configuração\n```\n\n## Tarefas comuns no workspace\n\n1. **Criar um notebook**: `Workspace > Create > Notebook`\n2. **Executar um notebook**: `Run all` ou `Ctrl+Alt+Enter`\n3. **Exportar notebook**: baixar como DBC, PDF ou HTML\n4. **Mover notebook**: arrastar para a pasta ou usar `Move`\n5. **Clonar notebook**: botão direito > `Clone`\n6. **Publicar notebook**: compartilhar como dashboard HTML\n\n## Casos de uso\n\n- **Desenvolvimento colaborativo em notebooks**: vários engenheiros trabalham ao mesmo tempo em notebooks compartilhados durante a sprint, usando coedição em tempo real e comentários inline para code review.\n- **Pipelines de CI/CD integrados ao Git**: uso de Git folders (antigo Repos) para conectar notebooks ao GitHub/GitLab, permitindo fluxos de pull request, desenvolvimento por branch e testes automatizados antes de promover o código para produção.\n\n## Problemas e erros comuns\n\n### Valor padrão do widget usado em vez do valor do job\n\n**Cenário:** um notebook executado por um Lakeflow Job continua processando a data padrão do widget em vez da data passada pelo job.\n**Correção:** o nome do parâmetro da task precisa ser exatamente igual ao nome do widget (`dbutils.widgets.get(\"run_date\")` lê um parâmetro `run_date`). Confira os parâmetros da task nos detalhes da execução.\n\n### Timeout da sessão do notebook\n\n**Cenário:** a sessão do notebook expira após inatividade e o trabalho não salvo nas células é perdido.\n**Correção:** mantenha o código em um Git folder (antigo Repos) e faça commits frequentes, para que as mudanças estejam sempre salvas no Git ([Git Folders](../05-implementing-cicd/01-git-folders.md)).\n\n## Dicas para a prova\n\n- Saiba a diferença entre o diretório Home (`/Users/{email}/`), a pasta Shared e os Git folders (antigo Repos)\n- Entenda os magic commands (`%python`, `%sql`, `%md` etc.) para trocar de linguagem dentro de um notebook\n- Global temporary views usam o banco `global_temp` e persistem entre sessões (no mesmo cluster); temp views comuns têm escopo de sessão\n\n## Pontos-chave\n\n- **Isolamento de workspace**: cada workspace é independente\n- **Permissões de objetos do workspace** (notebooks, pastas) são separadas dos privilégios de dados do Unity Catalog\n- **Versões de notebook**: o histórico de revisões é salvo automaticamente\n- **Git folders** (antigo Repos): integração Git para código de produção. Cobrado no Domínio 5\n- **Suporte multilinguagem**: SQL + Python no mesmo notebook\n\n## Tópicos relacionados\n\n- [Arquitetura Lakehouse](01-lakehouse-architecture.md)\n- [Compute e Clusters](03-compute-clusters.md)\n\n## Documentação oficial\n\n- [Navigate the workspace](https://docs.databricks.com/aws/en/workspace/)\n- [Databricks notebooks](https://docs.databricks.com/aws/en/notebooks/)\n- [Databricks Git folders](https://docs.databricks.com/aws/en/repos/)\n\n---\n\n**[← Anterior: Arquitetura Lakehouse](01-lakehouse-architecture.md) | [↑ Voltar para Databricks Intelligence Platform](README.md) | [Próximo: Compute e Clusters →](03-compute-clusters.md)**\n"},{"id":"01-databricks-intelligence-platform/03-compute-clusters","folder":"01-databricks-intelligence-platform","group":"modulo","order":3,"isIndex":false,"title":"Compute e Clusters","md":"# Compute e Clusters\n\n## Visão geral\n\nClusters de compute fornecem poder de processamento escalável para notebooks e jobs. Entender os tipos de cluster, a configuração e os custos é essencial para engenheiros de dados.\n\n> [!abstract] Resumo\n>\n> - **All-purpose compute** é interativo e compartilhável. **Jobs compute** é criado por execução e encerrado ao final\n> - **Serverless compute** (notebooks, jobs, pipelines) é gerenciado pela Databricks, inicia rápido e sempre roda o runtime mais recente\n> - **SQL warehouses**: serverless (início em ~2–6 s, recomendado), pro e classic. Escalam adicionando clusters para atender concorrência\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: entender os serviços de compute, suas características, limitações e modelos de custo, e escolher a melhor opção para um workload\n> - Cenário clássico: muitos usuários concorrentes rodando SQL ad hoc em tabelas curadas → **serverless SQL warehouse** com autoscaling\n> - Alavancas de custo: job vs all-purpose compute, auto termination, pools, instâncias spot, serverless pay-per-use\n\n---\n\n## Arquitetura do cluster\n\n```mermaid\nflowchart TD\n    User[\"Desenvolvedor/Usuário\"]\n\n    subgraph Cluster[\"Cluster Spark\"]\n        Driver[\"Nó Driver\"]\n        W1[\"Worker 1\"]\n        W2[\"Worker 2\"]\n        W3[\"Worker 3\"]\n    end\n\n    Storage[(\"Storage distribuído<br/>S3 / ADLS / GCS\")]\n\n    User -->|Submete job| Driver\n    Driver -->|Agenda tasks| W1\n    Driver -->|Agenda tasks| W2\n    Driver -->|Agenda tasks| W3\n    W1 --> Storage\n    W2 --> Storage\n    W3 --> Storage\n```\n\n## Serviços de compute em resumo\n\n| Compute | Quem gerencia | Inicialização | Workload típico | Modelo de custo |\n| :--- | :--- | :--- | :--- | :--- |\n| **Serverless compute** (notebooks, jobs, Lakeflow pipelines) | A Databricks. Os recursos não são provisionados na sua conta de nuvem | Rápida | A maioria dos novos notebooks, jobs e pipelines | DBUs pelo trabalho feito, com tempo ocioso minimizado. Acompanhe em `system.billing.usage` |\n| **All-purpose compute** (classic) | Você: tipos de nó, workers, runtime, políticas | Minutos | Desenvolvimento interativo, exploração compartilhada | DBUs mais custo de VM na nuvem enquanto roda, incluindo o tempo ocioso até o auto termination |\n| **Jobs compute** (classic) | Você define no job; é criado para a execução e encerrado no fim | Minutos (mais rápido a partir de um pool) | Jobs de produção agendados | Paga só enquanto a execução roda. Tem SKU de jobs separado (mais barato) do all-purpose ([preços](https://www.databricks.com/product/pricing)) |\n| **SQL warehouse** — serverless / pro / classic | Serverless: Databricks. Pro/classic: sua conta de nuvem | Serverless ~2–6 s; pro/classic ~4 min | Dashboards de BI, SQL ad hoc, muitos usuários concorrentes | DBUs por tamanho de warehouse enquanto roda; auto stop encerra a cobrança ociosa |\n| **Instance pool** | Você | Segundos para clusters que usam instâncias já aquecidas | Clusters classic que precisam iniciar rápido | Você paga ao provedor de nuvem pelas instâncias ociosas no pool |\n\nUma **DBU** (Databricks Unit) \"é uma unidade normalizada de poder de processamento\" usada para medição e precificação, cobrada com granularidade por segundo ([Databricks pricing](https://www.databricks.com/product/pricing)). Ela **não** é \"uma hora em um worker\". A taxa de DBU depende do tipo de compute e do tamanho da instância.\n\n### Serverless compute\n\n- \"Serverless compute está disponível por padrão na maioria dos workspaces e não requer habilitação\". Workspaces sem Unity Catalog precisam ser atualizados antes\n- **Versionless**: \"workloads serverless sempre rodam na versão mais recente do runtime\"\n- Bibliotecas são gerenciadas com **environments**, não com bibliotecas de cluster. A maioria das propriedades Spark não pode ser definida (veja [Spark Tuning Parameters](../03-data-transformation-and-modeling/07-spark-tuning-parameters.md))\n- Estime o custo fazendo benchmark de um workload representativo e consultando `system.billing.usage`. As cobranças podem levar até 24 horas para aparecer\n\nFonte: [Connect to serverless compute](https://docs.databricks.com/aws/en/compute/serverless/).\n\n### Configuração de classic compute\n\n| Configuração | O que a documentação diz |\n| :--- | :--- |\n| **Access mode** | **Auto** (padrão) escolhe **Standard**, a menos que você escolha runtime ML, GPU ou DBR abaixo de 14.3 — nesse caso escolhe **Dedicated**. Standard = vários usuários com isolamento (Python, SQL, Scala). Dedicated = um usuário ou grupo (adiciona R) |\n| **Runtime** | Versão mais recente para all-purpose. Uma versão **LTS** para jobs operacionais. O runtime **ML** para data science |\n| **Photon** | Habilitado por padrão a partir do DBR 9.1 LTS |\n| **Autoscaling** | Mínimo e máximo de workers. Não habilite também `spark.dynamicAllocation.enabled` |\n| **Auto termination** | Período de inatividade de 10–10.000 minutos (0 desativa) |\n| **Instâncias spot** | O driver é sempre on-demand. Workers podem usar spot |\n| **Single node** | Sem workers. O Spark roda localmente no driver, para dados pequenos e bibliotecas de máquina única |\n\nFonte: [Compute configuration reference](https://docs.databricks.com/aws/en/compute/configure), [Manage classic compute](https://docs.databricks.com/aws/en/compute/clusters-manage).\n\n### Tipos de SQL warehouse\n\n| Tipo | Photon | Predictive I/O | Intelligent Workload Management | Inicialização |\n| :--- | :---: | :---: | :---: | :--- |\n| **Serverless** | Sim | Sim | Sim | ~2–6 segundos |\n| **Pro** | Sim | Sim | Não | ~4 minutos |\n| **Classic** | Sim | Não | Não | ~4 minutos |\n\n- A Databricks recomenda **serverless** para ETL, BI e análise exploratória, \"especialmente quando a demanda de consultas varia muito\"\n- **Escala**: o padrão é mínimo e máximo de um cluster. Aumente o máximo para atender mais usuários concorrentes\n- **Auto stop** padrão: 10 minutos (serverless), 45 minutos (pro e classic)\n\nFontes: [SQL warehouse types](https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-types), [Create a SQL warehouse](https://docs.databricks.com/aws/en/compute/sql-warehouse/create).\n\n## Escolhendo o compute para um workload\n\n| Cenário | Melhor escolha | Por que não as outras |\n| :--- | :--- | :--- |\n| Muitos analistas rodando SQL ad hoc em tabelas Delta curadas o dia todo | **Serverless SQL warehouse** com autoscaling (aumente o max clusters) | Job compute é para ETL agendado. Um cluster all-purpose fixo não equilibra concorrência e custo |\n| Notebook de ETL noturno sem ninguém acompanhando | **Serverless jobs** ou **jobs compute** | All-purpose continua cobrando entre comandos e é feito para uso interativo |\n| Exploração interativa e debugging | **Serverless notebook** ou **all-purpose compute** | Jobs compute só existe durante uma execução |\n| Dataset pequeno, pandas ou scikit-learn | Compute **single-node** | Workers adicionam custo sem benefício |\n| Job classic que precisa iniciar em segundos | **Instance pool** (ou serverless) | Um cluster classic \"frio\" leva minutos para provisionar |\n| Código precisa de R, GPU ou init script customizado | Compute **classic** (access mode dedicated quando necessário) | Serverless não expõe esses controles |\n\n## Ciclo de vida do cluster\n\n```mermaid\nstateDiagram-v2\n    [*] --> Pending: Criar ou iniciar\n    Pending --> Running: Nós provisionados, Spark iniciado\n    Running --> Restarting: Reiniciar\n    Restarting --> Running\n    Running --> Terminating: Auto termination ou usuário para\n    Terminating --> Terminated\n    Terminated --> Pending: Iniciar de novo (mesmo cluster ID)\n```\n\n- \"Quando você inicia um compute encerrado, a Databricks recria o compute com o mesmo ID\", reinstala as bibliotecas e reanexa os notebooks\n- O **event log** do compute mantém eventos de ciclo de vida por 60 dias. Falhas de inicialização são tratadas em [Compute Troubleshooting](../06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting.md)\n\n## Otimização de custo\n\n| Alavanca | Efeito |\n| :--- | :--- |\n| Jobs compute ou serverless para trabalho agendado | Não paga por clusters interativos ociosos |\n| Auto termination no all-purpose | Impede que clusters esquecidos rodem a noite toda |\n| Auto stop nos SQL warehouses | Encerra a cobrança após o período ocioso |\n| Workers spot | Capacidade mais barata e interrompível para trabalho tolerante a falhas. O driver fica on-demand |\n| Pools | Inicialização mais rápida. Instâncias ociosas do pool ainda custam VM na nuvem |\n| Compute policies | Admins limitam tipos de nó, quantidade de workers e configurações |\n| `system.billing.usage` | Descobre quais jobs, warehouses e usuários geram gasto |\n\n## Casos de uso\n\n- **Dimensionamento correto para otimizar custo**: escolher tipos de nó e faixas de autoscaling adequados, com base no perfil do workload, equilibrando performance e custo para desenvolvimento interativo e jobs de produção.\n- **Pools para inicialização rápida**: pré-provisionar instâncias ociosas em pools para que job clusters subam em menos de um minuto, cumprindo SLAs apertados.\n\n## Problemas e erros comuns\n\n### Jobs agendados rodando em all-purpose compute\n\n**Cenário:** jobs noturnos estão anexados a um cluster all-purpose compartilhado que fica ligado o dia inteiro, e a conta mensal é alta.\n**Correção:** rode trabalho agendado em serverless jobs ou jobs compute, que só existem durante a execução. Mantenha all-purpose para trabalho interativo e configure auto termination.\n\n### Auto termination derruba jobs longos\n\n**Cenário:** a configuração de auto termination de um cluster o desliga enquanto um job longo ainda roda, fazendo o job falhar.\n**Correção:** aumente o timeout de auto termination dos clusters interativos que rodam workloads longos, ou use job clusters dedicados, que só encerram quando o job termina.\n\n### Atraso na inicialização do cluster\n\n**Cenário:** job clusters levam 5–10 minutos para provisionar, gerando latência inaceitável para pipelines sensíveis a tempo.\n**Correção:** use serverless jobs compute, ou um instance pool para que clusters classic usem instâncias pré-aquecidas.\n\n## Dicas para a prova\n\n- Muitos usuários concorrentes de SQL ad hoc → **serverless SQL warehouse** com autoscaling. ETL agendado → serverless jobs ou jobs compute\n- Jobs compute é criado para uma execução e encerrado depois, então você nunca paga por tempo interativo ocioso\n- Uma DBU é uma unidade normalizada de poder de processamento, cobrada por segundo. Não é \"uma hora em um worker\"\n- Serverless SQL warehouses iniciam em segundos. Pro e classic levam minutos\n- Instâncias spot se aplicam aos workers. O driver é sempre on-demand\n\n## Pontos-chave\n\n- **Serverless** (notebooks, jobs, pipelines, SQL warehouses) é gerenciado pela Databricks, inicia rápido e sempre roda o runtime mais recente\n- **All-purpose** é para trabalho interativo. **Jobs compute** é para execuções agendadas\n- **SQL warehouses**: serverless é o recomendado. Escale com max clusters para concorrência\n- **Alavancas de custo**: auto termination, auto stop, workers spot, pools, policies e `system.billing.usage`\n\n## Tópicos relacionados\n\n- [Databricks Workspace](02-databricks-workspace.md)\n- [Spark Tuning Parameters](../03-data-transformation-and-modeling/07-spark-tuning-parameters.md)\n\n## Documentação oficial\n\n- [Compute configuration reference](https://docs.databricks.com/aws/en/compute/configure)\n- [Connect to serverless compute](https://docs.databricks.com/aws/en/compute/serverless/)\n- [SQL warehouse types](https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-types)\n- [Databricks pricing](https://www.databricks.com/product/pricing)\n\n---\n\n**[← Anterior: Databricks Workspace](02-databricks-workspace.md) | [↑ Voltar para Databricks Intelligence Platform](README.md) | [Próximo: Fundamentos do Delta Lake →](04-delta-lake-fundamentals.md)**\n"},{"id":"01-databricks-intelligence-platform/04-delta-lake-fundamentals","folder":"01-databricks-intelligence-platform","group":"modulo","order":4,"isIndex":false,"title":"Fundamentos do Delta Lake","md":"# Fundamentos do Delta Lake\n\n## Visão geral\n\nO Delta Lake é uma camada de armazenamento open source que traz transações ACID, linhagem de dados e processamento unificado de streaming/batch para data lakes. Ele fica sobre o cloud storage (S3, ADLS, GCS) e complementa o Apache Spark.\n\n> [!abstract] Resumo\n>\n> - Uma tabela Delta é composta por arquivos de dados Parquet mais um transaction log `_delta_log`, o que dá transações ACID sobre object storage\n> - Schema enforcement rejeita escritas com schema incompatível. Schema evolution (`mergeSchema`) adiciona colunas de forma intencional\n> - DML completo: `INSERT`, `UPDATE`, `DELETE` e `MERGE INTO` para upserts\n\n> [!tip] O que a prova cobra\n>\n> - Apoia a habilidade do Domínio 1 sobre componentes centrais (Delta Lake)\n> - Ler a sintaxe de `MERGE` e escolher `MERGE` em vez de `INSERT` para evitar duplicatas\n> - Managed vs external tables são cobradas no Domínio 7. Veja [Managed and External Tables](../07-governance-and-security/02-managed-and-external-tables.md)\n\n---\n\n## O que é o Delta Lake?\n\n```mermaid\nflowchart TB\n    subgraph Traditional[\"Data Lake tradicional\"]\n        ParquetFiles[\"Arquivos Parquet\"]\n        NoACID[\"Sem garantias ACID\"]\n        Corruption[\"Problemas de corrupção\"]\n    end\n\n    subgraph DeltaLake[\"Delta Lake\"]\n        DeltaFormat[\"Formato Delta<br/>(Parquet + Log)\"]\n        ACID[\"Transações ACID\"]\n        Schema[\"Schema Enforcement\"]\n        Lineage[\"Linhagem de dados\"]\n        TimeTavel[\"Time Travel\"]\n    end\n\n    Traditional -.->|Upgrade| DeltaLake\n\n    DeltaLake --> Features[\"Melhor qualidade<br/>e confiabilidade\"]\n```\n\n## Por que o Delta Lake importa\n\n| Desafio | Data Lake legado | Delta Lake |\n|-----------|---|---|\n| **Atualizações concorrentes** | Falham, corrompem dados | ACID garante consistência |\n| **Evolução de schema** | Versionamento manual | Schema enforcement/evolution embutidos |\n| **Debugging** | Dados perdidos, sem histórico | Trilha de auditoria completa via log |\n| **Dados atrasados (late data)** | Reescreve a tabela inteira | UPSERT eficiente via MERGE |\n| **Exclusões acidentais** | Perda permanente | Time travel para recuperar |\n| **Performance** | Variável, consultas lentas | Otimizado com estatísticas |\n\n## Arquitetura do Delta Lake\n\n```mermaid\nflowchart LR\n    subgraph CloudStorage[\"Cloud Storage<br/>(S3/ADLS/GCS)\"]\n        Parquet[\"Arquivos de dados Parquet\"]\n        Log[\"Transaction Log<br/>(_delta_log/)\"]\n    end\n\n    subgraph Engine[\"Spark/Databricks\"]\n        Read[\"Engine de leitura\"]\n        Write[\"Engine de escrita\"]\n    end\n\n    CloudStorage <-->|ACID| Engine\n```\n\nA tabela Delta é composta por:\n\n- **Arquivos de dados**: formato Parquet (em `/path/to/table/`)\n- **Transaction log**: arquivos JSON que registram todas as mudanças (em `/path/to/table/_delta_log/`)\n\n## Transações ACID\n\n### Garantias ACID\n\n- **Atomicidade**: escritas tudo-ou-nada; sem commits parciais\n- **Consistência**: restrições de schema e de dados garantidas\n- **Isolamento**: vários leitores e escritores não interferem entre si\n- **Durabilidade**: escritas confirmadas nunca são perdidas\n\n### Exemplo: proteção ACID\n\n```python\n\n# Parquet tradicional - sem ACID\n# Se a escrita falhar no meio, os dados ficam corrompidos\n\ndf.write.format(\"parquet\").mode(\"overwrite\").save(\"/path\")\n\n# Delta Lake - protegido por ACID\n# Se a escrita falhar, a tabela volta ao estado anterior automaticamente\n\ndf.write.format(\"delta\").mode(\"overwrite\").save(\"/path\")\n```\n\n## Formatos de tabela Delta\n\n### Managed tables (padrão)\n\n```python\n# Dados armazenados em diretório gerenciado pela Databricks\n\nspark.sql(\"\"\"\nCREATE TABLE employees (\n    id INT,\n    name STRING,\n    salary DECIMAL(10, 2)\n)\nUSING DELTA\n\"\"\")\n\n# Remover a tabela também apaga os dados\n\nspark.sql(\"DROP TABLE employees\")  # Dados apagados\n```\n\n### External tables\n\n```python\n# Dados armazenados em um local externo que você controla\n\nspark.sql(\"\"\"\nCREATE TABLE employees_external (\n    id INT,\n    name STRING,\n    salary DECIMAL(10, 2)\n)\nUSING DELTA\nLOCATION '/mnt/data/employees'\n\"\"\")\n\n# Remover a tabela NÃO apaga os dados\n\nspark.sql(\"DROP TABLE employees_external\")  # Dados permanecem\n```\n\n## Criando tabelas Delta\n\n### A partir de um DataFrame\n\n```python\nemployees_df = spark.createDataFrame([\n    (1, \"Alice\", 85000),\n    (2, \"Bob\", 75000)\n], [\"id\", \"name\", \"salary\"])\n\n(employees_df.write\n    .format(\"delta\")\n    .mode(\"overwrite\")\n    .save(\"/mnt/data/employees\"))\n\n# Ou criar uma managed table\n\n(employees_df.write\n    .format(\"delta\")\n    .mode(\"overwrite\")\n    .saveAsTable(\"employees\"))\n```\n\n### Converter Parquet existente\n\n```python\nfrom delta.tables import DeltaTable\n\nDeltaTable.convertToDelta(\n    spark,\n    \"parquet.`/path/to/parquet/data`\"\n)\n\n# A tabela agora tem transaction log e garantias ACID\n```\n\n### Usando SQL\n\n```sql\n-- Criar nova tabela Delta\nCREATE TABLE products (\n    product_id INT,\n    name STRING,\n    price DECIMAL(10, 2),\n    category STRING\n)\nUSING DELTA;\n\n-- Criar a partir do resultado de uma consulta (CTAS)\nCREATE TABLE high_earners AS\nSELECT name, salary\nFROM employees\nWHERE salary > 100000;\n\n-- Criar tabela Delta externa\nCREATE TABLE orders (\n    order_id INT,\n    customer_id INT,\n    amount DECIMAL(10, 2)\n)\nUSING DELTA\nLOCATION '/mnt/data/orders';\n```\n\n## Metadados da tabela\n\n### Inspecionando informações\n\n```python\nspark.sql(\"DESCRIBE TABLE employees\").show()           # colunas\nspark.sql(\"DESCRIBE TABLE EXTENDED employees\").show()  # detalhes (local, tipo, provider)\nspark.sql(\"SHOW TABLES\").show()                        # listar tabelas\nspark.sql(\"SHOW TBLPROPERTIES employees\").show()       # propriedades\n```\n\n### Propriedades de tabela Delta\n\n```python\nspark.sql(\"\"\"\nALTER TABLE employees\nSET TBLPROPERTIES (\n    'delta.dataSkippingNumIndexedCols' = '32',\n    'delta.columnMapping.mode' = 'name'\n)\n\"\"\")\n```\n\n## Append vs Overwrite\n\n### Modo append\n\n```python\n# Adiciona novas linhas à tabela existente\n(new_employees.write\n    .format(\"delta\")\n    .mode(\"append\")\n    .save(\"/mnt/data/employees\"))\n```\n\n### Modos de overwrite\n\n```python\n# Sobrescreve todos os dados\n(updated_data.write.format(\"delta\").mode(\"overwrite\").save(\"/mnt/data/employees\"))\n\n# Erro se o schema não bater\n(updated_data.write.format(\"delta\").mode(\"append\").save(\"/mnt/data/employees\"))\n\n# Mescla schemas (adiciona novas colunas)\n(updated_data.write\n    .format(\"delta\")\n    .mode(\"append\")\n    .option(\"mergeSchema\", \"true\")\n    .save(\"/mnt/data/employees\"))\n```\n\n## Schema enforcement e evolution\n\n### Schema enforcement (impedir dados ruins)\n\n```python\n# Schema da tabela: id INT, name STRING, salary DECIMAL\n# Tentar escrever schema errado -> ERRO\n\nbad_data = spark.createDataFrame([\n    (\"Alice\", \"Not a number\", 85000)  # Tipos errados\n], [\"name\", \"salary\", \"bonus\"])\n\n(bad_data.write\n    .format(\"delta\")\n    .mode(\"append\")\n    .save(\"/mnt/data/employees\"))  # Falha!\n```\n\n### Schema evolution (adicionar colunas)\n\n```python\n# Tabela tem: id, name, salary\n# Novos dados trazem a coluna department\n\nnew_schema_data = spark.createDataFrame([\n    (1, \"Alice\", 85000, \"Engineering\")\n], [\"id\", \"name\", \"salary\", \"department\"])\n\n(new_schema_data.write\n    .format(\"delta\")\n    .mode(\"append\")\n    .option(\"mergeSchema\", \"true\")\n    .save(\"/mnt/data/employees\"))\n\n# A tabela agora tem: id, name, salary, department\n```\n\n## Operações de modificação (DML)\n\n### INSERT\n\n```sql\nINSERT INTO employees VALUES (4, \"David\", 80000);\n\nINSERT INTO employees\nSELECT id, name, salary FROM new_hires;\n```\n\n### UPDATE\n\n```sql\nUPDATE employees\nSET salary = salary * 1.1\nWHERE department = 'Engineering';\n```\n\n### DELETE\n\n```sql\nDELETE FROM employees\nWHERE salary < 30000;\n```\n\n### MERGE (upsert)\n\n```sql\nMERGE INTO employees t\nUSING new_employees s\nON t.id = s.id\nWHEN MATCHED THEN UPDATE SET *\nWHEN NOT MATCHED THEN INSERT *;\n```\n\n## Comparação: Delta vs Parquet vs Iceberg\n\n| Recurso | Delta Lake | Parquet | Apache Iceberg |\n|---------|-----------|---------|---|\n| **ACID** | Sim | Não | Sim |\n| **Evolução de schema** | Sim | Limitada | Sim |\n| **Time Travel** | Sim | Não | Sim |\n| **Governança** | Forte | Fraca | Forte |\n| **Performance** | Otimizada | Boa | Boa |\n| **Adoção** | Muito alta | A mais alta | Crescendo |\n\n## Detalhes do transaction log\n\nO diretório `_delta_log/` contém arquivos JSON que registram cada transação:\n\n```json\n{\n  \"add\": {\n    \"path\": \"part-00000-abc123.parquet\",\n    \"size\": 1024000,\n    \"modificationTime\": 1684756800000,\n    \"dataChange\": true\n  }\n}\n```\n\nCada arquivo JSON representa uma transação confirmada (commit), permitindo:\n\n- Atomicidade (tudo-ou-nada)\n- Consistência (validação de schema)\n- Isolamento (concorrência multiversão)\n- Durabilidade (registro permanente)\n\n## Casos de uso\n\n- **Transações ACID para pipelines concorrentes**: vários jobs de ETL escrevem com segurança na mesma tabela Delta ao mesmo tempo, contando com o ACID para evitar corrupção e escritas parciais.\n- **Schema enforcement na ingestão**: usar o schema enforcement do Delta para rejeitar registros malformados na escrita, impedindo que dados ruins entrem no lakehouse e detectando cedo mudanças de schema na origem.\n\n## Problemas e erros comuns\n\n### Problema de arquivos pequenos (small files)\n\n**Cenário:** escritas frequentes em micro-batch deixam as leituras lentas.\n**Correção:** rode `OPTIMIZE` regularmente (com Z-ORDER ou, de preferência, Liquid Clustering).\n\n### Acúmulo de arquivos pequenos por escritas frequentes\n\n**Cenário:** streaming em micro-batch ou appends frequentes criam milhares de arquivos Parquet pequenos, degradando muito a leitura.\n**Correção:** habilite `spark.databricks.delta.optimizeWrite.enabled = true` para agrupar arquivos na escrita e rode `OPTIMIZE` periodicamente para compactar arquivos pequenos.\n\n### VACUUM apagando arquivos usados por consultas ativas\n\n**Cenário:** rodar `VACUUM` com retenção curta remove arquivos ainda lidos por consultas longas, que falham com `FileNotFoundException`.\n**Correção:** garanta que a retenção do VACUUM seja maior que a duração da consulta ativa mais longa. A retenção padrão de 7 dias é segura para a maioria dos workloads.\n\n## Dicas para a prova\n\n- Delta Lake = arquivos Parquet + transaction log `_delta_log/` — saiba essa estrutura\n- Managed tables: `DROP TABLE` apaga metadados e dados; External tables: `DROP TABLE` apaga apenas os metadados\n- Schema enforcement é o comportamento padrão; `.option(\"mergeSchema\", \"true\")` habilita schema evolution\n- MERGE (upsert) é um recurso-chave do Delta Lake — entenda a sintaxe `WHEN MATCHED` / `WHEN NOT MATCHED`\n\n## Pontos-chave\n\n- **Delta Lake**: camada de armazenamento que adiciona ACID, governança e performance a data lakes\n- **Managed tables**: dados em diretório gerenciado, apagados junto com a tabela\n- **External tables**: dados em local externo, persistem após o DROP da tabela\n- **mergeSchema**: permite novas colunas durante o append\n- **Garantias ACID**: Atomicidade, Consistência, Isolamento, Durabilidade\n- **Transaction log**: `_delta_log/` mantém o histórico completo\n- **Schema enforcement**: impede dados ruins, garante tipos\n- **Schema evolution**: adição controlada de colunas via mergeSchema\n\n## Tópicos relacionados\n\n- [Time Travel e Versionamento](05-time-travel-versioning.md)\n- [Otimização do Delta Lake](../06-troubleshooting-monitoring-and-optimization/03-delta-optimization.md)\n\n## Documentação oficial\n\n- [Delta Lake Documentation](https://docs.databricks.com/en/delta/index.html)\n- [Delta Lake Table Properties](https://docs.databricks.com/en/delta/table-properties.html)\n\n---\n\n**[← Anterior: Compute e Clusters](03-compute-clusters.md) | [↑ Voltar para Databricks Intelligence Platform](README.md) | [Próximo: Time Travel e Versionamento →](05-time-travel-versioning.md)**\n"},{"id":"01-databricks-intelligence-platform/05-time-travel-versioning","folder":"01-databricks-intelligence-platform","group":"modulo","order":5,"isIndex":false,"title":"Time Travel e Versionamento","md":"# Time Travel e Versionamento\n\n## Visão geral\n\nO Delta Lake mantém o histórico completo de todas as mudanças no seu transaction log. Isso habilita time travel (consultar dados históricos), versionamento, rollback e operações de clone — recursos que os formatos de dados tradicionais não têm.\n\n> [!abstract] Resumo\n>\n> - Cada commit cria uma nova versão da tabela. `DESCRIBE HISTORY` lista as versões\n> - `VERSION AS OF` / `TIMESTAMP AS OF` consultam uma versão antiga, e `RESTORE TABLE` faz a tabela voltar\n> - `VACUUM` apaga arquivos não referenciados e limita até onde o time travel consegue voltar\n\n> [!tip] O que a prova cobra\n>\n> - Apoia a habilidade de componentes centrais do Domínio 1: rollback confiável após uma ingestão ruim e trilha de auditoria das mudanças\n> - `VERSION AS OF 7` (número da versão) vs `TIMESTAMP AS OF` (ponto no tempo)\n> - Shallow vs deep clone, e por que o `VACUUM` quebra o time travel\n\n---\n\n## Transaction log e versionamento\n\n```mermaid\nflowchart LR\n    T0[\"Versão 0<br/>Carga inicial<br/>1000 linhas\"]\n    T1[\"Versão 1<br/>Insere 100 linhas<br/>1100 linhas\"]\n    T2[\"Versão 2<br/>Atualiza salários<br/>1100 linhas\"]\n    T3[\"Versão 3<br/>Apaga 10 linhas<br/>1090 linhas\"]\n\n    T0 -->|delta_log/00...json| T1\n    T1 -->|delta_log/01...json| T2\n    T2 -->|delta_log/02...json| T3\n\n    AccessPoint[\"Consultar qualquer versão\"]\n\n    T0 -.->|Time Travel| AccessPoint\n    T1 -.->|Time Travel| AccessPoint\n    T2 -.->|Time Travel| AccessPoint\n    T3 -.->|Time Travel| AccessPoint\n```\n\n## Vendo o histórico de versões\n\n### DESCRIBE HISTORY\n\n```sql\nDESCRIBE HISTORY employees\n\n-- Saída: version, timestamp, userId, userName, operation, operationParameters, cluster_id\n```\n\n```python\nhistory_df = spark.sql(\"DESCRIBE HISTORY employees\")\nhistory_df.show()\n```\n\n### Detalhes das versões\n\n```sql\nSELECT version, timestamp, operation, operationParameters\nFROM (DESCRIBE HISTORY employees)\nORDER BY version DESC\nLIMIT 10;\n```\n\n## Consultas com time travel\n\n### Por número de versão\n\n```python\ndf_v0 = (spark.read\n    .format(\"delta\")\n    .option(\"versionAsOf\", 0)\n    .load(\"/mnt/data/employees\"))\n\ndf_v5 = (spark.read\n    .format(\"delta\")\n    .option(\"versionAsOf\", 5)\n    .load(\"/mnt/data/employees\"))\n\ndf_v0.count()  # 1000 linhas\ndf_v5.count()  # 1150 linhas\n```\n\n### Por timestamp\n\n```python\ndf_past = (spark.read\n    .format(\"delta\")\n    .option(\"timestampAsOf\", \"2025-01-15T10:30:00Z\")\n    .load(\"/mnt/data/employees\"))\n```\n\n### Time travel em SQL\n\n```sql\n-- Por versão\nSELECT * FROM employees VERSION AS OF 5;\nSELECT * FROM employees@v5;\n\n-- Por timestamp\nSELECT * FROM employees TIMESTAMP AS OF '2025-01-15T10:30:00Z';\nSELECT * FROM employees@'2025-01-15';\n```\n\n## Recuperação de dados e rollback\n\n### Restaurar para uma versão anterior\n\n```sql\n-- Restaurar a tabela para a versão 5\nRESTORE TABLE employees TO VERSION AS OF 5;\n\n-- Restaurar para um timestamp\nRESTORE TABLE employees TO TIMESTAMP AS OF '2025-01-15';\n```\n\n```python\nfrom delta.tables import DeltaTable\n\ndelta_table = DeltaTable.forPath(spark, \"/mnt/data/employees\")\ndelta_table.restoreToVersion(5)\n```\n\n### Exemplo completo de rollback\n\n```python\n# Cenário: DELETE acidental de 100 linhas\n\nspark.sql(\"SELECT COUNT(*) FROM employees\").show()  # 900 linhas (ops!)\n\n# Encontrar a versão antes do delete\nspark.sql(\"DESCRIBE HISTORY employees\").show(20)  # Versão 10 tinha 1000 linhas\n\n# Restaurar\nspark.sql(\"RESTORE TABLE employees TO VERSION AS OF 10\")\n\nspark.sql(\"SELECT COUNT(*) FROM employees\").show()  # 1000 linhas (recuperado!)\n```\n\n## Operações de clone\n\n### Shallow clone\n\nUm shallow clone copia os metadados Delta e **referencia os mesmos arquivos de dados**. É rápido e barato, mas compartilha os dados com a origem:\n\n```sql\nCREATE TABLE employees_clone SHALLOW CLONE employees;\n```\n\nBenefícios do shallow clone:\n\n- Quase instantâneo (copia só metadados)\n- Armazenamento mínimo (referencia os arquivos existentes)\n- Mudanças afetam apenas o clone\n\n### Deep clone\n\nUm deep clone copia os metadados **E** os arquivos de dados. Mudanças no clone não afetam a origem:\n\n```sql\nCREATE TABLE employees_backup DEEP CLONE employees;\n```\n\nBenefícios do deep clone:\n\n- Independência total (dados separados)\n- Seguro para testes/experimentos\n- Ocupa mais armazenamento\n\n### Casos de uso de clone\n\n```python\n# Caso 1: cópia de teste antes de experimentar\nspark.sql(\"CREATE TABLE test_df DEEP CLONE production_table\")\n\n# Caso 2: backup de um ponto no tempo\nspark.sql(\"CREATE TABLE backup_20250115 DEEP CLONE employees\")\n\n# Caso 3: referência zero-copy para acesso de leitura\nspark.sql(\"CREATE TABLE read_only SHALLOW CLONE sensitive_data\")\n```\n\n## Comparando versões\n\n```python\nv3 = spark.read.format(\"delta\").option(\"versionAsOf\", 3).load(\"/mnt/data/employees\")\nv5 = spark.read.format(\"delta\").option(\"versionAsOf\", 5).load(\"/mnt/data/employees\")\n\n# Linhas que estão na v5 e não na v3 (SQL EXCEPT ALL)\nnew_rows = v5.exceptAll(v3)\nnew_rows.show()\n```\n\n## Políticas de retenção\n\nExistem **duas** retenções diferentes — não confunda:\n\n| Propriedade | Padrão | Controla |\n| :--- | :--- | :--- |\n| `delta.logRetentionDuration` | 30 dias | Por quanto tempo as entradas do transaction log (histórico) são mantidas |\n| `delta.deletedFileRetentionDuration` | 7 dias | Por quanto tempo arquivos de dados não referenciados sobrevivem antes que o `VACUUM` possa apagá-los |\n\n```sql\nALTER TABLE employees\nSET TBLPROPERTIES (\n    'delta.logRetentionDuration' = 'interval 30 days',\n    'delta.deletedFileRetentionDuration' = 'interval 30 days'\n);\n\n-- Remover arquivos antigos não referenciados (respeita a retenção)\nVACUUM employees;\n```\n\n> [!warning] Atenção\n> Na prática, o time travel só funciona enquanto os **arquivos de dados** da versão ainda existem. Depois de um `VACUUM`, versões mais antigas que a retenção de arquivos (7 dias por padrão) deixam de ser consultáveis, mesmo que ainda apareçam no `DESCRIBE HISTORY`.\n\n## Boas práticas de versionamento\n\n- Sempre confira o histórico (`DESCRIBE HISTORY`) antes de modificar ou restaurar\n- Isole mudanças de teste/staging usando clones (`DEEP CLONE production`)\n- Arquive pontos importantes com deep clones (`CREATE TABLE archive_2024_12_31 DEEP CLONE employees`)\n\n## Limitações do time travel\n\n| Limitação | Detalhes | Impacto |\n|-----------|---------|--------|\n| **Retenção** | Log: 30 dias; arquivos: 7 dias (após VACUUM) | Versões antigas deixam de existir |\n| **Tamanho do log** | Cresce com a atividade | Custo de armazenamento |\n| **Performance** | Versões antigas podem ser mais lentas | I/O de rede até a nuvem |\n\n## Delta Lake vs outros formatos — time travel\n\n| Formato | Histórico de versões | Time Travel | Recuperação | Linhagem |\n|--------|---|---|---|---|\n| **Delta Lake** | Transaction log completo | Sim | Rollback completo | Sim |\n| **Parquet** | Nenhum | Não | Backups manuais | Não |\n| **Iceberg** | Histórico completo | Sim | Rollback completo | Sim |\n| **Hudi** | Histórico limitado | Sim | Restauração de snapshot | Limitada |\n\n## Casos de uso\n\n- **Recuperação de dados acidental**: restaurar uma tabela Delta para uma versão anterior após um `DELETE` ou `UPDATE` errado, usando `RESTORE TABLE ... TO VERSION AS OF n` para recuperar os dados em minutos.\n- **Auditoria regulatória e compliance**: consultar versões históricas para reproduzir relatórios como eram em uma data específica, sem manter cópias de snapshot separadas.\n\n## Problemas e erros comuns\n\n### Time travel falha depois que o predictive optimization roda VACUUM\n\n**Cenário:** uma consulta `VERSION AS OF` de uma versão de duas semanas falha em uma managed table do UC, embora ninguém tenha rodado `VACUUM` manualmente.\n**Correção:** o predictive optimization roda `VACUUM` automaticamente em managed tables do UC, com retenção padrão de 7 dias (`delta.deletedFileRetentionDuration`). Aumente essa propriedade se precisar de uma janela de time travel maior ([predictive optimization](https://docs.databricks.com/aws/en/optimizations/predictive-optimization)).\n\n### VersionNotFoundException depois do VACUUM\n\n**Cenário:** uma consulta como `SELECT * FROM table VERSION AS OF 5` falha com `VersionNotFoundException` porque o `VACUUM` já removeu os arquivos daquela versão.\n**Correção:** o time travel só está disponível dentro do período de retenção (padrão 7 dias). Planeje a retenção do VACUUM de acordo com seus requisitos de auditoria e recuperação, e use `DESCRIBE HISTORY` para ver quais versões ainda existem.\n\n### Restaurar para a versão errada por engano\n\n**Cenário:** um engenheiro roda `RESTORE TABLE ... TO VERSION AS OF n` com o número errado, sobrescrevendo o estado atual com dados incorretos.\n**Correção:** rode sempre `DESCRIBE HISTORY` antes para verificar cada versão. Como o RESTORE cria uma **nova** versão, dá para restaurar de novo e desfazer o erro.\n\n## Dicas para a prova\n\n- Saiba as duas sintaxes: `VERSION AS OF n` e `TIMESTAMP AS OF 'data'` em SQL; opções `versionAsOf` e `timestampAsOf` em PySpark\n- `RESTORE TABLE ... TO VERSION AS OF n` faz rollback — isso **cria uma nova versão** (não apaga versões)\n- Shallow clone copia só metadados (rápido, pequeno); deep clone copia dados e metadados (lento, independente)\n- VACUUM remove arquivos antigos e quebra o time travel para versões mais antigas que o período de retenção\n\n## Pontos-chave\n\n- **Histórico de versões**: registrado nos arquivos JSON do `_delta_log/`\n- **Time travel**: consulte qualquer versão histórica por número ou timestamp\n- **Restore**: volta a tabela a um estado anterior (criando nova versão)\n- **Shallow clone**: cópia de metadados, arquivos compartilhados, instantâneo\n- **Deep clone**: cópia completa, dados independentes, mais armazenamento\n- **Retenção**: log 30 dias; arquivos removidos pelo VACUUM após 7 dias (padrões)\n- **Trilha de auditoria**: histórico completo de todas as operações\n- **Recuperação point-in-time**: essencial para compliance e debugging\n\n## Tópicos relacionados\n\n- [Fundamentos do Delta Lake](04-delta-lake-fundamentals.md)\n- [Otimização do Delta Lake](../06-troubleshooting-monitoring-and-optimization/03-delta-optimization.md)\n\n## Documentação oficial\n\n- [Delta Lake Time Travel](https://docs.databricks.com/en/delta/history.html)\n- [Clone a Table on Databricks](https://docs.databricks.com/en/delta/clone.html)\n\n---\n\n**[← Anterior: Fundamentos do Delta Lake](04-delta-lake-fundamentals.md) | [↑ Voltar para Databricks Intelligence Platform](README.md)**\n"},{"id":"01-databricks-intelligence-platform/README","folder":"01-databricks-intelligence-platform","group":"modulo","order":0,"isIndex":true,"title":"Databricks Intelligence Platform","md":"# Databricks Intelligence Platform (6 % da prova)\n\nO Domínio 1 do blueprint de agosto de 2026 cobre duas habilidades. A primeira é conhecer os componentes centrais da plataforma: a arquitetura lakehouse, o Delta Lake e o Unity Catalog. A segunda é escolher o serviço de compute certo para cada workload, com base em suas características, limitações e modelo de custo. O peso é pequeno, mas todos os outros domínios dependem desse vocabulário.\n\n> [!note] Atualização da plataforma (out/2026)\n> A página da certificação agora chama a plataforma de **Databricks Data + AI Platform**. O nome do domínio na prova continua \"Databricks Intelligence Platform\", então espere esse termo nos enunciados ([página da certificação](https://www.databricks.com/learn/certification/data-engineer-associate)).\n\n## Visão geral dos tópicos\n\n```mermaid\nflowchart TD\n    P[Databricks Intelligence Platform] --> Arch[Arquitetura Lakehouse]\n    P --> WS[Workspace e Notebooks]\n    P --> Compute[Serviços de Compute e Custos]\n    P --> Delta[Delta Lake]\n    P --> TT[Time Travel e Versionamento]\n    Arch --> UC[Unity Catalog]\n```\n\n## Conteúdo da seção\n\n| Arquivo | Tópico | Prioridade |\n| :--- | :--- | :--- |\n| [01-lakehouse-architecture.md](01-lakehouse-architecture.md) | Conceito de lakehouse, camadas medallion, papel do Unity Catalog | Alta |\n| [02-databricks-workspace.md](02-databricks-workspace.md) | Organização do workspace, notebooks, magic commands, widgets | Média |\n| [03-compute-clusters.md](03-compute-clusters.md) | Compute all-purpose, job, serverless e SQL warehouse; modelos de custo | Alta |\n| [04-delta-lake-fundamentals.md](04-delta-lake-fundamentals.md) | Transações ACID, transaction log, DML, schema enforcement | Alta |\n| [05-time-travel-versioning.md](05-time-travel-versioning.md) | `DESCRIBE HISTORY`, `VERSION AS OF`, `RESTORE`, clones | Alta |\n\n## Cobertura das habilidades oficiais (agosto de 2026)\n\n| Habilidade do exam guide (parafraseada) | Onde é coberta |\n| :--- | :--- |\n| Componentes centrais: arquitetura, Delta Lake, Unity Catalog | [01](01-lakehouse-architecture.md), [04](04-delta-lake-fundamentals.md), [05](05-time-travel-versioning.md), [UC básico](../07-governance-and-security/01-unity-catalog-basics.md) |\n| Serviços de compute: características, limitações, custos, escolha por workload | [03](03-compute-clusters.md) |\n\n## Conceitos-chave\n\n- **Lakehouse**: uma única plataforma que combina o armazenamento de um data lake com a confiabilidade de um data warehouse, servindo BI e IA a partir de uma única fonte da verdade\n- **Delta Lake**: o formato de tabela padrão. Fornece transações ACID, schema enforcement e time travel sobre object storage na nuvem\n- **Unity Catalog**: a camada de governança para ativos de dados e IA: controle de acesso, linhagem (lineage) e auditoria\n- **Escolha de compute**: all-purpose para trabalho interativo, jobs compute ou serverless jobs para pipelines agendados, SQL warehouses (serverless recomendado) para BI e SQL ad hoc\n\n## Próximos passos\n\nSiga para [02 — Data Ingestion and Loading](../02-data-ingestion-and-loading/README.md) para aprender como os dados chegam às tabelas do Unity Catalog.\n\n---\n\n**[← Voltar à Certificação](../README.md) | [Próximo: Data Ingestion and Loading →](../02-data-ingestion-and-loading/README.md)**\n"},{"id":"02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect","folder":"02-data-ingestion-and-loading","group":"modulo","order":1,"isIndex":false,"title":"Padrões de Ingestão e Lakeflow Connect","md":"# Padrões de Ingestão e Lakeflow Connect\n\n## Visão geral\n\nTodo pipeline começa colocando dados em uma tabela governada pelo Unity Catalog. Este arquivo cobre os três **padrões** de ingestão (batch, streaming, incremental) e as **fontes** que a prova cita: arquivos locais, standard connectors e managed connectors do Lakeflow Connect. Também mostra como **escolher** entre Auto Loader, Lakeflow Connect, partner connectors e código escrito à mão.\n\n> [!abstract] Resumo\n>\n> - **Batch** carrega um conjunto limitado de dados por execução. **Streaming** processa registros continuamente conforme chegam. **Incremental** processa só o que é novo desde a última execução, seja como micro-batches disparados ou um `COPY INTO` agendado\n> - **Arquivos locais** entram pela UI **Add or upload data**, seja em um volume UC ou direto em uma nova managed table\n> - **Standard connectors** (object storage, Kafka, Kinesis, Pub/Sub, SFTP) são customizáveis e rodam com Auto Loader, `read_files`, streaming tables ou Structured Streaming. **Managed connectors** (apps SaaS e bancos de dados) são ingestion pipelines totalmente gerenciados em compute serverless\n> - A Databricks recomenda **começar pela camada mais gerenciada** e descer uma camada só quando ela não atender ao requisito\n\n> [!tip] O que a prova cobra\n>\n> - Habilidades do exam guide: padrões e fontes de ingestão (arquivos locais, standard e managed connectors), configurar o Lakeflow Connect e escolher o método de ingestão por volume, frequência, tipo de dado e governança\n> - Reconhecer qual camada de conector se encaixa no cenário: fonte SaaS → managed connector; arquivos em cloud storage → Auto Loader; banco sem conector suportado → JDBC\n> - Os componentes de um managed connector de banco de dados: connection, ingestion gateway e ingestion pipeline\n\n---\n\n## Os três padrões de ingestão\n\n| Padrão | O que roda | Ferramenta típica no Databricks | Latência vs custo |\n| :--- | :--- | :--- | :--- |\n| **Batch (completo)** | Lê a fonte inteira a cada execução e sobrescreve/substitui o destino | `CREATE OR REPLACE TABLE ... AS SELECT`, `spark.read` + `mode(\"overwrite\")` | Simples, mas o custo cresce com o tamanho da fonte |\n| **Batch incremental** | Cada execução agendada processa só os dados que chegaram desde a última, e para | `COPY INTO`, Auto Loader com `trigger(availableNow=True)`, streaming tables atualizadas por agenda | Custo baixo, latência igual ao intervalo da agenda |\n| **Streaming** | Uma consulta de longa duração processa novos registros continuamente | Auto Loader ou Kafka com trigger `processingTime`, pipelines contínuos | Menor latência, compute sempre ligado |\n\nA diferença entre \"incremental\" e \"streaming\" é **com que frequência o trabalho roda**, não qual API você usa. O mesmo stream do Auto Loader vira um job de batch incremental quando você o roda com `availableNow` a partir de um Lakeflow Job agendado.\n\n```python\n# Mesma fonte, dois padrões — só o trigger muda\nstream = (spark.readStream.format(\"cloudFiles\")\n    .option(\"cloudFiles.format\", \"json\")\n    .option(\"cloudFiles.schemaLocation\", \"/Volumes/main/raw/_schemas/orders\")\n    .load(\"/Volumes/main/raw/landing/orders\"))\n\n# Batch incremental: processa tudo que é novo e para (agende com Lakeflow Jobs)\n(stream.writeStream\n    .option(\"checkpointLocation\", \"/Volumes/main/raw/_checkpoints/orders\")\n    .trigger(availableNow=True)\n    .toTable(\"main.bronze.orders\"))\n\n# Streaming: verifica novos arquivos a cada minuto até ser parado\n# (stream.writeStream ... .trigger(processingTime=\"1 minute\") ...)\n```\n\n> [!note]\n> `Trigger.Once` está depreciado a partir do Databricks Runtime 11.3 LTS. Use `availableNow` para workloads de batch incremental ([trigger intervals](https://docs.databricks.com/aws/en/structured-streaming/triggers)).\n\n## Importando arquivos locais\n\nO exam guide lista arquivos locais como fonte. A UI do Databricks oferece dois caminhos:\n\n| Caminho | Resultado | Requisitos |\n| :--- | :--- | :--- |\n| **New → Add or upload data → Upload files to a volume** | Os arquivos vão para um volume do Unity Catalog (`/Volumes/<catalog>/<schema>/<volume>/...`) | `WRITE VOLUME` no volume; `USE CATALOG` e `USE SCHEMA` nos pais |\n| **Create table** a partir de arquivos enviados, no Catalog Explorer | Uma **managed table** do Unity Catalog criada a partir dos arquivos | `CREATE TABLE` no schema de destino e um SQL warehouse rodando |\n\n- Uploads pela UI têm **limite de 5 GB por arquivo**. Use o Databricks SDK for Python para arquivos maiores\n- Notebooks também oferecem **File → Upload files to volume**\n- Depois que os arquivos estão num volume, qualquer leitor pode carregá-los: `read_files`, `COPY INTO` ou Auto Loader\n\n```sql\n-- Ler um CSV enviado para um volume\nSELECT * FROM read_files(\n  '/Volumes/main/raw/uploads/customers.csv',\n  format => 'csv',\n  header => true\n);\n```\n\n## Lakeflow Connect: três camadas\n\nO Lakeflow Connect oferece conectores para arquivos locais, aplicações corporativas, bancos de dados, cloud storage e message buses. Todos são governados pelo Unity Catalog e orquestrados com Lakeflow Jobs ([What is Lakeflow Connect?](https://docs.databricks.com/aws/en/ingestion/overview)).\n\n```mermaid\nflowchart TB\n    L1[\"1. Managed connectors<br/>SaaS + bancos de dados<br/>(mais automação)\"]\n    L2[\"2. Lakeflow pipelines<br/>streaming tables, Auto Loader, read_files\"]\n    L3[\"3. Structured Streaming + APIs Spark<br/>(mais customização)\"]\n    L1 -->|\"fonte não suportada?<br/>desça uma camada\"| L2\n    L2 -->|\"precisa de controle total?\"| L3\n```\n\n### Standard connectors (customizáveis)\n\nStandard connectors são os caminhos de ingestão customizáveis em SQL e Spark para:\n\n- **Cloud object storage** (S3, ADLS, GCS, volumes UC): Auto Loader, `read_files`, streaming tables, `COPY INTO`\n- **Message buses**: Apache Kafka, Amazon Kinesis, Google Pub/Sub (Structured Streaming e Lakeflow pipelines)\n- **Servidores SFTP**\n\nVocê mesmo escreve a lógica de ingestão, o que dá controle total sobre transformações, tratamento de schema e triggers.\n\nExemplo de standard connector para um message bus:\n\n```python\nfrom pyspark.sql.functions import col\n\nevents = (spark.readStream\n    .format(\"kafka\")\n    .option(\"kafka.bootstrap.servers\", \"broker1:9092\")\n    .option(\"subscribe\", \"orders\")\n    .option(\"startingOffsets\", \"latest\")\n    .load()\n    # key e value sempre chegam como binário — faça cast ou desserialize\n    .select(col(\"key\").cast(\"string\"), col(\"value\").cast(\"string\").alias(\"json\"),\n            \"topic\", \"partition\", \"offset\", \"timestamp\"))\n\n(events.writeStream\n    .option(\"checkpointLocation\", \"/Volumes/main/raw/_checkpoints/kafka_orders\")\n    .trigger(processingTime=\"30 seconds\")\n    .toTable(\"main.bronze.kafka_orders\"))\n```\n\nA fonte Kafka retorna `key`, `value` (ambos binários), `topic`, `partition`, `offset`, `timestamp` e `timestampType` ([Connect to Apache Kafka](https://docs.databricks.com/aws/en/connect/streaming/kafka)).\n\n### Managed connectors (totalmente gerenciados)\n\nManaged connectors \"são construídos sobre Lakeflow pipelines, oferecendo ainda mais automação para as fontes de dados mais populares\" ([Lakeflow Connect overview](https://docs.databricks.com/aws/en/ingestion/overview)). Categorias:\n\n| Categoria | Exemplos da documentação |\n| :--- | :--- |\n| SaaS | Salesforce, HubSpot, Jira, Workday, Microsoft Dynamics 365 |\n| Banco de dados (CDC) | MySQL, PostgreSQL, SQL Server, Oracle |\n| Query-based | Consulta a fonte diretamente, sem configurar CDC |\n| Fonte de arquivos | Google Drive, SharePoint |\n| Streaming | RabbitMQ |\n\nNovos conectores chegam com frequência, muitos primeiro em Beta. Confira a [lista de conectores do Lakeflow Connect](https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/) antes de assumir que uma fonte é ou não suportada.\n\n## Configurando um managed connector\n\nUm managed connector produz um ingestion pipeline governado pelo Unity Catalog ([connector concepts](https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/)). Seus componentes:\n\n| Componente | O que é |\n| :--- | :--- |\n| **Connection** | Um securable do Unity Catalog que guarda os dados de autenticação da fonte |\n| **Ingestion gateway** *(só conectores de banco de dados)* | Roda como task contínua no seu próprio job e prepara (stage) os dados de mudança para captura contínua |\n| **Ingestion pipeline** | Lê a fonte (ou as mudanças preparadas) e escreve no destino; pipelines query-based rodam em serverless por padrão |\n| **Tabelas de destino** | **Streaming tables** no catálogo e schema que você escolher |\n\n```mermaid\nflowchart LR\n    SRC[(SQL Server)] --> GW[Ingestion gateway<br/>contínuo]\n    GW --> STG[Staging storage]\n    STG --> PIPE[Ingestion pipeline<br/>serverless]\n    PIPE --> ST[(Streaming tables<br/>main.bronze.*)]\n    CONN[UC connection] -.credenciais.-> GW\n```\n\nPassos típicos de configuração:\n\n1. **Criar a connection** no Catalog Explorer, ou programaticamente com a Connections API ou `databricks connections create --json ...`. Conectores cuja única autenticação é OAuth pelo navegador (OAuth U2M) não podem ser criados programaticamente\n2. **Criar o ingestion pipeline**: escolha a connection, os objetos de origem (tabelas ou relatórios) e o catálogo/schema de destino\n3. **Adicionar uma agenda**: \"Para cada agenda adicionada a um pipeline, o Lakeflow Connect cria automaticamente um job\", com o ingestion pipeline como task. Você pode adicionar tasks downstream a esse job\n4. **Implantar como código** (opcional): ingestion pipelines podem ser implantados com Declarative Automation Bundles (veja o [Domínio 5](../05-implementing-cicd/02-declarative-automation-bundles.md))\n\nA primeira execução ingere tudo que você selecionou. As seguintes usam change tracking para ingerir só o que mudou, quando a fonte suporta. Monitore o custo com a system table `system.billing.usage`.\n\n### Escritas diretas de aplicações (Zerobus Ingest)\n\nO Lakeflow Connect também tem um caminho push. A API **Zerobus Ingest** permite que aplicações escrevam registros diretamente em streaming tables, sem landing zone de arquivos ou message bus no meio. Não é citada no exam guide, mas é um contexto útil quando um cenário descreve uma aplicação que deve enviar eventos direto para uma tabela.\n\n## Partner connectors\n\nQuando nem um managed connector nem um standard connector servem, a Databricks lista **parceiros de ingestão validados**, alguns disponíveis via **Partner Connect**. Escolha uma ferramenta parceira quando sua organização já a licencia para uma fonte que a Databricks não cobre nativamente. O custo: mais um fornecedor para gerenciar, e governança que só começa quando os dados chegam ao Unity Catalog.\n\n## Escolhendo o método de ingestão\n\n| Requisito do cenário | Melhor opção | Por quê |\n| :--- | :--- | :--- |\n| Arquivos chegam continuamente em S3/ADLS/GCS, schema pode mudar, milhares a bilhões de arquivos | **Auto Loader** (ou streaming table com `STREAM read_files`) | Descoberta de arquivos escalável, checkpoint exactly-once, evolução de schema |\n| Equipe só de SQL, cargas periódicas de um conjunto modesto e conhecido de arquivos | **`COPY INTO`** | Comando SQL idempotente, sem conceitos de streaming |\n| Objetos do Salesforce ou Workday | **Managed connector** | Sem código. Incremental, serverless, governado |\n| Banco operacional com suporte a CDC | **Managed database connector** (gateway + pipeline) | Captura contínua de mudanças sem código customizado |\n| Eventos de Kafka, Kinesis ou Pub/Sub | **Standard connector** (Structured Streaming ou Lakeflow pipeline) | Streaming de baixa latência com seu próprio parsing |\n| Fonte só com driver JDBC ou API REST | **Código em notebook** agendado por Lakeflow Jobs | Veja [03-jdbc-rest-and-semi-structured-ingestion.md](03-jdbc-rest-and-semi-structured-ingestion.md) |\n| Planilha avulsa de um usuário de negócio | **Upload para volume / UI Create table** | Caminho mais rápido para arquivos locais pequenos |\n| Os dados **não podem** ser copiados | **Lakehouse Federation** ou **OpenSharing** | Consultar ou compartilhar no lugar, em vez de ingerir |\n\nDimensões de decisão que o exam guide destaca: **volume de dados, frequência de ingestão, tipos de dados e necessidades de governança com Unity Catalog**. Todas as opções acima levam os dados para tabelas governadas pelo UC. Managed connectors também guardam as credenciais da fonte em uma UC connection, então o acesso à fonte também é governado.\n\n## Landing zones no Unity Catalog\n\nToda fonte no exam guide termina em \"tabelas governadas pelo Unity Catalog\". Os arquivos brutos que alimentam essas tabelas também devem ser governados:\n\n| Opção de landing | Formato do caminho | Privilégio | Observações |\n| :--- | :--- | :--- | :--- |\n| **Managed volume** | `/Volumes/<catalog>/<schema>/<volume>/...` | `READ VOLUME` / `WRITE VOLUME` | O UC gerencia o local de armazenamento |\n| **External volume** | `/Volumes/<catalog>/<schema>/<volume>/...` sobre uma external location | `READ VOLUME` / `WRITE VOLUME` | Aponta para cloud storage existente |\n| **External location** (caminho direto) | `s3://...`, `abfss://...`, `gs://...` | `READ FILES` / `WRITE FILES` | A Databricks recomenda volumes em vez de acesso por caminho direto |\n| DBFS root / mounts DBFS | `dbfs:/...`, `/mnt/...` | Nenhum (legado) | **Depreciado.** Prefira volumes UC, external locations ou workspace files |\n\n```sql\n-- Volume de landing para arquivos brutos, legível pelo service principal de ingestão\nCREATE VOLUME IF NOT EXISTS main.raw.landing;\nGRANT READ VOLUME, WRITE VOLUME ON VOLUME main.raw.landing TO `ingest-sp`;\n```\n\nFontes: [UC privileges reference](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges), [What is DBFS?](https://docs.databricks.com/aws/en/dbfs/).\n\n## Cenários resolvidos\n\n**Cenário 1: arquivos noturnos de parceiro.** Um parceiro escreve ~200 arquivos CSV em um prefixo S3 toda noite. O schema às vezes ganha uma coluna. O time de analytics quer os dados até as 6h e nenhum compute ligado durante o dia.\n\n- Use Auto Loader com `availableNow` (batch incremental), agendado por um Lakeflow Job ou disparado por file arrival trigger\n- Não é managed connector, porque a fonte são arquivos, não um app SaaS ou banco\n- Não só `COPY INTO`. Funciona, mas o tratamento de schema drift e grandes quantidades de arquivos favorecem o Auto Loader\n\n**Cenário 2: objetos do CRM para relatórios de vendas.** A liderança de vendas quer contas e oportunidades do Salesforce atualizadas de hora em hora, e a equipe não tem engenheiros sobrando.\n\n- Use o **managed connector do Salesforce** com agenda horária. O Lakeflow Connect cria o job e grava streaming tables\n- Código REST customizado funcionaria, mas falha no requisito de \"menor overhead operacional\"\n\n**Cenário 3: banco legado on-premises sem managed connector.** A fonte é acessível pela rede e tem driver JDBC.\n\n- Use **leitura JDBC em um notebook**, paralelizada com `partitionColumn` e limites, gravando numa tabela UC e agendada com Lakeflow Jobs\n- Se o banco é suportado pelo Lakehouse Federation e os dados não podem ser copiados, federe em vez de ingerir\n\n## Casos de uso\n\n- **Replicação de CRM SaaS**: um managed connector do Salesforce grava objetos como streaming tables em `main.bronze`, atualizados de hora em hora pelo job que o Lakeflow Connect cria\n- **Offload de CDC de banco**: um managed connector do SQL Server mantém tabelas Bronze quase em tempo real sem código de change tracking\n- **Onboarding de planilhas**: um usuário de negócio envia um CSV para um volume e cria uma managed table pelo Catalog Explorer, sem código\n- **Arquivos de IoT**: dispositivos escrevem JSON em cloud storage e o Auto Loader ingere incrementalmente na Bronze\n\n## Problemas e erros comuns\n\n### Escrever um poller customizado para uma fonte SaaS suportada\n\n**Cenário:** uma equipe escreve um notebook que pagina uma API REST SaaS a cada hora e vive esbarrando em rate limits e mudanças de schema.\n**Correção:** confira primeiro a lista de managed connectors. A Databricks recomenda começar pela camada mais gerenciada; um managed connector cuida das leituras incrementais e do schema para você.\n\n### Conector não pode ser criado a partir do CI\n\n**Cenário:** um deploy de bundle falha ao criar uma connection para uma fonte que só autentica via OAuth no navegador.\n**Correção:** conectores que só suportam OAuth U2M precisam ser criados interativamente, por exemplo no Catalog Explorer. Crie a connection uma vez e referencie-a na definição do pipeline.\n\n### Upload rejeitado para arquivo grande\n\n**Cenário:** o upload de um CSV de 9 GB pela UI falha.\n**Correção:** o limite da UI é 5 GB por arquivo. Use o Databricks SDK for Python, ou coloque o arquivo em cloud storage e ingira com Auto Loader.\n\n### Reingerir tudo em toda execução\n\n**Cenário:** um notebook noturno lê todo o diretório de landing com `spark.read` e sobrescreve a tabela Bronze. O tempo de execução cresce toda semana conforme os arquivos se acumulam.\n**Correção:** mude para um padrão incremental: Auto Loader com `availableNow`, ou `COPY INTO`. Ambos rastreiam quais arquivos já processaram, então cada execução trata só os novos.\n\n### Arquivos brutos gravados em mounts DBFS\n\n**Cenário:** um novo pipeline grava arquivos em `/mnt/vendor/` porque um notebook antigo fazia isso, e os auditores perguntam quem pode lê-los.\n**Correção:** mounts DBFS estão depreciados e não são governados pelo Unity Catalog. Grave em um volume UC ou external location e conceda `READ VOLUME` ou `READ FILES` a quem precisa.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - A expressão \"mais gerenciado\" ou \"menor overhead operacional\" geralmente aponta para um **managed connector** (SaaS ou banco) ou para o **Auto Loader** (arquivos)\n> - Managed connectors gravam em **streaming tables**, rodam em compute **serverless** e são agendados por um **Lakeflow Job** criado automaticamente\n> - O **ingestion gateway** existe apenas para conectores de **banco de dados**\n> - `availableNow` transforma um stream em uma execução de batch incremental. `Trigger.Once` está depreciado\n> - Se o cenário diz que os dados **não** podem ser copiados, ingestão é a resposta errada. Use Lakehouse Federation ou compartilhamento\n\n## Pontos-chave\n\n- Batch, incremental e streaming diferem em com que frequência o trabalho roda e quanto ele processa\n- Arquivos locais entram por upload para volume ou pela UI Create table, com limite de 5 GB por arquivo na UI\n- Standard connectors são caminhos de código customizáveis. Managed connectors são pipelines totalmente gerenciados\n- Um managed connector é formado por UC connection, gateway (só bancos), ingestion pipeline e streaming tables\n- Escolha por volume, frequência, tipo de dado e governança, começando pela camada mais gerenciada\n\n## Tópicos relacionados\n\n- [COPY INTO e Auto Loader](02-copy-into-and-auto-loader.md)\n- [JDBC, REST e ingestão semiestruturada](03-jdbc-rest-and-semi-structured-ingestion.md)\n- [Objetos da camada Gold (streaming tables)](../03-data-transformation-and-modeling/06-gold-layer-objects.md)\n\n## Documentação oficial\n\n- [What is Lakeflow Connect?](https://docs.databricks.com/aws/en/ingestion/overview)\n- [Lakeflow Connect connector concepts](https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/)\n- [Ingest with SQL and Spark APIs (standard connectors)](https://docs.databricks.com/aws/en/ingestion/)\n- [Work with files in Unity Catalog volumes](https://docs.databricks.com/aws/en/volumes/volume-files)\n- [Configure Structured Streaming trigger intervals](https://docs.databricks.com/aws/en/structured-streaming/triggers)\n\n---\n\n**[↑ Voltar para Data Ingestion and Loading](README.md) | [Próximo: COPY INTO e Auto Loader →](02-copy-into-and-auto-loader.md)**\n"},{"id":"02-data-ingestion-and-loading/02-copy-into-and-auto-loader","folder":"02-data-ingestion-and-loading","group":"modulo","order":2,"isIndex":false,"title":"COPY INTO e Auto Loader","md":"# COPY INTO e Auto Loader\n\n## Visão geral\n\nO Databricks tem duas ferramentas de ingestão de arquivos para cloud object storage (S3, ADLS, GCS) e volumes do Unity Catalog. **`COPY INTO`** é um comando SQL idempotente. **Auto Loader** é uma fonte de Structured Streaming chamada `cloudFiles`. Ambos carregam arquivos incrementalmente em tabelas Delta governadas pelo Unity Catalog. Eles diferem em escala, tratamento de schema e forma de descobrir arquivos.\n\n> [!abstract] Resumo\n>\n> - **`COPY INTO`** pode ser reexecutado e é idempotente: arquivos já carregados são ignorados nas execuções seguintes. `COPY_OPTIONS ('mergeSchema' = 'true')` evolui o schema do destino\n> - **Auto Loader** registra os arquivos descobertos em um store RocksDB dentro do checkpoint, garantindo processamento exactly-once. Consegue processar bilhões de arquivos\n> - **Schema**: `cloudFiles.schemaLocation` habilita inferência e evolução. `cloudFiles.schemaEvolutionMode` controla o que acontece quando aparecem colunas novas. `_rescued_data` captura valores que não cabem no schema\n> - **Detecção de arquivos**: directory listing (padrão) ou file notification. A Databricks recomenda file notification com **file events** para a maioria dos workloads\n\n> [!tip] O que a prova cobra\n>\n> - Habilidades do exam guide: `COPY INTO` para cargas incrementais em tabelas UC, e Auto Loader com schema enforcement e evolution em modo directory listing ou file notification\n> - Por que reexecutar o `COPY INTO` carrega zero linhas novas, e como forçar a recarga\n> - Cada valor de `schemaEvolutionMode` e seu comportamento quando chega uma coluna nova\n> - Quando o Auto Loader é melhor que o `COPY INTO`: escala, chegada contínua e schema drift\n\n---\n\n## COPY INTO\n\n### Sintaxe\n\n```sql\nCOPY INTO target_table\nFROM 'source_path_or_volume'\nFILEFORMAT = JSON | CSV | XML | AVRO | ORC | PARQUET | TEXT | BINARYFILE\n[ VALIDATE [ ALL | num_rows ROWS ] ]\n[ FILES = ('f1.json', 'f2.json') | PATTERN = 'glob' ]\n[ FORMAT_OPTIONS ( 'option' = 'value', ... ) ]\n[ COPY_OPTIONS ( 'mergeSchema' = 'true', 'force' = 'false' ) ]\n```\n\n### Carregando em uma tabela do Unity Catalog\n\n```sql\n-- 1. Criar uma tabela vazia (placeholder); o COPY INTO infere o schema na primeira carga\nCREATE TABLE IF NOT EXISTS main.bronze.booking_updates;\n\n-- 2. Carregar JSON de um volume UC, inferindo e evoluindo o schema\nCOPY INTO main.bronze.booking_updates\nFROM '/Volumes/main/raw/landing/booking_updates'\nFILEFORMAT = JSON\nFORMAT_OPTIONS ('mergeSchema' = 'true', 'multiLine' = 'true')\nCOPY_OPTIONS ('mergeSchema' = 'true');\n\n-- 3. Reexecutar amanhã: só os arquivos que chegaram desde a última execução são carregados\n```\n\nComportamentos-chave ([Get started with COPY INTO](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/copy-into/), [COPY INTO reference](https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into)):\n\n| Comportamento | Detalhe |\n| :--- | :--- |\n| **Idempotente** | \"Arquivos no local de origem que já foram carregados são ignorados\", mesmo que tenham sido modificados depois |\n| **Placeholder sem schema** | No DBR 11.3 LTS+, crie uma tabela vazia e defina `mergeSchema` em `COPY_OPTIONS` para inferir o schema durante a carga |\n| **`force`** | `'force' = 'true'` desativa a idempotência e recarrega os arquivos, já carregados ou não |\n| **`FILES`** | Lista explícita de até **1.000** arquivos. Não pode ser combinada com `PATTERN` |\n| **`VALIDATE`** | Verifica os dados sem carregá-los — útil como dry run |\n| **Formatos** | CSV, JSON, XML, Avro, ORC, Parquet, texto, binário |\n| **Acesso no UC** | Lê de um volume UC ou external location. O destino precisa de `CREATE TABLE` (primeira carga) ou `MODIFY` |\n\n> [!note] Recomendação da documentação\n> \"Para uma ingestão de arquivos mais escalável e robusta, a Databricks recomenda que usuários de SQL usem streaming tables\" (`CREATE STREAMING TABLE ... AS SELECT * FROM STREAM read_files(...)`), que usam o Auto Loader por baixo ([COPY INTO](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/copy-into/)).\n\n### Mais padrões de COPY INTO\n\n```sql\n-- Dry run: verifica se as 10 primeiras linhas são lidas corretamente, sem carregar nada\nCOPY INTO main.bronze.orders\nFROM '/Volumes/main/raw/landing/orders'\nFILEFORMAT = CSV\nVALIDATE 10 ROWS\nFORMAT_OPTIONS ('header' = 'true');\n\n-- Carregar só os arquivos de um fornecedor com um padrão glob\nCOPY INTO main.bronze.orders\nFROM '/Volumes/main/raw/landing/orders'\nFILEFORMAT = CSV\nPATTERN = 'vendor_a_*.csv'\nFORMAT_OPTIONS ('header' = 'true', 'inferSchema' = 'true');\n```\n\n## Auto Loader\n\n### O que é\n\nO Auto Loader \"processa novos arquivos de dados de forma incremental e eficiente conforme chegam ao cloud storage\" ([Auto Loader overview](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/)). Fatos-chave:\n\n- É uma **fonte de Structured Streaming** chamada `cloudFiles`\n- Fontes: S3, ADLS, GCS, volumes UC e Azure Blob Storage\n- Formatos: JSON, CSV, XML, Parquet, Avro, ORC, texto, binary file\n- Os arquivos descobertos são registrados em um store chave-valor **RocksDB** dentro do **checkpoint**, o que \"garante que os dados sejam processados exatamente uma vez\". Após uma falha, retoma a partir do checkpoint\n- Funciona como stream contínuo ou como **batch incremental** com `trigger(availableNow=True)`\n\n### Padrão em Python\n\n```python\nbronze = (spark.readStream\n    .format(\"cloudFiles\")\n    .option(\"cloudFiles.format\", \"json\")\n    .option(\"cloudFiles.schemaLocation\", \"/Volumes/main/raw/_meta/events/schema\")\n    .option(\"cloudFiles.inferColumnTypes\", \"true\")\n    .option(\"cloudFiles.schemaHints\", \"event_ts TIMESTAMP, amount DECIMAL(10,2)\")\n    .load(\"/Volumes/main/raw/landing/events\"))\n\n(bronze.writeStream\n    .option(\"checkpointLocation\", \"/Volumes/main/raw/_meta/events/checkpoint\")\n    .trigger(availableNow=True)            # batch incremental, depois para\n    .toTable(\"main.bronze.events\"))\n```\n\n### Padrão em SQL (streaming table)\n\n```sql\nCREATE OR REFRESH STREAMING TABLE main.bronze.events\nAS SELECT * FROM STREAM read_files(\n  '/Volumes/main/raw/landing/events',\n  format => 'json'\n);\n```\n\nDentro de um Lakeflow pipeline, o próprio pipeline gerencia o schema location e o checkpoint.\n\n### Padrão em Python dentro de um Lakeflow pipeline\n\n```python\nfrom pyspark import pipelines as dp\n\n@dp.table(name=\"bronze_events\", comment=\"Eventos brutos gravados pelo Auto Loader\")\ndef bronze_events():\n    return (spark.readStream\n        .format(\"cloudFiles\")\n        .option(\"cloudFiles.format\", \"json\")\n        .load(\"/Volumes/main/raw/landing/events\"))\n```\n\nUma leitura streaming sob `@dp.table` define uma **streaming table**. Uma leitura batch sob `@dp.materialized_view` define uma materialized view. Não é preciso `schemaLocation` nem `checkpointLocation`, porque o pipeline gerencia ambos.\n\n> [!note] Atualização da plataforma (out/2026)\n> \"O módulo `dlt` foi substituído pelo módulo `pyspark.pipelines`.\" Código com `import dlt` e `@dlt.table` ainda roda, mas a Databricks recomenda `from pyspark import pipelines as dp` ([Python reference](https://docs.databricks.com/aws/en/ldp/developer/python-ref)). O produto que a prova chama de **Lakeflow Declarative Pipelines** (antigo DLT / Delta Live Tables) foi renomeado para **Lakeflow Spark Declarative Pipelines** em 12/11/2025.\n\n### Opções comuns\n\n| Opção | Padrão | Propósito |\n| :--- | :--- | :--- |\n| `cloudFiles.format` | *(obrigatória)* | Formato dos arquivos de origem |\n| `cloudFiles.schemaLocation` | Nenhum (obrigatório para inferência) | Onde o schema inferido e seu histórico (`_schemas`) são guardados |\n| `cloudFiles.inferColumnTypes` | `false` | Inferir tipos reais para JSON/CSV/XML. Sem isso, essas colunas são lidas como **strings** |\n| `cloudFiles.schemaHints` | Nenhum | Sobrescrever tipos inferidos, ou adicionar colunas esperadas, com sintaxe DDL |\n| `cloudFiles.schemaEvolutionMode` | `addNewColumns` (sem schema fornecido) / `none` (com schema fornecido) | O que fazer quando aparecem colunas novas |\n| `cloudFiles.includeExistingFiles` | `true` | Também processar arquivos que já estavam no diretório na primeira execução |\n| `cloudFiles.maxFilesPerTrigger` | `1000` | Limite de arquivos novos por micro-batch |\n| `cloudFiles.allowOverwrites` | `false` | Se mudanças em arquivos do diretório podem sobrescrever dados existentes |\n\nFonte: [Auto Loader options](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/options).\n\n## Schema enforcement e evolution\n\nO Auto Loader amostra **os primeiros 50 GB ou 1.000 arquivos** (o limite que for atingido primeiro) para inferir o schema, e o guarda em `cloudFiles.schemaLocation`. Colunas de JSON, CSV e XML são inferidas como strings, a menos que `cloudFiles.inferColumnTypes` seja `true`. Avro e Parquet usam os tipos gravados nos arquivos ([schema inference and evolution](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema)).\n\n### `cloudFiles.schemaEvolutionMode`\n\n| Modo | Chega uma coluna nova | O stream falha? | Uso típico |\n| :--- | :--- | :--- | :--- |\n| `addNewColumns` *(padrão sem schema fornecido)* | Schema atualizado; colunas adicionadas no fim | **Sim**, com `UnknownFieldException`. Ao reiniciar, usa o novo schema | Tabelas Bronze que devem acompanhar a fonte |\n| `addNewColumnsWithTypeWidening` *(Public Preview, DBR 16.4+)* | Como acima, mais alargamento de tipo suportado, ex. `int` → `long` | Sim | Fontes cujos tipos numéricos crescem |\n| `rescue` | O schema **nunca** evolui; colunas novas vão para `_rescued_data` | Não | Contratos downstream rígidos |\n| `failOnNewColumns` | Schema não é atualizado | **Sim, e continua falhando** até você atualizar o schema ou remover o arquivo | Controle de mudanças de schema |\n| `none` *(padrão com schema fornecido)* | Colunas novas ignoradas; sem rescue a menos que `rescuedDataColumn` esteja definido | Não | Schemas fixos |\n\n```mermaid\nflowchart LR\n    New[Coluna nova no arquivo] --> Mode{schemaEvolutionMode}\n    Mode -->|addNewColumns| Fail1[Stream para<br/>UnknownFieldException] --> Restart[Reinicia com<br/>schema evoluído]\n    Mode -->|rescue| Rescue[Valor → _rescued_data<br/>stream continua]\n    Mode -->|failOnNewColumns| Stop[Stream para até<br/>correção manual]\n    Mode -->|none| Ignore[Coluna ignorada]\n```\n\n> [!tip] Dica\n> Como o `addNewColumns` para o stream de propósito, a Databricks recomenda rodar streams do Auto Loader em **Lakeflow Jobs** com retries, para que o reinício aconteça automaticamente.\n\n### A coluna `_rescued_data`\n\nQuando o Auto Loader infere o schema, ele adiciona por padrão uma coluna `_rescued_data`. Ela guarda um JSON com os valores que não couberam no schema: colunas desconhecidas, tipos incompatíveis e diferenças de maiúsculas/minúsculas, além do caminho do arquivo de origem. Com schema fornecido, habilite com `rescuedDataColumn`. Consulte essa coluna para encontrar drift sem perder registros.\n\n**Schema enforcement** é a outra metade: valores que não batem com o tipo esperado nunca são convertidos silenciosamente para a coluna errada. Eles são resgatados, ignorados ou causam falha, conforme o modo escolhido.\n\n## Modos de detecção de arquivos\n\n| Modo | Como encontra arquivos novos | Configuração | Recomendação |\n| :--- | :--- | :--- | :--- |\n| **Directory listing** *(padrão)* | Lista o diretório de entrada a cada micro-batch | Só acesso de leitura aos dados | Rápido de começar; bom para diretórios pequenos |\n| **File notification** (clássico) | Serviços de notificação e fila na sua conta de nuvem, que o Auto Loader pode criar | Permissões na nuvem para criar esses recursos | Ainda suportado; file events é o preferido |\n| **File notification com file events** | File events habilitados na **external location do UC** que contém os arquivos | Sem permissões extras ao configurar o stream (DBR 14.3 LTS+) | **Recomendado para a maioria dos workloads** (\"mais performático e escalável\") |\n\n- Dá para trocar de modo entre reinícios do stream mantendo exactly-once\n- A ordem de descoberta não é garantida em nenhum modo, então não dependa da ordem de chegada\n- `cloudFiles.useIncrementalListing` está **depreciado**. Use file notification com file events\n\nFonte: [file detection modes](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/file-detection-modes).\n\n> [!note] Linguagem da prova\n> O exam guide fala em usar o Auto Loader \"em modos batch (por exemplo, directory listing ou file notification)\". Leia como: rodar o Auto Loader como batch incremental (`availableNow`) com qualquer um dos modos de descoberta.\n\n## COPY INTO vs Auto Loader\n\n| Dimensão | `COPY INTO` | Auto Loader |\n| :--- | :--- | :--- |\n| Interface | Comando SQL | Fonte de Structured Streaming (Python/Scala/SQL via `read_files`) |\n| Rastreamento de arquivos | Interno; arquivos carregados são ignorados nas reexecuções | Store RocksDB no checkpoint |\n| Escala | Cargas periódicas de um conjunto modesto e conhecido de arquivos | Feito para chegada contínua; \"consegue lidar com bilhões de arquivos\" |\n| Evolução de schema | `mergeSchema` em `COPY_OPTIONS` | `schemaLocation` + `schemaEvolutionMode` + `_rescued_data` |\n| Ingestão contínua | Não (reexecuta por agenda) | Sim (ou batch `availableNow`) |\n| Recomendado para usuários SQL | Streaming tables são recomendadas no lugar | Sim (streaming tables usam o Auto Loader) |\n\n### Checklist rápido de decisão\n\n1. A equipe é só SQL, com cargas periódicas de um conjunto modesto e conhecido de arquivos? `COPY INTO`, ou streaming table com `read_files`\n2. Os arquivos chegam continuamente, em grande volume ou com schema mudando? **Auto Loader**\n3. Precisa dos valores brutos que não cabem no schema? `_rescued_data` do Auto Loader\n4. O job precisa parar quando o schema muda? `failOnNewColumns`\n5. Deve continuar rodando com schema congelado? `rescue` ou `none`\n\n## Casos de uso\n\n- **Analistas só de SQL carregando exportações mensais**: `COPY INTO` de um volume para uma tabela Bronze, reexecutado com segurança todo mês\n- **Clickstream de alto volume**: Auto Loader com file events processa milhares de pequenos JSONs por hora em `main.bronze.clicks`\n- **Feed de fornecedor tolerante a drift**: `schemaEvolutionMode = rescue` mantém o contrato da Silver estável enquanto `_rescued_data` captura campos inesperados para revisão\n- **Batch incremental agendado**: Auto Loader com `availableNow` disparado por file arrival trigger, sem compute ocioso entre as cargas\n\n## Problemas e erros comuns\n\n### COPY INTO carrega zero linhas ao reexecutar\n\n**Cenário:** um engenheiro reexecuta o `COPY INTO` depois de corrigir um bug na tabela de destino, e nenhuma linha é carregada.\n**Correção:** é a idempotência funcionando. Arquivos já carregados são ignorados. Para recarregar de propósito, use `COPY_OPTIONS ('force' = 'true')`, ou faça truncate e recarregue, garantindo que duplicatas sejam tratadas.\n\n### Stream do Auto Loader para com UnknownFieldException\n\n**Cenário:** um stream noturno falha depois que a fonte adiciona uma coluna.\n**Correção:** com o padrão `addNewColumns`, a falha é esperada. O schema já foi atualizado no schema location, então reiniciar o stream resolve. Rode como Lakeflow Job com retries para o reinício ser automático.\n\n### Todas as colunas são string\n\n**Cenário:** uma tabela Bronze de JSON criada com Auto Loader tem `amount` e `is_active` como `STRING`.\n**Correção:** JSON, CSV e XML são inferidos como strings por padrão. Defina `cloudFiles.inferColumnTypes = true` ou fixe os tipos com `cloudFiles.schemaHints`.\n\n### Reusar um checkpoint para dois streams\n\n**Cenário:** dois streams do Auto Loader compartilham o caminho de checkpoint e pulam os arquivos um do outro.\n**Correção:** cada workload de ingestão precisa do seu próprio checkpoint e schema location.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - \"Reexecução não carregou linhas novas\" → idempotência do `COPY INTO`. \"Recarregar mesmo assim\" → `'force' = 'true'`\n> - \"Detectar automaticamente novos arquivos e evoluir schema em escala\" → **Auto Loader**\n> - `addNewColumns` **para** o stream e evolui no reinício. `rescue` nunca para e nunca evolui. `failOnNewColumns` para até ser corrigido\n> - JSON/CSV viram strings a menos que você defina `cloudFiles.inferColumnTypes`\n> - File notification com **file events** em uma external location do UC é o modo de descoberta recomendado\n\n## Pontos-chave\n\n- `COPY INTO` é uma carga SQL idempotente com opções `mergeSchema` e `force`\n- Auto Loader é a fonte streaming `cloudFiles` com rastreamento de arquivos exactly-once via checkpoint\n- A inferência de schema amostra até 50 GB ou 1.000 arquivos e é guardada em `cloudFiles.schemaLocation`\n- Cinco valores de `schemaEvolutionMode` controlam o drift, e `_rescued_data` guarda o que não coube\n- Directory listing é o modo padrão de descoberta. File notification com file events é o recomendado\n\n## Tópicos relacionados\n\n- [Padrões de Ingestão e Lakeflow Connect](01-ingestion-patterns-and-lakeflow-connect.md)\n- [JDBC, REST e ingestão semiestruturada](03-jdbc-rest-and-semi-structured-ingestion.md)\n- [Fundamentos do Delta Lake (schema enforcement)](../01-databricks-intelligence-platform/04-delta-lake-fundamentals.md)\n\n## Documentação oficial\n\n- [Get started with COPY INTO](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/copy-into/)\n- [COPY INTO SQL reference](https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into)\n- [What is Auto Loader?](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/)\n- [Auto Loader schema inference and evolution](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema)\n- [Auto Loader file detection modes](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/file-detection-modes)\n- [Auto Loader options](https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/options)\n\n---\n\n**[← Anterior: Padrões de Ingestão e Lakeflow Connect](01-ingestion-patterns-and-lakeflow-connect.md) | [↑ Voltar para Data Ingestion and Loading](README.md) | [Próximo: JDBC, REST e ingestão semiestruturada →](03-jdbc-rest-and-semi-structured-ingestion.md)**\n"},{"id":"02-data-ingestion-and-loading/03-jdbc-rest-and-semi-structured-ingestion","folder":"02-data-ingestion-and-loading","group":"modulo","order":3,"isIndex":false,"title":"JDBC, REST e Ingestão Semiestruturada","md":"# JDBC, REST e Ingestão Semiestruturada\n\n## Visão geral\n\nAlgumas fontes não têm managed connector. Só são acessíveis via **driver JDBC/ODBC** ou **API REST**. Para elas, você escreve código em notebook que grava os dados em cloud storage (um volume UC) ou direto em uma tabela do Unity Catalog, e agenda com **Lakeflow Jobs**. Este arquivo também cobre a ingestão de dados **semiestruturados** (JSON aninhado) e **não estruturados** em tabelas Delta do UC, e os triggers do Structured Streaming que transformam qualquer uma dessas cargas em batch, incremental ou streaming.\n\n> [!abstract] Resumo\n>\n> - **JDBC**: `spark.read.format(\"jdbc\")` com `url`, `dbtable` ou `query`, e credenciais vindas de **Databricks secrets**. Paralelize com `partitionColumn`, `lowerBound`, `upperBound` e `numPartitions`\n> - **REST**: chame a API a partir de um notebook, grave as respostas brutas em um **volume UC** e depois carregue com Auto Loader ou `COPY INTO` — ou grave um DataFrame direto numa tabela UC\n> - **Semiestruturado**: use structs e arrays com notação de ponto e `explode`, a sintaxe de caminho `:` em strings JSON, ou o tipo **`VARIANT`**, que a Databricks recomenda no lugar de strings JSON\n> - **Triggers**: `processingTime` (streaming), `availableNow` (batch incremental) ou sem trigger (micro-batches o mais rápido possível)\n\n> [!tip] O que a prova cobra\n>\n> - Habilidades do exam guide: clientes JDBC/ODBC ou REST em notebooks gravando em cloud storage ou tabelas UC, agendados com Lakeflow Jobs; ingerir dados semiestruturados e não estruturados (JSON, aninhados) em tabelas Delta do UC\n> - Manter credenciais fora do código com `dbutils.secrets.get`\n> - Por que uma leitura JDBC é lenta (uma única thread por padrão) e como paralelizar\n> - Ler campos de JSON aninhado e \"achatar\" arrays\n\n---\n\n## Leituras JDBC a partir de um notebook\n\n```python\njdbc_url = \"jdbc:postgresql://db.example.com:5432/sales\"\n\norders = (spark.read\n    .format(\"jdbc\")\n    .option(\"url\", jdbc_url)\n    .option(\"dbtable\", \"public.orders\")\n    .option(\"user\", dbutils.secrets.get(scope=\"jdbc\", key=\"username\"))\n    .option(\"password\", dbutils.secrets.get(scope=\"jdbc\", key=\"password\"))\n    # Leitura paralela: divide a faixa de chaves em 8 consultas concorrentes\n    .option(\"partitionColumn\", \"order_id\")\n    .option(\"lowerBound\", \"1\")\n    .option(\"upperBound\", \"10000000\")\n    .option(\"numPartitions\", \"8\")\n    .option(\"fetchSize\", \"1000\")\n    .load())\n\norders.write.mode(\"overwrite\").saveAsTable(\"main.bronze.orders_snapshot\")\n```\n\n| Opção | Propósito | Orientação da documentação |\n| :--- | :--- | :--- |\n| `url`, `dbtable` | String de conexão e tabela de origem. `dbtable` pode ser uma subquery, que é executada no banco (push down) | Guarde credenciais em **secrets**, não na URL |\n| `partitionColumn`, `lowerBound`, `upperBound`, `numPartitions` | Dividem a leitura em consultas paralelas | Uma leitura JDBC usa **uma thread por padrão**. Escolha uma coluna indexada. Cuidado acima de ~50 partições |\n| `fetchSize` | Linhas por ida e volta na rede | Muito baixo aumenta a latência; muito alto pode causar out-of-memory. O padrão do Oracle é 10 |\n\nFonte: [Query databases using JDBC](https://docs.databricks.com/aws/en/connect/external-systems/jdbc). A mesma página diz: \"Se o Lakehouse Federation suporta seu banco de origem, a Databricks recomenda usá-lo\". O Federation consulta a fonte no lugar, sem cópia. Escolha ingestão JDBC quando precisar de uma cópia governada em Delta, por exemplo para histórico ou performance.\n\n### JDBC vs Lakehouse Federation vs managed connector\n\n| Abordagem | Copia dados? | Incremental? | Esforço | Escolha quando |\n| :--- | :--- | :--- | :--- | :--- |\n| **Managed database connector** | Sim, em streaming tables | Sim, via CDC | Baixo (só configuração) | A fonte é um banco suportado e você quer replicação contínua e governada |\n| **Lakehouse Federation** | Não, as consultas rodam na fonte | n/a | Baixo | Precisa de consultas ao vivo sem cópia, e a fonte é suportada |\n| **Leitura JDBC em notebook** | Sim, em tabelas Delta que você controla | Só se você programar (watermark + `MERGE`) | Médio (código + agenda) | Não existe conector, ou você precisa de lógica de extração customizada |\n\n### Padrão JDBC incremental\n\nUm snapshot completo a cada execução fica caro. Um padrão incremental comum aplica um filtro de watermark na consulta de origem e faz merge do resultado:\n\n```python\nlast_ts = spark.sql(\"SELECT coalesce(max(updated_at), '1900-01-01') AS ts FROM main.bronze.orders\").first().ts\n\nchanges = (spark.read.format(\"jdbc\")\n    .option(\"url\", jdbc_url)\n    .option(\"query\", f\"SELECT * FROM public.orders WHERE updated_at > '{last_ts}'\")\n    .option(\"user\", dbutils.secrets.get(scope=\"jdbc\", key=\"username\"))\n    .option(\"password\", dbutils.secrets.get(scope=\"jdbc\", key=\"password\"))\n    .load())\n\nchanges.createOrReplaceTempView(\"changes\")\nspark.sql(\"\"\"\n  MERGE INTO main.bronze.orders AS t\n  USING changes AS s ON t.order_id = s.order_id\n  WHEN MATCHED THEN UPDATE SET *\n  WHEN NOT MATCHED THEN INSERT *\n\"\"\")\n```\n\nSe o banco é suportado por um **managed database connector** (MySQL, PostgreSQL, SQL Server, Oracle), a ingestão baseada em CDC do conector costuma ser melhor que esse padrão escrito à mão. Veja [01-ingestion-patterns-and-lakeflow-connect.md](01-ingestion-patterns-and-lakeflow-connect.md).\n\n### ODBC e outros drivers\n\nO mesmo padrão vale para clientes ODBC e bibliotecas Python de banco instaladas com escopo de notebook (`%pip install`) ou como bibliotecas de environment. Leia no driver, converta para DataFrame Spark e grave numa tabela UC. Mantenha os segredos da conexão em um secret scope.\n\n## APIs REST a partir de um notebook\n\n```python\nimport json, requests\nfrom datetime import datetime, timezone\n\ntoken = dbutils.secrets.get(scope=\"vendor_api\", key=\"token\")\nresp = requests.get(\n    \"https://api.vendor.example.com/v1/orders\",\n    headers={\"Authorization\": f\"Bearer {token}\"},\n    params={\"updated_since\": dbutils.widgets.get(\"updated_since\")},\n    timeout=60,\n)\nresp.raise_for_status()\n\n# Grava o payload bruto em um volume UC (cloud storage), um arquivo por execução\nrun_ts = datetime.now(timezone.utc).strftime(\"%Y%m%dT%H%M%S\")\npath = f\"/Volumes/main/raw/landing/vendor_orders/orders_{run_ts}.json\"\nwith open(path, \"w\") as f:\n    f.write(json.dumps(resp.json()[\"data\"]))\n```\n\nDuas opções de landing:\n\n| Opção | Como | Quando |\n| :--- | :--- | :--- |\n| **Gravar primeiro em cloud storage** (recomendado para dados brutos) | Escreva arquivos JSON em um volume UC e ingira com Auto Loader ou `COPY INTO` | Mantém uma cópia bruta imutável para reprocessar. A evolução de schema fica com o loader |\n| **Gravar direto numa tabela UC** | `spark.createDataFrame(records).write.mode(\"append\").saveAsTable(...)` | Payloads pequenos em que a cópia bruta não é necessária |\n\n### Parametrizando o notebook\n\nFaça da janela de extração um parâmetro em vez de valor fixo, para que o mesmo notebook sirva execuções diárias e backfills:\n\n```python\ndbutils.widgets.text(\"updated_since\", \"1900-01-01\")   # padrão para execuções interativas\nupdated_since = dbutils.widgets.get(\"updated_since\")   # o parâmetro do job sobrescreve\n```\n\nNo job, defina o parâmetro `updated_since` com um valor como `{{job.start_time.iso_date}}`. Dynamic value references são resolvidas quando a execução começa ([dynamic value references](https://docs.databricks.com/aws/en/jobs/dynamic-value-references)).\n\n### Agendando com Lakeflow Jobs\n\nFaça do notebook a primeira task de um Lakeflow Job:\n\n1. **Task 1 (notebook)**: chama a API e grava os arquivos. Passe `updated_since` como parâmetro do job ou valor dinâmico como `{{job.start_time.iso_date}}`\n2. **Task 2 (pipeline ou notebook)**: o Auto Loader leva os arquivos para a Bronze\n3. Adicione **retries** na Task 1 para erros HTTP transitórios, um **timeout** para chamadas travadas e um trigger **agendado**. Veja o [Domínio 4](../04-working-with-lakeflow-jobs/README.md)\n\n## Dados semiestruturados e aninhados\n\n### Structs e arrays (schema tipado)\n\nQuando o JSON é lido com schema inferido ou explícito, objetos aninhados viram **structs** e listas viram **arrays**:\n\n```python\nraw = spark.read.json(\"/Volumes/main/raw/landing/vendor_orders/\")\n\nfrom pyspark.sql.functions import col, explode\n\nflat = (raw\n    .select(\n        col(\"order_id\"),\n        col(\"customer.id\").alias(\"customer_id\"),        # campo de struct\n        col(\"customer.address.city\").alias(\"city\"),     # struct aninhado\n        explode(col(\"line_items\")).alias(\"item\"))       # uma linha por elemento do array\n    .select(\"order_id\", \"customer_id\", \"city\",\n            col(\"item.sku\").alias(\"sku\"), col(\"item.qty\").alias(\"qty\")))\n```\n\n### Strings JSON com a sintaxe de caminho `:`\n\nSe uma coluna guarda **strings** JSON, o Databricks SQL extrai campos com `<coluna>:<caminho>`:\n\n```sql\nSELECT\n  raw:customer.id              AS customer_id,\n  raw:line_items[0].sku        AS first_sku,     -- arrays começam em 0\n  raw:total::double            AS total          -- cast com ::\nFROM main.bronze.vendor_orders_raw;\n\n-- Converter um fragmento aninhado em struct tipado\nSELECT from_json(raw:customer, 'id BIGINT, name STRING') AS customer\nFROM main.bronze.vendor_orders_raw;\n```\n\nFonte: [Query JSON strings](https://docs.databricks.com/aws/en/semi-structured/json).\n\n### O tipo `VARIANT`\n\n`VARIANT` guarda dados semiestruturados em uma forma binária tipada. Está disponível a partir do Databricks Runtime 15.4, e \"a Databricks recomenda usar `VARIANT` em vez de strings JSON para dados semiestruturados\" ([Query variant data](https://docs.databricks.com/aws/en/semi-structured/variant)).\n\n```sql\nCREATE TABLE main.bronze.events_variant AS\nSELECT parse_json(raw) AS payload FROM main.bronze.vendor_orders_raw;\n\nSELECT payload:customer.id::bigint AS customer_id,\n       variant_get(payload, '$.total', 'double') AS total\nFROM main.bronze.events_variant;\n```\n\n### Dados não estruturados\n\n```python\n# Batch: ler PDFs como linhas binárias (path, modificationTime, length, content)\npdfs = (spark.read.format(\"binaryFile\")\n    .option(\"pathGlobFilter\", \"*.pdf\")\n    .load(\"/Volumes/main/raw/documents/contracts/\"))\n\n# Incremental: Auto Loader com formato binaryFile\ndocs = (spark.readStream.format(\"cloudFiles\")\n    .option(\"cloudFiles.format\", \"binaryFile\")\n    .load(\"/Volumes/main/raw/documents/contracts/\"))\n```\n\nImagens, PDFs e áudios ficam em um **volume UC**. Podem ser lidos com o formato `binaryFile` (retorna caminho, data de modificação, tamanho e conteúdo) ou com Auto Loader (`cloudFiles.format = \"binaryFile\"`) para cargas incrementais. **File source** connectors gerenciados como SharePoint e Google Drive trazem documentos sem código.\n\n## Triggers do Structured Streaming (referência rápida)\n\n| Trigger | Sintaxe | Comportamento |\n| :--- | :--- | :--- |\n| Padrão (nenhum definido) | — | Micro-batches um atrás do outro (`processingTime` de 0), latência de ~3–5 s |\n| Intervalo fixo | `.trigger(processingTime=\"1 minute\")` | Um micro-batch a cada intervalo até ser parado |\n| Batch incremental | `.trigger(availableNow=True)` | Processa tudo que está disponível em um ou mais micro-batches e para |\n| Once | `.trigger(once=True)` | **Depreciado** (DBR 11.3 LTS+). Use `availableNow` |\n| Continuous | `.trigger(continuous=\"1 second\")` | **Não suportado** no Databricks. Use o real-time mode |\n\nToda escrita streaming precisa de um **`checkpointLocation`** (a menos que um Lakeflow pipeline o gerencie), e um DataFrame streaming deve ser escrito com **`writeStream`**, não `write`. Fonte: [trigger intervals](https://docs.databricks.com/aws/en/structured-streaming/triggers).\n\n## Casos de uso\n\n- **ERP sem conector**: um Lakeflow Job noturno faz leitura JDBC paralela das mudanças de ontem e faz merge na Bronze\n- **API de marketing**: um notebook puxa estatísticas de campanhas de uma API REST a cada hora, grava JSON num volume e o Auto Loader ingere\n- **Eventos de pedido aninhados**: a Silver achata `line_items` com `explode` para que cada item seja uma linha na agregação de receita\n- **Payloads de eventos que evoluem**: a Bronze guarda o evento bruto como `VARIANT`, e a Silver extrai colunas tipadas conforme estabilizam\n\n## Problemas e erros comuns\n\n### Leitura JDBC roda em um core só\n\n**Cenário:** uma leitura JDBC de 200 milhões de linhas leva horas enquanto o cluster fica ocioso.\n**Correção:** sem `partitionColumn`, `lowerBound`, `upperBound` e `numPartitions`, o Spark lê com uma thread. Adicione essas opções usando uma coluna numérica ou de data indexada.\n\n### Senha visível no notebook\n\n**Cenário:** um revisor encontra a senha do banco escrita direto nas opções JDBC.\n**Correção:** guarde-a em um secret scope e leia com `dbutils.secrets.get`. Valores de secrets aparecem como `[REDACTED]` na saída do notebook.\n\n### `explode` some com pedidos sem lista de itens\n\n**Cenário:** depois de `explode(line_items)`, pedidos cujo `line_items` é NULL desaparecem da Silver.\n**Correção:** `explode` não retorna linhas quando a coleção é NULL. `explode_outer` gera uma linha com NULLs, preservando o pedido ([explode_outer](https://docs.databricks.com/aws/en/sql/language-manual/functions/explode_outer)).\n\n### Rate limit da API derruba o job noturno\n\n**Cenário:** a task de extração REST falha de forma intermitente com HTTP 429, e o job inteiro fica como falho.\n**Correção:** adicione **retries** com intervalo na task de extração e pagine a API em janelas menores. Como os arquivos brutos vão primeiro para um volume, uma reexecução regrava apenas a sua janela. O Auto Loader depois pega os arquivos novos.\n\n### DataFrame streaming escrito com `write`\n\n**Cenário:** `df.write.saveAsTable(...)` em um DataFrame de `readStream` gera `AnalysisException`.\n**Correção:** fontes streaming precisam ser escritas com `writeStream` (`.toTable(...)` ou `.start(...)`) e um checkpoint location.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - \"A fonte só tem driver JDBC\" → `spark.read.format(\"jdbc\")`. Se o Lakehouse Federation suporta a fonte e não é preciso copiar, federation é o preferido\n> - Credenciais sempre vêm de **`dbutils.secrets.get`**\n> - Leitura JDBC lenta → adicione `partitionColumn` / limites / `numPartitions`\n> - Padrão REST: grave arquivos brutos num **volume**, carregue com Auto Loader e agende os dois passos em um único **Lakeflow Job**\n> - `availableNow` = processa todos os dados novos e para. `once` está depreciado. `continuous` não é suportado\n\n## Pontos-chave\n\n- Código em notebook cobre o que os managed connectors não cobrem: JDBC/ODBC para bancos, REST para APIs\n- Grave dados brutos em volumes UC para poder reprocessar, depois carregue em tabelas UC\n- JSON aninhado é tratado com structs e arrays, `explode`, a sintaxe `:` ou `VARIANT`\n- Lakeflow Jobs agendam e reexecutam esses notebooks como qualquer outra task\n\n## Tópicos relacionados\n\n- [Padrões de Ingestão e Lakeflow Connect](01-ingestion-patterns-and-lakeflow-connect.md)\n- [COPY INTO e Auto Loader](02-copy-into-and-auto-loader.md)\n- [Transformações avançadas (arrays, structs, explode)](../03-data-transformation-and-modeling/04-advanced-transformations.md)\n- [Lakeflow Jobs e Tasks](../04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks.md)\n\n## Documentação oficial\n\n- [Query databases using JDBC](https://docs.databricks.com/aws/en/connect/external-systems/jdbc)\n- [Secret management](https://docs.databricks.com/aws/en/security/secrets/)\n- [Query JSON strings](https://docs.databricks.com/aws/en/semi-structured/json)\n- [Query variant data](https://docs.databricks.com/aws/en/semi-structured/variant)\n- [Configure Structured Streaming trigger intervals](https://docs.databricks.com/aws/en/structured-streaming/triggers)\n\n---\n\n**[← Anterior: COPY INTO e Auto Loader](02-copy-into-and-auto-loader.md) | [↑ Voltar para Data Ingestion and Loading](README.md)**\n"},{"id":"02-data-ingestion-and-loading/README","folder":"02-data-ingestion-and-loading","group":"modulo","order":0,"isIndex":true,"title":"Data Ingestion and Loading","md":"# Data Ingestion and Loading (21 % da prova)\n\nO Domínio 2 é o segundo maior bloco da prova de agosto de 2026. Ele trata de colocar dados em tabelas governadas pelo Unity Catalog. Você precisa conhecer os padrões de ingestão (batch, streaming, incremental), de onde os dados vêm (arquivos locais, conectores standard e managed do Lakeflow Connect, clientes JDBC/ODBC e REST) e as ferramentas que fazem a carga (`COPY INTO`, Auto Loader, Lakeflow Connect). Também precisa escolher a ferramenta certa para um dado volume, frequência, tipo de dado e requisito de governança.\n\n> [!note] Atualização da plataforma (out/2026)\n> O exam guide fala em **Lakeflow Connect standard connectors**. A documentação atual descreve a mesma camada como \"Ingest with SQL and Spark APIs\": Auto Loader, `read_files`, streaming tables e fontes de Structured Streaming como Kafka. Os managed connectors não mudaram ([What is Lakeflow Connect?](https://docs.databricks.com/aws/en/ingestion/overview), [Ingest with SQL and Spark APIs](https://docs.databricks.com/aws/en/ingestion/)).\n\n## Visão geral dos tópicos\n\n```mermaid\nflowchart LR\n    Src[Fontes] --> Local[Arquivos locais / volumes]\n    Src --> Std[Standard connectors<br/>cloud storage, Kafka, SFTP]\n    Src --> Mgd[Managed connectors<br/>SaaS + bancos de dados]\n    Src --> Code[JDBC / ODBC / REST<br/>em notebooks]\n    Std --> CI[COPY INTO]\n    Std --> AL[Auto Loader]\n    Mgd --> LC[Lakeflow Connect<br/>ingestion pipeline]\n    Local --> UC[(Unity Catalog<br/>tabelas Delta)]\n    CI --> UC\n    AL --> UC\n    LC --> UC\n    Code --> UC\n```\n\n## Conteúdo da seção\n\n| Arquivo | Tópico | Prioridade |\n| :--- | :--- | :--- |\n| [01-ingestion-patterns-and-lakeflow-connect.md](01-ingestion-patterns-and-lakeflow-connect.md) | Batch vs streaming vs incremental, upload de arquivos locais, standard vs managed connectors, como escolher | Alta |\n| [02-copy-into-and-auto-loader.md](02-copy-into-and-auto-loader.md) | `COPY INTO`, inferência/evolução de schema no Auto Loader, directory listing vs file notification | Alta |\n| [03-jdbc-rest-and-semi-structured-ingestion.md](03-jdbc-rest-and-semi-structured-ingestion.md) | Clientes JDBC/ODBC e REST em notebooks, JSON e dados aninhados, triggers do Structured Streaming | Alta |\n\n## Cobertura das habilidades oficiais (agosto de 2026)\n\n| Habilidade do exam guide (parafraseada) | Onde é coberta |\n| :--- | :--- |\n| Padrões de ingestão (batch, streaming, incremental); importar de arquivos locais e conectores standard/managed do Lakeflow Connect | [01](01-ingestion-patterns-and-lakeflow-connect.md), [03 — triggers](03-jdbc-rest-and-semi-structured-ingestion.md) |\n| `COPY INTO` para cargas incrementais de ADLS/S3/GCS em tabelas UC | [02](02-copy-into-and-auto-loader.md) |\n| Auto Loader com schema enforcement e evolution; directory listing vs file notification | [02](02-copy-into-and-auto-loader.md) |\n| Configurar o Lakeflow Connect para fontes corporativas | [01](01-ingestion-patterns-and-lakeflow-connect.md) |\n| Clientes JDBC/ODBC ou REST em notebooks, agendados com Lakeflow Jobs | [03](03-jdbc-rest-and-semi-structured-ingestion.md) |\n| Escolher entre Auto Loader, Lakeflow Connect, partner connectors e outros métodos | [01](01-ingestion-patterns-and-lakeflow-connect.md) |\n| Dados semiestruturados e não estruturados (JSON, aninhados) em tabelas Delta do UC | [03](03-jdbc-rest-and-semi-structured-ingestion.md), [02](02-copy-into-and-auto-loader.md) |\n\n## Conceitos-chave\n\n- **Comece pela camada mais gerenciada**: a Databricks recomenda primeiro managed connectors, depois Lakeflow pipelines, e só então Structured Streaming e APIs Spark se necessário\n- **`COPY INTO`**: comando SQL idempotente e que pode ser reexecutado. Arquivos já carregados são ignorados nas reexecuções\n- **Auto Loader (`cloudFiles`)**: uma fonte de Structured Streaming. Registra os arquivos descobertos no checkpoint para processamento exactly-once e suporta inferência de schema, evolução e a coluna `_rescued_data`\n- **Managed connectors do Lakeflow Connect**: uma UC connection, um ingestion gateway (só para CDC de banco de dados) e um ingestion pipeline que escreve em streaming tables em compute serverless\n\n## Próximos passos\n\nContinue para [03 — Data Transformation and Modeling](../03-data-transformation-and-modeling/README.md) para transformar dados Bronze em Silver e Gold.\n\n---\n\n**[← Anterior: Databricks Intelligence Platform](../01-databricks-intelligence-platform/README.md) | [↑ Voltar à Certificação](../README.md) | [Próximo: Data Transformation and Modeling →](../03-data-transformation-and-modeling/README.md)**\n"},{"id":"03-data-transformation-and-modeling/01-spark-sql-fundamentals","folder":"03-data-transformation-and-modeling","group":"modulo","order":1,"isIndex":false,"title":"Fundamentos de Spark SQL","md":"# Fundamentos de Spark SQL\n\n## Visão geral\n\nO Spark SQL oferece uma interface SQL para processar dados estruturados com o poder de computação distribuída do Spark. Ele executa consultas SQL, lê CSV, Parquet e Delta, e se conecta a fontes externas.\n\n> [!abstract] Resumo\n>\n> - Spark SQL e a API de DataFrame compartilham o mesmo otimizador e engine. Use a linguagem que fizer mais sentido para a tarefa\n> - Views permanentes vivem no Unity Catalog. Views temporárias existem só durante a sessão\n> - Comandos de catálogo (`SHOW`, `DESCRIBE`, `USE CATALOG`, `USE SCHEMA`) navegam pelo namespace de três níveis\n\n> [!tip] O que a prova cobra\n>\n> - Apoia as habilidades do Domínio 3 sobre criar tabelas e views no Unity Catalog com SQL\n> - Escopo de views temporárias vs permanentes\n> - Rodar SQL a partir de Python com `spark.sql()` e células `%sql`\n\n---\n\n## Arquitetura do Spark SQL\n\n```mermaid\nflowchart TB\n    SQL[\"Consulta SQL\"]\n    Parser[\"Parser SQL\"]\n    Analyzer[\"Analisador do plano lógico\"]\n    Optimizer[\"Catalyst Optimizer\"]\n    Planner[\"Planejador físico\"]\n    Executor[\"Engine Spark\"]\n\n    SQL --> Parser\n    Parser --> Analyzer\n    Analyzer --> Optimizer\n    Optimizer --> Planner\n    Planner --> Executor\n```\n\n## Spark SQL vs DataFrames\n\n| Aspecto | Spark SQL | DataFrames |\n|--------|-----------|------------|\n| **Interface** | Consultas SQL | API Python/Scala/Java |\n| **Performance** | Otimizada pelo Catalyst | O mesmo otimizador Catalyst |\n| **Curva de aprendizado** | Fácil para quem sabe SQL | Exige conhecer a API |\n| **Flexibilidade** | Sintaxe SQL | Controle programático |\n| **Interoperabilidade** | Pode misturar com DataFrames | Pode misturar com SQL |\n\n## Criando tabelas\n\n### Managed vs External\n\n```python\n# Managed table (dados no diretório gerenciado)\nspark.sql(\"\"\"\nCREATE TABLE my_table (\n    id INT,\n    name STRING,\n    salary DECIMAL(10, 2)\n)\nUSING DELTA\n\"\"\")\n\n# External table (dados em local externo)\nspark.sql(\"\"\"\nCREATE TABLE my_external (\n    id INT,\n    name STRING\n)\nUSING DELTA\nLOCATION '/mnt/data/my_table'\n\"\"\")\n```\n\n### A partir de um DataFrame\n\n```python\ndf.write.mode(\"overwrite\").saveAsTable(\"my_table\")  # Managed\n\n# Externa\n(df.write\n    .mode(\"overwrite\")\n    .option(\"path\", \"/mnt/data/external\")\n    .saveAsTable(\"my_external_table\"))\n\n# A partir de arquivo\nspark.sql(\"\"\"\nCREATE TABLE my_parquet\nUSING PARQUET\nLOCATION '/mnt/data/input.parquet'\n\"\"\")\n```\n\n## Consultas e agregações\n\n### SELECT básico\n\n```python\nspark.sql(\"\"\"\nSELECT id, name, salary\nFROM employees\nWHERE salary > 50000\nORDER BY salary DESC\nLIMIT 10\n\"\"\").show()\n```\n\n### Agregações\n\n```python\nspark.sql(\"\"\"\nSELECT\n    department,\n    COUNT(*) as emp_count,\n    AVG(salary) as avg_salary,\n    MAX(salary) as max_salary,\n    MIN(salary) as min_salary\nFROM employees\nGROUP BY department\nHAVING COUNT(*) > 5\n\"\"\")\n```\n\n> `WHERE` filtra linhas **antes** do agrupamento; `HAVING` filtra grupos **depois** da agregação.\n\n### Window functions\n\n```sql\nSELECT\n    name,\n    department,\n    salary,\n    ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) as rank,\n    SUM(salary) OVER (PARTITION BY department) as dept_total\nFROM employees\n```\n\n## Views e views temporárias\n\n### Views permanentes\n\n```python\n# Criar view (registrada no catálogo)\nspark.sql(\"\"\"\nCREATE VIEW high_earners AS\nSELECT name, salary\nFROM employees\nWHERE salary > 100000\n\"\"\")\n\nspark.sql(\"DROP VIEW IF EXISTS high_earners\")\n```\n\n### Views temporárias\n\n```python\n# Escopo de sessão (some quando a sessão termina)\nspark.sql(\"\"\"\nCREATE TEMP VIEW temp_view AS\nSELECT * FROM employees LIMIT 100\n\"\"\")\n\n# Global temporária (acessível entre sessões no mesmo cluster)\nspark.sql(\"\"\"\nCREATE GLOBAL TEMP VIEW global_view AS\nSELECT * FROM large_table\n\"\"\")\n\n# Consultar a global temp view\nspark.sql(\"SELECT * FROM global_temp.global_view\")\n```\n\n## Operações de catálogo\n\n### Listando objetos\n\n```python\nspark.catalog.listDatabases()          # bancos/schemas\nspark.catalog.listTables(\"default\")    # tabelas de um schema\nspark.catalog.listColumns(\"my_table\")  # colunas\nspark.catalog.tableExists(\"my_table\")  # existe?\n```\n\n### Trocando o contexto\n\n```python\nspark.sql(\"USE my_database\")\n\n# Agora as consultas referenciam my_database por padrão\nspark.sql(\"SELECT * FROM my_table\")  # Usa my_database.my_table\n```\n\nNo Unity Catalog, use `USE CATALOG main;` e `USE SCHEMA silver;` para definir catálogo e schema padrão.\n\n## Tipos de dados\n\n```sql\n-- Numéricos\nINT, BIGINT, FLOAT, DOUBLE, DECIMAL(10,2)\n\n-- Texto\nSTRING, VARCHAR(100), CHAR(10)\n\n-- Booleano\nBOOLEAN\n\n-- Data/Hora\nDATE, TIMESTAMP, TIMESTAMP_NTZ\n\n-- Complexos\nARRAY<INT>\nMAP<STRING, INT>\nSTRUCT<name STRING, age INT>\n\n-- Binário\nBINARY\n```\n\n## Particionamento\n\n```python\nspark.sql(\"\"\"\nCREATE TABLE sales (\n    id INT,\n    amount DECIMAL(10, 2)\n)\nPARTITIONED BY (year INT, month INT)\nUSING DELTA\n\"\"\")\n\nspark.sql(\"\"\"\nINSERT INTO sales\nPARTITION (year=2025, month=1)\nSELECT id, amount FROM new_sales\n\"\"\")\n```\n\n> Para tabelas novas, a Databricks recomenda **Liquid Clustering** em vez de particionamento (veja o [Domínio 6](../06-troubleshooting-monitoring-and-optimization/04-liquid-clustering-and-predictive-optimization.md)).\n\n## Spark SQL vs Hive SQL\n\n| Recurso | Spark SQL | Hive SQL |\n|---------|-----------|----------|\n| **Performance** | Rápida (Catalyst) | Mais lenta |\n| **Tipos de dados** | 20+ tipos | Limitados |\n| **Conformidade** | ANSI SQL | Dialeto Hive |\n| **Execução** | Engine Spark | Hive + MapReduce |\n\n## Casos de uso\n\n- **Transformações em larga escala**: usar a execução distribuída do Spark SQL para transformar datasets de vários terabytes com eficiência.\n- **Exploração interativa**: usar Spark SQL em notebooks para consultas ad hoc em tabelas Delta, inspecionar schema com `DESCRIBE` e prototipar lógica de transformação antes de levá-la para pipelines de produção.\n\n## Problemas e erros comuns\n\n### Erros de OOM\n\n**Cenário:** skew nos dados faz um executor ficar sem memória.\n**Correção:** use Adaptive Query Execution (AQE) e revise a lógica de join.\n\n### Temp views não visíveis entre SparkSessions\n\n**Cenário:** uma view temporária criada em um notebook não é acessível em outro notebook ou outra SparkSession, gerando `AnalysisException: Table or view not found`.\n**Correção:** use global temporary views (`CREATE GLOBAL TEMP VIEW`) consultando via `global_temp.view_name`, ou persista os dados como tabela em vez de view.\n\n### Diferenças de sintaxe entre Spark SQL e ANSI SQL\n\n**Cenário:** consultas com sintaxe ANSI estrita (divisão inteira, cast implícito) geram resultados inesperados ou erros no Spark SQL por diferenças de dialeto.\n**Correção:** defina `spark.sql.ansi.enabled = true` para impor o comportamento ANSI, ou revise as regras específicas do Spark SQL para operadores e casts.\n\n## Dicas para a prova\n\n- Saiba a diferença entre managed tables (dados apagados com `DROP TABLE`) e external tables (dados persistem após o `DROP TABLE`)\n- Temp views têm escopo de sessão; global temp views usam o banco `global_temp` e sobrevivem entre sessões\n- O Catalyst otimiza consultas SQL e de DataFrame da mesma forma\n- Entenda `CREATE TABLE ... USING DELTA` vs `CREATE TABLE ... USING PARQUET` e as vantagens do Delta\n\n## Pontos-chave\n\n- **Managed vs External**: local e ciclo de vida dos dados\n- **Temp views**: escopo de sessão, apagadas automaticamente\n- **Particionamento**: organiza tabelas grandes para performance\n- **Catálogo**: gestão de metadados\n- **Otimização SQL**: benefícios do Catalyst\n\n## Tópicos relacionados\n\n- [Operações com DataFrame](02-dataframe-operations.md)\n\n## Documentação oficial\n\n- [Spark SQL Guide](https://docs.databricks.com/en/sql/language-manual/index.html)\n- [Tables in Databricks](https://docs.databricks.com/en/tables/index.html)\n\n---\n\n**[↑ Voltar para Data Transformation and Modeling](README.md) | [Próximo: Operações com DataFrame →](02-dataframe-operations.md)**\n"},{"id":"03-data-transformation-and-modeling/02-dataframe-operations","folder":"03-data-transformation-and-modeling","group":"modulo","order":2,"isIndex":false,"title":"Operações com DataFrame","md":"# Operações com DataFrame\n\n## Visão geral\n\nDataFrames são a principal abstração do Spark para dados estruturados. São uma coleção distribuída de linhas organizadas em colunas nomeadas, com um schema definido. Combinam a familiaridade do SQL com o poder da computação distribuída.\n\n> [!abstract] Resumo\n>\n> - DataFrames são lazy: transformações montam um plano e ações (`count`, `show`, `write`) o executam\n> - Operações de coluna: `select`, `withColumn`, `withColumnRenamed`, `drop`, `filter` / `where`\n> - Deduplique com `distinct()` (todas as colunas) ou `dropDuplicates([...])` (chaves escolhidas)\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: manipular colunas, linhas e estrutura de tabelas (adicionar, remover, split, renomear, filtrar, explode)\n> - Habilidade do exam guide: deduplicação e agregações (count, contagem distinta aproximada, média, summary)\n> - Identificar quais chamadas são ações e quais são transformações\n\n---\n\n## O que é um DataFrame?\n\n```mermaid\nflowchart TB\n    subgraph Input[\"Fontes de dados\"]\n        CSV[\"Arquivos CSV\"]\n        JSON[\"Dados JSON\"]\n        DB[\"Bancos de dados\"]\n        Streaming[\"Streaming\"]\n    end\n\n    DataFrame[\"Apache Spark DataFrame\"]\n\n    subgraph Operations[\"Operações\"]\n        Transform[\"Transformações<br/>(select, filter, map)\"]\n        Action[\"Ações<br/>(show, collect, write)\"]\n    end\n\n    subgraph Output[\"Saída\"]\n        DF[\"Delta Lake\"]\n        SQL[\"Tabelas SQL\"]\n        Files[\"Parquet/CSV\"]\n    end\n\n    Input --> DataFrame\n    DataFrame --> Operations\n    Transform --> Action\n    Action --> Output\n```\n\n## Criando DataFrames\n\n### A partir de coleções Python\n\n```python\ndata = [\n    (1, \"Alice\", 85000),\n    (2, \"Bob\", 75000),\n    (3, \"Charlie\", 95000)\n]\n\ndf = spark.createDataFrame(data, [\"id\", \"name\", \"salary\"])\ndf.show()\n```\n\n### A partir de arquivos\n\n```python\ndf_csv = (spark.read.format(\"csv\")\n    .option(\"header\", \"true\")\n    .option(\"inferSchema\", \"true\")\n    .load(\"/path/to/data.csv\"))\n\ndf_json = spark.read.json(\"/path/to/data.json\")\ndf_parquet = spark.read.parquet(\"/path/to/data.parquet\")\ndf_delta = spark.read.format(\"delta\").load(\"/path/to/delta/table\")\n```\n\n### A partir de Pandas\n\n```python\nimport pandas as pd\n\npandas_df = pd.DataFrame({\n    \"id\": [1, 2, 3],\n    \"name\": [\"Alice\", \"Bob\", \"Charlie\"],\n    \"salary\": [85000, 75000, 95000]\n})\n\nspark_df = spark.createDataFrame(pandas_df)\n```\n\n### A partir de uma consulta SQL\n\n```python\ndf = spark.sql(\"\"\"\n    SELECT id, name, salary\n    FROM employees\n    WHERE department = 'Engineering'\n\"\"\")\n```\n\n## Schema do DataFrame\n\n### Inspecionando o schema\n\n```python\ndf.printSchema()\n# root\n#  |-- id: long (nullable = true)\n#  |-- name: string (nullable = true)\n#  |-- salary: decimal(10,2) (nullable = true)\n\nschema = df.schema    # StructType\ncolumns = df.columns  # ['id', 'name', 'salary']\ndtypes = df.dtypes    # [('id', 'long'), ('name', 'string'), ...]\n```\n\n### Definindo o schema explicitamente\n\n```python\nfrom pyspark.sql.types import StructType, StructField, IntegerType, StringType, DecimalType\n\nschema = StructType([\n    StructField(\"id\", IntegerType(), True),\n    StructField(\"name\", StringType(), True),\n    StructField(\"salary\", DecimalType(10, 2), True)\n])\n\ndf = spark.read.schema(schema).csv(\"/path/to/data.csv\", header=True)\n```\n\nTambém é possível passar o schema como string DDL: `spark.read.schema(\"id INT, name STRING, salary DECIMAL(10,2)\")`.\n\n## Transformações principais\n\n### Select e projeção\n\n```python\nfrom pyspark.sql.functions import col\n\ndf.select(\"id\", \"name\").show()\n\n# Com alias\ndf.select(\n    col(\"id\"),\n    col(\"name\").alias(\"employee_name\"),\n    col(\"salary\")\n).show()\n\n# Com expressões SQL\ndf.selectExpr(\n    \"id\",\n    \"name as employee_name\",\n    \"salary * 1.1 as projected_salary\"\n).show()\n```\n\n### Filter e WHERE\n\n```python\ndf.filter(col(\"salary\") > 80000).show()\n\n# Várias condições: & (and), | (or), ~ (not) — use parênteses!\ndf.filter((col(\"salary\") > 50000) & (col(\"name\") != \"Bob\")).show()\n\n# Filtro em string SQL\ndf.filter(\"salary > 80000 AND department = 'Engineering'\").show()\n```\n\n`filter` e `where` são sinônimos.\n\n### Adicionando, renomeando e removendo colunas\n\n```python\ndf_new = df.withColumn(\"bonus\", col(\"salary\") * 0.1)\n\ndf_new = (df.withColumn(\"annual_bonus\", col(\"salary\") * 0.15)\n    .withColumn(\"is_manager\", col(\"salary\") > 100000))\n\ndf_renamed = df.withColumnRenamed(\"salary\", \"annual_salary\")\n\ndf_dropped = df.drop(\"bonus\")\n```\n\n### Distinct e deduplicação\n\n```python\ndf.distinct().show()                               # linhas distintas (todas as colunas)\ndf.select(col(\"department\")).distinct().count()    # contagem de valores distintos\ndf.dropDuplicates([\"id\", \"name\"])                  # dedup por colunas específicas\n```\n\n### Ordenação\n\n```python\ndf.orderBy(\"salary\").show()\ndf.orderBy(col(\"salary\").desc()).show()\ndf.orderBy(col(\"department\").asc(), col(\"salary\").desc()).show()\n```\n\n### Estatísticas descritivas\n\n```python\ndf.describe().show()   # count, mean, stddev, min, max\ndf.summary().show()    # o mesmo + percentis 25%, 50%, 75%\n```\n\n## Ações\n\nAções calculam e retornam resultados ao driver ou gravam dados:\n\n```python\ndf.show()                 # primeiras 20 linhas\ndf.show(100)              # 100 linhas\ndf.show(truncate=False)   # não trunca strings longas\n\nall_rows = df.collect()   # TODAS as linhas para o driver — cuidado!\nrow_count = df.count()\nfirst_5 = df.take(5)\n\ndf.write.format(\"delta\").mode(\"overwrite\").save(\"/path/to/table\")\n```\n\n## Referência de tipos de dados\n\n| Tipo | Exemplo Python | Tamanho |\n|------|---|---|\n| `IntegerType` | `123` | 4 bytes |\n| `LongType` | `123456789` | 8 bytes |\n| `FloatType` | `1.23` | 4 bytes |\n| `DoubleType` | `1.23456` | 8 bytes |\n| `StringType` | `\"text\"` | Variável |\n| `BooleanType` | `True` | 1 byte |\n| `DateType` | `date(2025, 1, 15)` | 4 bytes |\n| `TimestampType` | `datetime.now()` | 8 bytes |\n| `ArrayType` | `[1, 2, 3]` | Variável |\n| `MapType` | `{\"key\": \"value\"}` | Variável |\n\n## Padrões comuns\n\n### Tamanho do DataFrame\n\n```python\nnum_rows = df.count()\n\n# Não existe API direta de uso de memória no PySpark.\n# Faça cache, dispare uma ação e veja a aba \"Storage\" da Spark UI.\ndf.cache()\ndf.count()\n\nprint(f\"Colunas: {len(df.columns)}\")\n```\n\n### DataFrame para Pandas (apenas dados pequenos)\n\n```python\n# ATENÇÃO: traz todos os dados para o driver\npandas_df = df.toPandas()\n\n# Só as primeiras 1000 linhas\npandas_df = df.limit(1000).toPandas()\n```\n\n### Amostragem\n\n```python\nsample_df = df.sample(fraction=0.1)  # amostra de 10%\n\n# Amostra estratificada\nsample_df = df.sampleBy(\"category\", fractions={\"A\": 0.2, \"B\": 0.3})\n```\n\n## Considerações de performance\n\n| Operação | Custo | Quando usar |\n|-----------|------|-----------|\n| `select` | Baixo | Sempre, para reduzir colunas |\n| `filter` | Baixo | Aplique filtros cedo |\n| `collect` | Alto | Evite em DataFrames grandes |\n| `distinct` | Alto | Com cuidado em datasets grandes (causa shuffle) |\n| `take` | Baixo | Use antes de show/collect |\n\n## Casos de uso\n\n- **Pipelines de ETL com schema garantido**: definir schemas explícitos com `StructType` para validar os dados recebidos antes de gravar em tabelas Delta, pegando incompatibilidades de tipo cedo.\n- **Profiling exploratório**: usar `describe()`, `summary()`, `printSchema()` e `distinct().count()` para conhecer datasets novos e identificar problemas de qualidade antes de escrever a lógica de transformação.\n\n## Problemas e erros comuns\n\n### OOM no driver depois de `collect()`\n\n**Cenário:** `df.collect()` ou `df.toPandas()` em uma tabela grande derruba o driver com out-of-memory.\n**Correção:** essas chamadas trazem todas as linhas para o driver. Use `display(df)`, `df.limit(n)` ou grave os resultados numa tabela. Veja [Compute Troubleshooting](../06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting.md).\n\n### Coluna ambígua após join\n\n**Cenário:** depois de juntar dois DataFrames com colunas de mesmo nome, `select()` ou `filter()` geram `AnalysisException: Reference is ambiguous`.\n**Correção:** use aliases ou a sintaxe `df[\"col\"]` para desambiguar, ou faça o join por lista de nomes (ex.: `[\"id\"]`), que deduplica a coluna-chave automaticamente.\n\n### AnalysisException por nome de coluna errado\n\n**Cenário:** `withColumn()` ou `select()` falha com `AnalysisException: cannot resolve column name` por erro de digitação ou maiúsculas/minúsculas.\n**Correção:** confira o schema com `df.columns` ou `df.printSchema()` antes de transformar.\n\n## Dicas para a prova\n\n- Entenda a diferença entre transformações (lazy, retornam novo DataFrame) e ações (disparam execução: `show`, `collect`, `count`, `write`)\n- Saiba definir schemas com `StructType` e `StructField` — a prova costuma cobrar\n- `collect()` traz tudo para o driver; evite em DataFrames grandes — use `take()` ou `limit()`\n- `dropDuplicates([\"col1\", \"col2\"])` deduplica por colunas específicas; `distinct()` usa todas as colunas\n\n## Pontos-chave\n\n- **DataFrame**: coleção distribuída e imutável de linhas com schema\n- **Lazy evaluation**: transformações só executam quando uma ação é chamada\n- **Schema**: nomes, tipos e nulabilidade das colunas\n- **Transformações**: retornam novo DataFrame (select, filter, withColumn)\n- **Ações**: calculam e retornam resultados (show, collect, count, write)\n- **Seleção de colunas**: use `col()` para expressões\n- **Condições**: use `&` (e), `|` (ou), `~` (não)\n\n## Tópicos relacionados\n\n- [Fundamentos de Spark SQL](01-spark-sql-fundamentals.md)\n- [Joins e Agregações](03-joins-aggregations.md)\n\n## Documentação oficial\n\n- [PySpark DataFrame API](https://docs.databricks.com/en/pyspark/index.html)\n- [Tutorial: Load and transform data using DataFrames](https://docs.databricks.com/aws/en/getting-started/dataframes)\n\n---\n\n**[← Anterior: Fundamentos de Spark SQL](01-spark-sql-fundamentals.md) | [↑ Voltar para Data Transformation and Modeling](README.md) | [Próximo: Joins e Agregações →](03-joins-aggregations.md)**\n"},{"id":"03-data-transformation-and-modeling/03-joins-aggregations","folder":"03-data-transformation-and-modeling","group":"modulo","order":3,"isIndex":false,"title":"Joins e Agregações","md":"# Joins e Agregações\n\n## Visão geral\n\nJoins e agregações são operações fundamentais para combinar dados de várias fontes e calcular estatísticas resumidas. Dominar a otimização de joins e as funções de agregação é essencial para construir pipelines eficientes.\n\n> [!abstract] Resumo\n>\n> - Tipos de join: inner, left/right/full outer, cross, semi, anti. Joins podem usar várias chaves\n> - `union` / `unionAll` mantêm duplicatas e casam por posição. `unionByName` casa por nome. O `UNION` do SQL deduplica e o `UNION ALL` não\n> - Broadcast joins evitam shuffle copiando o lado pequeno para todos os executores\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: combinar DataFrames com joins inner, left, broadcast, múltiplas chaves e cross, e com union e union all\n> - Habilidade do exam guide: agregações como count, contagem distinta aproximada e média\n> - Prever a quantidade de linhas de um join e identificar colunas duplicadas após o join\n\n---\n\n## Tipos de join\n\n```mermaid\nflowchart LR\n    subgraph Types[\"Tipos de Join\"]\n        Inner[\"Inner<br/>Casam nas duas tabelas\"]\n        Left[\"Left/Left Outer<br/>Toda a esquerda + matches\"]\n        Right[\"Right/Right Outer<br/>Toda a direita + matches\"]\n        Full[\"Full/Outer<br/>Tudo dos dois lados\"]\n        Cross[\"Cross<br/>Produto cartesiano\"]\n        Anti[\"Anti<br/>Esquerda SEM match\"]\n        Semi[\"Semi<br/>Esquerda COM match\"]\n    end\n\n    LeftDF[\"DataFrame esquerdo\"]\n    RightDF[\"DataFrame direito\"]\n    Result[\"Resultado\"]\n\n    LeftDF --> Types\n    RightDF --> Types\n    Types --> Result\n```\n\n## Sintaxe dos joins\n\n### Inner join\n\n```sql\nSELECT l.id, l.name, r.department, r.salary\nFROM employees l\nINNER JOIN departments r\n    ON l.department_id = r.id\nWHERE l.salary > 50000\n```\n\n```python\ndf_inner = employees.join(\n    departments,\n    employees.department_id == departments.id,\n    how=\"inner\"\n)\n\n# Ou pelo nome da chave (presente nos dois lados) — não duplica a coluna\ndf_inner = employees.join(departments, [\"department_id\"], how=\"inner\")\n```\n\n### Join com várias chaves\n\n```python\ndf = orders.join(\n    shipments,\n    (orders.order_id == shipments.order_id) & (orders.region == shipments.region),\n    \"inner\"\n)\n\n# Ou por lista de nomes\ndf = orders.join(shipments, [\"order_id\", \"region\"], \"inner\")\n```\n\n### Left outer join\n\n```sql\nSELECT l.id, l.name, COALESCE(r.department, 'Unknown') as department\nFROM employees l\nLEFT OUTER JOIN departments r\n    ON l.department_id = r.id\n```\n\n```python\ndf_left = employees.join(departments, employees.department_id == departments.id, how=\"left\")\n```\n\n### Right outer join\n\n```python\ndf_right = employees.join(departments, employees.department_id == departments.id, how=\"right\")\n```\n\n### Full outer join\n\n```sql\nSELECT COALESCE(l.id, r.id) as id, l.name, r.department\nFROM employees l\nFULL OUTER JOIN departments r\n    ON l.department_id = r.id\n```\n\n```python\ndf_full = employees.join(departments, employees.department_id == departments.id, how=\"outer\")\n```\n\n### Cross join\n\n```sql\n-- Produto cartesiano (cada linha da esquerda com cada linha da direita)\nSELECT l.id, r.option\nFROM employees l\nCROSS JOIN product_options r\n```\n\n```python\ndf_cross = employees.crossJoin(options)   # ou employees.join(options, how=\"cross\")\n```\n\nSe a esquerda tem 100 linhas e a direita 5, o resultado tem **500** linhas.\n\n### Semi join (join de filtro)\n\n```sql\n-- Linhas da esquerda que têm match na direita (sem colunas da direita)\nSELECT *\nFROM employees l\nWHERE EXISTS (\n    SELECT 1 FROM departments r\n    WHERE l.department_id = r.id AND r.budget > 100000\n)\n```\n\n```python\ndf_semi = employees.join(departments, employees.department_id == departments.id, how=\"semi\")\n```\n\n### Anti join\n\n```sql\n-- Linhas da esquerda que NÃO têm match na direita\nSELECT *\nFROM employees l\nWHERE NOT EXISTS (\n    SELECT 1 FROM blacklist r WHERE l.id = r.employee_id\n)\n```\n\n```python\ndf_anti = employees.join(blacklist, employees.id == blacklist.employee_id, how=\"anti\")\n```\n\n## Comparação de joins\n\n| Tipo | Linhas da esquerda | Linhas da direita | Caso de uso |\n|-----------|-----------|----------|----------|\n| Inner | Só matches | Só matches | Encontrar registros correspondentes |\n| Left | Todas | Só matches | Manter a esquerda, enriquecer se houver match |\n| Right | Só matches | Todas | Manter a direita, enriquecer se houver match |\n| Full | Todas | Todas | Nunca perder dados de nenhum lado |\n| Cross | Todas | Todas | Criar todas as combinações |\n| Semi | Com match | Nunca (sem colunas) | Filtrar a esquerda pela existência na direita |\n| Anti | Sem match | Nunca (sem colunas) | Filtrar a esquerda pela inexistência na direita |\n\n## Union e union all\n\n```python\n# union / unionAll: casam colunas por POSIÇÃO e mantêm duplicatas (= UNION ALL)\ncombined = df_2024.union(df_2025)\n\n# unionByName: casa colunas por NOME (seguro se a ordem das colunas diferir)\ncombined = df_2024.unionByName(df_2025)\n\n# Colunas que faltam em um lado viram NULL\ncombined = df_a.unionByName(df_b, allowMissingColumns=True)\n\n# Para remover duplicatas depois do union\ncombined_dedup = df_2024.union(df_2025).distinct()\n```\n\n```sql\nSELECT * FROM sales_2024\nUNION ALL          -- mantém duplicatas\nSELECT * FROM sales_2025;\n\nSELECT * FROM sales_2024\nUNION              -- remove duplicatas\nSELECT * FROM sales_2025;\n```\n\n> [!warning] Pegadinha\n> No PySpark, `df.union()` **não** remove duplicatas (diferente do `UNION` do SQL). E como casa por posição, unir DataFrames com colunas em ordem diferente gera dados trocados silenciosamente — use `unionByName`.\n\n## Agregações e GROUP BY\n\n### Agregações básicas\n\n```sql\nSELECT\n    department,\n    COUNT(*) as emp_count,\n    AVG(salary) as avg_salary,\n    MAX(salary) as max_salary,\n    MIN(salary) as min_salary,\n    SUM(salary) as total_salary\nFROM employees\nGROUP BY department\n```\n\n```python\nfrom pyspark.sql import functions as F\n\ndf_agg = (employees\n    .groupBy(\"department\")\n    .agg(\n        F.count(\"*\").alias(\"emp_count\"),\n        F.avg(\"salary\").alias(\"avg_salary\"),\n        F.max(\"salary\").alias(\"max_salary\"),\n        F.min(\"salary\").alias(\"min_salary\"),\n        F.sum(\"salary\").alias(\"total_salary\")\n    ))\n```\n\n### Várias colunas de agrupamento\n\n```python\ndf_multi_group = (employees\n    .groupBy(\"department\", \"job_title\")\n    .agg(\n        F.count(\"*\").alias(\"count\"),\n        F.avg(\"salary\").alias(\"avg_salary\"),\n        F.stddev(\"salary\").alias(\"salary_stddev\")\n    ))\n```\n\n### HAVING (filtro depois do GROUP BY)\n\n```sql\nSELECT department, COUNT(*) as emp_count, AVG(salary) as avg_salary\nFROM employees\nGROUP BY department\nHAVING COUNT(*) > 10 AND AVG(salary) > 80000\n```\n\n```python\ndf_having = (employees\n    .groupBy(\"department\")\n    .agg(F.count(\"*\").alias(\"emp_count\"), F.avg(\"salary\").alias(\"avg_salary\"))\n    .filter((F.col(\"emp_count\") > 10) & (F.col(\"avg_salary\") > 80000)))\n```\n\n## Funções de agregação\n\n| Função | Propósito | Exemplo |\n|----------|---------|---------|\n| `COUNT(*)` | Contagem de linhas | `COUNT(*) = 5` |\n| `SUM()` | Soma | `SUM(salary)` |\n| `AVG()` / `MEAN()` | Média | `AVG(salary)` |\n| `MIN()` / `MAX()` | Extremos | `MAX(salary)` |\n| `STDDEV()` | Desvio padrão | `STDDEV(salary)` |\n| `VARIANCE()` | Variância | `VARIANCE(salary)` |\n| `COLLECT_LIST()` | Junta em array (com repetição) | `COLLECT_LIST(name)` |\n| `COLLECT_SET()` | Junta em array (valores únicos) | `COLLECT_SET(category)` |\n| `FIRST()` / `LAST()` | Primeiro/último valor | `FIRST(hire_date)` |\n| `APPROX_COUNT_DISTINCT()` | Contagem distinta aproximada (HyperLogLog++) — muito mais barata que `COUNT(DISTINCT)` em dados enormes | `APPROX_COUNT_DISTINCT(id)` |\n\n## Agrupamento avançado\n\n### Várias agregações em uma consulta\n\n```python\ndf_complex = (employees\n    .groupBy(\"department\", \"year\")\n    .agg(\n        F.count(\"id\").alias(\"headcount\"),\n        F.sum(F.when(F.col(\"salary\") > 100000, 1).otherwise(0)).alias(\"high_earners\"),\n        F.avg(\"salary\").alias(\"avg_salary\"),\n        F.collect_list(\"name\").alias(\"employee_names\")\n    ))\n```\n\n### Agregação condicional\n\n```python\ndf_conditional = (employees\n    .groupBy(\"department\")\n    .agg(\n        F.count(F.when(F.col(\"salary\") > 100000, 1)).alias(\"high_earners\"),\n        F.count(F.when(F.col(\"salary\") <= 100000, 1)).alias(\"regular_earners\")\n    ))\n```\n\n## Performance de joins\n\n### Broadcast join (tabela pequena)\n\n```python\n# O Spark faz broadcast automático de tabelas < 10 MB\n# (spark.sql.autoBroadcastJoinThreshold), mas dá para forçar:\nfrom pyspark.sql.functions import broadcast\n\ndf_result = large_df.join(broadcast(small_df), large_df.key == small_df.key, how=\"inner\")\n```\n\n```sql\nSELECT /*+ BROADCAST(d) */ *\nFROM sales s JOIN dim_product d ON s.product_id = d.product_id\n```\n\n### Bucketing para joins\n\n```python\n(employees.write\n    .bucketBy(10, \"department_id\")\n    .mode(\"overwrite\")\n    .saveAsTable(\"employees_bucketed\"))\n```\n\n### Salting para joins com skew\n\n```python\nimport pyspark.sql.functions as F\n\nSALT_BUCKETS = 10\n\nemployees_salt = employees.withColumn(\"salt\", (F.rand() * SALT_BUCKETS).cast(\"int\"))\ndepartments_salt = departments.crossJoin(spark.range(0, SALT_BUCKETS).toDF(\"salt\"))\n\nresult = (employees_salt.join(\n    departments_salt,\n    (employees_salt.dept_id == departments_salt.id) &\n    (employees_salt.salt == departments_salt.salt),\n    \"inner\"\n).drop(\"salt\"))\n```\n\n## Window functions com agregações\n\n```sql\nSELECT\n    name,\n    department,\n    salary,\n    AVG(salary) OVER (PARTITION BY department) as dept_avg,\n    RANK() OVER (PARTITION BY department ORDER BY salary DESC) as salary_rank\nFROM employees\n```\n\n```python\nfrom pyspark.sql.window import Window\n\nwindow = Window.partitionBy(\"department\").orderBy(F.desc(\"salary\"))\n\ndf_window = (employees\n    .withColumn(\"dept_avg\", F.avg(\"salary\").over(Window.partitionBy(\"department\")))\n    .withColumn(\"salary_rank\", F.rank().over(window)))\n```\n\n## Problemas comuns de join\n\n| Problema | Causa | Solução |\n|-------|-------|----------|\n| Explosão cartesiana | Condição de join errada ou ausente | Confira se as chaves casam corretamente |\n| Erros de memória | Join de tabelas grandes sem broadcast | Use broadcast ou bucketing |\n| Dados com skew | Um valor de chave tem muitas linhas | Aplique salting (ou AQE skew join) |\n| Duplicatas | Vários matches dos dois lados | Use semi join ou deduplique antes |\n\n## Casos de uso\n\n- **Transformações em larga escala**: usar a execução distribuída do Spark para transformar datasets de vários terabytes.\n- **Enriquecer fatos com dimensões**: usar broadcast joins para enriquecer grandes tabelas de transações com tabelas de referência pequenas (ex.: milhões de pedidos com alguns milhares de categorias) com mínimo de shuffle.\n\n## Problemas e erros comuns\n\n### Erros de OOM\n\n**Cenário:** skew nos dados faz um executor ficar sem memória.\n**Correção:** use Adaptive Query Execution (AQE) e revise a lógica do join.\n\n### Shuffle spill em joins grandes causando OOM\n\n**Cenário:** juntar duas tabelas grandes causa shuffle spill excessivo em disco ou `OutOfMemoryError` nos executores.\n**Correção:** faça broadcast da tabela menor com `broadcast()`, ou aumente `spark.sql.shuffle.partitions` para distribuir os dados em mais tasks e reduzir a pressão de memória por partição.\n\n### Colunas duplicadas após join com chaves de mesmo nome\n\n**Cenário:** depois de juntar dois DataFrames por colunas de mesmo nome (ex.: ambos têm `id`), o resultado tem duas colunas `id`, causando ambiguidade.\n**Correção:** faça o join por lista de nomes (`df1.join(df2, [\"id\"])`), que deduplica a chave, ou remova a coluna duplicada depois.\n\n## Dicas para a prova\n\n- Saiba os sete tipos de join e quando usar cada um: inner, left, right, full, cross, semi, anti\n- Semi join retorna só colunas da esquerda (sem colunas da direita); anti join retorna as linhas sem match\n- `HAVING` filtra depois da agregação; `WHERE` filtra antes do agrupamento\n- Broadcast é automático para tabelas abaixo de 10 MB; use `broadcast()` para forçar em tabelas de referência maiores\n- `union` = por posição e com duplicatas; `unionByName` = por nome\n\n## Pontos-chave\n\n- **Inner join**: só as linhas que casam nas duas tabelas\n- **Left join**: todas as linhas da esquerda, as que casam da direita\n- **Full join**: todas as linhas das duas tabelas, nulos onde não há match\n- **GROUP BY**: agrega pelos campos indicados\n- **HAVING**: filtra grupos depois da agregação (não WHERE)\n- **Window functions**: agregam sobre partições sem colapsar linhas\n- **Otimização**: broadcast para tabelas pequenas, bucketing para grandes\n- **Anti join**: retorna as linhas da esquerda sem correspondência\n\n## Tópicos relacionados\n\n- [Operações com DataFrame](02-dataframe-operations.md)\n- [Transformações avançadas](04-advanced-transformations.md)\n\n## Documentação oficial\n\n- [Join Hints](https://docs.databricks.com/en/sql/language-manual/sql-ref-syntax-qry-select-hints.html)\n- [Aggregate Functions](https://docs.databricks.com/en/sql/language-manual/sql-ref-functions-builtin.html)\n\n---\n\n**[← Anterior: Operações com DataFrame](02-dataframe-operations.md) | [↑ Voltar para Data Transformation and Modeling](README.md) | [Próximo: Transformações avançadas →](04-advanced-transformations.md)**\n"},{"id":"03-data-transformation-and-modeling/04-advanced-transformations","folder":"03-data-transformation-and-modeling","group":"modulo","order":4,"isIndex":false,"title":"Transformações Avançadas","md":"# Transformações Avançadas\n\n## Visão geral\n\nTécnicas avançadas de transformação permitem processamentos complexos que vão além das operações SQL padrão. User-defined functions (UDFs), window functions e operações com coleções dão flexibilidade para pipelines sofisticados.\n\n> [!abstract] Resumo\n>\n> - Funções de coleção: `explode`, `split`, `array_contains`, `transform`, `filter`, `flatten`\n> - Window functions (`ROW_NUMBER`, `RANK`, `LAG`) para ranking, deduplicação e totais acumulados\n> - Prefira funções nativas a UDFs Python. UDFs são opacas para o otimizador e adicionam custo de serialização\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: manipular colunas e linhas: split de strings, explode de arrays, renomear, filtrar\n> - Habilidade do exam guide: limpeza Bronze → Silver, incluindo tratamento de nulos e padronização de tipos\n> - Escolher uma higher-order function (`filter`, `transform`) em vez de `explode` + `groupBy`\n\n---\n\n## User-Defined Functions (UDFs)\n\n### UDFs Python\n\n```python\nfrom pyspark.sql.functions import udf, col\nfrom pyspark.sql.types import StringType\n\ndef categorize_salary(salary):\n    if salary < 50000:\n        return \"Entry\"\n    elif salary < 100000:\n        return \"Mid\"\n    else:\n        return \"Senior\"\n\ncategorize_udf = udf(categorize_salary, StringType())\n\ndf_categorized = employees.withColumn(\"level\", categorize_udf(col(\"salary\")))\n```\n\n### Pandas UDFs (vetorizadas)\n\nPandas UDFs são mais rápidas que UDFs Python comuns porque operam em **lotes** (via Apache Arrow):\n\n```python\nfrom pyspark.sql.functions import pandas_udf\nimport pandas as pd\n\n@pandas_udf(\"string\")\ndef categorize_salary_pandas(salary_series: pd.Series) -> pd.Series:\n    \"\"\"UDF vetorizada - processa o lote inteiro de uma vez\"\"\"\n    return pd.cut(\n        salary_series,\n        bins=[0, 50000, 100000, float('inf')],\n        labels=['Entry', 'Mid', 'Senior']\n    ).astype(str)\n\ndf_categorized = employees.withColumn(\"level\", categorize_salary_pandas(col(\"salary\")))\n```\n\n### Registrando UDF para uso em SQL\n\n```python\nspark.udf.register(\"categorize_salary_sql\", categorize_salary, StringType())\n\nresult = spark.sql(\"\"\"\n    SELECT id, name, salary, categorize_salary_sql(salary) as level\n    FROM employees\n\"\"\")\n```\n\n### SQL UDFs no Unity Catalog\n\n```sql\nCREATE FUNCTION main.default.salary_level(salary DOUBLE)\nRETURNS STRING\nRETURN CASE WHEN salary < 50000 THEN 'Entry'\n            WHEN salary < 100000 THEN 'Mid'\n            ELSE 'Senior' END;\n\nSELECT main.default.salary_level(salary) FROM employees;\n```\n\n## Window functions\n\n```mermaid\nflowchart LR\n    Data[\"Dados de entrada<br/>Linhas com valores\"]\n    Window[\"Especificação da janela<br/>PARTITION BY + ORDER BY\"]\n    Compute[\"Cálculo sobre<br/>o frame da janela\"]\n    Result[\"Resultado<br/>Novas colunas\"]\n\n    Data --> Window\n    Window --> Compute\n    Compute --> Result\n```\n\n### Sintaxe\n\n```sql\nSELECT\n    name,\n    department,\n    salary,\n    -- Ranking\n    ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) as row_num,\n    RANK()       OVER (PARTITION BY department ORDER BY salary DESC) as rank,\n    DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC) as dense_rank,\n\n    -- Agregações sobre a janela\n    AVG(salary) OVER (PARTITION BY department) as dept_avg,\n    SUM(salary) OVER (PARTITION BY department) as dept_total,\n\n    -- Lead/Lag\n    LAG(salary)  OVER (ORDER BY hire_date) as prev_salary,\n    LEAD(salary) OVER (ORDER BY hire_date) as next_salary\nFROM employees\n```\n\n### Em Python\n\n```python\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\n\nwindow_dept = Window.partitionBy(\"department\").orderBy(F.desc(\"salary\"))\n\ndf_windowed = (employees\n    .withColumn(\"row_num\", F.row_number().over(window_dept))\n    .withColumn(\"rank\", F.rank().over(window_dept))\n    .withColumn(\"dense_rank\", F.dense_rank().over(window_dept))\n    .withColumn(\"dept_avg\", F.avg(\"salary\").over(Window.partitionBy(\"department\"))))\n```\n\n### Deduplicação com ROW_NUMBER (padrão muito cobrado)\n\n```python\n# Manter apenas o registro MAIS RECENTE de cada customer_id\nw = Window.partitionBy(\"customer_id\").orderBy(F.col(\"updated_at\").desc())\n\nlatest = (df\n    .withColumn(\"rn\", F.row_number().over(w))\n    .filter(\"rn = 1\")\n    .drop(\"rn\"))\n```\n\n### Window functions comuns\n\n| Função | Propósito | Exemplo |\n|----------|---------|---------|\n| `ROW_NUMBER()` | Número único da linha na janela | `1, 2, 3, ...` |\n| `RANK()` | Ranking com lacunas em empates | `1, 1, 3, ...` |\n| `DENSE_RANK()` | Ranking sem lacunas | `1, 1, 2, ...` |\n| `LAG()` | Valor da linha anterior | Salário anterior |\n| `LEAD()` | Valor da próxima linha | Próximo salário |\n| `FIRST_VALUE()` | Primeiro valor da janela | Primeiro salário da partição |\n| `LAST_VALUE()` | Último valor da janela | Último salário da partição |\n| `NTH_VALUE()` | N-ésimo valor da janela | 3º maior salário |\n\n## Funções de coleção\n\n### Arrays\n\n```python\nfrom pyspark.sql.functions import array, array_contains, split, explode, explode_outer, size\n\n# Criar array\ndf_array = employees.select(col(\"name\"), array(col(\"first_name\"), col(\"last_name\")).alias(\"name_parts\"))\n\n# Operações com array\ndf_array = employees.select(\n    col(\"skills\"),\n    array_contains(col(\"skills\"), \"Python\").alias(\"knows_python\"),\n    size(col(\"skills\")).alias(\"num_skills\")\n)\n\n# split: string -> array\ndf = df.withColumn(\"tags\", split(col(\"tags_csv\"), \",\"))\n\n# explode: um elemento do array por linha (linhas com array NULL/vazio somem)\ndf_exploded = employees.selectExpr(\"name\", \"explode(skills) as skill\")\n\n# explode_outer: mantém linhas com array NULL/vazio (gera NULL)\ndf_kept = employees.select(\"name\", explode_outer(\"skills\").alias(\"skill\"))\n\n# Juntar array a partir de GROUP BY\ndf_collected = employees.groupBy(\"department\").agg(F.collect_list(\"name\").alias(\"employees\"))\n```\n\n### Higher-order functions (sem explode)\n\n```sql\nSELECT\n  order_id,\n  filter(items, x -> x.qty > 0)            AS valid_items,   -- filtra elementos\n  transform(items, x -> x.price * x.qty)   AS line_totals,   -- mapeia elementos\n  exists(items, x -> x.sku = 'A1')         AS has_a1,\n  aggregate(items, 0D, (acc, x) -> acc + x.price * x.qty) AS order_total,\n  flatten(array_of_arrays)                 AS flat\nFROM orders;\n```\n\nElas operam dentro do array, sem explodir e reagrupar — mais simples e mais eficiente.\n\n### Maps\n\n```python\nfrom pyspark.sql.functions import create_map, lit, map_keys, map_values\n\ndf_map = employees.select(\n    col(\"name\"),\n    create_map(lit(\"salary\"), col(\"salary\"), lit(\"department\"), col(\"department\")).alias(\"info\")\n)\n\ndf_accessed = df_map.withColumn(\"dept\", col(\"info\")[\"department\"])\n\n# Explodir map em linhas chave-valor\ndf_exploded = df_map.selectExpr(\"name\", \"explode(info) as (key, value)\")\n```\n\n### Structs\n\n```python\nfrom pyspark.sql.functions import struct\n\ndf_struct = employees.select(\n    col(\"name\"),\n    struct(\n        col(\"name\").alias(\"full_name\"),\n        col(\"salary\").alias(\"annual_salary\"),\n        col(\"department\").alias(\"dept\")\n    ).alias(\"employee_info\")\n)\n\n# Acessar campos do struct (notação de ponto)\ndf_accessed = df_struct.withColumn(\"emp_name\", col(\"employee_info.full_name\"))\n\n# Expandir todos os campos\ndf_flat = df_struct.select(\"name\", \"employee_info.*\")\n```\n\n## Operações com strings\n\n```python\nfrom pyspark.sql.functions import lower, upper, trim, substring, concat, concat_ws, length, regexp_replace\n\ndf_strings = employees.select(\n    lower(col(\"name\")).alias(\"name_lower\"),\n    upper(col(\"department\")).alias(\"dept_upper\"),\n    trim(col(\"email\")).alias(\"email_clean\"),\n    substring(col(\"name\"), 1, 3).alias(\"name_prefix\"),\n    concat(col(\"first_name\"), lit(\" \"), col(\"last_name\")).alias(\"full_name\"),\n    concat_ws(\" \", \"first_name\", \"last_name\").alias(\"full_name2\"),\n    regexp_replace(col(\"phone\"), \"[^0-9]\", \"\").alias(\"phone_digits\"),\n    length(col(\"name\")).alias(\"name_length\")\n)\n```\n\n## Datas e timestamps\n\n```python\nfrom pyspark.sql.functions import current_date, year, month, dayofmonth, datediff, date_add, from_unixtime, to_date, to_timestamp\n\ndf_dates = employees.select(\n    year(col(\"hire_date\")).alias(\"hire_year\"),\n    month(col(\"hire_date\")).alias(\"hire_month\"),\n    dayofmonth(col(\"hire_date\")).alias(\"hire_day\"),\n    datediff(current_date(), col(\"hire_date\")).alias(\"days_employed\"),\n    date_add(col(\"hire_date\"), 365).alias(\"one_year_anniversary\"),\n    from_unixtime(col(\"timestamp_ms\") / 1000).alias(\"readable_timestamp\"),\n    to_date(col(\"date_str\"), \"dd/MM/yyyy\").alias(\"parsed_date\")\n)\n```\n\n## Lógica condicional\n\n```python\nfrom pyspark.sql.functions import when, coalesce\n\ndf_conditional = employees.withColumn(\n    \"bonus_eligible\", when(col(\"salary\") > 100000, True).otherwise(False))\n\ndf_bonus = employees.withColumn(\"bonus_pct\",\n    when(col(\"salary\") >= 150000, 0.20)\n    .when(col(\"salary\") >= 100000, 0.15)\n    .when(col(\"salary\") >= 50000, 0.10)\n    .otherwise(0.05))\n\n# coalesce: primeiro valor não nulo\ndf_coalesce = employees.withColumn(\n    \"contact\", coalesce(col(\"email\"), col(\"phone\"), lit(\"Sem contato\")))\n```\n\n## Achatando estruturas aninhadas\n\n```python\ndf_unnested = (employees\n    .select(\"id\", \"name\", F.explode(\"addresses\").alias(\"address\"))\n    .select(\"id\", \"name\", \"address.street\", \"address.city\"))\n\ndf_flattened = employees.select(\n    \"id\", \"name\",\n    col(\"contact_info.email\").alias(\"email\"),\n    col(\"contact_info.phone\").alias(\"phone\"))\n```\n\n## Pivot\n\n```sql\nSELECT *\nFROM employees\nPIVOT (\n    SUM(salary)\n    FOR department IN ('Engineering' as eng, 'Sales' as sales, 'HR' as hr)\n)\n```\n\n```python\ndf_pivoted = (employees\n    .groupBy(\"year\")\n    .pivot(\"department\", [\"Engineering\", \"Sales\", \"HR\"])\n    .agg(F.sum(\"salary\")))\n```\n\n## Tratamento de nulos\n\n```python\nfrom pyspark.sql.functions import isnan, isnull\n\ndf_nulls = employees.select(\n    col(\"name\"),\n    isnull(col(\"email\")).alias(\"email_missing\"),\n    isnan(col(\"salary\")).alias(\"salary_invalid\"))\n\n# Remover linhas com nulo\ndf_clean = employees.dropna(subset=[\"email\"])\n\n# Preencher nulos\ndf_filled = employees.fillna({\"email\": \"unknown@company.com\", \"department\": \"Unassigned\"})\n\n# Forward fill (último valor não nulo)\nwindow_fill = Window.orderBy(col(\"hire_date\"))\ndf_forward_filled = employees.withColumn(\n    \"salary\",\n    F.last(col(\"salary\"), ignorenulls=True).over(\n        window_fill.rowsBetween(Window.unboundedPreceding, 0)))\n```\n\n## Considerações de performance\n\n### Broadcast vs shuffle\n\n```python\nfrom pyspark.sql.functions import broadcast\n\nresult = large_df.join(broadcast(small_reference), large_df.key == small_reference.key)  # sem shuffle do lado grande\nresult = df1.join(df2, df1.key == df2.key)  # grande com grande: shuffle\n```\n\n### Estratégia de cache\n\n```python\ndf_cleaned = df.filter(col(\"sales\") > 100)\ndf_cleaned.cache()\n\nresult1 = df_cleaned.select(\"name\", \"sales\")\nresult2 = df_cleaned.filter(col(\"sales\") > 500)\n\ndf_cleaned.unpersist()\n```\n\n## UDF vs funções nativas\n\n| Aspecto | Nativa | UDF |\n|--------|----------|-----|\n| **Performance** | Rápida (otimizada) | Mais lenta |\n| **Flexibilidade** | Limitada | Ilimitada |\n| **Otimização** | O Catalyst otimiza | Otimização limitada |\n| **Quando usar** | Sempre prefira | Último recurso |\n\n## Casos de uso\n\n- **Achatar payloads JSON aninhados**: usar `explode()`, `from_json()` e acesso a structs para transformar respostas de APIs ou logs de eventos em tabelas Delta planas e consultáveis.\n- **Lógica de negócio customizada via UDFs**: aplicar UDFs Python ou Pandas para transformações específicas (parsing de endereço, scores customizados) que não dá para expressar com funções nativas.\n\n## Problemas e erros comuns\n\n### UDF Python deixa um job Silver lento\n\n**Cenário:** uma UDF Python que converte para minúsculas e remove espaços deixa um job Silver várias vezes mais lento.\n**Correção:** use funções nativas (`lower`, `trim`, `regexp_replace`). O otimizador não enxerga dentro de UDFs Python, e cada linha é serializada para Python. Se a UDF for inevitável, use uma pandas UDF vetorizada.\n\n### Erros de serialização em UDF\n\n**Cenário:** uma UDF Python falha com `PicklingError` porque referencia um objeto não serializável (ex.: conexão de banco ou logger).\n**Correção:** use Pandas UDFs ou funções nativas. Se precisar de UDF customizada, garanta que os objetos referenciados sejam serializáveis ou instancie-os dentro da função.\n\n### Schema inconsistente ao explodir dados aninhados\n\n**Cenário:** `explode()` em uma coluna derivada de JSON falha com `AnalysisException` porque o schema inferido de `ArrayType` ou `MapType` varia entre linhas.\n**Correção:** use `from_json()` com schema explícito antes de explodir.\n\n## Dicas para a prova\n\n- Sempre prefira funções nativas do Spark a UDFs; UDFs escapam do Catalyst e são mais lentas\n- Pandas UDFs (vetorizadas) são bem mais rápidas que UDFs Python comuns porque processam lotes\n- Saiba a diferença entre `ROW_NUMBER()`, `RANK()` e `DENSE_RANK()` — principalmente em empates\n- `explode()` transforma uma coluna array em várias linhas; padrão comum na prova. `explode_outer()` mantém linhas com array nulo\n\n## Pontos-chave\n\n- **UDF**: funções definidas pelo usuário; Pandas UDFs são mais rápidas que UDFs Python\n- **Window functions**: calculam valores sobre partições sem colapsar linhas\n- **Coleções**: arrays, maps e structs para tipos complexos\n- **String/Data**: funções padrão para texto e tempo\n- **Condicionais**: when/otherwise para lógica de negócio\n- **Nulos**: fillna/dropna/coalesce para qualidade de dados\n- **Otimização**: broadcast para tabelas pequenas, evite UDFs quando possível\n- **Pivot**: transforma linhas em colunas\n\n## Tópicos relacionados\n\n- [Joins e Agregações](03-joins-aggregations.md)\n- [Limpeza e Qualidade de Dados](05-data-cleaning-and-quality.md)\n\n## Documentação oficial\n\n- [PySpark Built-in Functions](https://docs.databricks.com/en/pyspark/index.html)\n- [Window Functions](https://docs.databricks.com/en/sql/language-manual/sql-ref-functions-builtin.html#window-functions)\n\n---\n\n**[← Anterior: Joins e Agregações](03-joins-aggregations.md) | [↑ Voltar para Data Transformation and Modeling](README.md) | [Próximo: Limpeza e Qualidade de Dados →](05-data-cleaning-and-quality.md)**\n"},{"id":"03-data-transformation-and-modeling/05-data-cleaning-and-quality","folder":"03-data-transformation-and-modeling","group":"modulo","order":5,"isIndex":false,"title":"Limpeza e Qualidade de Dados","md":"# Limpeza e Qualidade de Dados\n\n## Visão geral\n\nTabelas Silver existem para guardar dados **limpos e confiáveis**. Este arquivo cobre os passos de limpeza Bronze → Silver que o exam guide cita: ler a Bronze com PySpark ou SQL, tratar nulos, padronizar tipos, deduplicar e gravar uma nova tabela Silver. Também cobre as **verificações de qualidade e regras de validação** que mantêm Silver e Gold confiáveis: constraints `CHECK` e `NOT NULL` do Delta, **expectations** de pipeline e padrões de quarentena.\n\n> [!abstract] Resumo\n>\n> - **Kit de limpeza**: `cast` / `try_cast` para tipos, `coalesce` / `fillna` / `dropna` para nulos, `trim` / `lower` / `to_date` para padronizar, `dropDuplicates` ou `ROW_NUMBER()` para deduplicar\n> - **Profiling**: `describe()` (count, mean, stddev, min, max) e `summary()` (o mesmo + quartis aproximados de 25/50/75 %), `count_if`, `approx_count_distinct`\n> - **Constraints Delta** (`NOT NULL`, `CHECK`) são aplicadas em toda escrita. Uma violação faz a transação falhar\n> - **Expectations** em Lakeflow pipelines: warn (padrão), `ON VIOLATION DROP ROW` ou `ON VIOLATION FAIL UPDATE`, com métricas na UI do pipeline e no event log\n\n> [!tip] O que a prova cobra\n>\n> - Habilidades do exam guide: limpeza Bronze → Silver (nulos, tipos) com PySpark/SQL, deduplicação e agregados (count, contagem distinta aproximada, média, summary) e regras de qualidade/validação para Silver e Gold\n> - Escolher entre constraint (rejeita a escrita inteira) e expectation (warn, drop ou fail por registro)\n> - O que acontece com registros inválidos em cada ação de expectation\n> - Deduplicar \"o registro mais recente por chave\" corretamente\n\n---\n\n## Bronze → Silver: uma receita de limpeza\n\n```python\nfrom pyspark.sql import functions as F\nfrom pyspark.sql.window import Window\n\nbronze = spark.table(\"main.bronze.customers_raw\")\n\nsilver = (bronze\n    # 1. Padronizar strings\n    .withColumn(\"email\", F.lower(F.trim(\"email\")))\n    .withColumn(\"country\", F.upper(F.trim(\"country\")))\n    # 2. Padronizar tipos (try_cast retorna NULL em vez de falhar em valores ruins)\n    .withColumn(\"signup_date\", F.to_date(\"signup_date\", \"yyyy-MM-dd\"))\n    .withColumn(\"lifetime_value\", F.expr(\"try_cast(lifetime_value AS DECIMAL(12,2))\"))\n    # 3. Tratar nulos: valor padrão onde a regra de negócio permite, remover onde falta a chave\n    .fillna({\"country\": \"UNKNOWN\", \"lifetime_value\": 0})\n    .dropna(subset=[\"customer_id\"])\n    # 4. Renomear para o padrão de nomes da Silver\n    .withColumnRenamed(\"cust_nm\", \"customer_name\"))\n\n# 5. Deduplicar: manter o registro mais recente por customer_id\nw = Window.partitionBy(\"customer_id\").orderBy(F.col(\"_ingested_at\").desc())\nsilver_dedup = (silver\n    .withColumn(\"rn\", F.row_number().over(w))\n    .filter(\"rn = 1\")\n    .drop(\"rn\"))\n\n# 6. Gravar uma nova tabela Silver no Unity Catalog\nsilver_dedup.write.mode(\"overwrite\").saveAsTable(\"main.silver.customers\")\n```\n\nOs mesmos passos em SQL:\n\n```sql\nCREATE OR REPLACE TABLE main.silver.customers AS\nSELECT customer_id,\n       lower(trim(email))                          AS email,\n       coalesce(upper(trim(country)), 'UNKNOWN')   AS country,\n       to_date(signup_date, 'yyyy-MM-dd')          AS signup_date,\n       coalesce(try_cast(lifetime_value AS DECIMAL(12,2)), 0) AS lifetime_value\nFROM main.bronze.customers_raw\nWHERE customer_id IS NOT NULL\nQUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY _ingested_at DESC) = 1;\n```\n\n### Referência de tratamento de nulos\n\n| Necessidade | PySpark | SQL |\n| :--- | :--- | :--- |\n| Remover linhas com qualquer nulo | `df.dropna()` (`how=\"any\"` padrão) | `WHERE col1 IS NOT NULL AND ...` |\n| Remover só se todas as colunas forem nulas | `df.dropna(how=\"all\")` | — |\n| Remover se a coluna-chave for nula | `df.dropna(subset=[\"id\"])` | `WHERE id IS NOT NULL` |\n| Substituir nulos por padrão | `df.fillna({\"col\": value})` | `coalesce(col, value)` / `nvl(col, value)` |\n| Contar nulos | `F.count_if(F.col(\"c\").isNull())` (ou `F.sum(F.col(\"c\").isNull().cast(\"int\"))`) | `count_if(c IS NULL)` |\n\n`dropna` e `na.drop` são aliases. `dropna(how=\"any\")` remove a linha se tiver qualquer nulo, e `how=\"all\"` só se todos os valores forem nulos.\n\n### Opções de deduplicação\n\n| Método | Mantém | Use quando |\n| :--- | :--- | :--- |\n| `df.distinct()` | Uma cópia de cada linha totalmente idêntica | Duplicatas exatas |\n| `df.dropDuplicates([\"id\"])` | Uma linha **arbitrária** por `id` | Qualquer cópia serve |\n| `ROW_NUMBER() OVER (PARTITION BY id ORDER BY ts DESC) = 1` | A linha **mais recente** por `id` | \"O registro mais recente vence\" |\n| `MERGE INTO ... WHEN MATCHED THEN UPDATE ... WHEN NOT MATCHED THEN INSERT` | Uma linha por chave no destino | Cargas incrementais que não podem inserir duplicatas |\n\n## Profiling antes e depois da limpeza\n\n```python\ndf = spark.table(\"main.silver.customers\")\n\ndf.describe(\"lifetime_value\").show()     # count, mean, stddev, min, max\ndf.summary().show()                      # + quartis aproximados 25%, 50%, 75%\ndf.summary(\"count\", \"min\", \"10%\", \"90%\", \"max\").show()   # estatísticas escolhidas\n\ndf.agg(\n    F.count(\"*\").alias(\"rows\"),\n    F.countDistinct(\"customer_id\").alias(\"exact_customers\"),\n    F.approx_count_distinct(\"customer_id\").alias(\"approx_customers\"),   # HLL++, erro padrão ~5 %\n    F.mean(\"lifetime_value\").alias(\"avg_ltv\"),\n).show()\n```\n\n- `summary()` sem argumentos calcula count, mean, stddev, min, quartis aproximados (25 %, 50 %, 75 %) e max. `describe()` calcula só as estatísticas básicas\n- `approx_count_distinct(expr [, relativeSD])` estima valores distintos com HyperLogLog++. O desvio padrão relativo máximo padrão é 5 % ([approx_count_distinct](https://docs.databricks.com/aws/en/sql/language-manual/functions/approx_count_distinct)). Use quando um `COUNT(DISTINCT ...)` exato for caro demais em tabelas muito grandes\n\n## Regra de validação 1: constraints de tabela Delta\n\nConstraints são aplicadas pela própria tabela, em qualquer caminho de escrita: SQL, DataFrame, streaming ou `MERGE`.\n\n```sql\nALTER TABLE main.silver.customers ALTER COLUMN customer_id SET NOT NULL;\nALTER TABLE main.silver.customers ADD CONSTRAINT valid_ltv CHECK (lifetime_value >= 0);\nALTER TABLE main.silver.customers ADD CONSTRAINT valid_country CHECK (length(country) = 2 OR country = 'UNKNOWN');\n```\n\n| Constraint | Aplicada? | Em caso de violação |\n| :--- | :--- | :--- |\n| `NOT NULL` | Sim | \"A transação falha com erro\" |\n| `CHECK (expr)` | Sim | A transação falha — a escrita inteira é rejeitada |\n| `PRIMARY KEY`, `FOREIGN KEY`, `UNIQUE` | **Não, apenas informativas** | Nada é bloqueado. Documentam relacionamentos e podem ajudar na otimização |\n\nFonte: [Constraints on Databricks](https://docs.databricks.com/aws/en/tables/constraints).\n\n## Regra de validação 2: expectations de pipeline\n\nExpectations são cláusulas opcionais em **streaming tables, materialized views e temporary views** de um Lakeflow pipeline. Cada uma aplica uma verificação booleana SQL a cada registro ([pipeline expectations](https://docs.databricks.com/aws/en/ldp/expectations)).\n\n```sql\nCREATE OR REFRESH STREAMING TABLE main.silver.orders (\n  CONSTRAINT valid_id     EXPECT (order_id IS NOT NULL) ON VIOLATION DROP ROW,\n  CONSTRAINT valid_amount EXPECT (amount > 0)           ON VIOLATION FAIL UPDATE,\n  CONSTRAINT recent       EXPECT (order_ts > '2020-01-01')            -- só avisa (warn)\n)\nAS SELECT * FROM STREAM(main.bronze.orders);\n```\n\n```python\nfrom pyspark import pipelines as dp\n\n@dp.table(name=\"silver_orders\")\n@dp.expect_or_drop(\"valid_id\", \"order_id IS NOT NULL\")\n@dp.expect_or_fail(\"valid_amount\", \"amount > 0\")\n@dp.expect(\"recent\", \"order_ts > '2020-01-01'\")\ndef silver_orders():\n    return spark.readStream.table(\"main.bronze.orders\")\n```\n\n| Ação | SQL | Python | Registros inválidos | Pipeline |\n| :--- | :--- | :--- | :--- | :--- |\n| **Warn** *(padrão)* | `EXPECT (...)` | `@dp.expect` | **Gravados** no destino; violações contadas | Continua |\n| **Drop** | `... ON VIOLATION DROP ROW` | `@dp.expect_or_drop` | **Removidos** antes da escrita; contagem registrada | Continua |\n| **Fail** | `... ON VIOLATION FAIL UPDATE` | `@dp.expect_or_fail` | O update **falha e é revertido** | Para (precisa de intervenção) |\n\n- Variantes agrupadas (`expect_all`, `expect_all_or_drop`, `expect_all_or_fail`) recebem um dicionário nome → constraint. Existem **apenas em Python**\n- **Onde ver os resultados**: na aba **Data quality** de cada dataset na UI do pipeline (warn e drop; fail não registra métricas), ou no **event log**, única opção para pipelines SQL standalone\n- Desde junho de 2026 também é possível adicionar expectations a **materialized views criadas no Databricks SQL**\n\n> [!note] Atualização da plataforma (out/2026)\n> O **Lakeflow Declarative Pipelines** da prova se chama **Lakeflow Spark Declarative Pipelines** (forma curta \"Lakeflow pipelines\") na documentação atual. Os decorators legados `@dlt.expect*` ainda funcionam, mas o módulo `pyspark.pipelines` (`dp`) é o recomendado.\n\n## Padrão de quarentena\n\nÀs vezes registros ruins não podem ser descartados silenciosamente nem bloquear o pipeline. Direcione-os para uma tabela separada para revisão:\n\n```sql\n-- Linhas válidas seguem para a Silver\nCREATE OR REFRESH STREAMING TABLE main.silver.orders_valid AS\nSELECT * FROM STREAM(main.bronze.orders) WHERE order_id IS NOT NULL AND amount > 0;\n\n-- Linhas inválidas ficam guardadas para investigação, em vez de perdidas\nCREATE OR REFRESH STREAMING TABLE main.silver.orders_quarantine AS\nSELECT *, current_timestamp() AS quarantined_at\nFROM STREAM(main.bronze.orders) WHERE NOT (order_id IS NOT NULL AND amount > 0);\n```\n\n## Validando Silver e Gold com consultas\n\nConstraints e expectations verificam linhas individuais. Algumas regras abrangem o dataset inteiro e são melhor expressas como consultas de validação rodando como task depois da carga. A task falha o job se uma regra for quebrada:\n\n```python\n# Roda como task após o refresh da Gold; lançar exceção falha a task (e alerta o plantão)\nsilver_total = spark.sql(\"SELECT SUM(amount) AS t FROM main.silver.orders WHERE order_date = current_date() - 1\").first().t\ngold_total   = spark.sql(\"SELECT SUM(revenue) AS t FROM main.gold.daily_revenue WHERE order_date = current_date() - 1\").first().t\n\nif silver_total is None or gold_total is None or abs(silver_total - gold_total) > 0.01:\n    raise ValueError(f\"Reconciliação falhou: silver={silver_total} gold={gold_total}\")\n\ndupes = spark.sql(\"\"\"\n    SELECT COUNT(*) AS n FROM (\n      SELECT customer_id FROM main.silver.customers GROUP BY customer_id HAVING COUNT(*) > 1)\n\"\"\").first().n\nif dupes:\n    raise ValueError(f\"{dupes} customer_id duplicados na Silver\")\n```\n\nRegras típicas no nível do dataset:\n\n| Regra | Exemplo de verificação |\n| :--- | :--- |\n| **Reconciliação** | Totais da Gold iguais aos da Silver para o mesmo período |\n| **Unicidade** | Nenhuma chave de negócio aparece duas vezes na Silver |\n| **Completude** | A partição de ontem existe e a contagem de linhas está numa faixa esperada |\n| **Atualidade (freshness)** | `max(event_ts)` não é mais antigo que o SLA |\n| **Integridade referencial** | Todo `customer_id` dos fatos existe na dimensão de clientes. PK/FK são informativas, então verifique com consulta |\n\nSchema enforcement (o Delta rejeitando escritas com colunas ou tipos incompatíveis) é uma proteção separada e sempre ativa. Ela protege a **forma** dos dados; as verificações acima protegem o **conteúdo**.\n\n## Constraints vs expectations: como escolher\n\n| Requisito | Use |\n| :--- | :--- |\n| Nenhum caminho de escrita pode inserir linha ruim, e o lote deve falhar | Constraint Delta `CHECK` / `NOT NULL` |\n| Continuar carregando linhas boas e descartar as ruins | Expectation com `DROP ROW` |\n| Acompanhar a qualidade ao longo do tempo sem bloquear | Expectation (warn) |\n| Parar o pipeline em qualquer violação para alguém intervir | Expectation com `FAIL UPDATE` |\n| Guardar linhas ruins para revisão | Tabela de quarentena |\n\n## Casos de uso\n\n- **Cadastro de clientes na Silver**: trim e lowercase em emails, cast de datas, manter o registro mais recente por `customer_id` e aplicar `NOT NULL` na chave\n- **Stream de pagamentos**: `FAIL UPDATE` em valor negativo para o pipeline antes que valores errados cheguem à Gold\n- **Telemetria IoT**: `DROP ROW` descarta leituras fora da faixa física, e as contagens descartadas são revisadas na aba Data quality\n- **Guarda de KPI na Gold**: uma constraint `CHECK` numa tabela Gold rejeita qualquer refresh que publicaria receita total negativa\n\n## Problemas e erros comuns\n\n### `dropDuplicates` mantém um registro antigo\n\n**Cenário:** depois de `dropDuplicates([\"customer_id\"])`, alguns clientes aparecem com endereço desatualizado.\n**Correção:** `dropDuplicates` mantém uma linha arbitrária. Use `ROW_NUMBER()` ordenado por timestamp de atualização ou ingestão (ou `QUALIFY` em SQL) para manter a mais recente.\n\n### Escrita falha por violação de CHECK\n\n**Cenário:** um append noturno na Silver falha porque algumas linhas quebram `CHECK (amount > 0)`.\n**Correção:** constraints falham a transação inteira. Limpe ou filtre as linhas antes de gravar, ou mova a regra para uma expectation com `DROP ROW` se descartar for aceitável.\n\n### Registros ruins chegam silenciosamente à Gold\n\n**Cenário:** uma expectation foi adicionada sem cláusula `ON VIOLATION`, e linhas inválidas continuam aparecendo downstream.\n**Correção:** a ação padrão é warn: as linhas são gravadas e apenas contadas. Adicione `ON VIOLATION DROP ROW` ou `FAIL UPDATE`.\n\n### Erros de `CAST` param a carga\n\n**Cenário:** `CAST(amount AS DECIMAL(12,2))` falha em valores como `'N/A'` com o modo ANSI ligado.\n**Correção:** use `try_cast`, que retorna NULL para valores que não consegue converter, e depois trate os NULLs explicitamente.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - Expectations são **warn** por padrão: linhas mantidas e violações contadas. `DROP ROW` remove. `FAIL UPDATE` para e reverte\n> - Decorators agrupados `expect_all*` são **só Python**\n> - `CHECK` / `NOT NULL` do Delta são aplicadas. PK/FK/UNIQUE são **apenas informativas**\n> - \"Registro mais recente por chave\" → `ROW_NUMBER()` + filtro (ou `QUALIFY`), não `dropDuplicates`\n> - `summary()` adiciona quartis ao que o `describe()` retorna. `approx_count_distinct` troca ~5 % de erro por velocidade\n\n## Pontos-chave\n\n- Limpeza = padronizar strings, corrigir tipos (`try_cast`), tratar nulos, deduplicar e gravar a Silver\n- Constraints protegem a tabela em todo caminho de escrita. Expectations dão controle por registro dentro de pipelines\n- Métricas de expectations ficam na aba Data quality do pipeline e no event log\n- Tabelas de quarentena mantêm registros ruins visíveis em vez de descartá-los\n\n## Tópicos relacionados\n\n- [Operações com DataFrame](02-dataframe-operations.md)\n- [Transformações avançadas (nulos, arrays)](04-advanced-transformations.md)\n- [Objetos da camada Gold](06-gold-layer-objects.md)\n- [Fundamentos do Delta Lake (schema enforcement)](../01-databricks-intelligence-platform/04-delta-lake-fundamentals.md)\n\n## Documentação oficial\n\n- [Manage data quality with pipeline expectations](https://docs.databricks.com/aws/en/ldp/expectations)\n- [Constraints on Databricks](https://docs.databricks.com/aws/en/tables/constraints)\n- [approx_count_distinct function](https://docs.databricks.com/aws/en/sql/language-manual/functions/approx_count_distinct)\n- [PySpark DataFrame.summary](https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.summary.html)\n\n---\n\n**[← Anterior: Transformações avançadas](04-advanced-transformations.md) | [↑ Voltar para Data Transformation and Modeling](README.md) | [Próximo: Objetos da camada Gold →](06-gold-layer-objects.md)**\n"},{"id":"03-data-transformation-and-modeling/06-gold-layer-objects","folder":"03-data-transformation-and-modeling","group":"modulo","order":6,"isIndex":false,"title":"Objetos da Camada Gold","md":"# Objetos da Camada Gold\n\n## Visão geral\n\nA Gold é de onde os times de BI e analytics leem, então o tipo de objeto escolhido define atualidade, custo e velocidade das consultas. O exam guide pede que você entenda a diferença entre **materialized views, views, streaming tables e tables** no Unity Catalog, e como construir cada um. Este arquivo compara os quatro e mostra o SQL de cada um, tanto standalone no Databricks SQL quanto dentro de um Lakeflow pipeline.\n\n> [!abstract] Resumo\n>\n> - **Table** (Delta gerenciada): você controla cada escrita (`CREATE TABLE AS`, `INSERT`, `MERGE`). Os resultados ficam armazenados\n> - **View**: uma consulta salva que é **recalculada a cada leitura** e não armazena dados\n> - **Materialized view**: armazena **resultados pré-calculados** e os atualiza, incrementalmente quando possível. Boa para agregados que dashboards consultam repetidamente\n> - **Streaming table**: uma tabela UC com **processamento incremental, estilo append**. Cada refresh processa só as linhas novas da fonte. Boa para ingestão e CDC\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: a diferença entre, e como construir, objetos da camada Gold (materialized views, views, streaming tables, tables) para times de BI e analytics no Unity Catalog\n> - Escolher o objeto certo para um requisito de atualidade, custo ou performance\n> - Comportamento de refresh: na leitura (view), no refresh ou agenda (MV), append incremental (streaming table)\n> - Quais privilégios os consumidores precisam (`SELECT`, mais `REFRESH` para materialized views)\n\n---\n\n## Comparação lado a lado\n\n| | **Table** | **View** | **Materialized view** | **Streaming table** |\n| :--- | :--- | :--- | :--- | :--- |\n| Armazena dados? | Sim | Não | Sim (resultado pré-calculado) | Sim |\n| Quando é calculado? | Quando seu código grava | **Em toda consulta** | Na criação, `REFRESH`, agenda ou `TRIGGER ON UPDATE` | A cada refresh, **só linhas novas** |\n| Mudanças na fonte (updates/deletes) | Você trata no código | Sempre refletidas | Refletidas no próximo refresh (incremental ou completo) | Orientado a append. Linhas antigas não são recalculadas |\n| Uso típico na Gold | Tabelas de dimensão ou fato curadas, gravadas por jobs | Camada semântica leve, subconjunto de colunas, segurança | KPIs pré-agregados para dashboards | Tabelas de eventos ou fatos mantidas incrementalmente |\n| Quem roda o compute | Seu job ou warehouse | O warehouse que consulta, toda vez | Um pipeline serverless | Um pipeline serverless |\n\nFontes: [materialized views](https://docs.databricks.com/aws/en/views/materialized), [streaming tables](https://docs.databricks.com/aws/en/tables/streaming).\n\n```mermaid\nflowchart LR\n    S[(Tabelas Silver)] --> V[View<br/>recalculada na leitura]\n    S --> MV[Materialized view<br/>pré-calculada, atualizada]\n    S --> T[Table<br/>gravada por um job]\n    B[(Bronze / stream)] --> ST[Streaming table<br/>append incremental]\n    V --> BI[Dashboards de BI]\n    MV --> BI\n    T --> BI\n    ST --> MV\n```\n\n## Construindo cada objeto no Unity Catalog\n\n### Table (CTAS ou MERGE a partir de um job)\n\n```sql\nCREATE OR REPLACE TABLE main.gold.daily_revenue AS\nSELECT order_date, region, SUM(amount) AS revenue, COUNT(*) AS orders\nFROM main.silver.orders\nGROUP BY order_date, region;\n```\n\nVocê é dono da lógica de atualização. Um Lakeflow Job agendado reexecuta o CTAS, ou faz `MERGE` só das datas alteradas.\n\n### View\n\n```sql\nCREATE OR REPLACE VIEW main.gold.v_active_customers AS\nSELECT customer_id, customer_name, country\nFROM main.silver.customers\nWHERE is_active = true;\n```\n\n- Sem custo de armazenamento. Sempre atual, mas toda consulta paga o cálculo completo\n- `CREATE TEMPORARY VIEW` tem escopo de sessão e não é registrada no Unity Catalog. Não use para objetos Gold compartilhados\n\n### Materialized view (standalone, Databricks SQL)\n\n```sql\n-- Ad hoc: atualização manual\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.mv_revenue_by_region AS\nSELECT region, SUM(amount) AS revenue\nFROM main.silver.orders\nGROUP BY region;\n\nREFRESH MATERIALIZED VIEW main.gold.mv_revenue_by_region;   -- síncrono por padrão\n\n-- Agendada (cron estilo Quartz de seis campos)\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.mv_revenue_nightly\nSCHEDULE CRON '0 30 3 * * ?' AT TIME ZONE 'UTC'\nAS SELECT region, SUM(amount) AS revenue FROM main.silver.orders GROUP BY region;\n\n-- Atualiza automaticamente quando os dados upstream mudam\nCREATE OR REPLACE MATERIALIZED VIEW main.gold.mv_revenue_fresh\nTRIGGER ON UPDATE\nAS SELECT region, SUM(amount) AS revenue FROM main.silver.orders GROUP BY region;\n```\n\nFatos-chave ([Use standalone materialized views](https://docs.databricks.com/aws/en/views/materialized)):\n\n- A criação é **síncrona**: o comando retorna após a carga inicial. `REFRESH ... ASYNC` retorna imediatamente\n- Os refreshes rodam em um **pipeline serverless**. O SQL warehouse só coordena, e o custo é cobrado como DBUs de pipeline serverless\n- **Refresh incremental** mescla só dados novos ou alterados quando possível, o que exige fontes Delta com **row tracking** habilitado. Caso contrário, roda um recálculo completo. `EXPLAIN CREATE MATERIALIZED VIEW` mostra se a consulta pode ser atualizada incrementalmente\n- Agregados e expressões no `SELECT` precisam de **aliases**\n- MVs standalone rodam só em modo **triggered**, e **não suportam time travel**\n- O dono, e usuários com o privilégio **`REFRESH`**, podem atualizar. Leitores precisam de `SELECT`\n\n### Streaming table (standalone, Databricks SQL)\n\n```sql\nCREATE OR REFRESH STREAMING TABLE main.gold.order_events\nSCHEDULE EVERY 1 HOUR\nAS SELECT order_id, status, event_ts\nFROM STREAM main.silver.order_status_changes;\n```\n\n- \"Um refresh de streaming table avalia apenas as linhas novas que chegaram após a última atualização, e adiciona só os dados novos\" ([Use standalone streaming tables](https://docs.databricks.com/aws/en/tables/streaming))\n- Mudar a definição não recalcula linhas existentes. `REFRESH STREAMING TABLE ... FULL` reprocessa tudo, o que é arriscado quando a fonte tem retenção curta, como o Kafka\n- Conceder `SELECT` em uma streaming table **não** exige conceder `SELECT` nas fontes\n\n### Dentro de um Lakeflow pipeline\n\n```sql\n-- Um pipeline pode definir toda a cadeia medallion\nCREATE OR REFRESH STREAMING TABLE bronze_orders\nAS SELECT * FROM STREAM read_files('/Volumes/main/raw/landing/orders', format => 'json');\n\nCREATE OR REFRESH STREAMING TABLE silver_orders (\n  CONSTRAINT valid_amount EXPECT (amount > 0) ON VIOLATION DROP ROW\n) AS SELECT * FROM STREAM(bronze_orders);\n\nCREATE OR REFRESH MATERIALIZED VIEW gold_revenue_by_region\nAS SELECT region, SUM(amount) AS revenue FROM silver_orders GROUP BY region;\n```\n\n```python\nfrom pyspark import pipelines as dp\nfrom pyspark.sql import functions as F\n\n@dp.materialized_view(name=\"gold_revenue_by_region\")\ndef gold_revenue_by_region():\n    return (spark.read.table(\"silver_orders\")\n        .groupBy(\"region\")\n        .agg(F.sum(\"amount\").alias(\"revenue\")))\n```\n\n`@dp.materialized_view` substitui o legado `@dlt.table` sobre um DataFrame batch. `@dp.table` sobre um DataFrame streaming define uma streaming table, e `@dp.temporary_view` substitui `@dlt.view` ([Python reference](https://docs.databricks.com/aws/en/ldp/developer/python-ref)).\n\n> [!note] Sintaxe legada\n> Materiais antigos usam `CREATE LIVE TABLE` (hoje uma materialized view) e `CREATE STREAMING LIVE TABLE` (hoje uma streaming table). Se um enunciado mostrar a palavra-chave `LIVE`, mapeie para o tipo de objeto atual.\n\n## Exemplo resolvido: um KPI, quatro implementações\n\nUm time de BI precisa da **receita diária por região**, atualizada de hora em hora, para um dashboard que ~200 pessoas abrem toda manhã.\n\n| Implementação | Atualidade | Padrão de compute | Veredito |\n| :--- | :--- | :--- | :--- |\n| `CREATE VIEW ... GROUP BY` | Sempre atual | Agregação completa em **cada** carregamento de tile, ~200× por manhã | Simples, mas caro com esse volume de leitura |\n| `CREATE MATERIALIZED VIEW ... SCHEDULE EVERY 1 HOUR` | Até 1 hora de atraso | Um refresh por hora, incremental quando possível | **Melhor opção**: muita leitura e atualização horária é aceitável |\n| Streaming table sobre eventos de pedido da Silver | Minutos | Adiciona linhas novas, mas um agregado que precisa ser *recalculado* não combina com processamento só-append | Use para o feed de eventos, não para o agregado |\n| Tabela reconstruída por um Lakeflow Job a cada hora (`CREATE OR REPLACE TABLE AS`) | Até 1 hora de atraso | Reconstrução completa a cada hora, a menos que você escreva lógica de `MERGE` | Funciona, mas você é dono do código e da agenda |\n\nA materialized view vence porque combina resultados armazenados (leituras baratas) com refresh gerenciado (sem código de job), e pode atualizar incrementalmente quando a fonte suporta.\n\n## Publicando a Gold para consumidores de BI e analytics\n\nObjetos Gold são securables comuns do Unity Catalog, então o acesso é concedido da mesma forma para os quatro tipos:\n\n```sql\n-- Analistas podem navegar e ler tudo no schema Gold (objetos atuais e futuros)\nGRANT USE CATALOG ON CATALOG main TO `bi_analysts`;\nGRANT USE SCHEMA, SELECT ON SCHEMA main.gold TO `bi_analysts`;\n\n-- Um service principal de relatórios também pode disparar refreshes de uma MV\nGRANT REFRESH ON main.gold.mv_revenue_by_region TO `reporting-sp`;\n```\n\n- Grants em um schema são **herdados** pelos objetos atuais e futuros dele, então novas tabelas e views Gold ficam legíveis sem grants extras\n- Dashboards e ferramentas de BI geralmente consultam a Gold via **SQL warehouse**. Serverless SQL warehouse é o tipo recomendado para BI e SQL exploratório (veja [Compute e Clusters](../01-databricks-intelligence-platform/03-compute-clusters.md))\n- Row filters e column masks também se aplicam a tabelas Gold. Veja o [Domínio 7](../07-governance-and-security/04-row-filters-column-masks-abac.md)\n\n## Escolhendo um objeto Gold\n\n| Cenário | Melhor objeto |\n| :--- | :--- |\n| Um dashboard consulta a mesma agregação pesada centenas de vezes por dia | **Materialized view** (paga uma vez por refresh) |\n| Um time precisa de uma projeção filtrada e com colunas limitadas da Silver, sempre atual | **View** |\n| Um feed de eventos só-append precisa estar na Gold em minutos, processando só linhas novas | **Streaming table** |\n| Uma tabela fato precisa de lógica de upsert customizada (SCD, correções tardias) mantida pelo time de dados | **Table** mantida por job com `MERGE` |\n| Exploração ad hoc em uma sessão de notebook | Temporary view (não é objeto Gold) |\n\n## Casos de uso\n\n- **Dashboard executivo de KPIs**: uma materialized view com `TRIGGER ON UPDATE` mantém a receita por região atual sem compute por consulta\n- **Camada semântica self-service**: views expõem nomes amigáveis sobre a Silver, para que analistas não toquem nas tabelas brutas\n- **Status de pedidos quase em tempo real**: uma streaming table adiciona mudanças de status a cada poucos minutos para um dashboard de operações\n- **Tabela fato do financeiro**: um job agendado faz `MERGE` de correções tardias em uma tabela Gold com controle total\n\n## Problemas e erros comuns\n\n### Dashboard lento sobre uma view\n\n**Cenário:** uma view Gold com vários joins e agregações faz cada tile do dashboard levar 30 segundos.\n**Correção:** views recalculam a cada consulta. Converta a agregação pesada em materialized view e mantenha views para projeções leves.\n\n### Materialized view sempre recalcula tudo\n\n**Cenário:** o refresh noturno de uma MV leva tanto tempo quanto a criação inicial.\n**Correção:** o refresh incremental exige fontes Delta com row tracking (`delta.enableRowTracking = true`) e um formato de consulta compatível. Verifique com `EXPLAIN CREATE MATERIALIZED VIEW`.\n\n### Streaming table ignora uma linha atualizada na fonte\n\n**Cenário:** um pedido corrigido na Silver nunca altera a streaming table da Gold.\n**Correção:** streaming tables processam só linhas novas. Linhas já processadas não são reavaliadas. Use materialized view, ou tabela mantida com `MERGE`, quando a fonte atualiza linhas existentes.\n\n### Analistas não conseguem atualizar uma materialized view\n\n**Cenário:** um analista com `SELECT` recebe erro de permissão ao rodar `REFRESH MATERIALIZED VIEW`.\n**Correção:** atualizar exige ser o dono ou ter o privilégio `REFRESH` na materialized view.\n\n### Temporary view usada como objeto Gold compartilhado\n\n**Cenário:** um notebook cria `CREATE TEMPORARY VIEW gold_kpis`, mas o time do dashboard não a encontra no Catalog Explorer.\n**Correção:** temporary views só existem na sessão que as criou. Crie uma `VIEW` permanente (ou uma MV) em um schema do Unity Catalog e conceda `SELECT` aos consumidores.\n\n### Refresh da Gold falha depois que o dono sai\n\n**Cenário:** uma materialized view agendada para de atualizar depois que o acesso do dono à fonte Silver é removido.\n**Correção:** refreshes rodam com as permissões do dono, e perder `SELECT` na fonte os interrompe. Transfira a propriedade para um service principal ou grupo que mantenha acesso à fonte.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - **View** = sem armazenamento, recalculada por consulta. **MV** = armazenada, atualizada. **Streaming table** = append incremental. **Table** = você grava\n> - MVs e streaming tables são criadas e atualizadas por **pipelines serverless**, mesmo quando disparadas de um SQL warehouse\n> - Streaming tables processam **só linhas novas**; updates na fonte pedem MV ou `MERGE`\n> - `CREATE LIVE TABLE` → MV, `CREATE STREAMING LIVE TABLE` → streaming table (palavras-chave legadas)\n> - Leitores precisam de `SELECT`. Atualizar uma MV exige `REFRESH` (ou ser o dono)\n\n## Pontos-chave\n\n- Escolha o objeto Gold por atualidade, custo e quem é dono da lógica de atualização\n- Materialized views pré-calculam e atualizam, incrementalmente quando possível. Views calculam na leitura\n- Streaming tables dão manutenção incremental só-append com baixa latência\n- Os quatro são objetos do Unity Catalog governados pelo mesmo modelo de privilégios\n\n## Tópicos relacionados\n\n- [Limpeza e Qualidade de Dados](05-data-cleaning-and-quality.md)\n- [Fundamentos de Spark SQL (views, temp views)](01-spark-sql-fundamentals.md)\n- [Padrões de Ingestão e Lakeflow Connect](../02-data-ingestion-and-loading/01-ingestion-patterns-and-lakeflow-connect.md)\n\n## Documentação oficial\n\n- [Use standalone materialized views](https://docs.databricks.com/aws/en/views/materialized)\n- [Use standalone streaming tables](https://docs.databricks.com/aws/en/tables/streaming)\n- [Lakeflow pipelines Python language reference](https://docs.databricks.com/aws/en/ldp/developer/python-ref)\n- [Manage data quality with pipeline expectations](https://docs.databricks.com/aws/en/ldp/expectations)\n- [Configure materialized views (privileges, REFRESH)](https://docs.databricks.com/aws/en/sql/mv-st/materialized-configure)\n\n---\n\n**[← Anterior: Limpeza e Qualidade de Dados](05-data-cleaning-and-quality.md) | [↑ Voltar para Data Transformation and Modeling](README.md) | [Próximo: Parâmetros de tuning do Spark →](07-spark-tuning-parameters.md)**\n"},{"id":"03-data-transformation-and-modeling/07-spark-tuning-parameters","folder":"03-data-transformation-and-modeling","group":"modulo","order":7,"isIndex":false,"title":"Parâmetros de Tuning do Spark","md":"# Parâmetros de Tuning do Spark\n\n## Visão geral\n\nO exam guide cita quatro grupos de parâmetros básicos de tuning: **`spark.sql.shuffle.partitions`**, **`spark.default.parallelism`**, **`spark.executor.memory` / `spark.driver.memory`** e **`spark.sql.autoBroadcastJoinThreshold`**. Também espera que você **meça a performance de novo** depois de alterá-los. Este arquivo explica o que cada um controla, seu padrão, onde pode ser definido (classic vs serverless) e como o Adaptive Query Execution (AQE) muda o cenário no Databricks.\n\n> [!abstract] Resumo\n>\n> - **`spark.sql.shuffle.partitions`** (padrão OSS `200`) define o número de partições após um shuffle em joins e agregações. No Databricks, `auto` deixa o Spark escolher. É o padrão no serverless\n> - **`spark.default.parallelism`** é o número padrão de partições para operações **RDD** (`parallelize`, `reduceByKey`, `join` em RDDs). Não controla shuffles de DataFrame\n> - **`spark.executor.memory` / `spark.driver.memory`** (padrão OSS `1g`) definem o heap JVM por executor e do driver. São configurações do compute e não podem ser mudadas numa sessão em execução\n> - **`spark.sql.autoBroadcastJoinThreshold`** (padrão **10 MB**, `-1` desativa) é o tamanho máximo de tabela para broadcast em um join. O AQE no Databricks tem seu próprio limite em runtime, `spark.databricks.adaptive.autoBroadcastJoinThreshold` (padrão **30 MB**)\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: entender os parâmetros básicos de tuning e medir a performance de novo\n> - Qual parâmetro mexer para cada sintoma: milhares de tasks minúsculas, poucas tasks enormes com spill, broadcast que não aconteceu, ou OOM no driver com `collect()`\n> - Que o AQE (ligado por padrão) já agrupa partições de shuffle e troca para broadcast join em runtime\n> - Que o serverless expõe só algumas propriedades Spark, entre elas `spark.sql.shuffle.partitions`\n\n---\n\n## Os quatro parâmetros\n\n| Parâmetro | Controla | Padrão | Aumente quando | Diminua quando |\n| :--- | :--- | :--- | :--- | :--- |\n| `spark.sql.shuffle.partitions` | Partições após shuffle em joins e agregações de DataFrame/SQL | `200` (Spark OSS). `auto` no serverless | Partições de shuffle são enormes e fazem **spill**. Dados muito grandes | Dados pequenos, com milhares de tasks minúsculas e alto overhead de agendamento |\n| `spark.default.parallelism` | Partições padrão para transformações **RDD** (`join`, `reduceByKey`, `parallelize`) | Partições do maior RDD pai, ou para `parallelize`, total de cores dos executores (mínimo 2) | Jobs RDD deixam cores ociosos | Raramente. Não afeta shuffles de DataFrame |\n| `spark.executor.memory` | Heap JVM por executor | `1g` (Spark OSS) | Executores dão OOM ou fazem muito spill | Para caber mais executores por nó |\n| `spark.driver.memory` | Heap JVM do driver | `1g` (Spark OSS) | OOM no driver: `collect()`, `toPandas()`, broadcasts grandes, muitos arquivos pequenos | — |\n| `spark.sql.autoBroadcastJoinThreshold` | Tamanho máx. (bytes) de tabela enviada por broadcast a cada executor | `10485760` (10 MB). `-1` desativa | Uma dimensão um pouco acima de 10 MB ainda deve ir por broadcast | Broadcasts causam pressão de memória no driver/executores |\n\nFontes: [Spark configuration](https://spark.apache.org/docs/latest/configuration.html), [Spark SQL performance tuning](https://spark.apache.org/docs/latest/sql-performance-tuning.html).\n\n> [!note] Atenção\n> `spark.sql.shuffle.partitions` afeta o engine de DataFrame/SQL, que é o que quase todo código no Databricks usa. `spark.default.parallelism` afeta só a API RDD. Espere uma alternativa errada que troca os dois.\n\n## Onde configurá-los\n\n| Compute | Como | O que dá para mudar |\n| :--- | :--- | :--- |\n| **Classic: nível do compute** | Configuração do compute → **Advanced → Spark → Spark config**, um `chave valor` por linha (ou `spark_conf` na Clusters API) | Tudo, incluindo memória de executor/driver. Vale para todo notebook e job naquele compute |\n| **Classic: nível da sessão** | `spark.conf.set(\"spark.sql.shuffle.partitions\", \"64\")` ou `SET spark.sql.shuffle.partitions = 64` | Configurações SQL de runtime (shuffle partitions, broadcast threshold). **Não** a memória da JVM |\n| **Notebooks e jobs serverless** | `spark.conf.set(...)` / `SET ...` | **Apenas** uma lista curta: `spark.sql.shuffle.partitions` (padrão `auto`), `spark.sql.session.timeZone`, `spark.sql.ansi.enabled`, `spark.sql.files.maxPartitionBytes`, `spark.sql.legacy.timeParserPolicy`, `spark.databricks.execution.timeout` |\n\nFonte: [Set Spark configuration properties on Databricks](https://docs.databricks.com/aws/en/spark/conf). A mesma página diz que \"a Databricks geralmente recomenda não configurar a maioria das propriedades Spark\", porque configurações legadas podem sobrescrever comportamentos padrão mais novos.\n\n```text\n# Classic compute → Advanced → Spark config (nível do compute)\nspark.executor.memory 16g\nspark.driver.memory 8g\nspark.sql.shuffle.partitions auto\n```\n\n```python\n# Nível da sessão (classic ou serverless), afeta só esta SparkSession\nspark.conf.set(\"spark.sql.shuffle.partitions\", \"64\")\nspark.conf.set(\"spark.sql.autoBroadcastJoinThreshold\", str(50 * 1024 * 1024))   # 50 MB (só classic)\nprint(spark.conf.get(\"spark.sql.shuffle.partitions\"))\n```\n\n> [!warning] Erro comum\n> `spark.conf.set(\"spark.driver.memory\", \"8g\")` num notebook em execução não tem efeito. A JVM do driver já iniciou. A documentação do Spark diz que a memória do driver \"não deve ser definida via SparkConf diretamente na aplicação\" no modo client. Defina no Spark config do compute e reinicie.\n\n## Adaptive Query Execution (AQE) no Databricks\n\nO AQE reotimiza o plano de consulta em runtime, usando os tamanhos reais medidos nas fronteiras de shuffle e broadcast. Está **ligado por padrão** e se aplica a consultas não-streaming que tenham pelo menos um exchange ou subquery ([Adaptive query execution](https://docs.databricks.com/aws/en/optimizations/aqe)).\n\n| Recurso do AQE | O que faz | Parâmetro relacionado |\n| :--- | :--- | :--- |\n| **Agrupar partições pós-shuffle** | Junta partições de shuffle pequenas em partições de tamanho razoável | `spark.sql.adaptive.coalescePartitions.enabled` (`true`) |\n| **Trocar estratégia de join** | Converte um sort-merge join em broadcast hash join quando um lado se revela pequeno | `spark.databricks.adaptive.autoBroadcastJoinThreshold` (`30MB`) |\n| **Tratar skew em join** | Divide e replica partições com skew em **sort-merge e shuffle-hash joins** | `spark.sql.adaptive.skewJoin.enabled` (`true`) |\n| **Propagação de relação vazia** | Corta partes do plano que não retornam linhas | — |\n\n> [!important] Importante\n> O tratamento de skew do AQE vale **só para joins**: sort-merge e shuffle-hash, nunca broadcast. Uma **agregação `groupBy` com skew** não é resolvida pelo AQE. Faça salting na chave e agregue em duas etapas (veja [Spark UI e System Tables](../06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables.md)).\n\nDefinir `spark.sql.shuffle.partitions` como **`auto`** \"habilita o shuffle auto-otimizado, que define a quantidade de partições com base no plano e no tamanho dos dados de entrada\". Costuma ser um primeiro passo melhor do que chutar um número.\n\n## Broadcast joins na prática\n\n```python\nfrom pyspark.sql.functions import broadcast\n\n# Força o broadcast mesmo que as estatísticas coloquem a dimensão acima do limite\nenriched = facts.join(broadcast(dim_store), \"store_id\")\n```\n\n```sql\nSELECT /*+ BROADCAST(s) */ f.*, s.region\nFROM main.silver.sales f JOIN main.silver.stores s ON f.store_id = s.store_id;\n```\n\n- Um hint `BROADCAST` é respeitado \"mesmo que o tamanho da tabela sugerido pelas estatísticas esteja acima\" de `spark.sql.autoBroadcastJoinThreshold`\n- Fazer broadcast de uma tabela grande a faz passar pelo driver e ser copiada para cada executor, com risco de OOM. Faça broadcast só de dimensões realmente pequenas\n\n## Ciclo ajustar → medir de novo\n\nO exam guide associa tuning a **medir de novo**. Mude uma coisa por vez e compare com uma linha de base:\n\n```mermaid\nflowchart LR\n    A[Execução base<br/>registre a duração] --> B[Leia a Spark UI<br/>métricas dos stages]\n    B --> C{Sintoma}\n    C -->|milhares de tasks minúsculas| D[Menos shuffle partitions<br/>ou auto]\n    C -->|poucas tasks enormes, spill| E[Mais shuffle partitions<br/>ou mais memória no executor]\n    C -->|sort-merge com dim pequena| F[Hint de broadcast /<br/>aumentar threshold]\n    C -->|uma task retardatária| G[Skew: AQE para joins,<br/>salting para agregações]\n    D --> H[Reexecute com a mesma entrada<br/>compare duração + métricas]\n    E --> H\n    F --> H\n    G --> H\n    H --> A\n```\n\nO que comparar em cada reexecução:\n\n1. **Duração total** do job ou task: o histórico de execuções / matrix view dos Lakeflow Jobs mostra por execução\n2. **Métricas dos stages** na Spark UI: número de tasks, duração mediana vs máxima das tasks, shuffle read/write e spill (memória e disco)\n3. **Plano da consulta** na aba SQL / DataFrame: o `SortMergeJoin` virou `BroadcastHashJoin`?\n\n```python\n# Um harness mínimo de tempo antes/depois, com a mesma entrada\nimport time\n\ndef timed(label, fn):\n    start = time.time()\n    fn()\n    print(f\"{label}: {time.time() - start:.1f}s\")\n\nquery = lambda: spark.table(\"main.silver.sales\").groupBy(\"store_id\").count().write.mode(\"overwrite\").saveAsTable(\"main.scratch.sales_by_store\")\n\nspark.conf.set(\"spark.sql.shuffle.partitions\", \"200\"); timed(\"200 partições\", query)\nspark.conf.set(\"spark.sql.shuffle.partitions\", \"auto\"); timed(\"partições auto\", query)\n```\n\n> [!note] Observação\n> Disk cache e layout dos dados distorcem execuções isoladas. Compare várias execuções com a mesma entrada, de preferência no mesmo compute, antes de tirar conclusões.\n\n## Cola: sintoma → parâmetro\n\n| Sintoma na Spark UI ou nos logs | Correção provável |\n| :--- | :--- |\n| 200 tasks de poucos KB cada em um dataset pequeno | Diminua `spark.sql.shuffle.partitions` ou use `auto` (o coalescing do AQE geralmente já resolve) |\n| Tasks do stage de shuffle fazem spill em disco | Aumente shuffle partitions (partições menores) ou a memória do executor |\n| `SortMergeJoin` contra uma dimensão de 15 MB | Hint de broadcast, ou aumente `spark.sql.autoBroadcastJoinThreshold` |\n| `OutOfMemoryError` no driver após `collect()` | Não colete resultados grandes. Senão, aumente `spark.driver.memory` no compute |\n| Uma task roda 10× mais que as outras | Skew: o AQE resolve em joins; faça salting na chave em agregações |\n| Job RDD usa só alguns cores | Aumente `spark.default.parallelism` ou reparticione o RDD |\n\n## Casos de uso\n\n- **Dimensão pequena, join lento**: uma dimensão de lojas de 20 MB entra em sort-merge. Um hint de broadcast reduz o stage de minutos para segundos\n- **Agregação com spill**: aumentar shuffle partitions de 200 para 800 em um `groupBy` de vários terabytes elimina o spill em disco\n- **Job pequeno superparticionado**: um job horário sobre 50 MB roda 200 tasks minúsculas. Trocar para `auto` reduz o overhead\n- **OOM no driver em notebook de relatório**: a correção é parar de chamar `toPandas()` em 100 milhões de linhas, não aumentar a memória do driver indefinidamente\n\n## Problemas e erros comuns\n\n### Definir memória pelo notebook não faz nada\n\n**Cenário:** `spark.conf.set(\"spark.executor.memory\", \"32g\")` roda sem erro, mas os OOMs continuam.\n**Correção:** memória de executor e driver é fixada quando as JVMs iniciam. Defina no Spark config do compute e reinicie. No serverless, a memória não é configurável.\n\n### Serverless rejeita uma propriedade Spark\n\n**Cenário:** um notebook movido para serverless não consegue mais definir `spark.sql.autoBroadcastJoinThreshold`.\n**Correção:** o serverless suporta só uma lista curta de propriedades. Remova a configuração e confie no AQE, ou use um hint `BROADCAST` na consulta.\n\n### Ajustar `spark.default.parallelism` para um job de DataFrame\n\n**Cenário:** um engenheiro aumenta `spark.default.parallelism`, mas a agregação de DataFrame continua com 200 tasks de shuffle.\n**Correção:** shuffles de DataFrame usam `spark.sql.shuffle.partitions`. `spark.default.parallelism` vale para operações RDD.\n\n### Broadcast de uma tabela grande\n\n**Cenário:** depois de aumentar o broadcast threshold para 2 GB, os jobs falham com OOM no driver.\n**Correção:** tabelas em broadcast passam pelo driver e são copiadas para cada executor. Mantenha o limite modesto e faça broadcast só de dimensões pequenas.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - **Shuffle partitions** = shuffles de DataFrame/SQL (padrão 200, `auto` no Databricks). **Default parallelism** = RDDs\n> - O **broadcast threshold** padrão é 10 MB, e `-1` desativa. O limite do AQE em runtime no Databricks é 30 MB\n> - **Memória** de driver/executor é definida no compute, não com `spark.conf.set` na sessão\n> - Diminuir shuffle partitions deixa as partições **maiores**, o que piora spill e skew\n> - O tratamento de skew do AQE cobre **só joins**. Agregações com skew pedem **salting**\n> - Sempre **meça de novo** com a mesma entrada depois de uma mudança\n\n## Pontos-chave\n\n- Quatro parâmetros: shuffle partitions, default parallelism, memória de executor/driver, broadcast threshold\n- O AQE (ligado por padrão) agrupa partições, troca para broadcast join e divide partições de join com skew em runtime\n- O serverless expõe só algumas propriedades Spark, e `spark.sql.shuffle.partitions` é uma delas\n- Ajuste com base em evidências da Spark UI, mude uma configuração por vez e meça de novo\n\n## Tópicos relacionados\n\n- [Joins e Agregações](03-joins-aggregations.md)\n- [Spark UI e System Tables](../06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables.md)\n- [Compute Troubleshooting (OOM)](../06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting.md)\n\n## Documentação oficial\n\n- [Adaptive query execution](https://docs.databricks.com/aws/en/optimizations/aqe)\n- [Set Spark configuration properties on Databricks](https://docs.databricks.com/aws/en/spark/conf)\n- [Compute configuration reference (Spark config)](https://docs.databricks.com/aws/en/compute/configure)\n- [Apache Spark configuration](https://spark.apache.org/docs/latest/configuration.html)\n- [Apache Spark SQL performance tuning](https://spark.apache.org/docs/latest/sql-performance-tuning.html)\n\n---\n\n**[← Anterior: Objetos da camada Gold](06-gold-layer-objects.md) | [↑ Voltar para Data Transformation and Modeling](README.md)**\n"},{"id":"03-data-transformation-and-modeling/README","folder":"03-data-transformation-and-modeling","group":"modulo","order":0,"isIndex":true,"title":"Data Transformation and Modeling","md":"# Data Transformation and Modeling (22 % da prova)\n\nO Domínio 3 é o maior da prova de agosto de 2026. Cobre o trabalho que transforma Bronze em Silver e Gold. Você limpa nulos e tipos com PySpark ou SQL. Faz join e union de DataFrames, reestrutura colunas e arrays, deduplica e agrega. Também precisa conhecer os parâmetros básicos de tuning do Spark, construir objetos da camada Gold (tabelas, views, materialized views, streaming tables) no Unity Catalog e aplicar verificações de qualidade de dados.\n\n## Visão geral dos tópicos\n\n```mermaid\nflowchart TD\n    T[Transformação e Modelagem] --> SQL[Spark SQL]\n    T --> DF[Operações com DataFrame]\n    T --> JA[Joins e agregações]\n    T --> ADV[Arrays, structs, explode, UDFs]\n    T --> CLEAN[Limpeza Bronze → Silver<br/>+ qualidade de dados]\n    T --> GOLD[Objetos da camada Gold]\n    T --> TUNE[Parâmetros de tuning]\n```\n\n## Conteúdo da seção\n\n| Arquivo | Tópico | Prioridade |\n| :--- | :--- | :--- |\n| [01-spark-sql-fundamentals.md](01-spark-sql-fundamentals.md) | Consultas SQL, tabelas, temp views, operações de catálogo | Alta |\n| [02-dataframe-operations.md](02-dataframe-operations.md) | API de DataFrame: select, filter, adicionar/remover/renomear colunas, dedup | Alta |\n| [03-joins-aggregations.md](03-joins-aggregations.md) | Joins inner/left/cross/semi/anti, broadcast joins, GROUP BY, contagem distinta aproximada | Alta |\n| [04-advanced-transformations.md](04-advanced-transformations.md) | Arrays, maps, structs, `explode`, `split`, pivot, UDFs, tratamento de nulos | Alta |\n| [05-data-cleaning-and-quality.md](05-data-cleaning-and-quality.md) | Limpeza Bronze → Silver, constraints, expectations de pipeline | Alta |\n| [06-gold-layer-objects.md](06-gold-layer-objects.md) | Tabelas vs views vs materialized views vs streaming tables no UC | Alta |\n| [07-spark-tuning-parameters.md](07-spark-tuning-parameters.md) | `spark.sql.shuffle.partitions`, `spark.default.parallelism`, memória de executor/driver, broadcast threshold, AQE | Média |\n\n## Cobertura das habilidades oficiais (agosto de 2026)\n\n| Habilidade do exam guide (parafraseada) | Onde é coberta |\n| :--- | :--- |\n| Limpar Bronze para Silver (nulos, tipos) com PySpark/SQL | [05](05-data-cleaning-and-quality.md), [02](02-dataframe-operations.md), [04](04-advanced-transformations.md) |\n| Combinar DataFrames: joins inner, left, broadcast, múltiplas chaves, cross; union / union all | [03](03-joins-aggregations.md) |\n| Manipular colunas, linhas e estrutura: adicionar, remover, split, renomear, filtrar, explode | [02](02-dataframe-operations.md), [04](04-advanced-transformations.md) |\n| Deduplicação e agregados (count, contagem distinta aproximada, média, summary) | [02](02-dataframe-operations.md), [03](03-joins-aggregations.md), [05](05-data-cleaning-and-quality.md) |\n| Parâmetros básicos de tuning e medir a performance de novo | [07](07-spark-tuning-parameters.md) |\n| Objetos da camada Gold: materialized views, views, streaming tables, tabelas | [06](06-gold-layer-objects.md) |\n| Verificações de qualidade e regras de validação para Silver e Gold | [05](05-data-cleaning-and-quality.md) |\n\n## Conceitos-chave\n\n- **Lazy evaluation**: transformações montam um plano; ações (`count`, `show`, `write`) o executam\n- **`union` vs `unionByName`**: `union` casa colunas por posição; `unionByName` casa por nome. Ambos mantêm duplicatas (semântica de `UNION ALL`), enquanto o `UNION` do SQL as remove\n- **Objetos Gold**: uma **view** recalcula a cada consulta; uma **materialized view** guarda resultados pré-calculados e é atualizada; uma **streaming table** adiciona dados novos incrementalmente\n- **Expectations**: `CONSTRAINT ... EXPECT (...)` com warn (padrão), `DROP ROW` ou `FAIL UPDATE`\n\n## Próximos passos\n\nContinue para [04 — Working with Lakeflow Jobs](../04-working-with-lakeflow-jobs/README.md) para orquestrar essas transformações.\n\n---\n\n**[← Anterior: Data Ingestion and Loading](../02-data-ingestion-and-loading/README.md) | [↑ Voltar à Certificação](../README.md) | [Próximo: Working with Lakeflow Jobs →](../04-working-with-lakeflow-jobs/README.md)**\n"},{"id":"04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks","folder":"04-working-with-lakeflow-jobs","group":"modulo","order":1,"isIndex":false,"title":"Lakeflow Jobs e Tasks","md":"# Lakeflow Jobs e Tasks\n\n## Visão geral\n\n**Lakeflow Jobs** (antigo Databricks Jobs, parte do que se chamava Workflows) é o serviço de orquestração para workloads de engenharia de dados em produção. Um job agrupa uma ou mais **tasks** em um DAG e adiciona triggers, parâmetros, compute, retries e notificações.\n\n> [!abstract] Resumo\n>\n> - Um **job** tem um trigger e configurações. **Tasks** são os nós do DAG, ligadas por **Depends on**. Tasks sem dependência entre si rodam em paralelo\n> - Tipos comuns de task: Notebook, SQL, SQL Alert, Dashboards, Pipeline, Python script, Python wheel, dbt, JAR, Run Job, If/else, For each\n> - Parâmetros: job parameters mais dynamic value references como `{{job.run_id}}` e `{{job.start_time.iso_date}}`\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: configurar tasks comuns (notebook, SQL query, dashboard e pipeline) e suas dependências usando Lakeflow Jobs e seu grafo de tasks (DAG)\n> - Inserir uma task upstream alterando o **Depends on**\n> - Escolher o compute das tasks: serverless, jobs compute ou um cluster all-purpose existente\n\n---\n\n## O que é um job?\n\n```mermaid\nflowchart TB\n    subgraph JobDef[\"Definição do Job\"]\n        Name[\"Nome e ID\"]\n        Config[\"Configuração\"]\n        Tasks[\"Lista de tasks\"]\n        Schedule[\"Agenda/Trigger\"]\n    end\n\n    subgraph Execution[\"Execuções\"]\n        Run1[\"Run 1\"]\n        Run2[\"Run 2\"]\n        Run3[\"Run 3\"]\n    end\n\n    subgraph Monitoring[\"Monitoramento\"]\n        Logs[\"Logs\"]\n        Status[\"Status\"]\n        Alerts[\"Alertas\"]\n    end\n\n    JobDef --> Execution\n    Execution --> Monitoring\n```\n\nUm job empacota:\n\n- **Tasks**: o código a executar (notebook, Python, SQL, JAR etc.)\n- **Configuração**: parâmetros, clusters, dependências\n- **Agendamento**: quando/com que frequência rodar\n- **Monitoramento**: logs, alertas, política de retry\n\n## Tipos de task\n\nTipos listados na documentação atual ([Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task)):\n\n| Tipo de task | Executa | Relevância na prova |\n|-----------|------|----------------|\n| **Notebook** | Um notebook (Python, SQL, Scala, R) em serverless ou classic | **Alta**: a task de ETL mais comum |\n| **SQL** | Uma consulta SQL ou arquivo SQL em um **SQL warehouse** | **Alta**: \"SQL query task\" no exam guide |\n| **Dashboards** | Atualiza um dashboard AI/BI (e pode notificar assinantes) | **Alta**: \"dashboard task\" |\n| **Pipeline** | Dispara um update de um Lakeflow (Declarative) pipeline, incluindo ingestion pipelines do Lakeflow Connect | **Alta**: \"pipeline task\" |\n| **SQL Alert** | Avalia um alerta do Databricks SQL | Média |\n| **Python script** / **Python wheel** / **JAR** / **Spark Submit** | Código empacotado | Baixa–média |\n| **dbt** | Um projeto dbt | Baixa |\n| **Run Job** | Dispara outro Lakeflow Job | Média: orquestração modular |\n| **If/else** / **For each** | Control flow (veja [Control Flow](03-control-flow.md)) | **Alta** |\n| Power BI, Clean Room notebook e outros | Integrações especializadas | Baixa |\n\n```yaml\n# Tasks de notebook, SQL, dashboard e pipeline ligadas em um DAG (formato YAML de bundle)\ntasks:\n  - task_key: ingest\n    pipeline_task:\n      pipeline_id: ${resources.pipelines.orders_pipeline.id}\n  - task_key: quality_check\n    depends_on: [{task_key: ingest}]\n    sql_task:\n      warehouse_id: ${var.warehouse_id}\n      file:\n        path: ../sql/check_orders.sql\n  - task_key: enrich\n    depends_on: [{task_key: quality_check}]\n    notebook_task:\n      notebook_path: ../notebooks/enrich_orders\n  - task_key: refresh_dashboard\n    depends_on: [{task_key: enrich}]\n    dashboard_task:\n      dashboard_id: ${resources.dashboards.sales.id}\n      warehouse_id: ${var.warehouse_id}\n```\n\n### Exemplo de task de notebook\n\n```python\n# O job passa parâmetros, lidos via widgets\nenv = dbutils.widgets.get(\"env\")     # \"prod\"\ndate = dbutils.widgets.get(\"date\")   # \"2025-01-15\"\n\nimport pyspark.sql.functions as F\n\ndf = spark.read.table(\"main.bronze.events\").filter(F.col(\"event_date\") == date)\n\ndf_processed = (df\n    .filter(F.col(\"value\") > 0)\n    .groupBy(\"category\")\n    .agg(F.count(\"*\").alias(\"count\")))\n\ndf_processed.write.mode(\"overwrite\").saveAsTable(\"main.silver.event_counts\")\n```\n\n### Exemplo de task de Python script\n\n```python\n# Parâmetros chegam como argumentos de linha de comando\nimport argparse\nfrom pyspark.sql import SparkSession\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--environment\", required=True)\n    parser.add_argument(\"--date\", required=True)\n    args = parser.parse_args()\n\n    spark = SparkSession.builder.appName(\"ETL\").getOrCreate()\n    df = spark.read.table(\"main.bronze.events\").filter(f\"event_date = '{args.date}'\")\n    df.write.mode(\"overwrite\").saveAsTable(\"main.silver.events_clean\")\n\nif __name__ == \"__main__\":\n    main()\n```\n\n## Criando jobs pela UI\n\n1. Abra **Jobs & Pipelines** na barra lateral (antigo Workflows)\n2. Clique em **Create → Job**\n3. **Configure a task:** tipo (Notebook, Python, SQL etc.), compute, nome e caminho do código\n4. **Adicione parâmetros** (opcional): `environment` = \"prod\", `date` = `{{job.start_time.iso_date}}`\n5. **Configure o trigger** (opcional): agenda cron + fuso horário, file arrival, table update\n6. **Adicione notificações** (opcional): email, Slack/webhooks\n7. **Salve e rode**\n\n## Criando jobs pela API (Jobs API 2.1)\n\n```json\n{\n  \"name\": \"daily_etl_pipeline\",\n  \"description\": \"Processo de ETL diário\",\n  \"max_concurrent_runs\": 1,\n  \"tasks\": [\n    {\n      \"task_key\": \"extract_data\",\n      \"notebook_task\": {\n        \"notebook_path\": \"/Users/user@company.com/etl/extract\",\n        \"base_parameters\": {\n          \"environment\": \"prod\",\n          \"date\": \"{{job.start_time.iso_date}}\"\n        }\n      },\n      \"existing_cluster_id\": \"cluster-123\",\n      \"timeout_seconds\": 3600\n    }\n  ],\n  \"schedule\": {\n    \"quartz_cron_expression\": \"0 0 * * * ?\",\n    \"timezone_id\": \"America/Sao_Paulo\"\n  }\n}\n```\n\n```bash\ncurl -X POST https://<workspace>.cloud.databricks.com/api/2.1/jobs/create \\\n  -H \"Authorization: Bearer <TOKEN>\" \\\n  -d @job_config.json\n\n# Ou com a Databricks CLI\ndatabricks jobs create --json @job_config.json\n```\n\n## Parâmetros\n\n### Estáticos e dinâmicos\n\n```json\n{\n  \"base_parameters\": {\n    \"environment\": \"prod\",\n    \"run_date\": \"{{job.start_time.iso_date}}\",\n    \"run_id\": \"{{job.run_id}}\",\n    \"task_run_id\": \"{{task.run_id}}\"\n  }\n}\n```\n\n### Dynamic value references disponíveis\n\n| Referência | Descrição | Exemplo |\n|-------|-----------|---------|\n| `{{job.id}}` | ID do job | \"123456\" |\n| `{{job.name}}` | Nome do job na execução | \"daily_etl\" |\n| `{{job.run_id}}` | ID único da execução do job | \"1234567890\" |\n| `{{job.start_time.iso_date}}` | Data de início da execução (ISO) | \"2026-10-26\" |\n| `{{job.trigger.type}}` | O que iniciou a execução | — |\n| `{{job.trigger.file_arrival.location}}` | Local do file arrival trigger | `/Volumes/main/raw/landing/` |\n| `{{job.parameters.<nome>}}` | Um parâmetro do job | — |\n| `{{task.run_id}}` | ID da execução da task | — |\n| `{{tasks.<task>.values.<chave>}}` | Um task value definido upstream | — |\n\n`{{start_date}}` e variáveis legadas parecidas estão depreciadas. Use `{{job.start_time.<argumento>}}` ([dynamic value references](https://docs.databricks.com/aws/en/jobs/dynamic-value-references)).\n\n### Lendo parâmetros nas tasks\n\n```python\n# Notebook: via dbutils.widgets\nenv = dbutils.widgets.get(\"environment\")\nrun_date = dbutils.widgets.get(\"run_date\")\n\n# Python script: via argparse\nimport argparse\nparser = argparse.ArgumentParser()\nparser.add_argument(\"--environment\")\nparser.add_argument(\"--run_date\")\nargs = parser.parse_args()\n```\n\n## Jobs multi-task\n\n### Job com dependências (sequencial)\n\n```json\n{\n  \"name\": \"etl_pipeline_with_tasks\",\n  \"tasks\": [\n    {\"task_key\": \"extract\",\n     \"notebook_task\": {\"notebook_path\": \"/Users/user/extract\"}},\n    {\"task_key\": \"transform\",\n     \"depends_on\": [{\"task_key\": \"extract\"}],\n     \"notebook_task\": {\"notebook_path\": \"/Users/user/transform\"}},\n    {\"task_key\": \"load\",\n     \"depends_on\": [{\"task_key\": \"transform\"}],\n     \"notebook_task\": {\"notebook_path\": \"/Users/user/load\"}}\n  ]\n}\n```\n\n### Tasks em paralelo (fan-out / fan-in)\n\n```json\n{\n  \"tasks\": [\n    {\"task_key\": \"process_region_a\", \"notebook_task\": {\"notebook_path\": \"/users/user/process_region_a\"}},\n    {\"task_key\": \"process_region_b\", \"notebook_task\": {\"notebook_path\": \"/users/user/process_region_b\"}},\n    {\"task_key\": \"merge_results\",\n     \"depends_on\": [{\"task_key\": \"process_region_a\"}, {\"task_key\": \"process_region_b\"}],\n     \"notebook_task\": {\"notebook_path\": \"/users/user/merge\"}}\n  ]\n}\n```\n\n`process_region_a` e `process_region_b` rodam **em paralelo**; `merge_results` só começa quando as duas terminarem.\n\n```mermaid\nflowchart LR\n    A[process_region_a] --> M[merge_results]\n    B[process_region_b] --> M\n```\n\n## Opções de compute\n\n| Opção | Prós | Contras |\n| :--- | :--- | :--- |\n| **Serverless jobs** | Início rápido, sem gestão de infra, paga pelo uso | Menos controle (sem init scripts, poucas configs Spark) |\n| **Jobs compute (`new_cluster` / job cluster)** | Criado e encerrado automaticamente, SKU mais barato | Latência de inicialização (minutos) |\n| **Cluster all-purpose existente (`existing_cluster_id`)** | Já está rodando, início rápido | Mais caro, gestão manual, custo com tempo ocioso |\n\n```json\n{\n  \"task_key\": \"my_task\",\n  \"notebook_task\": {\"notebook_path\": \"/path/to/notebook\"},\n  \"new_cluster\": {\n    \"spark_version\": \"15.4.x-scala2.12\",\n    \"node_type_id\": \"i3.xlarge\",\n    \"num_workers\": 2,\n    \"aws_attributes\": {\"availability\": \"SPOT_WITH_FALLBACK\"}\n  }\n}\n```\n\nUse `job_cluster_key` para que várias tasks do mesmo job **compartilhem** um job cluster.\n\n## Boas práticas de configuração\n\n```json\n{\n  \"max_concurrent_runs\": 1,\n  \"tasks\": [\n    {\n      \"task_key\": \"main\",\n      \"timeout_seconds\": 3600,\n      \"max_retries\": 2,\n      \"min_retry_interval_millis\": 60000\n    }\n  ],\n  \"email_notifications\": {\n    \"on_success\": [\"user@company.com\"],\n    \"on_failure\": [\"user@company.com\", \"ops@company.com\"]\n  },\n  \"webhook_notifications\": {\n    \"on_failure\": [{\"id\": \"slack-webhook-123\"}]\n  }\n}\n```\n\n## Ciclo de vida de um job\n\n```mermaid\nflowchart LR\n    Created[\"Criado\"]\n    Scheduled[\"Agendado\"]\n    Running[\"Rodando\"]\n    Success[\"Sucesso\"]\n    Failed[\"Falhou\"]\n    Retry[\"Retry\"]\n\n    Created --> Scheduled\n    Scheduled --> Running\n    Running --> Success\n    Running --> Failed\n    Failed --> Retry\n    Retry --> Running\n    Success -.->|Próxima execução| Scheduled\n```\n\n## Casos de uso\n\n- **Pipelines ETL multi-task**: definir extract, transform e load como tasks separadas em um único job, usando `depends_on` para criar um DAG que roda na ordem certa, com ramos paralelos quando possível.\n- **Jobs de backfill parametrizados**: usar dynamic value references como `{{job.start_time.iso_date}}` para rodar o mesmo job em intervalos de datas diferentes, fazendo backfills sem duplicar definições.\n\n## Problemas e erros comuns\n\n### Inserir uma task upstream na direção errada\n\n**Cenário:** um engenheiro adiciona um notebook de validação que deve rodar **antes** da task existente, mas configura a nova task para depender da antiga — então ela roda depois.\n**Correção:** a nova task upstream não tem dependência. Edite o **Depends on** da task **original** para incluir a nova task.\n\n### Job falha e ninguém é alertado\n\n**Cenário:** um job de produção falha de madrugada, mas o plantão não é avisado porque notificações nunca foram configuradas.\n**Correção:** configure notificações por email (on_failure) e/ou webhooks (ex.: Slack). Verifique a entrega com uma execução de teste antes de confiar nelas em produção.\n\n### Dependência mal configurada faz tasks serem puladas\n\n**Cenário:** uma task downstream nunca executa porque o `depends_on` referencia o `task_key` errado, ou a falha de uma task upstream não é tratada.\n**Correção:** revise a visualização do DAG na UI de Jobs para confirmar as arestas de dependência e as condições Run if.\n\n## Dicas para a prova\n\n- Job clusters são mais baratos que all-purpose para jobs de produção; encerram automaticamente ao fim do job\n- Jobs multi-task usam `depends_on` para definir o DAG; tasks sem dependências rodam em paralelo\n- Saiba as dynamic value references: `{{job.run_id}}`, `{{job.start_time.iso_date}}`, `{{job.parameters.<nome>}}`, `{{tasks.<task>.values.<chave>}}`\n- Tipos de task do exam guide: **notebook, SQL query, dashboard, pipeline**. Saiba o compute de cada um (tasks SQL e dashboard usam SQL warehouse)\n- `max_concurrent_runs: 1` evita execuções sobrepostas. Uma execução que excederia o limite é pulada (status **Skipped**)\n\n## Pontos-chave\n\n- **Job**: contêiner de workloads agendados/disparados\n- **Task**: unidade de trabalho (notebook, Python, SQL etc.)\n- **Compute**: serverless, job cluster ou cluster existente\n- **Parâmetros**: entradas estáticas/dinâmicas via dynamic value references\n- **Dependências**: workflows multi-task com ordem definida\n- **Max concurrent runs**: limita execuções simultâneas\n- **Timeout**: tempo máximo de execução por task\n- **Max retries**: nova tentativa automática em caso de falha\n\n## Tópicos relacionados\n\n- [Agendamento e Triggers](02-scheduling-triggers.md)\n- [Monitoramento de Jobs](../06-troubleshooting-monitoring-and-optimization/01-job-monitoring.md)\n- [Compute e Clusters](../01-databricks-intelligence-platform/03-compute-clusters.md)\n\n## Documentação oficial\n\n- [Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/)\n- [Configure and edit tasks in Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/configure-task)\n- [Configure task dependencies](https://docs.databricks.com/aws/en/jobs/conditional-tasks)\n- [Dynamic value references](https://docs.databricks.com/aws/en/jobs/dynamic-value-references)\n\n---\n\n**[↑ Voltar para Working with Lakeflow Jobs](README.md) | [Próximo: Agendamento e Triggers →](02-scheduling-triggers.md)**\n"},{"id":"04-working-with-lakeflow-jobs/02-scheduling-triggers","folder":"04-working-with-lakeflow-jobs","group":"modulo","order":2,"isIndex":false,"title":"Agendamento e Triggers","md":"# Agendamento e Triggers\n\n## Visão geral\n\nUm Lakeflow Job inicia execuções a partir de um **trigger**. O exam guide cita três tipos: **scheduled** (por tempo), **file arrival** e **table update** (ambos por dados). Também espera que você escolha entre trigger por tempo e por dados com base na disponibilidade dos dados e nas dependências do pipeline. Execuções contínuas e manuais completam o quadro.\n\n> [!abstract] Resumo\n>\n> - **Scheduled**: intervalo simples, ou cron Quartz avançado com fuso horário (mínimo de 10 segundos entre execuções)\n> - **File arrival**: monitora uma external location ou volume do UC e inicia uma execução quando chegam arquivos novos\n> - **Table update**: inicia uma execução quando tabelas UC monitoradas (ou views, MVs e streaming tables) mudam, esperando *qualquer uma* ou *todas*\n> - **Continuous**: inicia uma nova execução sempre que a anterior termina. Não pode ser combinado com outros triggers\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: implementar agendas de jobs entendendo os tipos de trigger (scheduled, file arrival e table update)\n> - Habilidade do exam guide: escolher entre triggers por tempo e por dados com base na disponibilidade dos dados e dependências do pipeline\n> - Ler cron Quartz (`segundo minuto hora dia-do-mês mês dia-da-semana`) e usar `?` corretamente\n\n---\n\n## Tipos de trigger em resumo\n\n| Trigger | Inicia uma execução quando… | Tipo | Escolha quando |\n| :--- | :--- | :--- | :--- |\n| **Scheduled** | Uma agenda por tempo dispara (intervalo simples ou cron Quartz + fuso) | Por tempo | Os dados chegam em horário conhecido, ou os consumidores precisam do resultado em horário fixo (ex.: relatório às 6h) |\n| **File arrival** | Chegam arquivos novos em uma **external location ou volume do UC** monitorado | Por dados | Arquivos chegam em horários imprevisíveis e devem ser processados logo depois, sem compute ocioso |\n| **Table update** | Tabelas UC monitoradas (incluindo views, MVs, streaming tables, tabelas OpenSharing, system tables) são atualizadas | Por dados | O job depende de tabelas upstream produzidas por *outros* jobs ou equipes |\n| **Continuous** | A execução anterior termina ou falha, então sempre há uma execução ativa | Sempre ligado | Workloads de streaming que precisam rodar sem parar. Não combina com outros triggers |\n| **Nenhum (manual)** | **Run now**, a API ou um orquestrador externo | Manual | Execuções ad hoc e orquestradas externamente |\n| Model update *(Beta)* | Uma versão ou alias de modelo no UC muda | Por dados | Promoção de ML (fora desta prova) |\n\nFonte: [Automate jobs with schedules and triggers](https://docs.databricks.com/aws/en/jobs/triggers).\n\n- Por padrão só **uma execução** de um job pode estar ativa por vez. Execuções que excedem a concorrência máxima são puladas (skipped)\n- Pausar um trigger impede novas execuções, mas as ativas continuam. Cada trigger pode ser pausado de forma independente\n- **Múltiplos triggers** por job (até cinco) estão em **Beta**\n\n## Triggers agendados (por tempo)\n\nUma agenda pode ser **simples** (a cada N unidades; o agendador escolhe o primeiro horário) ou **avançada** (período, horário inicial e fuso, opcionalmente em sintaxe cron). \"A Databricks impõe um intervalo mínimo de 10 segundos entre execuções subsequentes\" ([Run jobs on a schedule](https://docs.databricks.com/aws/en/jobs/scheduled)).\n\n### Sintaxe do cron Quartz\n\nAgendas avançadas usam cron **Quartz**: 6 ou 7 campos, com **segundos primeiro** e ano opcional:\n\n```text\n┌ segundos (0-59)\n│ ┌ minutos (0-59)\n│ │ ┌ horas (0-23)\n│ │ │ ┌ dia do mês (1-31)\n│ │ │ │ ┌ mês (1-12 ou JAN-DEC)\n│ │ │ │ │ ┌ dia da semana (1-7 ou SUN-SAT; 1 = domingo)\n│ │ │ │ │ │ ┌ ano (opcional)\n0 0 2 * * ?\n```\n\n- `?` significa \"sem valor específico\". Quando você restringe o dia da semana, coloque `?` no dia do mês, e vice-versa\n- Cron Unix tem 5 campos e não tem segundos — não cole cron Unix numa agenda Quartz\n\n| Agenda | Expressão Quartz |\n| :--- | :--- |\n| Todo dia às 02:00 | `0 0 2 * * ?` |\n| Todo dia ao meio-dia | `0 0 12 * * ?` |\n| A cada hora cheia | `0 0 * * * ?` |\n| A cada 15 minutos | `0 0/15 * * * ?` |\n| Dias úteis às 09:00 | `0 0 9 ? * MON-FRI` |\n| Dias úteis às 10:15 | `0 15 10 ? * MON-FRI` |\n| Primeiro dia de cada mês à meia-noite | `0 0 0 1 * ?` |\n| Segundas à meia-noite | `0 0 0 ? * MON` |\n| De hora em hora, das 9h às 17h, seg–sex | `0 0 9-17 ? * MON-FRI` |\n\n```json\n{\n  \"schedule\": {\n    \"quartz_cron_expression\": \"0 0 2 * * ?\",\n    \"timezone_id\": \"America/Sao_Paulo\",\n    \"pause_status\": \"UNPAUSED\"\n  }\n}\n```\n\n### Fusos horários comuns\n\n| Fuso | Identificador |\n|----------|-----------|\n| UTC | `UTC` |\n| Brasília | `America/Sao_Paulo` |\n| EUA Leste | `America/New_York` |\n| EUA Pacífico | `America/Los_Angeles` |\n| Reino Unido | `Europe/London` |\n| Europa Central | `Europe/Berlin` |\n| Tóquio | `Asia/Tokyo` |\n\n### Horário de verão\n\n- Com um fuso que tem horário de verão, \"um job horário é pulado ou pode parecer atrasado em uma ou duas horas\" na mudança\n- Use **UTC** quando as execuções precisam acontecer em intervalos absolutos\n- Documente o fuso pretendido na descrição do job\n\n## Políticas de agendamento\n\n### Max concurrent runs\n\nImpede que várias instâncias do mesmo job rodem ao mesmo tempo:\n\n```json\n{\n  \"name\": \"daily_load\",\n  \"max_concurrent_runs\": 1,\n  \"schedule\": {\"quartz_cron_expression\": \"0 0 * * * ?\"}\n}\n```\n\nSe um job demora mais que o intervalo da agenda com `max_concurrent_runs: 1`:\n\n- As novas execuções agendadas são **puladas** (Skipped)\n- Não se forma fila\n- Evita falhas em cascata e processamento duplicado\n\n### Comportamento de timeout\n\nQuando o `timeout_seconds` de uma task é excedido:\n\n1. A task é encerrada (status **Timed out**)\n2. Alertas de falha são enviados\n3. A lógica de retry é acionada (se configurada)\n4. A execução do job fica como falha\n\n## File arrival triggers (por dados)\n\nUm file arrival trigger monitora a raiz ou um subcaminho de uma **external location ou volume do Unity Catalog**, recursivamente, e faz o \"melhor esforço para verificar novos arquivos a cada minuto\" ([Trigger jobs when new files arrive](https://docs.databricks.com/aws/en/jobs/file-arrival-triggers)).\n\n| Configuração | Efeito |\n| :--- | :--- |\n| **Minimum time between triggers in seconds** | Cooldown: no máximo uma execução por intervalo (ex.: `900` = uma a cada 15 min) |\n| **Wait after last change in seconds** | Debounce: cada arquivo novo reinicia o timer, e a execução começa quando as chegadas param (ex.: `60` para lotes) |\n\n- Só arquivos **novos** disparam execuções. Sobrescrever um arquivo com o mesmo nome não dispara\n- Sem file events, um workspace suporta no máximo 50 desses triggers, e o local pode ter até 10.000 arquivos. **Habilite file events** na external location para remover o limite de arquivos\n- Permissões: `READ` no local de armazenamento e **CAN MANAGE** no job\n- Dentro do job disparado, use **Auto Loader** (com checkpoint fora do caminho monitorado) para processar exatamente os arquivos novos. `{{job.trigger.file_arrival.location}}` passa o local para a task\n\n## Table update triggers (por dados)\n\nUm table update trigger roda o job quando tabelas monitoradas mudam (updates, merges, deletes), sem um cluster rodando continuamente ([Trigger jobs when source tables are updated](https://docs.databricks.com/aws/en/jobs/trigger-table-update)).\n\n| Configuração | Efeito |\n| :--- | :--- |\n| **Trigger when** | **Any table is updated** ou **All tables are updated** (quando você monitora várias) |\n| **Minimum time between triggers in seconds** | Espera após uma execução terminar antes de disparar de novo |\n| **Wait after last change in seconds** | Espera após um update antes de disparar; novos updates reiniciam o timer |\n\n- Fontes suportadas: tabelas Delta e Iceberg gerenciadas pelo UC, tabelas Delta externas, materialized views, streaming tables, views e metric views do UC (quando suas dependências são suportadas), objetos OpenSharing e system tables\n- Até **10 tabelas** por trigger\n- O principal **Run as** do job precisa de `SELECT` em cada tabela, mais `USE CATALOG` e `USE SCHEMA`. Sem isso, o trigger não consegue avaliar e o job nunca roda\n\n```mermaid\nflowchart LR\n    A[Job do Time A<br/>grava main.silver.orders] -->|tabela atualizada| T{{Table update trigger<br/>All tables updated}}\n    B[Job do Time B<br/>grava main.silver.customers] -->|tabela atualizada| T\n    T --> J[Job que constrói a Gold]\n```\n\n## Escolhendo: por tempo vs por dados\n\n| Pergunta | Aponta para |\n| :--- | :--- |\n| Os dados chegam em horário imprevisível e devem ser processados logo depois? | **File arrival** |\n| O job depende de tabelas mantidas por outros jobs ou equipes, sem agenda compartilhada? | **Table update** (*All tables* quando precisa de todas as entradas atualizadas) |\n| O prazo é fixo (relatório até 06:00), ou a fonte entrega em horário fixo? | **Scheduled** |\n| Nenhum compute deve rodar, nem execuções vazias, em longos períodos ociosos? | Por dados (file arrival ou table update) |\n| O workload nunca pode parar? | **Continuous** |\n| As dependências são *dentro* de um pipeline? | Nenhum: use dependências de task em **um** DAG |\n\nUm job agendado que verifica a cada 5 minutos \"por via das dúvidas\" inicia execuções que não encontram dados. Um trigger por dados só roda quando há algo a fazer.\n\n## Padrões de agendamento\n\n- **Diário em horário fixo**: `0 0 6 * * ?` com `timezone_id` definido\n- **Várias vezes ao dia**: `0 0 * * * ?` (de hora em hora)\n- **Horário comercial**: `0 0 9-17 ? * MON-FRI`\n- **Escalonar jobs independentes** para distribuir carga: região A `0 0 * * * ?`, região B `0 10 * * * ?`, região C `0 20 * * * ?`\n- **Ambientes diferentes**: agendas separadas para prod e teste evitam interferência\n\n> [!note] Atenção\n> Escalonar horários **não** é a forma certa de garantir a ordem entre tarefas dependentes. Se B depende de A, coloque as duas como tasks no **mesmo job** com `depends_on`, ou use um table update trigger.\n\n## Pausar e retomar\n\n- **Pela UI**: em **Jobs & Pipelines**, abra o job e clique em **Pause** — nenhuma nova execução é agendada\n- **Pela API**: não há endpoint de pause separado. Defina o `pause_status` do trigger nas configurações do job (`jobs/update`, ou `pause_status` no YAML do bundle):\n\n```bash\ncurl -X POST https://<workspace-host>/api/2.1/jobs/update \\\n  -H \"Authorization: Bearer <token>\" \\\n  -d '{\"job_id\": 123, \"new_settings\": {\"schedule\": {\"quartz_cron_expression\": \"0 0 2 * * ?\", \"timezone_id\": \"UTC\", \"pause_status\": \"PAUSED\"}}}'\n```\n\nUse `\"pause_status\": \"UNPAUSED\"` para retomar. Pausar impede novas execuções; as ativas continuam.\n\n## Execução manual\n\n```bash\n# Rodar o job agora (ignora a agenda)\ncurl -X POST https://<workspace-host>/api/2.1/jobs/run-now \\\n  -H \"Authorization: Bearer <TOKEN>\" \\\n  -d '{\"job_id\": 123}'\n\n# Com parâmetros customizados\ncurl -X POST https://<workspace-host>/api/2.1/jobs/run-now \\\n  -H \"Authorization: Bearer <TOKEN>\" \\\n  -d '{\"job_id\": 123, \"job_parameters\": {\"date\": \"2025-01-20\", \"environment\": \"staging\"}}'\n```\n\n## Casos de uso\n\n- **Batch agendado por tempo**: rodar ETL noturno às 2h via cron para processar os dados do dia anterior antes que os usuários cheguem, com fuso definido para equipes globais.\n- **Ingestão orientada a eventos via file arrival**: disparar um job automaticamente quando arquivos novos chegam ao cloud storage (S3/ADLS), eliminando atraso de polling e processando os dados assim que ficam disponíveis.\n\n## Problemas e erros comuns\n\n### Execuções vazias por agenda de polling\n\n**Cenário:** um job agendado a cada 5 minutos para \"verificar arquivos do fornecedor\" inicia centenas de execuções por dia, e a maioria não encontra nada.\n**Correção:** substitua a agenda por um **file arrival** trigger na external location ou volume do fornecedor, e use Auto Loader dentro do job.\n\n### Cron roda no horário errado por causa do fuso\n\n**Cenário:** um job agendado para 2h no horário local roda na hora errada porque o fuso não foi definido explicitamente, caindo em UTC.\n**Correção:** sempre defina `timezone_id` na agenda (ex.: `\"timezone_id\": \"America/Sao_Paulo\"`). Documente o fuso na descrição do job.\n\n### Execuções sobrepostas por file arrival\n\n**Cenário:** um file arrival trigger dispara várias vezes seguidas (um lote de arquivos chegando ao mesmo tempo), causando execuções duplicadas ou concorrentes que corrompem tabelas downstream.\n**Correção:** configure **Wait after last change** para que uma rajada de arquivos gere uma única execução, e **Minimum time between triggers** para limitar a frequência. Mantenha `max_concurrent_runs = 1`; o Auto Loader pega na próxima execução os arquivos que chegarem depois.\n\n## Dicas para a prova\n\n- O exam guide cita três triggers: **scheduled**, **file arrival** e **table update**. Saiba qual é por tempo e quais são por dados\n- \"Arquivos chegam em intervalos imprevisíveis, processar logo após chegar, sem compute ocioso, sem execuções vazias\" → **file arrival**\n- \"Rodar quando tabelas upstream de outra equipe mudarem\" → **table update** (escolha *All tables* se toda entrada precisa estar atualizada)\n- Cron Quartz tem **segundos primeiro**. `?` vai no dia do mês ou no dia da semana. Dias úteis às 9h = `0 0 9 ? * MON-FRI`\n- Triggers contínuos não combinam com outros triggers. Agendas têm intervalo mínimo de 10 segundos\n\n## Pontos-chave\n\n- **Scheduled** = por tempo (simples ou cron Quartz com fuso)\n- **File arrival** = arquivos novos em uma external location ou volume do UC. Debounce com *wait after last change*\n- **Table update** = mudanças em até 10 tabelas UC monitoradas, disparando em *qualquer* ou *todas*\n- **Continuous** = sempre ligado. **Manual** = Run now ou API\n- Escolha triggers por dados quando é a disponibilidade dos dados, não o relógio, que decide quando o trabalho deve rodar\n\n## Tópicos relacionados\n\n- [Lakeflow Jobs e Tasks](01-lakeflow-jobs-and-tasks.md)\n- [Monitoramento de Jobs](../06-troubleshooting-monitoring-and-optimization/01-job-monitoring.md)\n\n## Documentação oficial\n\n- [Automate jobs with schedules and triggers](https://docs.databricks.com/aws/en/jobs/triggers)\n- [Run jobs on a schedule](https://docs.databricks.com/aws/en/jobs/scheduled)\n- [Trigger jobs when new files arrive](https://docs.databricks.com/aws/en/jobs/file-arrival-triggers)\n- [Trigger jobs when source tables are updated](https://docs.databricks.com/aws/en/jobs/trigger-table-update)\n\n---\n\n**[← Anterior: Lakeflow Jobs e Tasks](01-lakeflow-jobs-and-tasks.md) | [↑ Voltar para Working with Lakeflow Jobs](README.md) | [Próximo: Control Flow →](03-control-flow.md)**\n"},{"id":"04-working-with-lakeflow-jobs/03-control-flow","folder":"04-working-with-lakeflow-jobs","group":"modulo","order":3,"isIndex":false,"title":"Control Flow em Lakeflow Jobs","md":"# Control Flow em Lakeflow Jobs\n\n## Visão geral\n\nUm DAG de tasks resolve \"rode B depois de A\". Pipelines de produção também precisam de **control flow**: tentar de novo uma task instável, ramificar conforme uma condição, iterar sobre uma lista de entradas e rodar uma limpeza independentemente do que aconteceu antes. O Lakeflow Jobs oferece isso com **retries e timeouts**, a task **If/else condition**, a task **For each**, condições de dependência **Run if** e **task values** para passar dados entre tasks.\n\n> [!abstract] Resumo\n>\n> - **Retries**: política de retry por task, com intervalo entre tentativas. Quando ambos estão definidos, o **timeout vale para cada tentativa**\n> - **If/else condition**: uma expressão booleana sobre dois operandos (job parameters, task values, literais). Tasks downstream dependem do resultado `(true)` ou `(false)`\n> - **For each**: roda **uma task aninhada** para cada elemento de um array de entrada, com **concorrência** configurável (padrão 1)\n> - **Run if**: *All succeeded* (padrão), *At least one succeeded*, *None failed*, *All done*, *At least one failed*, *All failed*\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: implementar control flow (retries e tasks condicionais como ramificação e loop) usando Lakeflow Jobs\n> - Qual status resulta de cada condição Run if (**Upstream failed** vs **Excluded**)\n> - Comparação de string vs numérica nos operadores do If/else\n> - Passar valores entre tasks com `dbutils.jobs.taskValues` e `{{tasks.<task>.values.<chave>}}`\n\n---\n\n## Retries e timeouts\n\n| Configuração | Comportamento |\n| :--- | :--- |\n| **Retries** | Adicione uma política de retry por task. A maioria das configurações não faz retry por padrão. O **retry interval** é em milissegundos, medido do início da execução que falhou até a nova tentativa |\n| **Timeout** | Se uma task roda mais que o timeout, o status vira **Timed Out**. Com retries configurados, \"o timeout vale para cada tentativa\" |\n| **Metric thresholds → Run duration → Warning** | Tempo esperado de conclusão. Excedê-lo gera evento e notificação, mas não para a execução |\n| Jobs serverless / contínuos | Jobs serverless otimizam retries automaticamente. Jobs contínuos usam backoff exponencial |\n\nFonte: [Configure and edit tasks](https://docs.databricks.com/aws/en/jobs/configure-task).\n\n```yaml\ntasks:\n  - task_key: call_vendor_api\n    notebook_task:\n      notebook_path: ../notebooks/call_vendor_api\n    max_retries: 3\n    min_retry_interval_millis: 60000      # espera 1 minuto entre tentativas\n    retry_on_timeout: false\n    timeout_seconds: 1800                 # cada tentativa pode rodar 30 minutos\n```\n\n> [!warning] Erro comum\n> Uma task falha como **Timed Out** aos 45 minutos, mas precisa de ~60 minutos para o volume de dados de hoje. Aumente o **timeout** da task para acima de 60 minutos, com folga. Retries, max concurrent runs e auto termination do cluster não ajudam.\n\n## Task If/else condition\n\nA task If/else adiciona ramificação: \"um operador booleano e um par de operandos\" ([Add branching logic with If/else](https://docs.databricks.com/aws/en/jobs/if-else)).\n\n| Operadores | Comparação |\n| :--- | :--- |\n| `==`, `!=` | Comparação de **string**, então `12.0 == 12` é **falso** |\n| `>`, `>=`, `<`, `<=` | Comparação **numérica**, então `12.0 >= 12` é **verdadeiro** |\n\n- Operandos: literais, `{{job.parameters.<nome>}}`, parâmetros de task e `{{tasks.<task>.values.<chave>}}`. Task values usados como operandos devem ser numéricos, string ou booleanos — booleanos viram `\"true\"` / `\"false\"`\n- Tasks downstream escolhem o ramo no **Depends on**: `<task> (true)` (padrão) ou `<task> (false)`\n- A task If/else falha se a task upstream que fornece o valor da condição estiver desabilitada\n\n```mermaid\nflowchart LR\n    I[ingest<br/>define rows_loaded] --> C{has_new_data<br/>rows_loaded > 0}\n    C -->|true| T[transform] --> G[refresh_gold]\n    C -->|false| N[notify_no_data]\n```\n\n```python\n# No notebook de ingestão: publica um task value\nrows = new_df.count()\ndbutils.jobs.taskValues.set(key=\"rows_loaded\", value=rows)\n```\n\n```yaml\n  - task_key: has_new_data\n    depends_on: [{task_key: ingest}]\n    condition_task:\n      op: GREATER_THAN\n      left: \"{{tasks.ingest.values.rows_loaded}}\"\n      right: \"0\"\n  - task_key: transform\n    depends_on: [{task_key: has_new_data, outcome: \"true\"}]\n    notebook_task: {notebook_path: ../notebooks/transform}\n```\n\n## Task For each (loop)\n\nA task For each \"roda uma task aninhada em loop, passando um conjunto diferente de parâmetros para cada iteração\" ([Use a For each task](https://docs.databricks.com/aws/en/jobs/for-each)).\n\n| Aspecto | Detalhe |\n| :--- | :--- |\n| **Entradas** | Um array JSON digitado (limite de 5.000 caracteres), um job parameter `{{job.parameters.<nome>}}` ou um task value `{{tasks.<task>.values.<chave>}}` |\n| **Task aninhada** | Exatamente uma task de qualquer tipo padrão, **exceto outro For each** |\n| **Concorrência** | Quantas iterações rodam em paralelo. **Padrão 1** |\n| **Valor da iteração** | `{{input}}`, ou `{{input.<chave>}}` ao iterar sobre objetos |\n| **Downstream** | Tasks dependem da task For each, não da aninhada. Task values por iteração voltam como lista ordenada (Beta) |\n\n```yaml\n  - task_key: load_each_table\n    for_each_task:\n      inputs: '[{\"table\": \"orders\"}, {\"table\": \"customers\"}, {\"table\": \"products\"}]'\n      concurrency: 3\n      task:\n        task_key: load_one_table\n        notebook_task:\n          notebook_path: ../notebooks/load_table\n          base_parameters:\n            table_name: \"{{input.table}}\"\n```\n\n## Dependências Run if\n\nA condição **Run if** de cada task decide se ela roda, com base nas tasks upstream ([Configure task dependencies](https://docs.databricks.com/aws/en/jobs/conditional-tasks)).\n\n| Run if | Roda quando | Caso contrário, fica |\n| :--- | :--- | :--- |\n| **All succeeded** *(padrão)* | Todas as dependências rodaram e tiveram sucesso | `Upstream failed` |\n| **At least one succeeded** | Uma ou mais dependências tiveram sucesso | `Upstream failed` |\n| **None failed** | Nenhuma dependência falhou e pelo menos uma rodou | `Upstream failed` |\n| **All done** | Todas as dependências terminaram, **qualquer que seja o resultado** | (sempre roda) |\n| **At least one failed** | Uma ou mais dependências falharam | `Excluded` |\n| **All failed** | Todas as dependências falharam | `Excluded` |\n\n- Upstream `Excluded` conta como sucesso na avaliação das condições. `Upstream failed` e `Upstream canceled` contam como falha\n- Se **todas** as dependências de uma task forem excluídas, ela também é excluída. A exclusão se propaga pela cadeia\n- Use **All done** para tasks de limpeza (apagar tabelas temporárias, liberar locks) e **At least one failed** para tratamento customizado de falhas\n\n## Passando valores entre tasks\n\n```python\n# Task upstream (notebook Python)\ndbutils.jobs.taskValues.set(key=\"max_order_date\", value=\"2026-10-25\")\n\n# Task downstream (notebook Python)\nmax_date = dbutils.jobs.taskValues.get(taskKey=\"ingest\", key=\"max_order_date\", debugValue=\"2026-01-01\")\n```\n\n- Os valores precisam ser serializáveis em JSON, até 48 KiB, e as chaves precisam ser strings\n- A forma recomendada de consumir um valor é por referência em parâmetros ou condições: `{{tasks.ingest.values.max_order_date}}`\n- `debugValue` é usado quando o notebook roda interativamente fora de um job. A Databricks não recomenda definir `default`\n\nFonte: [Use task values to pass information between tasks](https://docs.databricks.com/aws/en/jobs/task-values).\n\n## Task Run Job (orquestração modular)\n\nUma task **Run Job** dispara outro Lakeflow Job como etapa. Times usam isso para reaproveitar um job de ingestão compartilhado em várias orquestrações downstream, em vez de copiar suas tasks.\n\n## Casos de uso\n\n- **Pular trabalho quando não há nada novo**: If/else sobre o task value `rows_loaded` pula as tasks Silver e Gold em dias vazios\n- **Carregar 40 tabelas com uma definição**: For each sobre uma lista de nomes de tabelas, com concorrência 5\n- **Fonte REST instável**: três retries com um minuto de intervalo só na task de extração\n- **Sempre limpar**: uma task final com Run if **All done** apaga tabelas de staging mesmo após falhas\n- **Caminho de falha customizado**: uma task com Run if **At least one failed** abre um ticket de incidente\n\n## Problemas e erros comuns\n\n### Task values lidos na task errada\n\n**Cenário:** `dbutils.jobs.taskValues.get(taskKey=\"ingest\", ...)` falha em uma task que não depende de `ingest`.\n**Correção:** task values são lidos de tasks upstream. Adicione `ingest` ao **Depends on** da task que lê.\n\n### If/else compara números como strings\n\n**Cenário:** a condição `{{tasks.count.values.n}} == 10` é falsa quando `n` é `10.0`.\n**Correção:** `==` e `!=` comparam strings. Use um operador numérico como `>=`, ou publique o valor em formato consistente.\n\n### Task de limpeza nunca roda após uma falha\n\n**Cenário:** uma task de limpeza depende da transformação com o Run if padrão, e é pulada sempre que a transformação falha.\n**Correção:** o padrão é **All succeeded**. Defina o Run if da limpeza como **All done**.\n\n### For each roda uma iteração por vez\n\n**Cenário:** um For each sobre 30 tabelas leva horas.\n**Correção:** a concorrência padrão é 1. Aumente dentro da capacidade do compute.\n\n## Dicas para a prova\n\n- **Ramificação** = task If/else condition. **Loop** = task For each. **Retries** = política de retry da task\n- O timeout vale **por tentativa** quando há retries\n- Run if **All done** = roda de qualquer jeito (limpeza). O padrão **All succeeded** marca a task como `Upstream failed` quando uma dependência falha\n- `==` / `!=` comparam strings. `>`, `<` e afins comparam números\n- Um For each tem **uma** task aninhada, que não pode ser outro For each. Concorrência padrão 1\n\n## Pontos-chave\n\n- Retries e timeouts tratam falhas transitórias e tasks descontroladas\n- If/else direciona o DAG com base em parâmetros ou task values\n- For each repete uma task aninhada sobre um array de entrada, opcionalmente em paralelo\n- Condições Run if permitem rodar tasks no sucesso, na falha ou na conclusão das dependências\n- Task values são a forma nativa de passar resultados pequenos entre tasks\n\n## Tópicos relacionados\n\n- [Lakeflow Jobs e Tasks](01-lakeflow-jobs-and-tasks.md)\n- [Agendamento e Triggers](02-scheduling-triggers.md)\n- [Monitoramento de Jobs (status e histórico)](../06-troubleshooting-monitoring-and-optimization/01-job-monitoring.md)\n\n## Documentação oficial\n\n- [Configure task dependencies](https://docs.databricks.com/aws/en/jobs/conditional-tasks)\n- [Add branching logic with the If/else task](https://docs.databricks.com/aws/en/jobs/if-else)\n- [Use a For each task to run another task in a loop](https://docs.databricks.com/aws/en/jobs/for-each)\n- [Use task values to pass information between tasks](https://docs.databricks.com/aws/en/jobs/task-values)\n- [Configure and edit tasks in Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/configure-task)\n\n---\n\n**[← Anterior: Agendamento e Triggers](02-scheduling-triggers.md) | [↑ Voltar para Working with Lakeflow Jobs](README.md)**\n"},{"id":"04-working-with-lakeflow-jobs/README","folder":"04-working-with-lakeflow-jobs","group":"modulo","order":0,"isIndex":true,"title":"Working with Lakeflow Jobs","md":"# Working with Lakeflow Jobs (16 % da prova)\n\nO Domínio 4 cobre orquestração com **Lakeflow Jobs**. Você configura tipos comuns de task (notebook, SQL query, dashboard, pipeline) e liga suas dependências em um DAG. Adiciona control flow: retries, ramificação If/else e loop For each. E escolhe um trigger: agendado (por tempo), ou file arrival e table update (por dados).\n\n> [!note] Terminologia\n> \"Workflows\" e \"Databricks Jobs\" são nomes legados. O exam guide usa **Lakeflow Jobs** do início ao fim, assim como a documentação atual. Monitoramento de jobs e histórico de execuções foram para o [Domínio 6](../06-troubleshooting-monitoring-and-optimization/README.md) no blueprint de agosto de 2026.\n\n## Visão geral dos tópicos\n\n```mermaid\nflowchart TD\n    J[Lakeflow Jobs] --> Tasks[Tasks e dependências do DAG]\n    J --> CF[Control flow]\n    J --> Trig[Triggers]\n    CF --> Retry[Retries]\n    CF --> IfElse[Task de condição If/else]\n    CF --> ForEach[Task For each]\n    CF --> RunIf[Dependências Run if]\n    Trig --> Sched[Agendado]\n    Trig --> File[File arrival]\n    Trig --> Table[Table update]\n    Trig --> Cont[Contínuo]\n```\n\n## Conteúdo da seção\n\n| Arquivo | Tópico | Prioridade |\n| :--- | :--- | :--- |\n| [01-lakeflow-jobs-and-tasks.md](01-lakeflow-jobs-and-tasks.md) | Jobs vs tasks, tipos de task, parâmetros, dynamic value references, DAGs multi-task, opções de compute | Alta |\n| [02-scheduling-triggers.md](02-scheduling-triggers.md) | Agendado (cron Quartz), file arrival, table update, contínuo; por tempo vs por dados | Alta |\n| [03-control-flow.md](03-control-flow.md) | Retries, timeouts, If/else, For each, dependências Run if, task values | Alta |\n\n## Cobertura das habilidades oficiais (agosto de 2026)\n\n| Habilidade do exam guide (parafraseada) | Onde é coberta |\n| :--- | :--- |\n| Control flow: retries, tasks condicionais (ramificação) e de loop | [03](03-control-flow.md) |\n| Tasks comuns (notebook, SQL query, dashboard, pipeline) e dependências do DAG | [01](01-lakeflow-jobs-and-tasks.md) |\n| Agendas e tipos de trigger (scheduled, file arrival, table update) | [02](02-scheduling-triggers.md) |\n| Escolher trigger por tempo vs por dados | [02](02-scheduling-triggers.md) |\n\n## Conceitos-chave\n\n- **Job vs task**: um job é a unidade de orquestração com um trigger. Tasks são os nós do DAG, e tasks sem dependência entre si rodam em paralelo\n- **Run if**: o padrão é *All succeeded*. *All done* roda tasks de limpeza independentemente do resultado\n- **If/else**: `==` / `!=` comparam como strings; `>`, `>=`, `<`, `<=` comparam como números\n- **For each**: roda uma task aninhada por elemento da entrada. A concorrência padrão é 1\n- **Triggers**: agendado (por tempo) vs file arrival / table update (por dados). Contínuo mantém uma execução sempre ativa\n\n## Próximos passos\n\nContinue para [05 — Implementing CI/CD](../05-implementing-cicd/README.md) para versionar e promover seus jobs com Git folders e Declarative Automation Bundles.\n\n---\n\n**[← Anterior: Data Transformation and Modeling](../03-data-transformation-and-modeling/README.md) | [↑ Voltar à Certificação](../README.md) | [Próximo: Implementing CI/CD →](../05-implementing-cicd/README.md)**\n"},{"id":"05-implementing-cicd/01-git-folders","folder":"05-implementing-cicd","group":"modulo","order":1,"isIndex":false,"title":"Git Folders","md":"# Git Folders\n\n## Visão geral\n\n**Databricks Git folders** (antigo Databricks Repos) são \"um cliente Git visual e uma API que integram repositórios Git ao seu workspace\" ([Databricks Git folders](https://docs.databricks.com/aws/en/repos/)). O exam guide espera que você gerencie todo o ciclo de desenvolvimento pela UI do workspace: clonar, criar e trocar branches, commit e push, pull, e passar para um **pull request** de revisão antes que o CI/CD implante o código.\n\n> [!abstract] Resumo\n>\n> - Crie um Git folder clonando um repositório remoto. Você precisa de credenciais Git configuradas e `CAN MANAGE` na pasta pai\n> - O **diálogo Git** faz criar branch, trocar branch, **Commit & Push** (uma única ação, com mensagem obrigatória), pull, merge, rebase, resolução de conflitos e reset\n> - **Pull requests** são criados na interface do **provedor Git**. Os Git folders cuidam de branches e pushes; o provedor cuida da revisão e do merge na branch padrão\n> - Automatize Git folders com **service principals**, a Repos API ou Terraform. Faça deploy com **Declarative Automation Bundles**\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: gerenciar o fluxo de código na UI do workspace: criar e trocar branches em Git folders (antigo Repos), commit e push, e criar pull requests usando a integração Git da Databricks\n> - Quais operações acontecem na Databricks e quais no provedor Git\n> - O que trocar de branch faz com mudanças não commitadas e com os ativos do workspace\n> - Por que **Pull** é a forma de sincronizar mudanças dos colegas, e o que o **Reset** destrói\n\n---\n\n## O ciclo de desenvolvimento\n\n```mermaid\nsequenceDiagram\n    participant Dev as Engenheiro (UI do workspace)\n    participant GF as Git folder\n    participant GP as Provedor Git (GitHub, GitLab, Azure DevOps, ...)\n    participant CI as Runner de CI/CD\n    Dev->>GF: Cria branch feature/orders-dedup (a partir da main)\n    Dev->>GF: Edita notebooks / YAML do bundle\n    Dev->>GF: Commit & Push (mensagem obrigatória)\n    GF->>GP: Push da branch\n    Dev->>GP: Abre pull request → revisão → merge na main\n    GP->>CI: Evento de merge\n    CI->>CI: databricks bundle validate / deploy -t prod\n```\n\n## Operações Git no workspace\n\nTodas as operações abaixo são feitas pelo **diálogo Git** de um Git folder ([Create and manage Git folders](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)).\n\n| Operação | Como | O que saber |\n| :--- | :--- | :--- |\n| **Clonar / criar** | Workspace → Create → Git folder → URL do repositório | Precisa de credenciais Git e `CAN MANAGE` na pasta pai. O `git clone` no web terminal também funciona |\n| **Criar branch** | Diálogo Git → **Create Branch** → nome + branch base | Crie a partir da branch padrão para trabalho de feature |\n| **Trocar branch** | Dropdown de branch no diálogo Git | Mudanças não commitadas podem ser levadas junto. Trocar \"pode apagar ativos do workspace quando a nova branch não os contém\", e voltar recria esses ativos com **novos IDs e URLs** |\n| **Commit & Push** | Selecione as mudanças, escreva uma mensagem de commit **obrigatória**, clique em **Commit & Push** | Faz commit e push em **uma ação**. Sem permissão na branch padrão, faça push de uma nova branch |\n| **Pull** | **Pull** no diálogo Git | Atualiza notebooks e arquivos para a versão remota e **limpa o estado do notebook**. Conflitos precisam ser resolvidos |\n| **Merge** | Menu (kebab) → **Merge** | Recomendado em vez de rebase para iniciantes em Git. Um merge limpo é enviado ao remoto |\n| **Rebase** | Menu (kebab) → **Rebase** | Termina com commit e **force push**, reescrevendo o histórico para os colaboradores |\n| **Resolver conflitos** | Edite o arquivo, ou **Keep all current** / **Take all incoming**, depois **Mark As Resolved** → **Continue Merge/Rebase** | Ou aborte |\n| **Reset** | UI de Git folders | Equivale a `git reset --hard` + `git push --force`. \"Você perde todas as mudanças, commitadas ou não, na versão local e remota da branch\" |\n| **Pull request** | No **provedor Git** | \"Use a interface do seu provedor Git para criar um pull request e fazer merge na branch padrão\" |\n\n> [!note] Linguagem da prova vs documentação\n> O exam guide fala em \"criar pull requests usando a integração Git da Databricks\". Na documentação atual, o diálogo Git leva você ao provedor Git, onde o pull request é aberto, revisado e mesclado. Espere respostas que combinam **Commit & Push na Databricks** com **revisão e merge do PR no provedor**.\n\n## Estratégia de branches\n\n```text\nmain (protegida, implantada em prod pelo CI)\n├── feature/orders-dedup     ← trabalhe aqui no seu Git folder\n├── feature/new-ingest\n└── hotfix/null-amounts\n```\n\n- Um Git folder por engenheiro por repositório, cada um em sua branch de feature. Evite compartilhar um Git folder entre pessoas\n- Proteja a `main` no provedor Git e exija revisão de PR\n- Jobs de produção **não** devem rodar a partir do Git folder de alguém. O CI implanta um bundle da `main` no workspace de prod, rodando como service principal (veja [Declarative Automation Bundles](02-declarative-automation-bundles.md))\n\n## Git folders vs histórico de versões do notebook\n\n| Necessidade | Histórico de revisões do notebook | Git folder |\n| :--- | :--- | :--- |\n| Desfazer uma edição recente em um notebook | Sim | Sim |\n| Várias branches | Não | **Sim** |\n| Code review via pull requests | Não | **Sim** (no provedor) |\n| Versionar notebooks *e* arquivos, SQL, YAML juntos | Não | **Sim** |\n| Alimentar deploys de CI/CD | Não | **Sim** |\n\n## Automação e CI/CD\n\n- **Service principals** podem ser donos e atualizar Git folders programaticamente\n- **Terraform** pode provisionar Git folders como infraestrutura como código\n- Para deploys, prefira **Declarative Automation Bundles** executados pelo CI a partir da branch mesclada, em vez de apontar jobs de produção para um Git folder\n\n## Casos de uso\n\n- **Desenvolvimento de feature**: um engenheiro cria `feature/orders-dedup`, itera no workspace, faz commit e push e abre um PR\n- **Hotfix**: branch a partir da `main`, corrige, push e PR com prioridade. O CI reimplanta o bundle\n- **Sincronizar o trabalho de um colega**: **Pull** traz as mudanças mescladas para o seu Git folder\n- **Recuperar de um estado local ruim**: **Reset** descarta mudanças locais e remotas da branch (use com cuidado)\n\n## Problemas e erros comuns\n\n### Notebook perdeu o vínculo com o job após trocar de branch\n\n**Cenário:** um notebook que não existe na nova branch some do workspace. Quando o engenheiro volta, um job que apontava para ele falha.\n**Correção:** trocar de branch pode apagar e recriar ativos do workspace com novos IDs e URLs. Rode jobs de produção a partir de bundles implantados, não de um Git folder pessoal.\n\n### Push rejeitado na branch padrão\n\n**Cenário:** Commit & Push na `main` falha com erro de permissão.\n**Correção:** crie uma branch, faça push dela e abra um pull request no provedor Git.\n\n### Pull apaga as variáveis do notebook\n\n**Cenário:** depois de um **Pull**, o estado do notebook (variáveis, DataFrames em cache) sumiu.\n**Correção:** o Pull limpa o estado do notebook por design. Reexecute o notebook.\n\n### Rebase quebra a branch de um colega\n\n**Cenário:** depois de um rebase pela UI, um colaborador não consegue fazer push.\n**Correção:** rebase reescreve o histórico e faz force push. Prefira **Merge** em branches compartilhadas.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - Git folders = o **nome atual** de Repos\n> - **Commit & Push** é uma única ação, com mensagem de commit **obrigatória**\n> - **Pull** sincroniza mudanças remotas no seu Git folder (fetch + merge)\n> - Crie e troque branches na Databricks. Abra, revise e faça merge de **pull requests no provedor Git**\n> - Git folders suportam várias branches. O histórico de versões do notebook não\n\n## Pontos-chave\n\n- Git folders trazem branches, commits, pushes, pulls, merges e resolução de conflitos para a UI do workspace\n- Pull requests e políticas de branch protegida ficam no provedor Git\n- Trocar de branch pode recriar ativos com novos IDs, e o Reset descarta trabalho local e remoto\n- O CI/CD implanta a partir da branch mesclada com bundles, não a partir de Git folders pessoais\n\n## Tópicos relacionados\n\n- [Declarative Automation Bundles](02-declarative-automation-bundles.md)\n- [Databricks Workspace](../01-databricks-intelligence-platform/02-databricks-workspace.md)\n\n## Documentação oficial\n\n- [Databricks Git folders](https://docs.databricks.com/aws/en/repos/)\n- [Create and manage Git folders (Git operations)](https://docs.databricks.com/aws/en/repos/git-operations-with-repos)\n\n---\n\n**[↑ Voltar para Implementing CI/CD](README.md) | [Próximo: Declarative Automation Bundles →](02-declarative-automation-bundles.md)**\n"},{"id":"05-implementing-cicd/02-declarative-automation-bundles","folder":"05-implementing-cicd","group":"modulo","order":2,"isIndex":false,"title":"Declarative Automation Bundles","md":"# Declarative Automation Bundles\n\n## Visão geral\n\n**Declarative Automation Bundles** (antigo **Databricks Asset Bundles**, frequentemente abreviado como **DABs**) descrevem Lakeflow Jobs, Lakeflow (Declarative) Pipelines, dashboards e outros ativos do workspace como YAML junto ao código-fonte. A **Databricks CLI** os valida e implanta. **Targets** (dev, test, prod) com **variables** e **overrides** permitem promover um único código entre ambientes — a espinha dorsal do domínio de CI/CD da prova.\n\n> [!note] Atualização da plataforma (out/2026)\n> \"Databricks Asset Bundles foi renomeado para Declarative Automation Bundles\" (16/03/2026). O grupo de comandos da CLI continua `databricks bundle` e o arquivo raiz continua `databricks.yml`. O exam guide usa o novo nome com \"(antigo Databricks Asset Bundles)\".\n\n> [!abstract] Resumo\n>\n> - Um bundle é o `databricks.yml` (raiz) + YAMLs de recursos incluídos + código-fonte, versionados no Git\n> - **Variables** (`${var.nome}`) são resolvidas no deploy a partir de `--var`, `BUNDLE_VAR_<nome>`, `variable-overrides.json`, valores do target ou o default, **nessa ordem de precedência**\n> - **Targets** sobrescrevem configurações por ambiente. `mode: development` adiciona prefixo aos nomes e pausa triggers. `mode: production` adiciona validações de segurança\n> - CLI: `databricks bundle validate`, `deploy -t <target>`, `run`, `summary`, `plan`, `destroy`\n\n> [!tip] O que a prova cobra\n>\n> - Habilidades do exam guide: configuração por ambiente com variables e overrides em dev, test e prod; deploy de bundles para empacotar e promover jobs, pipelines e outros ativos; usar a Databricks CLI para validar, implantar e gerenciar bundles em CI/CD automatizado\n> - Manter segredos fora do YAML (variáveis de ambiente `BUNDLE_VAR_` alimentadas pelos secrets do CI)\n> - Diferenças entre modo development e production\n> - O que cada comando da CLI faz\n\n---\n\n## Anatomia de um bundle\n\n```text\norders-pipeline/\n├── databricks.yml            # nome do bundle, includes, variables, targets\n├── resources/\n│   ├── orders_job.yml        # definição do Lakeflow Job\n│   └── orders_pipeline.yml   # definição do Lakeflow (Declarative) Pipeline\n├── src/\n│   ├── ingest_orders.py\n│   └── silver_orders.sql\n└── tests/\n```\n\n```yaml\n# databricks.yml\nbundle:\n  name: orders_pipeline\n\ninclude:\n  - resources/*.yml\n\nvariables:\n  catalog:\n    description: Catálogo do Unity Catalog para este ambiente\n    default: dev\n  warehouse_id:\n    description: SQL warehouse usado pelas tasks SQL\n    lookup:\n      warehouse: \"Shared Serverless\"     # resolvido para um ID no deploy\n  db_password:\n    description: Senha do banco de origem (nunca commitada; fornecida pelo CI)\n\ntargets:\n  dev:\n    mode: development\n    default: true\n    workspace:\n      host: https://dev-workspace.cloud.databricks.com\n\n  test:\n    workspace:\n      host: https://test-workspace.cloud.databricks.com\n    variables:\n      catalog: test\n\n  prod:\n    mode: production\n    workspace:\n      host: https://prod-workspace.cloud.databricks.com\n      root_path: /Workspace/Shared/.bundle/${bundle.name}/${bundle.target}\n    variables:\n      catalog: prod\n    run_as:\n      service_principal_name: 6d5c-orders-sp-application-id\n```\n\n```yaml\n# resources/orders_job.yml\nresources:\n  jobs:\n    orders_job:\n      name: orders_job\n      tasks:\n        - task_key: refresh_pipeline\n          pipeline_task:\n            pipeline_id: ${resources.pipelines.orders_pipeline.id}\n        - task_key: publish\n          depends_on: [{task_key: refresh_pipeline}]\n          notebook_task:\n            notebook_path: ../src/ingest_orders.py\n            base_parameters:\n              catalog: ${var.catalog}\n      schedule:\n        quartz_cron_expression: \"0 0 2 * * ?\"\n        timezone_id: UTC\n```\n\n## Variables e overrides\n\nDeclare variáveis em um mapeamento `variables` de nível superior e referencie como `${var.<nome>}` ([Substitutions and variables](https://docs.databricks.com/aws/en/dev-tools/bundles/variables)).\n\n| Fonte do valor | Exemplo | Precedência |\n| :--- | :--- | :---: |\n| Opção `--var` da CLI | `databricks bundle deploy -t prod --var=\"catalog=prod\"` | **1** (maior) |\n| Variável de ambiente `BUNDLE_VAR_<nome>` | `export BUNDLE_VAR_db_password=$DB_PASSWORD` (de secrets do GitHub) | 2 |\n| `.databricks/bundle/<target>/variable-overrides.json` | `{\"catalog\": \"prod\"}` | 3 |\n| `variables` dentro de um **target** | `targets.prod.variables.catalog: prod` | 4 |\n| `default` na declaração de nível superior | `default: dev` | 5 (menor) |\n\n- **`lookup`** resolve o ID de um objeto pelo nome (`cluster`, `job`, `pipeline`, `warehouse`, ...). Dá erro se o nome não corresponder a nenhum objeto ou a mais de um\n- `type: complex` permite valores estruturados, como uma definição inteira de cluster\n- Variables são resolvidas no **deploy**. Use **job parameters** para valores que mudam a cada execução\n- Substituições nativas: `${bundle.name}`, `${bundle.target}` (use esta, não a antiga `${bundle.environment}`), `${workspace.current_user.userName}`, `${resources.jobs.<nome>.id}`\n\n> [!tip] Segredos no CI\n> Nunca escreva senhas no `databricks.yml` ou em notebooks. Declare uma variável sem default e faça o runner de CI exportar `BUNDLE_VAR_<nome>` a partir do seu cofre de segredos, para que o valor nunca toque o Git. Para credenciais em runtime, notebooks podem ler Databricks secrets com `dbutils.secrets.get`.\n\n**Target overrides** não se limitam a variáveis. Qualquer mapeamento de nível superior (host do workspace, `run_as`, permissões ou configurações de recursos como tamanho de cluster ou agenda) pode ser sobrescrito por target, então os mesmos `resources/*.yml` servem todos os ambientes.\n\n## Modos de deploy\n\n| | `mode: development` | `mode: production` |\n| :--- | :--- | :--- |\n| Nomes dos recursos | Prefixo `[dev ${workspace.current_user.short_name}]` e tag `dev` | Inalterados |\n| Agendas e triggers | **Pausados** nos recursos implantados | Ativos |\n| Execuções concorrentes | Habilitadas, para iteração rápida | Conforme configurado |\n| Pipelines | Marcados `development: true` | Validados como `development: false` |\n| Override de cluster | `--cluster-id` / `cluster_id` permitido | **Não permitido** |\n| Branch Git | — | Deve bater com a branch configurada no target (contorne com `--force`) |\n| Identidade | Quem fez o deploy | Service principal recomendado. Validações checam `run_as`, `permissions` e se os caminhos não são específicos de usuário |\n| Lock de deploy | Desabilitado | Habilitado |\n\n**Presets** personalizam o comportamento do target além dos padrões do modo, por exemplo prefixo de nome, status de pausa dos triggers ou concorrência de jobs. Configurações individuais de recursos sobrescrevem presets. Fonte: [Deployment modes](https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes).\n\n## A CLI `databricks bundle`\n\n| Comando | Propósito |\n| :--- | :--- |\n| `databricks bundle init` | \"Inicializa um novo bundle a partir de um template\" |\n| `databricks bundle validate` | \"Valida se os arquivos de configuração do bundle estão sintaticamente corretos\" |\n| `databricks bundle plan` | \"Mostra o plano de deploy para a configuração atual\" |\n| `databricks bundle deploy -t <target>` | \"Implanta um bundle no workspace remoto\" |\n| `databricks bundle run <recurso> -t <target>` | \"Roda um job, pipeline, app ou script\" |\n| `databricks bundle summary` | Resume a identidade do bundle e os recursos implantados, com links para o workspace |\n| `databricks bundle generate` | Gera YAML de bundle para um recurso que já existe no workspace |\n| `databricks bundle deployment bind` / `unbind` | Liga um recurso do bundle a um recurso existente no workspace, ou remove essa ligação |\n| `databricks bundle destroy` | \"Apaga jobs, pipelines, outros recursos e artefatos implantados anteriormente\" |\n\nFlags globais: `-t, --target` escolhe o target, e `--var=\"chave=valor\"` define variáveis. Fonte: [bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands).\n\n## Um pipeline de CI/CD com bundles\n\n```yaml\n# .github/workflows/deploy.yml (esboço, baseado na página de GitHub Actions da documentação)\non:\n  push:\n    branches: [main]\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    env:\n      DATABRICKS_HOST: ${{ secrets.PROD_HOST }}\n      DATABRICKS_CLIENT_ID: ${{ secrets.SP_CLIENT_ID }}          # OAuth de service principal\n      DATABRICKS_CLIENT_SECRET: ${{ secrets.SP_CLIENT_SECRET }}\n      BUNDLE_VAR_db_password: ${{ secrets.DB_PASSWORD }}\n    steps:\n      - uses: actions/checkout@v4\n      - uses: databricks/setup-cli@main\n      - run: databricks bundle validate -t prod\n      - run: databricks bundle deploy -t prod\n      - run: databricks bundle run orders_job -t prod\n```\n\n1. **Branch de feature** → `databricks bundle deploy -t dev` (cópia pessoal, com prefixo e pausada)\n2. **PR mesclado na `main`** → o CI roda `validate`, depois `deploy -t test` e testes de integração\n3. **Release** → o CI roda `deploy -t prod` como **service principal**. O mesmo YAML é usado, com target overrides fornecendo os valores de prod\n\n## Casos de uso\n\n- **Promover um pipeline entre três workspaces** com overrides de `catalog` e `host` por target\n- **Segredos vindos do CI**: `BUNDLE_VAR_db_password` injetado do cofre de segredos do CI no deploy\n- **Adotar jobs existentes**: `bundle generate` transforma um job criado pela UI em YAML, e `deployment bind` faz a ligação\n- **Ingestão do Lakeflow Connect como código**: ingestion pipelines são implantados com bundles como qualquer outro pipeline\n\n## Problemas e erros comuns\n\n### Senha commitada no `databricks.yml`\n\n**Cenário:** um revisor encontra uma senha de banco no default de uma variável do bundle.\n**Correção:** remova o default, troque a senha e forneça-a via `BUNDLE_VAR_<nome>` a partir dos secrets do CI, ou leia em runtime com `dbutils.secrets.get`.\n\n### Deploy de produção rejeitado\n\n**Cenário:** `databricks bundle deploy -t prod` falha na validação.\n**Correção:** o modo production verifica a branch Git, `run_as`/permissões e caminhos específicos de usuário. Faça o deploy a partir da branch configurada, como service principal, com `root_path` compartilhado.\n\n### Agendas do deploy de dev nunca disparam\n\n**Cenário:** um job implantado com `-t dev` nunca roda na agenda.\n**Correção:** o modo development pausa agendas e triggers por design. Rode com `databricks bundle run`, ou despause explicitamente em dev.\n\n### Ambiente errado implantado\n\n**Cenário:** `databricks bundle deploy` sem `-t` implanta em dev quando a intenção era prod.\n**Correção:** sem `-t`, o bundle usa o target marcado com `default: true`. Sempre passe `-t` no CI.\n\n### Valor da variável ignorado\n\n**Cenário:** um target define `catalog: prod`, mas o deploy continua usando `dev`.\n**Correção:** uma fonte de maior precedência está vencendo: uma flag `--var`, uma variável de ambiente `BUNDLE_VAR_catalog` ou o `variable-overrides.json`. Verifique essas primeiro.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - **Declarative Automation Bundles** = o antigo **Databricks Asset Bundles**. Mesma CLI (`databricks bundle`), mesmo `databricks.yml`\n> - Segredos → variáveis de ambiente `BUNDLE_VAR_<nome>` (ou `--var`), nunca YAML commitado\n> - Precedência de variáveis: `--var` > `BUNDLE_VAR_` > `variable-overrides.json` > `variables` do target > `default`\n> - `mode: development` adiciona prefixo aos nomes e **pausa** agendas. `mode: production` valida branch, identidade e caminhos\n> - `validate` checa a config, `deploy -t` implanta, `run` executa um job ou pipeline, `destroy` remove os recursos implantados\n\n## Pontos-chave\n\n- Bundles tornam jobs, pipelines e outros ativos versionados, revisáveis e repetíveis\n- Targets mais variables e overrides promovem um código de dev para test e prod\n- Deploys de produção rodam como service principal, a partir do CI, na branch de release\n- A Databricks CLI (`databricks bundle ...`) é a interface de automação\n\n## Tópicos relacionados\n\n- [Git Folders](01-git-folders.md)\n- [Lakeflow Jobs e Tasks](../04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks.md)\n\n## Documentação oficial\n\n- [Declarative Automation Bundles](https://docs.databricks.com/aws/en/dev-tools/bundles/)\n- [Substitutions and variables](https://docs.databricks.com/aws/en/dev-tools/bundles/variables)\n- [Deployment modes](https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes)\n- [bundle command group](https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands)\n- [Bundles release notes](https://docs.databricks.com/aws/en/release-notes/dev-tools/bundles)\n- [GitHub Actions for Databricks (Public Preview)](https://docs.databricks.com/aws/en/dev-tools/ci-cd/github)\n\n---\n\n**[← Anterior: Git Folders](01-git-folders.md) | [↑ Voltar para Implementing CI/CD](README.md)**\n"},{"id":"05-implementing-cicd/README","folder":"05-implementing-cicd","group":"modulo","order":0,"isIndex":true,"title":"Implementing CI/CD","md":"# Implementing CI/CD (10 % da prova)\n\nO Domínio 5 cobre o caminho do código até a produção. Você gerencia branches, commits, pushes e pull requests em **Databricks Git folders (antigo Databricks Repos)**. Empacota jobs, pipelines e outros ativos do workspace como **Declarative Automation Bundles (antigo Databricks Asset Bundles)** e usa **variables** e **target overrides** do bundle para promover um único código entre dev, test e prod. Tudo isso é conduzido pela **Databricks CLI** em pipelines automatizados.\n\n> [!note] Atualização da plataforma (out/2026)\n> A renomeação \"Databricks Asset Bundles agora é Declarative Automation Bundles\" foi anunciada em 16/03/2026. O grupo de comandos da CLI continua `databricks bundle`, e o arquivo de configuração continua `databricks.yml`. Os enunciados podem abreviar o produto como **DABs**.\n\n## Visão geral dos tópicos\n\n```mermaid\nflowchart LR\n    Dev[Desenvolvedor] --> GF[Git folder<br/>branch, commit & push]\n    GF --> PR[Pull request<br/>no provedor Git]\n    PR --> CI[Runner de CI<br/>databricks bundle validate]\n    CI --> D1[deploy -t dev]\n    D1 --> D2[deploy -t test]\n    D2 --> D3[deploy -t prod<br/>run_as service principal]\n```\n\n## Conteúdo da seção\n\n| Arquivo | Tópico | Prioridade |\n| :--- | :--- | :--- |\n| [01-git-folders.md](01-git-folders.md) | Criar/clonar, branch, trocar, commit & push, pull, merge, conflitos, pull requests | Alta |\n| [02-declarative-automation-bundles.md](02-declarative-automation-bundles.md) | Anatomia do bundle, variables, target overrides, modos de deploy, CLI `databricks bundle` | Alta |\n\n## Cobertura das habilidades oficiais (agosto de 2026)\n\n| Habilidade do exam guide (parafraseada) | Onde é coberta |\n| :--- | :--- |\n| Fluxo de código na UI do workspace: branches em Git folders, commit & push, pull requests | [01](01-git-folders.md) |\n| Configuração por ambiente com variables e overrides do bundle entre targets dev/test/prod | [02](02-declarative-automation-bundles.md) |\n| Deploy de bundles para empacotar e promover Lakeflow Jobs, pipelines e outros ativos | [02](02-declarative-automation-bundles.md) |\n| Databricks CLI para validar, implantar e gerenciar bundles em CI/CD automatizado | [02](02-declarative-automation-bundles.md) |\n\n## Conceitos-chave\n\n| Conceito | Por que importa |\n| :--- | :--- |\n| **Git folders** | Cliente Git visual no workspace (antigo Repos). Branch, commit & push, pull, merge e rebase pela UI |\n| **Pull requests** | Criados na interface do seu provedor Git. O diálogo Git leva até o provedor |\n| **`databricks.yml`** | Raiz do bundle: `bundle`, `include`, `variables`, `resources`, `targets` |\n| **Variables** | `${var.nome}`. Os valores vêm de `--var`, `BUNDLE_VAR_<nome>`, `variable-overrides.json`, `variables` do target ou `default`, nessa ordem de precedência |\n| **`mode: development` vs `mode: production`** | Dev adiciona prefixo aos nomes e pausa triggers. Prod valida branch Git, `run_as` e caminhos |\n| **CLI** | `databricks bundle validate`, `deploy -t <target>`, `run`, `summary`, `destroy` |\n\n## Próximos passos\n\nContinue para [06 — Troubleshooting, Monitoring, and Optimization](../06-troubleshooting-monitoring-and-optimization/README.md).\n\n---\n\n**[← Anterior: Working with Lakeflow Jobs](../04-working-with-lakeflow-jobs/README.md) | [↑ Voltar à Certificação](../README.md) | [Próximo: Troubleshooting, Monitoring, and Optimization →](../06-troubleshooting-monitoring-and-optimization/README.md)**\n"},{"id":"06-troubleshooting-monitoring-and-optimization/01-job-monitoring","folder":"06-troubleshooting-monitoring-and-optimization","group":"modulo","order":1,"isIndex":false,"title":"Monitoramento de Jobs","md":"# Monitoramento de Jobs\n\n## Visão geral\n\nMonitorar Lakeflow Jobs é saber onde olhar: a lista **Jobs & Pipelines**, a aba **Runs** de um job (matrix view do histórico) e as visões **Graph / Timeline / List** de uma execução. Você também precisa ler corretamente os status de execução e de task, e ser alertado quando algo quebra.\n\n> [!abstract] Resumo\n>\n> - A **matrix view** mostra o histórico de um job: uma barra por execução, altura = duração, cor = status. É assim que você encontra execuções mais lentas que a linha de base\n> - Status de execução: Queued, Pending, Running, Skipped, Succeeded, **Succeeded with failures**, Failed, Timed Out, Canceling, Canceled. O resultado é decidido pelas **leaf tasks**\n> - Estados de task incluem **Upstream failed** (uma dependência falhou) e **Excluded** (uma condição de ramo ou Run if não foi atendida)\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: identificar tendências de performance usando o histórico de execuções dos Lakeflow Jobs para comparar tempos atuais com a linha de base histórica\n> - Habilidade do exam guide: usar a UI de Lakeflow Jobs para monitorar a saúde do pipeline: interpretar status, usar o grafo do DAG para encontrar bloqueios upstream e acompanhar tempos e taxas de falha\n> - Corrigir uma task **Timed Out** aumentando o timeout, e alertar com notificações\n\n---\n\n## Onde olhar na UI de Jobs\n\n| Visão | O que mostra | Use para |\n| :--- | :--- | :--- |\n| Lista **Jobs & Pipelines** | Todos os jobs e pipelines que você acessa, com criador, trigger e as **últimas cinco execuções** | Ver de relance quais jobs estão falhando |\n| Aba **Runs** (do workspace) | Execuções de jobs e pipelines dos últimos 60 dias, gráfico *Finished runs count* (48 h) e *Top 5 error types* | Acompanhar taxas de falha e erros comuns |\n| **Job → Runs → matrix view** | Uma coluna por execução, com uma linha **Run total duration** e uma linha por task. **Altura = duração**, cor = status | **Comparar durações atuais com a linha de base histórica** e ver qual task ficou mais lenta |\n| **Detalhes da execução → Graph** | O DAG, com o status de cada task | Encontrar o **bloqueio upstream** que falhou ou foi pulado |\n| **Detalhes da execução → Timeline** | Durações, dependências e sobreposição das tasks | Encontrar o caminho crítico da execução |\n| **Detalhes da execução → List** | Lista de tasks pesquisável e ordenável | Filtrar por status ou duração |\n\nCores da matrix view: **verde** = sucesso, **vermelho** = sem sucesso, **rosa** = pulado, **amarelo** = aguardando retry, **cinza** = pendente, cancelado ou timed out. Um aviso aparece quando uma execução excede o tempo esperado (limite de **run duration warning**). Fonte: [Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor).\n\n```mermaid\nflowchart LR\n    A[Alerta de duração ou<br/>reclamação de usuário] --> B[Job → Runs → matrix view<br/>compare a altura das barras]\n    B --> C[Qual linha de task cresceu?]\n    C --> D[Detalhes → Timeline / Graph]\n    D --> E[Task → Spark UI<br/>métricas de stage]\n```\n\nO histórico de execuções é mantido por **60 dias**. Para tendências mais longas, consulte as tabelas de jobs em `system.lakeflow` (veja [Spark UI e System Tables](02-spark-ui-and-system-tables.md)) ou junte com `system.billing.usage` para custo.\n\n## Status de execução e de task\n\n**Status de execução** (da documentação): `Queued`, `Pending`, `Running`, `Skipped`, `Succeeded`, `Succeeded with failures`, `Failed`, `Timed Out`, `Canceling`, `Canceled`.\n\n| Status | Significado | Ação típica |\n| :--- | :--- | :--- |\n| **Queued** | Aguardando porque um limite de concorrência foi atingido e o enfileiramento está ligado | Verifique max concurrent runs |\n| **Pending** | Preparando para rodar, ex.: enquanto o compute inicia | Verifique a inicialização do compute se demorar |\n| **Skipped** | Não iniciou, ex.: porque max concurrent runs já tinha sido atingido | A execução anterior ainda está ativa. Ajuste agenda ou concorrência |\n| **Succeeded with failures** | Algumas tasks falharam, mas **todas as leaf tasks** tiveram sucesso | Inspecione as tasks não-leaf que falharam |\n| **Failed** | Uma leaf task falhou | Abra a saída e os logs da task que falhou |\n| **Timed Out** | Uma task excedeu o **timeout** configurado | Aumente o timeout (cada retry tem o timeout inteiro) ou acelere a task |\n| **Canceled** | Parado por usuário, API ou propagação de cancelamento | — |\n\n**Estados de task** para reconhecer na visão Graph:\n\n| Estado da task | Causa |\n| :--- | :--- |\n| **Upstream failed** | Uma dependência falhou e o Run if da task (padrão *All succeeded*) não foi atendido. O problema real está **upstream** |\n| **Excluded** | Uma condição Run if como *At least one failed* não foi atendida, ou um ramo If/else não foi seguido |\n| **Waiting for retry** | A task falhou e um retry está agendado |\n| **Disabled** | A task foi desabilitada na definição do job e pulada |\n\nO resultado geral de uma execução depende das **leaf tasks** (tasks sem dependentes downstream).\n\n### Encontrando o bloqueio upstream\n\n1. Abra a execução que falhou → visão **Graph**\n2. Tasks marcadas **Upstream failed** não são a causa. Siga as arestas para cima até a primeira task **Failed** ou **Timed Out**\n3. Abra a saída e os logs dessa task e, se precisar, sua **Spark UI**\n4. Corrija e use **Repair run** para reexecutar só a task que falhou e suas dependentes\n\n## Logs e debugging\n\n- **Pela UI**: Jobs & Pipelines → job → execução → task → saída da task e logs (driver logs)\n- **Driver logs**: inicialização, parâmetros e a maioria das exceções Python/SQL — o primeiro lugar a olhar\n- **Logs dos workers/executores**: específicos das tasks Spark; úteis para OOM em executores\n- `print()` e o módulo `logging` do Python aparecem na saída da task\n\n```python\nimport logging\nlogger = logging.getLogger(__name__)\nlogger.info(\"Processamento iniciado\")\nlogger.warning(\"Encontradas linhas duplicadas\")\nlogger.error(\"Falha ao conectar no banco\")\n```\n\n```sql\n-- Consultas mais lentas do último dia (SQL warehouses)\nSELECT statement_id, statement_text, total_duration_ms, produced_rows\nFROM system.query.history\nWHERE start_time > current_timestamp() - INTERVAL 1 DAY\nORDER BY total_duration_ms DESC\nLIMIT 10;\n```\n\n### Validação no próprio notebook\n\n```python\nrows_in = spark.table(\"main.bronze.orders\").count()\nrows_out = spark.table(\"main.silver.orders\").count()\n\nif rows_out == 0:\n    raise ValueError(\"Tabela de saída vazia!\")       # falha a task → aciona alertas\nif rows_out > rows_in * 2:\n    raise ValueError(\"Contagem de saída suspeitamente alta!\")\n```\n\n## Alertas e notificações\n\n```json\n{\n  \"email_notifications\": {\n    \"on_start\": [],\n    \"on_success\": [\"user@company.com\"],\n    \"on_failure\": [\"user@company.com\", \"ops@company.com\"],\n    \"on_duration_warning_threshold_exceeded\": [\"ops@company.com\"]\n  },\n  \"webhook_notifications\": {\n    \"on_failure\": [{\"id\": \"slack-notification-destination-id\"}]\n  },\n  \"health\": {\n    \"rules\": [{\"metric\": \"RUN_DURATION_SECONDS\", \"op\": \"GREATER_THAN\", \"value\": 3600}]\n  }\n}\n```\n\n- Notificações podem ir para email ou para **notification destinations** (Slack, Microsoft Teams, PagerDuty, webhooks) configurados pelo admin\n- Eventos: início, sucesso, falha, duração acima do limite e backlog de streaming\n- Você pode notificar **por task** ou **por job**, e silenciar notificações de execuções puladas/canceladas ou de retries intermediários\n\n## Métricas de performance\n\nDurante a execução, acompanhe:\n\n- **CPU/memória do driver e dos workers** (aba Metrics do compute)\n- **Shuffle read/write**: custo de movimentação de dados\n- **GC time**: pausas de garbage collection\n- **Duração por task** na matrix view\n\nPara tendências de longo prazo, as system tables `system.lakeflow.jobs`, `system.lakeflow.job_run_timeline` e `system.lakeflow.job_task_run_timeline` guardam o histórico além dos 60 dias da UI.\n\n## Troubleshooting de problemas comuns\n\n| Problema | Causas | Soluções |\n| :--- | :--- | :--- |\n| **Timeout** (`Timed Out`) | Consulta longa, compute pequeno, código ineficiente, volume de dados cresceu | Aumente `timeout_seconds`; otimize a consulta (filtros cedo, Liquid Clustering); aumente o compute |\n| **Out of memory** | DataFrame grande no driver (`collect`), partições enormes, skew | Evite `collect`/`toPandas`; mais shuffle partitions; workers maiores; trate o skew |\n| **Execução Skipped** | Execução anterior ainda rodando com `max_concurrent_runs: 1` | Acelere o job, ajuste a agenda, ou aumente a concorrência se for seguro |\n| **Falha ao iniciar o cluster** | Quota excedida, tipo de instância indisponível, problemas de rede/subnet | Verifique quotas, troque o tipo de nó, revise VPC/subnet; veja [Compute Troubleshooting](05-compute-troubleshooting.md) |\n| **Dados errados com sucesso** | Falta de validação, processamento duplicado | Adicione verificações de qualidade, registre contagens por etapa, use expectations |\n\n## Casos de uso\n\n- **Dashboards proativos de saúde do pipeline**: consultar as system tables `system.lakeflow.*` em um dashboard do Databricks SQL para acompanhar tendências de duração, aderência a SLA e taxas de falha.\n- **Alertas e escalonamento automáticos**: notificações por email e Slack em falhas de jobs, com escalonamento (dono da task na primeira falha, plantão após esgotar os retries).\n\n## Problemas e erros comuns\n\n### Task continua dando timeout conforme os dados crescem\n\n**Cenário:** uma task falha como **Timed Out** após 45 minutos. O volume cresceu e a task agora precisa de ~60 minutos.\n**Correção:** aumente o **timeout** da task (ex.: para 90 minutos). Retries, max concurrent runs e auto termination não impedem o timeout de encerrar a task.\n\n### Spark UI não carrega para execuções concluídas\n\n**Cenário:** depois que o job cluster encerra, a Spark UI da execução fica inacessível, dificultando investigar performance de uma execução passada.\n**Correção:** acesse a Spark UI enquanto o cluster ainda roda, ou consulte system tables para métricas históricas. Considere registrar contadores-chave (contagens, durações) no próprio notebook.\n\n### Fadiga de alertas por notificações de falha ruidosas\n\n**Cenário:** erros transitórios (preempção de spot, falhas rápidas de rede) disparam alertas a cada tentativa, inundando o plantão com notificações não acionáveis.\n**Correção:** configure retries na task (`max_retries: 2-3`) e notificações apenas na falha final, após esgotar os retries, não a cada tentativa.\n\n## Dicas para a prova\n\n- **Tendências ao longo do tempo** → a **matrix view** do job (altura da barra = duração por execução) ou tabelas `system.lakeflow` além de 60 dias\n- **Bloqueios upstream** → visão **Graph** da execução. Tasks `Upstream failed` apontam de volta para a falha real\n- **Succeeded with failures** = todas as leaf tasks tiveram sucesso, mas alguma outra task falhou\n- **Timed Out** → aumente o **timeout** da task. O **warning** de duração só alerta\n- Execuções **Skipped** geralmente significam que max concurrent runs já tinha sido atingido\n- **Repair run** reexecuta as tasks que falharam e suas dependentes, não o DAG inteiro\n\n## Pontos-chave\n\n- Lista Jobs & Pipelines → aba Runs do job (matrix view) → detalhes da execução (Graph, Timeline, List) → task → Spark UI\n- O resultado da execução é decidido pelas leaf tasks. Saiba a diferença entre Upstream failed e Excluded\n- Notificações (email, webhooks) disparam em início, sucesso, falha e limites de duração\n- O histórico é mantido por 60 dias. Use system tables para análises mais longas\n\n## Tópicos relacionados\n\n- [Lakeflow Jobs e Tasks](../04-working-with-lakeflow-jobs/01-lakeflow-jobs-and-tasks.md)\n- [Control Flow](../04-working-with-lakeflow-jobs/03-control-flow.md)\n- [Spark UI e System Tables](02-spark-ui-and-system-tables.md)\n\n## Documentação oficial\n\n- [Monitor Lakeflow Jobs](https://docs.databricks.com/aws/en/jobs/monitor)\n- [Diagnose Lakeflow Jobs performance](https://docs.databricks.com/aws/en/jobs/diagnose-job-performance)\n- [Add notifications on a job](https://docs.databricks.com/aws/en/jobs/notifications)\n- [Repair a failed job run](https://docs.databricks.com/aws/en/jobs/repair-job-failures)\n\n---\n\n**[↑ Voltar para Troubleshooting, Monitoring, and Optimization](README.md) | [Próximo: Spark UI e System Tables →](02-spark-ui-and-system-tables.md)**\n"},{"id":"06-troubleshooting-monitoring-and-optimization/02-spark-ui-and-system-tables","folder":"06-troubleshooting-monitoring-and-optimization","group":"modulo","order":2,"isIndex":false,"title":"Spark UI e System Tables","md":"# Spark UI e System Tables\n\n## Visão geral\n\nQuando o histórico de execuções de um job mostra uma regressão, a **Spark UI** explica *por quê*. Suas métricas por stage revelam os três gargalos que o exam guide cita: **data skew**, **shuffle** e **disk spill**. As **system tables** adicionam um histórico consultável em SQL de execuções de jobs, eventos de auditoria, linhagem e cobrança, para tendências que uma única execução não mostra.\n\n> [!abstract] Resumo\n>\n> - Comece pela aba **Stages**: ordene por duração, abra o stage mais lento e leia as **Summary Metrics** (Min / 25º / Mediana / 75º / Max) de duração das tasks, shuffle read e spill\n> - **Skew**: \"Se a duração Max excede o percentil 75 em 50 % ou mais, o stage pode ter skew\"\n> - **Spill**: a memória de execução acabou e os dados foram gravados em disco. As estatísticas de spill aparecem nos detalhes do stage\n> - O **AQE** divide partições com skew só em **sort-merge e shuffle-hash joins**. **Agregações** com skew precisam de **salting**\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: identificar gargalos comuns como data skew, shuffle e disk spill interpretando métricas de stage na Spark UI\n> - Escolher a correção que bate com o sintoma: salting, broadcast, número de partições, memória ou Liquid Clustering\n> - Por que adicionar executores não resolve uma task com skew, e por que menos shuffle partitions piora o skew\n> - Qual system table responde \"quais jobs falharam?\", \"quem leu esta tabela?\" ou \"quanto isso custou?\"\n\n---\n\n## Lendo a Spark UI\n\n| Aba | Use para |\n| :--- | :--- |\n| **Jobs** | Cada job Spark disparado por uma ação, e seus stages |\n| **Stages** | **Comece aqui.** Duração por stage. Clique para ver Summary Metrics e detalhes por task |\n| **SQL / DataFrame** | O plano físico: `Exchange` (shuffle), `BroadcastHashJoin` vs `SortMergeJoin` e replanejamentos do AQE |\n| **Storage** | DataFrames em cache e seu uso de memória ou disco |\n| **Executors** | Tempo de GC, memória e tasks com falha por executor |\n| **Environment** | Configuração Spark efetiva |\n\nUm fluxo de investigação:\n\n1. Encontre o **stage** mais lento (ordene por Duration)\n2. Leia suas **Summary Metrics**: compare o **Max** com o **percentil 75 / Mediana** para duração e tamanho do shuffle read\n3. Verifique o **spill (memory) / spill (disk)** e o **Peak Execution Memory** do stage\n4. Abra a aba **SQL / DataFrame** para ver qual operador (join, agregação, sort) gerou o stage\n\n## Os três gargalos\n\n| Sintoma nas métricas do stage | Diagnóstico | Correções |\n| :--- | :--- | :--- |\n| A maioria das tasks termina rápido, mas uma ou poucas demoram muito mais. Shuffle read Max muito maior que a mediana | **Data skew**: uma chave \"quente\" coloca dados demais em uma partição | Joins: confirme o tratamento de skew do AQE (ou ajuste os limites). **Agregações: faça salting da chave** e agregue em duas etapas. Skew em tabela armazenada: **Liquid Clustering**. Na escrita: hint `REBALANCE` |\n| Grande **Shuffle Read/Write** em um stage de join, com `Exchange` antes de um `SortMergeJoin` | **Shuffle caro** | Faça broadcast do lado pequeno. Filtre e selecione colunas antes do join. Evite `repartition` desnecessário |\n| **Spill (disk)** > 0, Peak Execution Memory alto, tasks lentas | **Disk spill**: faltou memória de execução durante shuffle, join, sort ou agregação | `spark.sql.shuffle.partitions=auto` (ou mais partições). Reduza linhas e colunas largas em memória. Mais memória por executor (menos workers, maiores, para ETL pesado) |\n| Nem skew nem spill, mas lento | Provavelmente **limitado por I/O** | Verifique tamanho e layout dos arquivos (`OPTIMIZE`, Liquid Clustering) e predicate pushdown |\n\nFonte: [Skew and spill](https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/long-spark-stage-page), [Adaptive query execution](https://docs.databricks.com/aws/en/optimizations/aqe).\n\n### Skew em agregação: salting\n\nO AQE \"divide e, se necessário, replica partições com skew em sort merge joins e shuffle hash joins\", e nunca em broadcast joins. Ele **não** resolve um `groupBy` com skew. Espalhe a chave quente entre tasks com um salt e depois combine os resultados parciais:\n\n```python\nfrom pyspark.sql import functions as F\n\nSALT_BUCKETS = 16\n\n# Etapa 1: agrega por (customer_id, salt). O cliente \"quente\" agora fica dividido em 16 tasks\npartial = (spark.table(\"main.silver.events\")\n    .withColumn(\"salt\", (F.rand() * SALT_BUCKETS).cast(\"int\"))\n    .groupBy(\"customer_id\", \"salt\")\n    .agg(F.count(\"*\").alias(\"cnt\"), F.sum(\"amount\").alias(\"amt\")))\n\n# Etapa 2: combina os agregados parciais por customer_id\nresult = (partial\n    .groupBy(\"customer_id\")\n    .agg(F.sum(\"cnt\").alias(\"events\"), F.sum(\"amt\").alias(\"amount\")))\n```\n\n> [!warning] Erros comuns com skew\n>\n> - **Adicionar executores** não ajuda: a partição gigante continua sendo processada por uma única task\n> - **Diminuir `spark.sql.shuffle.partitions`** deixa as partições maiores, piorando skew e spill\n> - **\"O AQE está ligado, então o skew está resolvido\"** só é verdade para **joins** sort-merge e shuffle-hash\n\n### Shuffle: broadcast do lado pequeno\n\n```sql\n-- Antes: Exchange + SortMergeJoin nos dois lados\n-- Depois: a dimensão de 20 MB vai para cada executor; o lado grande não sofre shuffle\nSELECT /*+ BROADCAST(d) */ f.*, d.region\nFROM main.silver.sales f JOIN main.silver.stores d ON f.store_id = d.store_id;\n```\n\nVeja [Parâmetros de tuning do Spark](../03-data-transformation-and-modeling/07-spark-tuning-parameters.md) para `spark.sql.autoBroadcastJoinThreshold` e o limite de broadcast em runtime do AQE.\n\n## System tables que você deve conhecer\n\n| Tabela | Contém |\n| :--- | :--- |\n| `system.lakeflow.jobs` | Definições de jobs |\n| `system.lakeflow.job_run_timeline` | Execuções de jobs: início, fim, resultado |\n| `system.lakeflow.job_task_run_timeline` | Execuções de tasks dentro das execuções de jobs |\n| `system.access.audit` | Eventos de auditoria: quem fez o quê, e quando |\n| `system.access.table_lineage` | Linhagem de leitura/escrita entre tabelas |\n| `system.billing.usage` | Uso cobrável (DBUs) por workspace, SKU, job, warehouse e mais |\n| `system.storage.predictive_optimization_operations_history` | Execuções de `OPTIMIZE` / `VACUUM` / `ANALYZE` pelo predictive optimization |\n\n\"System tables não suportam monitoramento em tempo real\", e a atualidade varia por tabela ([System tables](https://docs.databricks.com/aws/en/admin/system-tables/)).\n\n```sql\n-- Taxa de falha por job nos últimos 7 dias\nSELECT job_id,\n       COUNT(*) AS runs,\n       COUNT_IF(result_state = 'FAILED') AS failed,\n       ROUND(100 * COUNT_IF(result_state = 'FAILED') / COUNT(*), 1) AS failure_pct\nFROM system.lakeflow.job_run_timeline\nWHERE period_start_time >= current_timestamp() - INTERVAL 7 DAYS\nGROUP BY job_id\nORDER BY failure_pct DESC;\n```\n\n> [!note] Observação\n> Nomes de colunas nas system tables evoluem. Confira a [referência das system tables de jobs](https://docs.databricks.com/aws/en/admin/system-tables/jobs) antes de construir dashboards.\n\n## Notificações e repair runs\n\n- **Notificações**: email e destinos do sistema (ex.: Slack ou webhook) no início, sucesso, falha e avisos de duração, configuradas por job ou por task\n- **Repair run**: reexecuta só as tasks que falharam de uma execução multi-task e suas dependentes, reaproveitando os resultados upstream bem-sucedidos. É mais barato que **Run now**, que reexecuta o DAG inteiro\n\n## Casos de uso\n\n- **Agregação de clientes com skew**: um stage `groupBy(\"customer_id\")` tem uma task de 10 minutos entre tasks de 30 segundos. O salting reduz para minutos\n- **Join com spill**: o disk spill em um join de 2 TB some com shuffle partitions `auto` e workers maiores\n- **Join de dimensão com muito shuffle**: um hint de broadcast remove o `Exchange` da tabela fato\n- **Relatório semanal de confiabilidade**: um dashboard sobre `system.lakeflow.job_run_timeline` acompanha a taxa de falha por job\n\n## Problemas e erros comuns\n\n### Escalar não resolve uma task retardatária\n\n**Cenário:** depois de dobrar os workers, o stage mais lento ainda tem uma task rodando por 10 minutos.\n**Correção:** é skew. Faça salting na chave da agregação, ou, para joins, confie no tratamento de skew do AQE (ou ajuste-o). Mais executores não dividem uma partição.\n\n### Spark UI sumiu depois que o job cluster encerrou\n\n**Cenário:** engenheiros querem inspecionar os stages de uma execução passada, mas o job cluster não existe mais.\n**Correção:** abra a Spark UI a partir dos detalhes da execução da task. Compute reiniciado mostra só a Spark UI mais recente, então registre métricas-chave ou configure entrega de logs para análise posterior.\n\n### Esperar dados em tempo real das system tables\n\n**Cenário:** um alerta construído sobre `system.lakeflow.job_run_timeline` dispara atrasado.\n**Correção:** system tables não suportam monitoramento em tempo real. Use notificações de job para alertas imediatos e system tables para tendências.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - Duração Max ou shuffle read muito acima da mediana ou do percentil 75 = **skew**\n> - **groupBy** com skew e AQE já ligado → **salting da chave** (agregação em duas etapas)\n> - **Join** com skew → tratamento de skew join do AQE (sort-merge ou shuffle-hash), ou salting\n> - **Spill** → mais (ou `auto`) shuffle partitions, menos dados por task ou mais memória no executor\n> - **Shuffle** grande com dimensão pequena → **broadcast**\n> - System tables são para tendências e auditoria, não para alertas em tempo real\n\n## Pontos-chave\n\n- As Summary Metrics do stage são a evidência para skew, shuffle e spill\n- O AQE ajuda em joins e no agrupamento de partições. Skew em agregação precisa de salting\n- Faça broadcast de tabelas pequenas para evitar shuffles, e dimensione partições para evitar spill\n- `system.lakeflow.*`, `system.access.*` e `system.billing.usage` cobrem execuções, auditoria, linhagem e custo\n\n## Tópicos relacionados\n\n- [Monitoramento de Jobs](01-job-monitoring.md)\n- [Parâmetros de tuning do Spark](../03-data-transformation-and-modeling/07-spark-tuning-parameters.md)\n- [Liquid Clustering e Predictive Optimization](04-liquid-clustering-and-predictive-optimization.md)\n\n## Documentação oficial\n\n- [Skew and spill](https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/long-spark-stage-page)\n- [Adaptive query execution](https://docs.databricks.com/aws/en/optimizations/aqe)\n- [System tables](https://docs.databricks.com/aws/en/admin/system-tables/)\n- [Add notifications on a job](https://docs.databricks.com/aws/en/jobs/notifications)\n- [Repair a failed job run](https://docs.databricks.com/aws/en/jobs/repair-job-failures)\n\n---\n\n**[← Anterior: Monitoramento de Jobs](01-job-monitoring.md) | [↑ Voltar para Troubleshooting, Monitoring, and Optimization](README.md) | [Próximo: Otimização do Delta Lake →](03-delta-optimization.md)**\n"},{"id":"06-troubleshooting-monitoring-and-optimization/03-delta-optimization","folder":"06-troubleshooting-monitoring-and-optimization","group":"modulo","order":3,"isIndex":false,"title":"Otimização do Delta Lake","md":"# Otimização do Delta Lake\n\n## Visão geral\n\nA otimização do Delta Lake mantém as tabelas performáticas conforme crescem. As operações-chave são compactar arquivos pequenos, remover arquivos antigos, organizar os dados para consultas mais rápidas e coletar estatísticas para o otimizador.\n\n> [!abstract] Resumo\n>\n> - `OPTIMIZE` compacta arquivos pequenos. `ZORDER BY` co-localiza valores para data skipping em tabelas particionadas ou sem clustering\n> - `VACUUM` remove arquivos de dados não referenciados pelo log após o período de retenção (7 dias por padrão), e limita o time travel\n> - Para tabelas novas, a Databricks recomenda **Liquid Clustering** em vez de particionamento + Z-order. Veja [Liquid Clustering e Predictive Optimization](04-liquid-clustering-and-predictive-optimization.md)\n\n> [!tip] O que a prova cobra\n>\n> - Apoia as habilidades de otimização do Domínio 6 (Liquid Clustering e predictive optimization se baseiam nesses comandos)\n> - `OPTIMIZE` vs `VACUUM`: compactação vs exclusão de arquivos\n> - Por que `VACUUM` com retenção curta quebra o time travel e leitores concorrentes\n\n---\n\n## OPTIMIZE (compactação)\n\n```mermaid\nflowchart TB\n    subgraph Before[\"Antes do OPTIMIZE\"]\n        F1[\"Arquivo 1<br/>10MB\"]\n        F2[\"Arquivo 2<br/>5MB\"]\n        F3[\"Arquivo 3<br/>7MB\"]\n        F5[\"Arquivo N...\"]\n        Total[\"Muitos arquivos pequenos<br/>Leituras lentas\"]\n    end\n\n    subgraph After[\"Depois do OPTIMIZE\"]\n        Large[\"Poucos arquivos grandes<br/>(~1 GB alvo)\"]\n        Optimized[\"Menos arquivos<br/>Consultas mais rápidas\"]\n    end\n\n    Before -->|OPTIMIZE| After\n```\n\n### OPTIMIZE básico\n\n```sql\nOPTIMIZE employees;\n\n-- Só algumas partições (tabelas particionadas)\nOPTIMIZE employees WHERE year = 2025 AND month = 1;\n```\n\n```python\nfrom delta.tables import DeltaTable\n\ndelta_table = DeltaTable.forName(spark, \"main.silver.employees\")\ndelta_table.optimize().executeCompaction()\ndelta_table.optimize().where(\"year = 2025\").executeCompaction()\n```\n\n- O `OPTIMIZE` é **idempotente**: rodá-lo de novo sem novos dados não faz nada\n- Não altera os dados lógicos — cria novos arquivos maiores e marca os pequenos como removidos no log (eles continuam no storage até o `VACUUM`)\n\n### OPTIMIZE com Z-order\n\nZ-order reorganiza os dados para co-localizar valores das colunas mais filtradas, melhorando o **data skipping**:\n\n```sql\nOPTIMIZE employees ZORDER BY (department, hire_date);\nOPTIMIZE orders ZORDER BY (customer_id, order_date);\n```\n\n```python\nDeltaTable.forName(spark, \"main.silver.employees\").optimize().executeZOrderBy(\"department\")\n```\n\n### Quando usar Z-order\n\n| Tipo de coluna | Benefício | Exemplo |\n|-----------|---------|---------|\n| **Muito filtrada** | Alto | `WHERE department = 'X'` |\n| **Consultas por faixa** | Alto | `WHERE salary BETWEEN X AND Y` |\n| **Alta cardinalidade e usada em filtros** | Alto | `customer_id`, `device_id` |\n| **Colunas de data** | Alto | `WHERE date > '2025-01-01'` |\n| **Baixa cardinalidade** | Baixo | `WHERE active = true` |\n\n- A eficácia cai a cada coluna adicionada — use poucas (1 a 4)\n- As colunas precisam ter **estatísticas coletadas** (por padrão, as primeiras 32 colunas)\n- Z-order **não é incremental**: rodar de novo reescreve os dados. Liquid Clustering resolve isso\n\n## VACUUM\n\nO VACUUM remove arquivos de dados que **não são mais referenciados** pela versão atual e são mais antigos que o período de retenção:\n\n```sql\nVACUUM employees;                    -- retenção padrão: 7 dias\nVACUUM employees RETAIN 720 HOURS;   -- 30 dias\nVACUUM employees DRY RUN;            -- mostra o que seria apagado\n```\n\n```python\nDeltaTable.forName(spark, \"main.silver.employees\").vacuum(168)  # horas = 7 dias\n```\n\n### Segurança do VACUUM\n\n- A retenção padrão vem de `delta.deletedFileRetentionDuration` (`interval 7 days`)\n- Retenções abaixo de 7 dias são bloqueadas por uma verificação de segurança (`spark.databricks.delta.retentionDurationCheck.enabled`); desativá-la é perigoso\n- Leitores/escritores concorrentes podem falhar se o VACUUM apagar arquivos que ainda estão usando\n- O VACUUM apaga **arquivos de dados**; o log de transações é limpo separadamente, nos checkpoints, conforme `delta.logRetentionDuration` (30 dias)\n\n### Impacto do VACUUM no time travel\n\n```text\nTabela criada (v0) e atualizada diariamente por 60 dias (v0 → v60)\n\nVACUUM RETAIN 720 HOURS (30 dias)\n  → arquivos usados só por versões com mais de 30 dias são apagados\n  → time travel para v5 FALHA\n\nRetenção de 60 dias → time travel funciona para todas as versões dos últimos 60 dias\n```\n\n## Estatísticas da tabela\n\nO Delta coleta estatísticas por arquivo automaticamente na escrita (min, max, contagem de nulos) para as **primeiras 32 colunas**. Elas permitem o **data skipping**: arquivos cujo intervalo min/max não satisfaz o filtro nem são lidos.\n\n```sql\n-- Força a coleta de estatísticas para o otimizador (custo/cardinalidade)\nANALYZE TABLE employees COMPUTE STATISTICS;\nANALYZE TABLE employees COMPUTE STATISTICS FOR COLUMNS salary, department;\n\n-- Detalhes da tabela: número de arquivos, tamanho total, local, clustering\nDESCRIBE DETAIL employees;\n```\n\n## Propriedades de tabela para otimização\n\n```sql\n-- Optimized writes + auto compaction (agrupam arquivos na escrita / após a escrita)\nALTER TABLE employees SET TBLPROPERTIES (\n    'delta.autoOptimize.optimizeWrite' = 'true',\n    'delta.autoOptimize.autoCompact' = 'true'\n);\n\n-- Quantas colunas têm estatísticas coletadas (padrão 32)\nALTER TABLE employees SET TBLPROPERTIES ('delta.dataSkippingNumIndexedCols' = '32');\n\n-- Ou escolha explicitamente as colunas com estatísticas\nALTER TABLE employees SET TBLPROPERTIES ('delta.dataSkippingStatsColumns' = 'customer_id,order_date');\n```\n\n- **Optimized writes**: reduz o número de arquivos na própria escrita (agrupa dados antes de gravar)\n- **Auto compaction**: depois de uma escrita, compacta arquivos pequenos de forma síncrona\n- Nenhum dos dois substitui o `OPTIMIZE` completo, mas reduzem o problema de arquivos pequenos\n\n## Estratégia de manutenção\n\n| Frequência | Tarefa |\n| :--- | :--- |\n| A cada escrita | Optimized writes / auto compaction (se habilitados) |\n| Diária/semanal | `OPTIMIZE` nas tabelas grandes ou muito atualizadas |\n| Semanal/mensal | `VACUUM` com retenção adequada ao seu time travel |\n| Quando o padrão de consulta mudar | Revisar chaves de clustering (Liquid Clustering) ou Z-order |\n| **Melhor opção em managed tables do UC** | Habilitar **predictive optimization**, que agenda `OPTIMIZE`, `VACUUM` e `ANALYZE` automaticamente |\n\n## Verificando a performance da consulta\n\n```sql\nEXPLAIN EXTENDED\nSELECT * FROM employees WHERE salary > 100000;\n-- Procure filtros empurrados (PushedFilters / DataFilters) e o número de arquivos lidos na Spark UI\n```\n\n## Casos de uso\n\n- **Manutenção agendada**: rodar `OPTIMIZE` semanal e `VACUUM` mensal num job de manutenção para manter tabelas Delta rápidas conforme o volume cresce (ou deixar o predictive optimization fazer isso).\n- **Aceleração de dashboards de BI**: organizar as tabelas pelas colunas usadas nos filtros do dashboard (ex.: `region`, `product_category`) para que as consultas pulem arquivos irrelevantes.\n\n## Problemas e erros comuns\n\n### Problema de arquivos pequenos\n\n**Cenário:** escritas frequentes em micro-batch deixam as leituras lentas.\n**Correção:** rode `OPTIMIZE` regularmente, habilite optimized writes/auto compaction, ou use predictive optimization.\n\n### OPTIMIZE não melhora a consulta\n\n**Cenário:** o `OPTIMIZE` compacta os arquivos, mas as consultas continuam lentas porque filtram por colunas que não estão organizadas.\n**Correção:** organize pelos campos realmente usados nos `WHERE` (Z-order ou, melhor, Liquid Clustering). Só compactar ajuda pouco em consultas seletivas.\n\n### Z-order em colunas erradas desperdiça recursos\n\n**Cenário:** fazer Z-order em muitas colunas, ou em colunas de baixa cardinalidade que nunca aparecem nos filtros, não melhora o data skipping e gasta compute.\n**Correção:** faça Z-order em 1–4 colunas **frequentemente filtradas**, idealmente de **alta cardinalidade** (ex.: `customer_id`, datas). Colunas booleanas ou com poucos valores trazem pouco ganho.\n\n## Dicas para a prova\n\n- `OPTIMIZE` compacta arquivos pequenos; `ZORDER BY` agrupa os dados pelas colunas indicadas para filtros mais rápidos — saiba a sintaxe `OPTIMIZE tabela ZORDER BY (col)`\n- Retenção padrão do VACUUM: 7 dias; `VACUUM RETAIN 0 HOURS` quebra o time travel e é perigoso\n- `ANALYZE TABLE ... COMPUTE STATISTICS` coleta estatísticas para o otimizador\n- `delta.autoOptimize.optimizeWrite` e `delta.autoOptimize.autoCompact` reduzem arquivos pequenos na escrita\n- Para tabelas novas, prefira Liquid Clustering a particionamento + Z-order\n\n## Pontos-chave\n\n- **OPTIMIZE**: compacta arquivos pequenos em maiores para leituras mais rápidas\n- **Z-order**: co-localiza valores das colunas filtradas para data skipping\n- **VACUUM**: remove arquivos de dados antigos não referenciados para economizar armazenamento\n- **Estatísticas**: coletadas automaticamente nas primeiras 32 colunas; habilitam data skipping\n- **Retenção**: 7 dias por padrão evita perda acidental\n- **Optimized writes / auto compaction**: menos arquivos pequenos na escrita\n- **Manutenção**: OPTIMIZE, ANALYZE e VACUUM regulares — ou predictive optimization\n\n## Tópicos relacionados\n\n- [Time Travel e Versionamento](../01-databricks-intelligence-platform/05-time-travel-versioning.md)\n- [Fundamentos do Delta Lake](../01-databricks-intelligence-platform/04-delta-lake-fundamentals.md)\n- [Liquid Clustering e Predictive Optimization](04-liquid-clustering-and-predictive-optimization.md)\n\n## Documentação oficial\n\n- [Optimize Data Files](https://docs.databricks.com/en/delta/optimize.html)\n- [Remove Unused Data Files with Vacuum](https://docs.databricks.com/en/delta/vacuum.html)\n- [Data skipping](https://docs.databricks.com/aws/en/delta/data-skipping)\n\n---\n\n**[← Anterior: Spark UI e System Tables](02-spark-ui-and-system-tables.md) | [↑ Voltar para Troubleshooting, Monitoring, and Optimization](README.md) | [Próximo: Liquid Clustering e Predictive Optimization →](04-liquid-clustering-and-predictive-optimization.md)**\n"},{"id":"06-troubleshooting-monitoring-and-optimization/04-liquid-clustering-and-predictive-optimization","folder":"06-troubleshooting-monitoring-and-optimization","group":"modulo","order":4,"isIndex":false,"title":"Liquid Clustering e Predictive Optimization","md":"# Liquid Clustering e Predictive Optimization\n\n## Visão geral\n\n**Liquid Clustering** é a técnica de layout de dados da Databricks para tabelas Delta (e Iceberg). Ela \"substitui o particionamento de tabelas e o `ZORDER`\", e você pode mudar as chaves de clustering sem reescrever os dados existentes. **Predictive optimization** tira a manutenção de tabelas da sua lista de tarefas, rodando `OPTIMIZE`, `VACUUM` e `ANALYZE` automaticamente em managed tables do Unity Catalog. Juntos, são a resposta moderna para \"deixe esta tabela rápida e mantenha assim\".\n\n> [!abstract] Resumo\n>\n> - Habilite com `CLUSTER BY (col, ...)` (até **quatro** chaves) no `CREATE TABLE` ou `ALTER TABLE`. Deixe a Databricks escolher as chaves com `CLUSTER BY AUTO`\n> - `OPTIMIZE` faz clustering incremental. `OPTIMIZE ... FULL` reorganiza tudo após mudar as chaves\n> - Clustering **não é compatível com particionamento nem com `ZORDER`**\n> - **Predictive optimization** faz manutenção apenas em **managed tables do UC**, em serverless jobs compute, e vem habilitado por padrão para contas criadas a partir de 11/11/2024\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: entender os recursos do Liquid Clustering e do predictive optimization\n> - Quando o Liquid Clustering é melhor que particionamento ou Z-order: filtros de alta cardinalidade, skew, crescimento rápido e padrões de acesso que mudam\n> - O que o predictive optimization automatiza, a quais tabelas se aplica e como habilitar/desabilitar por catálogo, schema ou tabela\n> - Que o liquid clustering automático (`CLUSTER BY AUTO`) exige predictive optimization\n\n---\n\n## Liquid Clustering\n\n### Sintaxe\n\n```sql\n-- Nova tabela com chaves explícitas\nCREATE TABLE main.silver.events (\n  event_id BIGINT, customer_id BIGINT, event_ts TIMESTAMP, event_type STRING\n) CLUSTER BY (customer_id, event_ts);\n\n-- Habilitar ou mudar chaves em uma tabela existente não particionada (sem reescrever os dados)\nALTER TABLE main.silver.events CLUSTER BY (event_type, event_ts);\n\n-- Deixar a Databricks escolher as chaves pelos padrões de consulta (exige predictive optimization)\nALTER TABLE main.silver.events CLUSTER BY AUTO;\n\n-- Remover o clustering\nALTER TABLE main.silver.events CLUSTER BY NONE;\n\n-- Disparar o clustering\nOPTIMIZE main.silver.events;          -- incremental: só dados novos ou não organizados\nOPTIMIZE main.silver.events FULL;     -- reorganiza todos os dados pelas chaves atuais (pode levar horas)\n\n-- Converter uma tabela particionada (DBR 18.1+)\nALTER TABLE main.silver.legacy_events REPLACE PARTITIONED BY WITH CLUSTER BY (customer_id);\n```\n\nFonte: [Use liquid clustering for tables](https://docs.databricks.com/aws/en/delta/clustering).\n\n### Fatos-chave\n\n| Recurso | Detalhe |\n| :--- | :--- |\n| **Substitui** | Particionamento e `ZORDER`. \"Não é compatível\" com nenhum dos dois |\n| **Máximo de chaves** | Quatro. Em tabelas abaixo de 10 TB, mais chaves podem deixar filtros de uma coluna mais lentos |\n| **Mudar as chaves** | `ALTER TABLE ... CLUSTER BY (...)` a qualquer momento. Dados existentes não são reescritos até serem reorganizados (`OPTIMIZE FULL`) |\n| **Incremental** | `OPTIMIZE` reescreve só o que precisa ser organizado. As escritas também podem organizar dados |\n| **Automático** | `CLUSTER BY AUTO` escolhe e evolui as chaves. Exige predictive optimization |\n| **Runtime** | GA para Delta no DBR 15.4 LTS+. Converter tabelas particionadas exige DBR 18.1+ |\n| **Recomendado para** | Todas as tabelas novas, especialmente filtros por colunas de alta cardinalidade, skew forte, tabelas que crescem rápido, escritores concorrentes e padrões de acesso que mudam |\n\n### Liquid Clustering vs particionamento vs Z-order\n\n| | Particionamento | Z-order | Liquid Clustering |\n| :--- | :--- | :--- | :--- |\n| Cardinalidade boa da chave | Baixa (data, região) | Alta | Baixa ou alta |\n| Mudar chaves depois | Reescrever a tabela | Rodar de novo com novas colunas | `ALTER TABLE ... CLUSTER BY`, sem reescrita imediata |\n| Risco de arquivos pequenos / skew | Alto com chave mal escolhida | — | Tratado pelo clustering |\n| Manutenção | Manual | `OPTIMIZE ... ZORDER BY` (reescrita completa dos dados alvo) | `OPTIMIZE` (incremental), ou automático com predictive optimization |\n| Combinar com os outros? | — | Não com clustering | **Não** com particionamento nem Z-order |\n\n## Predictive optimization\n\nO predictive optimization roda automaticamente `OPTIMIZE`, `VACUUM` e `ANALYZE` em managed tables do Unity Catalog, e coleta estatísticas quando os dados são escritos ([Predictive optimization](https://docs.databricks.com/aws/en/optimizations/predictive-optimization)).\n\n| Aspecto | Detalhe |\n| :--- | :--- |\n| **Operações** | `OPTIMIZE` (clustering incremental; não roda `ZORDER`), `VACUUM` (retenção padrão de 7 dias, via `delta.deletedFileRetentionDuration`), `ANALYZE` |\n| **Aplica-se a** | **Managed tables do UC** (Delta e Iceberg) apenas. Não a external tables, nem a tabelas recebidas via OpenSharing |\n| **Padrão** | Habilitado para contas criadas a partir de **11/11/2024**. Contas existentes receberam aos poucos, com conclusão prevista até agosto de 2026 |\n| **Compute e cobrança** | Roda em serverless jobs compute, cobrado em SKU de serverless jobs |\n| **Observabilidade** | `system.storage.predictive_optimization_operations_history` |\n| **Pré-requisitos** | Plano Premium ou superior, região suportada, e SQL warehouses ou DBR 12.2 LTS+ |\n\n```sql\n-- Sobrescreve a configuração da conta em qualquer nível; INHERIT volta à configuração do pai\nALTER CATALOG main ENABLE PREDICTIVE OPTIMIZATION;\nALTER SCHEMA main.scratch DISABLE PREDICTIVE OPTIMIZATION;\nALTER TABLE main.silver.events INHERIT PREDICTIVE OPTIMIZATION;\n\n-- O que ele fez?\nSELECT * FROM system.storage.predictive_optimization_operations_history\nLIMIT 20;\n```\n\n> [!note] Observação\n> Com predictive optimization ligado, \"normalmente você não precisa de jobs agendados de OPTIMIZE\" para tabelas com clustering. Lembre que ele também roda `VACUUM`, o que limita até onde o time travel consegue voltar (7 dias por padrão).\n\n```mermaid\nflowchart LR\n    W[Escritas em managed<br/>table do UC] --> PO{Predictive<br/>optimization}\n    PO --> O[OPTIMIZE<br/>clustering incremental]\n    PO --> V[VACUUM<br/>remove arquivos antigos]\n    PO --> A[ANALYZE<br/>estatísticas]\n    PO -.CLUSTER BY AUTO.-> K[Escolhe / evolui<br/>chaves de clustering]\n```\n\n## Casos de uso\n\n- **Tabela de eventos de clientes** filtrada por `customer_id` (alta cardinalidade) e tempo: `CLUSTER BY (customer_id, event_ts)` em vez de partições por data + Z-order\n- **Padrões de consulta desconhecidos ou que mudam**: `CLUSTER BY AUTO` deixa a Databricks escolher as chaves\n- **Centenas de tabelas, nenhum job de manutenção**: predictive optimization cuida de compactação, vacuum e estatísticas\n- **Tabela particionada legada com arquivos minúsculos**: converta com `REPLACE PARTITIONED BY WITH CLUSTER BY` e depois rode `OPTIMIZE`\n\n## Problemas e erros comuns\n\n### `CLUSTER BY` falha em tabela particionada\n\n**Cenário:** `ALTER TABLE t CLUSTER BY (customer_id)` falha em uma tabela particionada por `event_date`.\n**Correção:** clustering não é compatível com particionamento. No DBR 18.1+, use `REPLACE PARTITIONED BY WITH CLUSTER BY`, ou recrie a tabela com `CLUSTER BY`.\n\n### Novas chaves não aceleram os dados antigos\n\n**Cenário:** depois de mudar as chaves de clustering, consultas em dados históricos continuam lentas.\n**Correção:** dados existentes não são reescritos quando as chaves mudam. Rode `OPTIMIZE ... FULL` para reorganizar tudo.\n\n### Predictive optimization não roda em uma tabela\n\n**Cenário:** uma external table nunca aparece no histórico do predictive optimization.\n**Correção:** o predictive optimization só se aplica a **managed tables do UC**. Converta a tabela com `ALTER TABLE ... SET MANAGED` (veja [Managed and External Tables](../07-governance-and-security/02-managed-and-external-tables.md)), ou agende a manutenção você mesmo.\n\n### `CLUSTER BY AUTO` nunca escolhe chaves\n\n**Cenário:** o liquid clustering automático está habilitado, mas as chaves continuam vazias.\n**Correção:** a seleção automática de chaves exige predictive optimization. Verifique se está habilitado no catálogo, schema ou tabela.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - Liquid Clustering = `CLUSTER BY` (até 4 chaves). Substitui particionamento e Z-order e não pode ser combinado com eles\n> - Mude as chaves com `ALTER TABLE ... CLUSTER BY` (sem reescrita imediata). `OPTIMIZE FULL` reorganiza todos os dados\n> - `CLUSTER BY AUTO` precisa de predictive optimization\n> - Predictive optimization = `OPTIMIZE` + `VACUUM` + `ANALYZE` automáticos **só em managed tables do UC**\n> - Habilite/desabilite com `ALTER CATALOG | SCHEMA | TABLE ... ENABLE | DISABLE | INHERIT PREDICTIVE OPTIMIZATION`\n\n## Pontos-chave\n\n- Liquid Clustering é o layout recomendado para tabelas novas: chaves flexíveis, clustering incremental e solução para skew\n- Predictive optimization automatiza a manutenção e combina com o clustering automático\n- Ambos favorecem **managed tables do Unity Catalog** — mais um motivo pelo qual a Databricks as recomenda\n\n## Tópicos relacionados\n\n- [Otimização do Delta Lake (OPTIMIZE, Z-order, VACUUM)](03-delta-optimization.md)\n- [Spark UI e System Tables](02-spark-ui-and-system-tables.md)\n- [Managed and External Tables](../07-governance-and-security/02-managed-and-external-tables.md)\n\n## Documentação oficial\n\n- [Use liquid clustering for tables](https://docs.databricks.com/aws/en/delta/clustering)\n- [Predictive optimization for Unity Catalog managed tables](https://docs.databricks.com/aws/en/optimizations/predictive-optimization)\n\n---\n\n**[← Anterior: Otimização do Delta Lake](03-delta-optimization.md) | [↑ Voltar para Troubleshooting, Monitoring, and Optimization](README.md) | [Próximo: Compute Troubleshooting →](05-compute-troubleshooting.md)**\n"},{"id":"06-troubleshooting-monitoring-and-optimization/05-compute-troubleshooting","folder":"06-troubleshooting-monitoring-and-optimization","group":"modulo","order":5,"isIndex":false,"title":"Troubleshooting de Compute","md":"# Troubleshooting de Compute\n\n## Visão geral\n\nO exam guide pede que você diagnostique três classes de problema de compute: **falhas de inicialização de cluster**, **conflitos de bibliotecas** e erros de **falta de memória (OOM)**. Cada um deixa uma trilha diferente no **event log** do compute, nos **driver logs** ou na **Spark UI**. Este arquivo mapeia sintomas para causas e correções, usando os códigos de término documentados e as regras de precedência de bibliotecas da Databricks.\n\n> [!abstract] Resumo\n>\n> - **Falhas de inicialização**: leia o motivo ou código de término no event log. Causas típicas: capacidade ou quota na nuvem, falta de IPs na subnet, init scripts falhando e Spark não iniciando\n> - **Conflitos de bibliotecas**: bibliotecas com escopo de notebook (`%pip`) têm precedência sobre as do compute, que têm precedência sobre as nativas do Databricks Runtime. Instalar uma versão conflitante de um pacote central pode quebrar o REPL Python\n> - **OOM**: OOM no driver geralmente vem de trazer dados para o driver (`collect()`, `toPandas()`, broadcasts enormes). OOM ou spill no executor vem de partições grandes demais, skew ou linhas largas\n> - Verifique o **event log** (ciclo de vida), os **driver logs** (stdout, stderr, log4j) e a **Spark UI** (executores, stages)\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: diagnosticar falhas de inicialização de cluster, conflitos de bibliotecas e problemas de falta de memória\n> - Diferenciar OOM no driver de OOM no executor, e a correção certa para cada um\n> - Onde olhar primeiro: event log, driver logs, Spark UI ou logs de init script\n> - Por que bibliotecas com escopo de notebook e versões fixadas evitam conflitos\n\n---\n\n## Onde ficam as evidências\n\n| Fonte | Contém | Retenção / observações |\n| :--- | :--- | :--- |\n| **Event log do compute** | Eventos de ciclo de vida: criação, início, término, resize, edições de configuração | 60 dias. Exportável como CSV ou Excel |\n| **Driver logs** | stdout, stderr e Log4j de notebooks, jobs e bibliotecas | Configure log delivery para guardar por mais tempo |\n| **Spark UI → Executors / Stages** | Memória dos executores, tempo de GC, tasks com falha, spill | Mostra só a sessão mais recente após um restart |\n| **Logs de init script** | Saída dos init scripts com escopo de cluster | Primeiro lugar a olhar quando o código é `INIT_SCRIPT_FAILURE` |\n| **Detalhes da execução (jobs)** | Divisão do tempo: na fila, aguardando recursos, instalando bibliotecas, rodando | Mostra *onde* o tempo foi antes mesmo do código rodar |\n\n## Falhas de inicialização do cluster\n\n| Código de término (exemplos) | Causa | Correção |\n| :--- | :--- | :--- |\n| `CLOUD_PROVIDER_LAUNCH_FAILURE` | O provedor de nuvem não conseguiu iniciar a VM | Tente mais tarde. Escale com o provedor se persistir |\n| `CLOUD_PROVIDER_RESOURCE_STOCKOUT_DUE_TO_MISCONFIG` | Sem capacidade para o tipo de instância ou zona pedidos por configurações restritivas | Habilite tipos de nó flexíveis, ou mude a zona ou o tipo de instância |\n| `AWS_RESOURCE_QUOTA_EXCEEDED` (e equivalentes) | A inicialização excederia uma quota da conta | Peça aumento de quota, ou use outros tipos de instância ou regiões |\n| `AWS_INSUFFICIENT_FREE_ADDRESSES_IN_SUBNET_FAILURE` | \"Não há endereços livres suficientes na subnet\" | Use outra zona ou `auto`, ou amplie o CIDR da subnet |\n| `INIT_SCRIPT_FAILURE` | Um init script de cluster não carregou ou saiu com código diferente de zero | Leia os logs do init script e corrija caminho, permissões ou comando |\n| `SPARK_STARTUP_FAILURE` | O driver Spark não iniciou dentro do timeout | Remova configs Spark customizadas e init scripts para isolar a causa, ou tente outro tipo de instância |\n| `INVALID_ARGUMENT` | Parâmetros ruins, secrets ausentes ou problemas de permissão | Corrija a configuração indicada e confira o secret scope e a chave |\n\nFonte: [Classic compute termination error codes](https://docs.databricks.com/aws/en/compute/troubleshooting/cluster-error-codes). A Knowledge Base da Databricks também documenta **timeouts de instalação de bibliotecas** (ex.: \"Library installation timed out after 1800 seconds\"), geralmente problemas intermitentes de rede resolvidos com nova execução ou restart.\n\n```mermaid\nflowchart TD\n    F[Compute não inicia] --> E[Event log: motivo do término]\n    E --> C1{Capacidade / quota<br/>/ subnet?}\n    C1 -->|sim| R1[Troque tipo de instância ou zona,<br/>aumente a quota, corrija a subnet]\n    E --> C2{INIT_SCRIPT_FAILURE?}\n    C2 -->|sim| R2[Logs do init script → corrija o script]\n    E --> C3{SPARK_STARTUP_FAILURE?}\n    C3 -->|sim| R3[Remova Spark conf customizada /<br/>init scripts para isolar]\n    E --> C4{Timeout instalando biblioteca?}\n    C4 -->|sim| R4[Tente de novo; hospede pacotes em<br/>volume UC ou fixe versões]\n```\n\n> [!tip] Dica\n> Serverless elimina a maioria das falhas de inicialização: não há tipos de instância, quotas ou init scripts para gerenciar. Se um job agendado vive falhando ao provisionar compute classic, migrá-lo para serverless costuma ser a solução mais simples.\n\n## Conflitos de bibliotecas\n\nQuando o código roda `import <biblioteca>`, a cópia com maior precedência vence ([Install libraries](https://docs.databricks.com/aws/en/libraries/)):\n\n1. Diretório de trabalho atual (só em Git folders)\n2. Raiz do Git folder (só em Git folders)\n3. **Bibliotecas com escopo de notebook** (`%pip install`)\n4. **Bibliotecas com escopo de compute**\n5. **Bibliotecas nativas do Databricks Runtime**\n6. Diretório de trabalho atual (fora de Git folders)\n7. Workspace files adicionados ao `sys.path`\n\n| Sintoma | Causa provável | Correção |\n| :--- | :--- | :--- |\n| `ImportError` / `AttributeError` depois de adicionar uma biblioteca | Uma biblioteca do compute sobrescreveu uma versão nativa do Runtime | Fixe uma versão compatível com o Runtime, ou isole como biblioteca de notebook |\n| Dois notebooks no mesmo cluster precisam de versões diferentes | Bibliotecas do compute são compartilhadas por todos os notebooks | Use `%pip install pkg==x.y` em cada notebook, ou computes separados |\n| Comandos Python passam a retornar **Cancelled** após mudar um pacote | Uma versão conflitante de um pacote central (ex.: numpy ou pandas) quebrou o REPL | Remova a biblioteca conflitante e reinstale a versão correta |\n| Uma biblioteca resolve de forma diferente a cada execução | Instalada por init script, cuja ordem em relação às nativas pode variar | A Databricks \"não recomenda instalar bibliotecas com init scripts\". Use bibliotecas do compute ou `requirements.txt` |\n| Arquivos de biblioteca editados por usuários desconhecidos | Guardados no DBFS | Armazenar bibliotecas no DBFS está depreciado (e desabilitado por padrão no DBR 15.1+). Use volumes UC ou workspace files |\n\n```python\n# Escopo de notebook e versão fixada: isolado dos outros notebooks no mesmo compute\n%pip install pandas==2.2.2\ndbutils.library.restartPython()   # reinicia o Python para importar a nova versão\n```\n\nNo **serverless**, gerencie dependências com **environments** (base environments) em vez de bibliotecas de compute. No DBR 15.0+, arquivos `requirements.txt` podem gerenciar dependências Python.\n\n## Erros de falta de memória (OOM)\n\n| Onde | Mensagem / sinal típico | Causas comuns | Correções |\n| :--- | :--- | :--- | :--- |\n| **Driver** | `java.lang.OutOfMemoryError` no driver, \"driver is temporarily unavailable\", notebook desanexado | `collect()` / `toPandas()` em dados grandes, broadcast de tabela grande, muitíssimos arquivos pequenos rastreados no driver | Mantenha os dados distribuídos: grave resultados numa tabela, `display()` / `limit()`. Não faça broadcast de tabelas grandes. Aumente `spark.driver.memory` (no compute) só quando necessário |\n| **Executor** | Executor perdido ou OOM, tasks reexecutadas, muito **spill** | Partições de shuffle grandes demais, **skew**, linhas largas ou arrays grandes, cache demais | `spark.sql.shuffle.partitions=auto` ou mais partições. Trate o skew (salting). Selecione menos colunas. Use workers maiores ou otimizados para memória. Faça unpersist de caches sem uso |\n| **Worker Python** | Processo Python morto em uma UDF | UDFs Python ou pandas UDFs segurando lotes grandes | Use funções nativas. Reduza o tamanho do lote Arrow ou os dados por grupo |\n\n```python\n# Antipadrão: traz 200 milhões de linhas para o driver\npdf = spark.table(\"main.silver.events\").toPandas()          # OOM no driver\n\n# Padrão: agregue no Spark e colete só o resultado pequeno\nsummary = (spark.table(\"main.silver.events\")\n    .groupBy(\"event_type\").count()\n    .toPandas())                                             # poucas linhas\n```\n\nVeja [Parâmetros de tuning do Spark](../03-data-transformation-and-modeling/07-spark-tuning-parameters.md) para configurações de memória, e [Spark UI e System Tables](02-spark-ui-and-system-tables.md) para ler spill e skew.\n\n## Casos de uso\n\n- **Job noturno preso em Pending e depois encerrado**: o event log mostra código de falta de IPs na subnet; mudar de zona resolve\n- **Pipeline quebra após upgrade \"inofensivo\" de biblioteca**: um upgrade de pandas no compute conflita com o Runtime; a versão é fixada e movida para escopo de notebook\n- **Notebook de relatório derruba o driver**: `toPandas()` substituído por agregação no Spark + coleta pequena\n- **Stage de join perde executores**: o skew é tratado com salting e shuffle partitions passa a `auto`\n\n## Problemas e erros comuns\n\n### Tratar todo OOM como \"adicione mais workers\"\n\n**Cenário:** um OOM no driver após `collect()` persiste mesmo depois de dobrar os workers.\n**Correção:** workers não adicionam memória ao driver. Pare de coletar dados grandes no driver, ou aumente a memória do driver no compute.\n\n### Mudança em init script derruba o cluster\n\n**Cenário:** depois de editar um init script de cluster, o cluster encerra com `INIT_SCRIPT_FAILURE`.\n**Correção:** leia os logs do init script, corrija (caminho, permissões, comando que falha) e reinicie. Prefira bibliotecas de compute ou environments a instalações via init script.\n\n### Versão da biblioteca diferente entre dev e prod\n\n**Cenário:** o código funciona num cluster de dev mas falha no job de prod com `AttributeError`.\n**Correção:** os dois computes rodam bibliotecas nativas ou versões diferentes. Fixe as versões nas bibliotecas ou environment do job e use um runtime LTS para jobs.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - Falha de inicialização → **motivo de término no event log** primeiro. Falha de init script → **logs do init script**\n> - Precedência de bibliotecas: **notebook (`%pip`) > compute > nativas do Runtime**\n> - Use bibliotecas de notebook ou versões fixadas para evitar conflitos. Evite instalar via init script e bibliotecas no DBFS\n> - **OOM no driver** ← `collect()` / `toPandas()` / broadcast grande. **OOM ou spill no executor** ← partições grandes, skew, linhas largas\n> - Mais workers não resolvem nem OOM no driver nem uma única task com skew\n\n## Pontos-chave\n\n- Event log, driver logs e Spark UI respondem, cada um, a um \"por que falhou?\" diferente\n- Códigos de término apontam para causas de capacidade, quota, rede, init script ou inicialização do Spark\n- A precedência de bibliotecas explica a maioria dos conflitos de versão. Isole e fixe versões\n- Diagnostique o OOM por *onde* ele acontece (driver vs executor) e corrija o padrão de dados antes de adicionar memória\n\n## Tópicos relacionados\n\n- [Compute e Clusters](../01-databricks-intelligence-platform/03-compute-clusters.md)\n- [Parâmetros de tuning do Spark](../03-data-transformation-and-modeling/07-spark-tuning-parameters.md)\n- [Spark UI e System Tables](02-spark-ui-and-system-tables.md)\n\n## Documentação oficial\n\n- [Classic compute termination error codes](https://docs.databricks.com/aws/en/compute/troubleshooting/cluster-error-codes)\n- [Manage classic compute](https://docs.databricks.com/aws/en/compute/clusters-manage)\n- [Install libraries](https://docs.databricks.com/aws/en/libraries/)\n- [Diagnose Lakeflow Jobs performance](https://docs.databricks.com/aws/en/jobs/diagnose-job-performance)\n\n---\n\n**[← Anterior: Liquid Clustering e Predictive Optimization](04-liquid-clustering-and-predictive-optimization.md) | [↑ Voltar para Troubleshooting, Monitoring, and Optimization](README.md)**\n"},{"id":"06-troubleshooting-monitoring-and-optimization/README","folder":"06-troubleshooting-monitoring-and-optimization","group":"modulo","order":0,"isIndex":true,"title":"Troubleshooting, Monitoring, and Optimization","md":"# Troubleshooting, Monitoring, and Optimization (10 % da prova)\n\nO Domínio 6 cobre manter os pipelines saudáveis e rápidos. Você lê o histórico de execuções dos **Lakeflow Jobs** para comparar durações com uma linha de base, e interpreta status de jobs e grafos de tasks para achar bloqueios upstream. Diagnostica skew, shuffle e disk spill a partir das métricas de stage da Spark UI. Sabe o que **Liquid Clustering** e **predictive optimization** fazem, e consegue resolver falhas de inicialização de cluster, conflitos de bibliotecas e erros de falta de memória.\n\n## Visão geral dos tópicos\n\n```mermaid\nflowchart TD\n    M[Troubleshooting, Monitoramento e Otimização] --> Runs[Histórico e status de execuções]\n    M --> SUI[Spark UI: skew, shuffle, spill]\n    M --> Layout[Layout dos dados]\n    M --> Compute[Falhas de compute]\n    Layout --> OPT[OPTIMIZE / VACUUM / Z-order]\n    Layout --> LC[Liquid Clustering]\n    Layout --> PO[Predictive optimization]\n    Compute --> Start[Falhas de inicialização]\n    Compute --> Lib[Conflitos de bibliotecas]\n    Compute --> OOM[Out of memory]\n```\n\n## Conteúdo da seção\n\n| Arquivo | Tópico | Prioridade |\n| :--- | :--- | :--- |\n| [01-job-monitoring.md](01-job-monitoring.md) | Lista Jobs & Pipelines, matrix view, status de execução, visões graph/timeline, notificações, repair runs | Alta |\n| [02-spark-ui-and-system-tables.md](02-spark-ui-and-system-tables.md) | Métricas de stage, skew, shuffle, spill, limites do AQE, system tables | Alta |\n| [03-delta-optimization.md](03-delta-optimization.md) | `OPTIMIZE`, Z-order, `VACUUM`, estatísticas, tamanho de arquivos | Média |\n| [04-liquid-clustering-and-predictive-optimization.md](04-liquid-clustering-and-predictive-optimization.md) | `CLUSTER BY`, `CLUSTER BY AUTO`, `OPTIMIZE FULL`, predictive optimization | Alta |\n| [05-compute-troubleshooting.md](05-compute-troubleshooting.md) | Códigos de término, init scripts, precedência e conflitos de bibliotecas, OOM no driver/executor | Alta |\n\n## Cobertura das habilidades oficiais (agosto de 2026)\n\n| Habilidade do exam guide (parafraseada) | Onde é coberta |\n| :--- | :--- |\n| Tendências de performance a partir do histórico de execuções vs linha de base | [01](01-job-monitoring.md) |\n| Monitorar a saúde do pipeline na UI de Jobs: status, grafo do DAG, tempos de execução, taxas de falha | [01](01-job-monitoring.md) |\n| Métricas de stage da Spark UI para skew, shuffle e disk spill | [02](02-spark-ui-and-system-tables.md) |\n| Recursos do Liquid Clustering e do predictive optimization | [04](04-liquid-clustering-and-predictive-optimization.md), [03](03-delta-optimization.md) |\n| Falhas de inicialização de cluster, conflitos de bibliotecas, problemas de falta de memória | [05](05-compute-troubleshooting.md) |\n\n## Conceitos-chave\n\n- **Matrix view**: histórico de execuções de um job, uma barra por execução. A altura é a duração e a cor é o status, então uma barra crescendo mostra regressão em relação à linha de base\n- **Resultado da execução**: decidido pelas leaf tasks (tasks finais). *Succeeded with failures* significa que algumas tasks falharam, mas todas as leaf tasks tiveram sucesso\n- **Teste de skew**: nas Summary Metrics de um stage, se a duração Max das tasks está pelo menos 50 % acima do percentil 75, o stage pode ter skew\n- **Tratamento de skew do AQE**: vale só para sort-merge e shuffle-hash joins, não para broadcast joins e nem para agregações `groupBy`. Em agregações, faça salting da chave\n- **Liquid Clustering**: substitui particionamento e Z-order (não pode ser combinado com nenhum dos dois). Use até quatro chaves, que podem ser alteradas sem reescrever os dados\n- **Predictive optimization**: roda `OPTIMIZE`, `VACUUM` e `ANALYZE` automaticamente em managed tables do UC\n\n## Próximos passos\n\nTermine com [07 — Governance and Security](../07-governance-and-security/README.md).\n\n---\n\n**[← Anterior: Implementing CI/CD](../05-implementing-cicd/README.md) | [↑ Voltar à Certificação](../README.md) | [Próximo: Governance and Security →](../07-governance-and-security/README.md)**\n"},{"id":"07-governance-and-security/01-unity-catalog-basics","folder":"07-governance-and-security","group":"modulo","order":1,"isIndex":false,"title":"Unity Catalog Básico","md":"# Unity Catalog Básico\n\n## Visão geral\n\nO Unity Catalog (UC) é a solução centralizada de metadados e controle de acesso da Databricks, um único lugar para governar dados em toda a plataforma. Ele resolve problemas de governança como metadados espalhados, controle de acesso inconsistente e falta de trilhas de auditoria.\n\n> [!abstract] Resumo\n>\n> - O metastore é o contêiner de nível mais alto (um por região). Abaixo dele fica o namespace de três níveis `catalog.schema.object`\n> - Objetos securables incluem tabelas, views, volumes, functions, models, external locations e storage credentials\n> - Storage credentials + external locations governam o acesso a caminhos no cloud storage\n\n> [!tip] O que a prova cobra\n>\n> - Apoia as habilidades do Domínio 7: a hierarquia de objetos sobre a qual privilégios são concedidos\n> - Configurar storage externo na ordem: storage credential → external location → external table ou volume\n> - Unity Catalog vs o Hive metastore legado, por workspace\n\n---\n\n## Arquitetura do Unity Catalog\n\n```mermaid\nflowchart TB\n    subgraph UC[\"Hierarquia do Unity Catalog\"]\n        Metastore[\"🏢 Metastore<br/>(por região)\"]\n\n        subgraph Catalogs[\"📚 Catalogs\"]\n            Cat1[\"prod\"]\n            Cat2[\"staging\"]\n            Cat3[\"external\"]\n        end\n\n        subgraph Schemas[\"📖 Schemas\"]\n            Sch1[\"analytics\"]\n            Sch2[\"raw\"]\n            Sch3[\"processed\"]\n        end\n\n        subgraph Objects[\"📄 Objetos\"]\n            Tbl[\"Tables\"]\n            Vws[\"Views\"]\n            Vols[\"Volumes\"]\n            Fns[\"Functions / Models\"]\n        end\n    end\n\n    Metastore --> Catalogs\n    Cat1 --> Schemas\n    Schemas --> Objects\n```\n\n## Metastore\n\nUm **metastore** é o contêiner raiz do Unity Catalog em uma região. É criado por região e contém:\n\n- Todos os catálogos, schemas e objetos\n- Políticas de controle de acesso\n- Logs de auditoria\n- Informações de linhagem\n\nCada região tem **um** metastore por conta; vários workspaces da mesma região podem ser anexados ao mesmo metastore e compartilhar os mesmos dados governados.\n\n## Namespace de três níveis\n\nO Unity Catalog usa um namespace de **três níveis**: `catalog.schema.object`\n\n```text\nmetastore/\n├── prod/                          (Catalog)\n│   ├── analytics/                 (Schema)\n│   │   ├── orders                 (Table)\n│   │   ├── customers              (Table)\n│   │   └── revenue_metrics        (View)\n│   └── raw/                       (Schema)\n│       ├── events                 (Table)\n│       └── landing                (Volume)\n├── staging/                       (Catalog)\n│   └── experimental/              (Schema)\n│       └── test_data              (Table)\n└── external/                      (Catalog)\n    └── partner_data/              (Schema)\n        └── partner_a_forecast     (Table)\n```\n\n```sql\nSELECT * FROM prod.analytics.orders;\nSELECT * FROM staging.experimental.test_data;\n-- O Hive metastore legado usava dois níveis: schema.table (dentro de hive_metastore)\n```\n\n## Criando catálogos e schemas\n\n```sql\nCREATE CATALOG IF NOT EXISTS prod COMMENT \"Catálogo de produção\";\nCREATE CATALOG IF NOT EXISTS staging COMMENT \"Dados de staging e teste\";\n\nCREATE SCHEMA IF NOT EXISTS prod.analytics COMMENT \"Datasets analíticos\";\nCREATE SCHEMA IF NOT EXISTS prod.raw COMMENT \"Camada de ingestão bruta\";\n\n-- Opcional: local de armazenamento gerenciado próprio do catálogo/schema\nCREATE CATALOG finance MANAGED LOCATION 's3://finance-bucket/managed/';\n\nSHOW CATALOGS;\nSHOW SCHEMAS IN prod;\nDESCRIBE CATALOG prod;\nDESCRIBE SCHEMA prod.analytics;\n```\n\n## Objetos no Unity Catalog\n\n### Managed tables\n\n```sql\nCREATE TABLE prod.analytics.orders (\n    order_id INT,\n    customer_id INT,\n    amount DECIMAL(10, 2),\n    order_date DATE\n);\n-- Dados no local gerenciado do UC; a Databricks gerencia ciclo de vida e layout\n```\n\n### External tables\n\n```sql\nCREATE TABLE external.partner_data.forecasts (\n    forecast_id INT,\n    product_id INT,\n    predicted_sales DECIMAL(10, 2)\n)\nLOCATION 's3://partner-bucket/forecasts/';\n-- Dados no bucket do parceiro; o UC fornece metadados e controle de acesso\n-- O caminho precisa estar coberto por uma external location\n```\n\n### Views\n\n```sql\nCREATE VIEW prod.analytics.high_value_orders AS\nSELECT order_id, customer_id, amount\nFROM prod.analytics.orders\nWHERE amount > 10000;\n```\n\n### Volumes\n\nVolumes são locais de armazenamento governados para **arquivos** (documentos, imagens, CSVs brutos, código):\n\n```sql\nCREATE VOLUME IF NOT EXISTS prod.raw.landing;                              -- managed volume\nCREATE EXTERNAL VOLUME prod.raw.vendor LOCATION 's3://vendor-bucket/in/'; -- external volume\n```\n\n```python\ndbutils.fs.ls(\"/Volumes/prod/raw/landing/\")\nspark.read.csv(\"/Volumes/prod/raw/landing/customers.csv\", header=True)\n```\n\n## Storage credentials e external locations\n\nO acesso a cloud storage passa por dois objetos:\n\n1. **Storage credential**: guarda a identidade de nuvem (IAM role na AWS, managed identity na Azure, service account no GCP)\n2. **External location**: combina um caminho de storage com uma storage credential\n\n```sql\n-- Admin: external location sobre uma credential existente\nCREATE EXTERNAL LOCATION partner_data\nURL 's3://partner-bucket/data/'\nWITH (STORAGE CREDENTIAL partner_role);\n\nGRANT READ FILES, CREATE EXTERNAL TABLE ON EXTERNAL LOCATION partner_data TO `data_engineers`;\n\n-- Tabela externa dentro dessa external location\nCREATE TABLE external.partner_data.sales\nLOCATION 's3://partner-bucket/data/sales/';\n```\n\n## UC vs Hive metastore\n\n| Recurso | Unity Catalog | Hive Metastore (legado) |\n|---------|---|---|\n| **Namespace** | 3 níveis (catalog.schema.table) | 2 níveis (schema.table) |\n| **Controle de acesso** | Privilégios granulares por objeto, centralizados na conta | Limitado, por workspace |\n| **Auditoria** | Linhagem e trilha de acesso completas | Limitada |\n| **Dados externos** | External locations governadas | Mounts/caminhos não governados |\n| **Escopo** | Um metastore compartilhado por vários workspaces da região | Um metastore por workspace |\n| **Compartilhamento** | OpenSharing (antigo Delta Sharing) | Exportações manuais |\n\n## Navegando no catálogo\n\n```sql\nUSE CATALOG prod;\nUSE SCHEMA analytics;\n\nSELECT * FROM orders;  -- equivale a prod.analytics.orders\n```\n\n```python\nspark.sql(\"USE CATALOG prod\")\nspark.sql(\"SELECT * FROM analytics.orders\")  # equivale a prod.analytics.orders\n```\n\n## Convenções de nomes e organização\n\n```text\nCatálogos: minúsculos e descritivos   → prod, staging, dev\nSchemas: área funcional ou camada     → raw, silver, gold, reporting\nTabelas/colunas: snake_case           → customer_transactions, order_date\nViews: descritivas, prefixo v_        → v_high_value_customers\n```\n\n| Padrão | Exemplo |\n| :--- | :--- |\n| Por ambiente | `prod`, `staging`, `dev` (schemas por camada dentro) |\n| Por camada | `bronze`, `silver`, `gold` |\n| Por domínio/fonte | `crm`, `erp`, `finance` |\n\n## Casos de uso\n\n- **Governança centralizada multiambiente**: separar os dados em catálogos (`prod`, `staging`, `dev`) para que controle de acesso, linhagem e auditoria sejam aplicados de forma consistente a partir de um único metastore.\n- **Descoberta de dados entre times**: permitir que analistas e cientistas de dados naveguem pelo namespace `catalog.schema.table` para encontrar e pedir acesso a datasets sem conhecer caminhos de storage.\n\n## Problemas e erros comuns\n\n### Tabela criada no catálogo errado\n\n**Cenário:** um notebook roda `CREATE TABLE orders ...` e a tabela vai para o catálogo padrão do workspace em vez de `prod`.\n**Correção:** nomes de uma ou duas partes são resolvidos contra o catálogo e schema atuais. Use nomes totalmente qualificados `catalog.schema.table`, ou rode `USE CATALOG` / `USE SCHEMA` antes.\n\n### INSUFFICIENT_PERMISSIONS ao consultar outro catálogo\n\n**Cenário:** um usuário recebe `INSUFFICIENT_PERMISSIONS` em `SELECT * FROM other_catalog.schema.table` mesmo tendo `SELECT` na tabela.\n**Correção:** verifique se ele também tem `USE CATALOG` no catálogo e `USE SCHEMA` no schema. Os três privilégios (`USE CATALOG` + `USE SCHEMA` + `SELECT`) são necessários.\n\n### Metastore não anexado ao workspace\n\n**Cenário:** objetos do Unity Catalog não aparecem no workspace, e `SHOW CATALOGS` volta vazio ou com erro.\n**Correção:** um account admin precisa anexar o metastore do UC ao workspace pelo account console. Cada workspace deve ser associado explicitamente a um metastore regional.\n\n## Dicas para a prova\n\n- O namespace de três níveis é `catalog.schema.object` — saiba escrever referências como `prod.analytics.orders`\n- Um metastore por região; ele é o contêiner raiz de todos os objetos do UC\n- Managed tables (UC gerencia o storage) vs external tables (dados em local externo, com controle de acesso do UC)\n- Volumes guardam arquivos não tabulares (PDFs, imagens, CSVs brutos) e são acessados em `/Volumes/catalog/schema/volume/`\n- Ordem para storage externo: **storage credential → external location → external table/volume**\n\n## Pontos-chave\n\n- **Unity Catalog**: governança centralizada em toda a plataforma Databricks\n- **Metastore**: contêiner raiz (um por região)\n- **Catalog**: contêiner organizacional de nível superior\n- **Schema**: agrupa objetos relacionados\n- **Namespace de três níveis**: `catalog.schema.object`\n- **Managed tables**: o UC gerencia storage e ciclo de vida\n- **External tables**: controle de acesso do UC, dados em storage externo\n- **Volumes**: armazenamento governado para arquivos\n- **External locations**: caminhos de cloud storage associados a uma storage credential\n\n## Tópicos relacionados\n\n- [Managed and External Tables](02-managed-and-external-tables.md)\n- [Controle de acesso e permissões](03-access-control-permissions.md)\n- [Compartilhamento de dados](05-data-sharing.md)\n\n## Documentação oficial\n\n- [Unity Catalog Overview](https://docs.databricks.com/en/data-governance/unity-catalog/index.html)\n- [Create and Manage Catalogs](https://docs.databricks.com/en/catalogs/index.html)\n\n---\n\n**[↑ Voltar para Governance and Security](README.md) | [Próximo: Managed and External Tables →](02-managed-and-external-tables.md)**\n"},{"id":"07-governance-and-security/02-managed-and-external-tables","folder":"07-governance-and-security","group":"modulo","order":2,"isIndex":false,"title":"Managed e External Tables","md":"# Managed e External Tables\n\n## Visão geral\n\nO Unity Catalog tem dois tipos de tabela com ciclos de vida bem diferentes. Numa tabela **managed**, o Unity Catalog é dono do armazenamento, do layout e da otimização dos dados. Numa tabela **external**, o Unity Catalog governa os metadados enquanto os arquivos ficam em um caminho que você controla. O exam guide espera que você diferencie as duas e saiba **criar, modificar, apagar e converter** entre elas, incluindo os comandos mais novos `SET MANAGED` e `UNSET MANAGED`.\n\n> [!abstract] Resumo\n>\n> - **Managed** (padrão, recomendada): criada sem `LOCATION`. Os dados ficam no managed storage do schema ou catálogo. Elegível para predictive optimization e liquid clustering automático\n> - **External**: criada com `LOCATION` em um caminho coberto por uma **external location** do UC. `DROP TABLE` remove só os metadados; os arquivos permanecem\n> - Managed tables removidas podem ser recuperadas com **`UNDROP TABLE` por 7 dias** (padrão); depois disso os arquivos são apagados\n> - Converta external → managed com **`ALTER TABLE ... SET MANAGED`** (DBR 17.3 LTS+ ou serverless). Desfaça em até **14 dias** com **`ALTER TABLE ... UNSET MANAGED`**\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: diferenciar managed e external tables no Unity Catalog e fazer operações básicas (criar, modificar, apagar e converter entre elas)\n> - O que o `DROP TABLE` faz com os dados em cada tipo\n> - Privilégios para criar external tables (`CREATE EXTERNAL TABLE` na external location)\n> - Comandos de conversão e rollback, suas janelas e efeitos colaterais (streams reiniciam, time travel só por versão)\n\n---\n\n## Lado a lado\n\n| | Managed table | External table |\n| :--- | :--- | :--- |\n| Criar | `CREATE TABLE c.s.t (...)` (sem `LOCATION`) | `CREATE TABLE c.s.t (...) LOCATION 's3://...'` |\n| Local dos dados | Managed storage do schema ou catálogo | Um caminho que você escolhe, dentro de uma external location do UC |\n| Formatos | Delta (padrão) ou Iceberg (`USING iceberg`) | DELTA, CSV, JSON, AVRO, PARQUET, ORC, TEXT |\n| Quem gerencia layout e otimização | Unity Catalog (predictive optimization, liquid clustering automático) | Você |\n| `DROP TABLE` | Metadados removidos. Dados recuperáveis com `UNDROP` por 7 dias (configurável: 0 h ou 7–30 dias), depois apagados | **Só metadados**. \"O Unity Catalog não apaga os dados no cloud storage\" |\n| Recomendação da Databricks | **Padrão e recomendada** na maioria dos casos | Dados existentes incompatíveis com managed tables, ou clientes externos que precisam de acesso direto aos arquivos |\n\nFontes: [Unity Catalog managed tables](https://docs.databricks.com/aws/en/tables/managed), [Work with external tables](https://docs.databricks.com/aws/en/tables/external).\n\n## Criar\n\n```sql\n-- Managed (Delta por padrão)\nCREATE TABLE main.silver.customers (\n  customer_id BIGINT NOT NULL,\n  email STRING,\n  country STRING\n);\n\n-- Managed a partir de uma consulta\nCREATE TABLE main.gold.revenue AS\nSELECT region, SUM(amount) AS revenue FROM main.silver.orders GROUP BY region;\n\n-- External: os dados ficam em um caminho governado\nCREATE TABLE main.bronze.vendor_feed (\n  id BIGINT, payload STRING\n)\nLOCATION 's3://acme-landing/vendor_feed/';\n```\n\n```python\n# External table a partir de uma escrita de DataFrame (opção path)\n(df.write\n   .option(\"path\", \"s3://acme-landing/vendor_feed/\")\n   .saveAsTable(\"main.bronze.vendor_feed\"))\n```\n\n**Privilégios para external table**: `CREATE EXTERNAL TABLE` em uma external location que cubra o caminho, mais `USE CATALOG`, `USE SCHEMA` e `CREATE TABLE` nos pais. Managed tables precisam de `USE CATALOG`, `USE SCHEMA` e `CREATE TABLE`.\n\n## Modificar\n\n```sql\nALTER TABLE main.silver.customers ADD COLUMN signup_date DATE;\nALTER TABLE main.silver.customers RENAME COLUMN email TO email_address;    -- pode exigir column mapping\nALTER TABLE main.silver.customers SET TBLPROPERTIES ('contains_pii' = 'true');\nALTER TABLE main.silver.customers OWNER TO `data-platform-admins`;\nCOMMENT ON TABLE main.silver.customers IS 'Cadastro de clientes deduplicado';\n\n-- External tables: se os metadados mudaram fora do Unity Catalog, ressincronize\nMSCK REPAIR TABLE main.bronze.vendor_feed SYNC METADATA;\n```\n\n## Apagar e recuperar\n\n```sql\nDROP TABLE main.silver.customers;            -- managed: recuperável durante o período de recuperação\nUNDROP TABLE main.silver.customers;          -- em até 7 dias por padrão\n\nDROP TABLE main.bronze.vendor_feed;          -- external: os arquivos continuam no LOCATION\n-- Para remover os dados também, apague os arquivos no cloud storage você mesmo\n```\n\nApagar exige ser dono ou ter `MANAGE` na tabela. O período de recuperação de managed tables pode ser definido por catálogo ou schema (Public Preview): 0 horas (sem recuperação) ou 7–30 dias.\n\n## Converter external → managed (`SET MANAGED`)\n\n```sql\nALTER TABLE main.bronze.vendor_feed SET MANAGED;\n\n-- Se a external table tiver leituras Iceberg (UniForm) habilitadas:\nALTER TABLE main.bronze.vendor_feed SET MANAGED TRUNCATE UNIFORM HISTORY;\n```\n\n| Aspecto | O que a documentação diz |\n| :--- | :--- |\n| **Requisitos** | Databricks Runtime **17.3 LTS+ ou serverless**. A tabela precisa ser Delta e você precisa ser o **dono**. Leitores e escritores devem estar no DBR 15.4 LTS+ |\n| **O que é mantido** | Nome, configurações, permissões, views e histórico da tabela |\n| **Como funciona** | Etapa 1 copia os dados e o transaction log para o managed storage, sem downtime. Etapa 2 traz os commits feitos durante a cópia e atualiza os metadados. Escritores ficam bloqueados por pouco tempo (~1–5 minutos, conforme o tamanho) |\n| **Streams** | Streams de leitura e escrita existentes **falham** após a conversão. Reinicie-os com a mesma configuração |\n| **Time travel** | No DBR 15.3 ou anterior, após a conversão só dá para fazer time travel **por versão**, não por timestamp |\n| **Antes de começar** | Cancele jobs de `OPTIMIZE` em execução e não agende novos durante a conversão |\n\n## Desfazer managed → external (`UNSET MANAGED`)\n\n```sql\nALTER TABLE main.bronze.vendor_feed UNSET MANAGED;\n```\n\n- Disponível **em até 14 dias** após a conversão. A Databricks guarda os dados de origem por 14 dias para permitir o rollback\n- \"Atualiza os metadados da tabela para apontar de volta para a external location original\", e escritas feitas no local gerenciado após a conversão são preservadas\n- Commits feitos entre a conversão e o rollback suportam time travel **por versão, mas não por timestamp**\n- **Sete dias após o rollback**, a Databricks apaga automaticamente os dados no local gerenciado\n- Reinicie os streams depois do rollback também. Confirme verificando que o tipo da tabela é `EXTERNAL`\n\nFonte: [Convert external or foreign tables to managed tables](https://docs.databricks.com/aws/en/tables/convert-external-managed).\n\n> [!warning] Erro comum\n> `RESTORE TABLE ... VERSION AS OF` restaura **versões de dados**. Não muda o **tipo** da tabela. Para desfazer um `SET MANAGED`, use `UNSET MANAGED` dentro da janela de 14 dias. Não é preciso apagar e recriar a tabela.\n\n## Casos de uso\n\n- **Silver e Gold novas**: crie managed tables para ganhar predictive optimization e clustering automático\n- **Pastas existentes do data lake**: registre como external tables primeiro e depois `SET MANAGED` quando nada mais escrever direto no caminho\n- **Drop acidental**: `UNDROP TABLE` restaura uma managed table dentro do período de recuperação\n- **Dados que engines externas escrevem diretamente**: mantenha external, porque escritas diretas no caminho passam por fora da governança do UC\n\n## Problemas e erros comuns\n\n### Os dados continuam lá depois do DROP\n\n**Cenário:** depois de `DROP TABLE`, os arquivos ainda existem no S3.\n**Correção:** a tabela era external, então o `DROP` removeu só os metadados. Apague os arquivos você mesmo se precisarem ser removidos.\n\n### Os dados sumiram depois do DROP\n\n**Cenário:** uma managed table foi apagada por engano.\n**Correção:** rode `UNDROP TABLE` dentro do período de recuperação (7 dias por padrão). Depois disso, os arquivos são apagados.\n\n### Permissão negada em `CREATE TABLE ... LOCATION`\n\n**Cenário:** um engenheiro consegue criar managed tables, mas recebe erro de permissão com `LOCATION`.\n**Correção:** external tables exigem `CREATE EXTERNAL TABLE` em uma external location que cubra o caminho.\n\n### Streams falham logo após a conversão\n\n**Cenário:** depois de `SET MANAGED`, um job de streaming que lê a tabela dá erro.\n**Correção:** é o comportamento esperado. Reinicie os streams com a mesma configuração.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - **Managed** = o UC é dono dos dados. O `DROP` os apaga depois da janela do `UNDROP`. **External** = `DROP` remove só os metadados\n> - Managed tables são o tipo **padrão e recomendado**, e o único em que o predictive optimization roda\n> - External → managed: `ALTER TABLE ... SET MANAGED`. Desfazer: `ALTER TABLE ... UNSET MANAGED` **em até 14 dias**\n> - `RESTORE` restaura versões de dados. Não reverte uma conversão de tipo\n> - External tables precisam de `CREATE EXTERNAL TABLE` em uma **external location**\n\n## Pontos-chave\n\n- Os dois tipos diferem em quem é dono do storage, do layout e do ciclo de vida dos dados\n- `UNDROP` recupera managed tables apagadas dentro do período de recuperação\n- `SET MANAGED` / `UNSET MANAGED` convertem nos dois sentidos, com janelas e efeitos colaterais documentados\n- Prefira managed tables. Mantenha external tables para dados que precisam ficar em um caminho onde outras engines escrevem\n\n## Tópicos relacionados\n\n- [Unity Catalog Básico](01-unity-catalog-basics.md)\n- [Controle de acesso e permissões](03-access-control-permissions.md)\n- [Liquid Clustering e Predictive Optimization](../06-troubleshooting-monitoring-and-optimization/04-liquid-clustering-and-predictive-optimization.md)\n- [Fundamentos do Delta Lake](../01-databricks-intelligence-platform/04-delta-lake-fundamentals.md)\n\n## Documentação oficial\n\n- [Unity Catalog managed tables](https://docs.databricks.com/aws/en/tables/managed)\n- [Work with external tables](https://docs.databricks.com/aws/en/tables/external)\n- [Convert external or foreign tables to managed tables](https://docs.databricks.com/aws/en/tables/convert-external-managed)\n\n---\n\n**[← Anterior: Unity Catalog Básico](01-unity-catalog-basics.md) | [↑ Voltar para Governance and Security](README.md) | [Próximo: Controle de acesso e permissões →](03-access-control-permissions.md)**\n"},{"id":"07-governance-and-security/03-access-control-permissions","folder":"07-governance-and-security","group":"modulo","order":3,"isIndex":false,"title":"Controle de Acesso e Permissões","md":"# Controle de Acesso e Permissões\n\n## Visão geral\n\nControle de acesso e permissões no Unity Catalog dão controle granular sobre quem acessa quais dados. O modelo de privilégios é hierárquico e permite delegar a gestão de acesso pela organização.\n\n> [!abstract] Resumo\n>\n> - Principals: usuários, grupos e service principals. Conceda a **grupos** sempre que possível\n> - Para chegar a um objeto você precisa de `USE CATALOG` + `USE SCHEMA`, mais o privilégio do objeto (`SELECT`, `MODIFY`, ...). Grants em um pai são herdados pelos filhos atuais e futuros\n> - `GRANT` adiciona e `REVOKE` remove. O comando clássico `DENY` é **só do Hive metastore legado**. O mecanismo de negação do Unity Catalog é a política ABAC DENY (Beta)\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: configurar controles de acesso pela UI e por SQL aplicando GRANT, REVOKE e DENY a principals no nível certo da hierarquia\n> - Os privilégios mínimos para um cenário (ex.: ler uma tabela sem acesso ao resto do schema)\n> - Quem pode conceder: o dono, um usuário com `MANAGE`, o dono do pai ou um metastore admin\n\n---\n\n## Principals: usuários, grupos e service principals\n\n```mermaid\nflowchart TB\n    subgraph Principals[\"Tipos de principal\"]\n        User[\"Usuários<br/>user@company.com\"]\n        Group[\"Grupos<br/>finance_team\"]\n        SP[\"Service principals<br/>CI/CD, automação (por applicationId)\"]\n    end\n    Principals --> Privileges[\"Privilégios (GRANT / REVOKE)\"]\n    Privileges --> Objects[\"Metastore → Catalog → Schema →<br/>Table / View / Volume / Function / Model\"]\n```\n\n| Principal | Identificado por | Use para |\n| :--- | :--- | :--- |\n| **Usuário** | Email | Pessoas. Evite conceder a indivíduos em produção |\n| **Grupo** | Nome do grupo | **Escolha padrão**: o acesso acompanha automaticamente as mudanças de membros |\n| **Service principal** | Application ID | Jobs, CI/CD e deploys de bundles (`run_as`) |\n\nNomes de principals com caracteres especiais (como `@` ou `-`) precisam estar entre **crases** (backticks).\n\n## Hierarquia de securables e herança\n\n```text\nMetastore\n└── Catalog                       USE CATALOG, CREATE SCHEMA, BROWSE, ...\n    └── Schema                    USE SCHEMA, CREATE TABLE, CREATE VOLUME, CREATE FUNCTION, ...\n        ├── Table / View / MV     SELECT, MODIFY, REFRESH (MV)\n        ├── Volume                READ VOLUME, WRITE VOLUME\n        ├── Function              EXECUTE\n        └── Model                 EXECUTE\nExternal locations / storage credentials: CREATE EXTERNAL TABLE, READ FILES, WRITE FILES, ...\n```\n\n- **Herança**: um privilégio concedido em um catálogo ou schema vale para os objetos dentro dele, **incluindo objetos futuros**. `GRANT SELECT ON SCHEMA main.gold` cobre toda tabela e view atual e futura de `main.gold`\n- **Privilégios de uso**: `USE CATALOG` e `USE SCHEMA` são \"necessários para interagir com qualquer objeto dentro\" do catálogo ou schema, mas **não dão acesso aos dados por si sós**\n\nFonte: [Unity Catalog privileges reference](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges).\n\n## Privilégios principais\n\n| Privilégio | Permite |\n| :--- | :--- |\n| `USE CATALOG` / `USE SCHEMA` | Chegar aos objetos dentro do catálogo/schema (sem acesso a dados sozinho) |\n| `BROWSE` | Descobrir objetos e ver metadados **sem** privilégios de uso (recomendado em catálogos) |\n| `SELECT` | \"Consultar dados de uma tabela, view, materialized view ou share\" |\n| `MODIFY` | \"Inserir, atualizar e apagar dados de uma tabela\" |\n| `CREATE SCHEMA` | Criar um schema em um catálogo |\n| `CREATE TABLE` | \"Criar tabelas ou views em um schema\" |\n| `CREATE MATERIALIZED VIEW` / `CREATE VOLUME` / `CREATE FUNCTION` | Criar esses objetos em um schema |\n| `REFRESH` | Atualizar manualmente uma materialized view |\n| `READ VOLUME` / `WRITE VOLUME` | Ler ou alterar arquivos em um volume |\n| `EXECUTE` | Executar uma function ou carregar um modelo registrado |\n| `CREATE EXTERNAL TABLE` | Criar external tables em uma external location |\n| `READ FILES` / `WRITE FILES` | Acesso direto por caminho via external location (prefira volumes) |\n| `MANAGE` | \"Gerenciar privilégios, transferir propriedade, renomear e apagar um objeto\" |\n| `ALL PRIVILEGES` | Todos os privilégios aplicáveis, **exceto** `EXTERNAL USE SCHEMA`, `EXTERNAL USE LOCATION`, `MANAGE` e `READ METADATA` |\n\n> [!note] Nomes legados\n> `USAGE`, `READ_METADATA` e `CREATE_TABLE` (com underscore) pertencem ao modelo legado de table ACLs do Hive metastore. No Unity Catalog use `USE CATALOG`, `USE SCHEMA`, `BROWSE` e `CREATE TABLE`.\n\n## GRANT e REVOKE\n\n```sql\n-- Privilégios mínimos para ler UMA tabela (não o schema inteiro)\nGRANT USE CATALOG ON CATALOG prod TO `analysts`;\nGRANT USE SCHEMA  ON SCHEMA  prod.analytics TO `analysts`;\nGRANT SELECT      ON TABLE   prod.analytics.revenue TO `analysts`;\n\n-- Ler tudo em um schema, agora e no futuro\nGRANT USE SCHEMA, SELECT ON SCHEMA prod.analytics TO `analysts`;\n\n-- Engenheiros podem criar e escrever tabelas no schema silver\nGRANT USE SCHEMA, CREATE TABLE, MODIFY, SELECT ON SCHEMA prod.silver TO `data_engineers`;\n\n-- Service principal usado pelo job de produção\nGRANT USE CATALOG ON CATALOG prod TO `6d5c1f2e-orders-sp-application-id`;\nGRANT USE SCHEMA, SELECT, MODIFY ON SCHEMA prod.silver TO `6d5c1f2e-orders-sp-application-id`;\n\n-- Descobrir sem ler dados\nGRANT BROWSE ON CATALOG prod TO `all_employees`;\n\n-- Remover privilégios\nREVOKE MODIFY ON SCHEMA prod.silver FROM `data_engineers`;\nREVOKE SELECT ON TABLE prod.analytics.revenue FROM `user@company.com`;\n\n-- Inspecionar\nSHOW GRANTS ON TABLE prod.analytics.revenue;\nSHOW GRANTS `analysts` ON SCHEMA prod.analytics;\n```\n\n- Sintaxe: `GRANT <privilégio> ON <tipo> <nome> TO <principal>` e `REVOKE <privilégio> ON <tipo> <nome> FROM <principal>`\n- \"Um `REVOKE` tem sucesso mesmo que os privilégios nunca tenham sido concedidos\"\n- **REVOKE remove um grant feito naquele nível**. Se o principal também recebe o privilégio por um objeto pai ou por um grupo, o acesso continua até esses grants serem revogados também\n\n### Pela UI\n\nNo **Catalog Explorer**, abra o catálogo, schema ou tabela → aba **Permissions** → **Grant** (ou selecione um grant → **Revoke**). Escolha o principal e os privilégios. A propriedade é alterada na aba **Overview** do objeto (ícone de edição ao lado de **Owner**).\n\n### Quem pode conceder\n\n- O **dono** do objeto (que tem todos os privilégios nele)\n- O dono do **catálogo ou schema pai**\n- Um usuário com **`MANAGE`** no objeto\n- Um **metastore admin**. Account admins também podem conceder diretamente no metastore\n\nA transferência de propriedade é feita com `ALTER <securable> <nome> OWNER TO <principal>`, por exemplo `ALTER TABLE prod.analytics.revenue OWNER TO accounting`. Pode ser feita pelo dono atual, por um metastore admin, pelo dono do contêiner pai ou por um usuário com `MANAGE`.\n\n## DENY: comando legado vs políticas ABAC DENY\n\nO exam guide lista **DENY** junto com GRANT e REVOKE. A documentação atual separa isso em duas coisas diferentes:\n\n| | Comando clássico `DENY` | **Política DENY** do ABAC (Beta) |\n| :--- | :--- | :--- |\n| Aplica-se a | **Apenas** o catálogo legado `hive_metastore` (\"Esta função não é suportada pelo Unity Catalog\") | Unity Catalog, anexada no metastore (Beta), catálogo ou schema |\n| Sintaxe | `DENY SELECT ON TABLE hive_metastore.default.t TO user` | `CREATE POLICY ... DENY MANAGE ACCESS CONTROL FOR <tipo> [WHEN ...]` |\n| O que bloqueia | Qualquer privilégio. \"Negar um privilégio tem precedência sobre qualquer grant explícito ou implícito\" | Hoje, só **`MANAGE ACCESS CONTROL`**: a capacidade de conceder ou revogar, mudar propriedade e gerenciar políticas |\n| Desfazer | `REVOKE` do mesmo privilégio do mesmo principal | `DROP POLICY` |\n| Visibilidade | `SHOW GRANTS` | `SHOW EFFECTIVE POLICIES` (não `SHOW GRANTS`) |\n\nFontes: [DENY](https://docs.databricks.com/aws/en/sql/language-manual/security-deny), [ABAC DENY policies](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/deny-policies).\n\nComo responder questões sobre DENY:\n\n- Para impedir alguém de **ler dados** no Unity Catalog, **não conceda** o privilégio, ou faça **REVOKE** (inclusive dos grupos de que ele faz parte). Restrinja *linhas ou colunas* com **row filters, column masks ou ABAC** (veja [Row Filters, Column Masks e ABAC](04-row-filters-column-masks-abac.md))\n- Um `DENY` que sobrepõe grants vale para o **Hive metastore legado**. No Unity Catalog, o conceito de negação é a política ABAC DENY, que hoje governa só `MANAGE ACCESS CONTROL`\n\n## Boas práticas de controle de acesso\n\n- **Menor privilégio**: conceda só o que a função precisa, no nível mais restrito que fizer sentido\n- **Conceda a grupos**, nunca a indivíduos em produção\n- **Organize por schema** (`bronze`, `silver`, `gold`, `finance`) para que um grant no schema cubra uma camada inteira\n- **Separe ambientes** com catálogos (`dev`, `test`, `prod`) e dê escrita em produção só a service principals\n- **Rode jobs como service principals** (`run_as`), não com identidades pessoais\n- Dê descoberta ampla com `BROWSE`, não com `SELECT`\n\n## Auditando o acesso\n\n```sql\n-- Mudanças de permissão e leituras de tabelas recentes\nSELECT event_time, user_identity.email, action_name, request_params\nFROM system.access.audit\nWHERE service_name = 'unityCatalog'\n  AND action_name IN ('updatePermissions', 'getTable')\nORDER BY event_time DESC\nLIMIT 100;\n```\n\n## Cenários de permissão\n\n| Cenário | Grants |\n| :--- | :--- |\n| Analistas leem todo objeto da Gold | `USE CATALOG` em `prod`. `USE SCHEMA`, `SELECT` em `prod.gold` |\n| Analista lê só uma tabela | `USE CATALOG`, `USE SCHEMA` e `SELECT` naquela **tabela** |\n| Engenheiros constroem a Silver | `USE CATALOG`. `USE SCHEMA`, `CREATE TABLE`, `MODIFY`, `SELECT` em `prod.silver` |\n| SP de ingestão grava arquivos brutos | `READ VOLUME`, `WRITE VOLUME` no volume de landing |\n| Todos podem encontrar datasets | `BROWSE` no catálogo |\n| Um time deve perder acesso | `REVOKE` do grupo (e verifique outros grupos e grants em níveis superiores) |\n\n## Casos de uso\n\n- **Gestão de acesso por grupo**: grants para `finance_team` acompanham automaticamente as mudanças de membros\n- **Identidade de produção**: jobs rodam como service principal que tem `MODIFY` só nos schemas em que escreve\n- **Descoberta self-service**: `BROWSE` nos catálogos permite encontrar dados e pedir acesso sem lê-los\n\n## Problemas e erros comuns\n\n### GRANT funciona, mas o usuário ainda não acessa\n\n**Cenário:** um admin roda `GRANT SELECT ON TABLE ...` e o usuário continua recebendo erro de permissão.\n**Correção:** o usuário também precisa de `USE CATALOG` e `USE SCHEMA` nos pais. Grants em um filho não dão passagem pelos pais.\n\n### O acesso continua depois do REVOKE\n\n**Cenário:** depois de `REVOKE SELECT ... FROM user`, o usuário ainda consulta a tabela.\n**Correção:** ele tem o privilégio por um grupo ou por um grant no schema. Revogue no nível, e do principal, que realmente concedeu.\n\n### DENY falha no Unity Catalog\n\n**Cenário:** `DENY SELECT ON TABLE prod.gold.revenue TO contractors` falha.\n**Correção:** o comando clássico `DENY` só funciona no `hive_metastore`. No Unity Catalog, revogue ou não conceda o grant, use filtros, máscaras ou ABAC para acesso parcial, ou use uma política ABAC DENY (Beta) para remover `MANAGE ACCESS CONTROL`.\n\n### Usar nomes de privilégios legados\n\n**Cenário:** `GRANT USAGE ON SCHEMA prod.gold TO analysts` não dá aos analistas o que eles esperam no Unity Catalog.\n**Correção:** use os privilégios do Unity Catalog `USE CATALOG` / `USE SCHEMA` (e `BROWSE` para descoberta).\n\n## Dicas para a prova\n\n- Ler uma tabela = `USE CATALOG` + `USE SCHEMA` + `SELECT` na tabela\n- Grants em catálogo ou schema são herdados pelos objetos filhos **atuais e futuros**\n- Três tipos de principal: usuários, grupos, **service principals**. Conceda a grupos\n- `ALL PRIVILEGES` exclui `MANAGE` (e alguns privilégios de uso externo)\n- O comando clássico **DENY** é **só Hive metastore**. A negação do Unity Catalog é a política ABAC DENY (Beta), limitada a `MANAGE ACCESS CONTROL`\n- Donos, donos do pai, quem tem `MANAGE` e metastore admins podem conceder e transferir propriedade\n\n## Pontos-chave\n\n- **Principals**: usuários, grupos, service principals\n- **Hierarquia**: metastore → catalog → schema → objetos, com herança para baixo\n- **GRANT / REVOKE** em SQL ou na aba Permissions do Catalog Explorer\n- **DENY**: comando legado do Hive metastore vs política ABAC DENY do Unity Catalog\n- **Menor privilégio + grupos + service principals** é o padrão de produção\n\n## Tópicos relacionados\n\n- [Unity Catalog Básico](01-unity-catalog-basics.md)\n- [Managed e External Tables](02-managed-and-external-tables.md)\n- [Row Filters, Column Masks e ABAC](04-row-filters-column-masks-abac.md)\n\n## Documentação oficial\n\n- [Manage privileges in Unity Catalog](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/)\n- [Unity Catalog privileges reference](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)\n- [DENY (legacy Hive metastore)](https://docs.databricks.com/aws/en/sql/language-manual/security-deny)\n- [ABAC DENY policies (Beta)](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/deny-policies)\n\n---\n\n**[← Anterior: Managed e External Tables](02-managed-and-external-tables.md) | [↑ Voltar para Governance and Security](README.md) | [Próximo: Row Filters, Column Masks e ABAC →](04-row-filters-column-masks-abac.md)**\n"},{"id":"07-governance-and-security/04-row-filters-column-masks-abac","folder":"07-governance-and-security","group":"modulo","order":4,"isIndex":false,"title":"Row Filters, Column Masks e ABAC","md":"# Row Filters, Column Masks e ABAC\n\n## Visão geral\n\nPrivilégios decidem **se** um principal pode consultar uma tabela. O controle de acesso granular decide **quais linhas e quais valores de coluna** esse principal vê. O Unity Catalog oferece três ferramentas para isso. **Row filters** e **column masks** são SQL UDFs anexadas a uma tabela. **Dynamic views** são a abordagem clássica baseada em views. **Políticas de controle de acesso baseado em atributos (ABAC)** aplicam filtros e máscaras de forma centralizada, usando governed tags em um catálogo ou schema.\n\n> [!abstract] Resumo\n>\n> - **Row filter**: uma SQL UDF que retorna `BOOLEAN`, anexada com `ALTER TABLE ... SET ROW FILTER fn ON (cols)`. Linhas para as quais ela retorna `FALSE` ficam ocultas\n> - **Column mask**: uma SQL UDF que retorna o tipo da coluna, anexada com `ALTER TABLE ... ALTER COLUMN c SET MASK fn`. Cada coluna pode ter uma máscara\n> - Condicione ambos ao grupo com **`is_account_group_member('grupo')`**\n> - **ABAC**: `CREATE POLICY ... ROW FILTER | COLUMN MASK ... FOR TABLES WHEN has_tag_value(...)`, anexada no nível de catálogo, schema ou tabela. Donos de tabelas não podem sobrescrever políticas definidas por admins de nível superior\n\n> [!tip] O que a prova cobra\n>\n> - Habilidade do exam guide: entender mascaramento por coluna e segurança por linha para restringir a visibilidade conforme o grupo do usuário\n> - Habilidade do exam guide: entender políticas ABAC do Unity Catalog para controlar centralmente row filtering e column masking de dados sensíveis\n> - Escrever uma máscara com `is_account_group_member(...)` para que só um grupo veja o valor real\n> - Quando usar filtros/máscaras por tabela, dynamic views ou ABAC\n\n---\n\n## Column masks\n\n```sql\n-- 1. Função de máscara: finance vê o número completo do cartão, os demais veem só os 4 últimos dígitos\nCREATE OR REPLACE FUNCTION main.security.mask_card(card STRING)\nRETURNS STRING\nRETURN CASE\n  WHEN is_account_group_member('finance_team') THEN card\n  ELSE concat('****-****-****-', right(card, 4))\nEND;\n\n-- 2. Anexe à coluna\nALTER TABLE main.silver.payments\n  ALTER COLUMN credit_card_number SET MASK main.security.mask_card;\n\n-- 3. Remova\nALTER TABLE main.silver.payments ALTER COLUMN credit_card_number DROP MASK;\n```\n\n- A função recebe o valor da coluna e retorna o original ou um valor mascarado. O **tipo de retorno deve ser igual** ao da coluna, ou conversível para ele\n- **Uma máscara por coluna**. Máscaras podem referenciar outras colunas\n\n## Row filters\n\n```sql\n-- Usuários veem só as linhas da sua região; admins veem tudo\nCREATE OR REPLACE FUNCTION main.security.region_filter(region STRING)\nRETURNS BOOLEAN\nRETURN is_account_group_member('admins')\n    OR (is_account_group_member('emea_sales') AND region = 'EMEA')\n    OR (is_account_group_member('amer_sales') AND region = 'AMER');\n\nALTER TABLE main.silver.orders SET ROW FILTER main.security.region_filter ON (region);\n\nALTER TABLE main.silver.orders DROP ROW FILTER;\n```\n\nLinhas para as quais a função retorna `FALSE` são excluídas dos resultados ([Row filters and column masks](https://docs.databricks.com/aws/en/tables/row-and-column-filters)).\n\n### Requisitos e limitações (filtros e máscaras por tabela)\n\n| Tópico | Detalhe |\n| :--- | :--- |\n| **Runtime** | DBR abaixo de 12.2 LTS não suporta, e **não retorna dados** em vez de liberar o acesso |\n| **Access mode dedicated** | DBR 15.4 LTS+ com serverless habilitado no workspace (as consultas passam pelo fine-grained access control serverless). DBR 15.4–16.2 é só leitura; escritas exigem 16.3+ |\n| **Views** | Você **não pode** aplicar row filters ou column masks a uma view |\n| **Não suportado** | Time travel em tabelas com políticas por tabela. Deep ou shallow clones. OpenSharing dessas tabelas. Criar índice de AI Search a partir delas |\n| **Quem gerencia** | O dono da tabela ou um usuário com `MANAGE` |\n\n> [!note] Atualização da plataforma (out/2026)\n> A documentação agora usa **AI Search** para o que os exam guides chamam de **Vector Search**, e **OpenSharing** para Delta Sharing (renomeado em 10/06/2026).\n\n## Dynamic views\n\nAntes de existirem filtros e máscaras por tabela, o padrão era uma **dynamic view**: uma view sobre a tabela base que filtra ou mascara com base no usuário que consulta, concedida aos consumidores no lugar da tabela base.\n\n```sql\nCREATE OR REPLACE VIEW main.gold.v_payments AS\nSELECT payment_id,\n       CASE WHEN is_account_group_member('finance_team') THEN credit_card_number\n            ELSE '****' END AS credit_card_number,\n       amount, region\nFROM main.silver.payments\nWHERE is_account_group_member('admins') OR region = 'EMEA';\n\nGRANT SELECT ON main.gold.v_payments TO `analysts`;   -- analistas NÃO recebem SELECT na tabela base\n```\n\nDynamic views ainda servem quando você compartilha uma **fatia curada ou transformada** dos dados, ou quando os consumidores nunca devem tocar na tabela base.\n\n## Políticas ABAC\n\nO controle de acesso baseado em atributos avalia **atributos (governed tags)** nos objetos. Uma política pode proteger toda tabela e coluna com as tags alvo, atuais e futuras, em um catálogo ou schema ([Unity Catalog ABAC](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/)).\n\n```sql\n-- Marque os dados (governed tags precisam existir e ser aplicadas)\nALTER TABLE main.silver.customers ALTER COLUMN email SET TAGS ('pii' = 'email');\n\n-- UDF de máscara\nCREATE OR REPLACE FUNCTION main.security.mask_email(email STRING)\nRETURNS STRING\nRETURN concat('***@', split(email, '@')[1]);\n\n-- Uma política mascara toda coluna de email marcada no schema para os analistas\nCREATE POLICY mask_pii_email\nON SCHEMA main.silver\nCOMMENT 'Mascara emails para analistas'\nCOLUMN MASK main.security.mask_email\nTO `analysts`\nEXCEPT `privacy_admins`\nFOR TABLES\nMATCH COLUMNS has_tag_value('pii', 'email') AS email\nON COLUMN email;\n\n-- Política de row filter em tabelas marcadas com sensitivity = high\nCREATE POLICY us_rows_only\nON CATALOG main\nROW FILTER main.security.us_only\nTO `contractors`\nFOR TABLES\nWHEN has_tag_value('sensitivity', 'high')\nMATCH COLUMNS has_tag('region') AS region\nUSING COLUMNS (region);\n```\n\nGramática da política: `CREATE [OR REPLACE] POLICY nome ON { METASTORE | CATALOG c | SCHEMA s | TABLE t } { ROW FILTER fn | COLUMN MASK fn } TO principals [EXCEPT principals] FOR TABLES [WHEN condição] [MATCH COLUMNS condição AS alias] [ON COLUMN alias] [USING COLUMNS (...)]`.\n\n| Aspecto | Detalhe |\n| :--- | :--- |\n| **Anexar em** | Catálogo, schema ou tabela. Nível de metastore é Beta |\n| **Alvos** | Objetos cujas **governed tags** batem com `WHEN` / `MATCH COLUMNS` (`has_tag`, `has_tag_value`) |\n| **Requisitos** | DBR **16.4+ ou serverless**. `MANAGE` (ou propriedade) no objeto onde a política é anexada. `EXECUTE` na UDF |\n| **Sobrescrever** | Definidas por admins de nível superior, então **donos de tabelas não podem sobrescrever nem remover** |\n| **Outros tipos de política** | GRANT policies (Beta) e DENY policies (Beta, que negam `MANAGE ACCESS CONTROL`) |\n\n## Escolhendo uma abordagem\n\n| Necessidade | Use |\n| :--- | :--- |\n| Mascarar ou filtrar uma tabela específica | **Column mask** ou **row filter** por tabela |\n| Regras consistentes em muitas tabelas que têm o mesmo atributo sensível | **Política ABAC** no catálogo ou schema, aplicada por governed tags. A documentação recomenda para escala |\n| Compartilhar uma fatia curada e transformada, ocultando a tabela base | **Dynamic view** |\n| Esconder uma tabela inteira de um grupo | Não conceda `SELECT`. Filtro ou máscara não são necessários |\n\n## Casos de uso\n\n- **PCI**: só `finance_team` vê os números completos dos cartões. Os demais veem os quatro últimos dígitos\n- **Vendas regionais**: cada grupo de vendas vê só os pedidos da sua região por meio de um row filter\n- **Programa corporativo de PII**: o time de privacidade marca as colunas de PII uma vez, e uma política ABAC as mascara em todos os schemas\n- **Extração para parceiros**: uma dynamic view expõe um subconjunto agregado e mascarado\n\n## Problemas e erros comuns\n\n### Função de máscara rejeitada\n\n**Cenário:** `SET MASK` falha porque a função retorna `STRING` mas a coluna é `DECIMAL`.\n**Correção:** o tipo de retorno da máscara deve ser igual ao da coluna, ou conversível para ele.\n\n### Usuários num runtime antigo não veem linhas\n\n**Cenário:** um time no DBR 11.3 recebe resultados vazios de uma tabela com filtro.\n**Correção:** runtimes abaixo de 12.2 LTS não suportam row filters ou máscaras, e não retornam dados em vez de liberar o acesso. Atualize, ou use serverless ou um SQL warehouse.\n\n### Time travel falha numa tabela mascarada\n\n**Cenário:** `SELECT ... VERSION AS OF 3` falha depois que um row filter foi adicionado.\n**Correção:** time travel não é suportado com políticas por tabela. Planeje auditorias sobre os dados atuais, ou mantenha um histórico governado separado.\n\n### Dono da tabela não consegue remover uma máscara\n\n**Cenário:** o dono de uma tabela tenta remover uma regra de máscara em uma coluna de email e não consegue.\n**Correção:** a máscara vem de uma política ABAC anexada no schema ou catálogo, então só um admin com `MANAGE` ali pode alterá-la.\n\n## Dicas para a prova\n\n> [!tip] Dicas para a prova\n>\n> - \"Só o grupo X vê o valor completo\" → UDF de **column mask** com `is_account_group_member('X')`\n> - \"Usuários veem só suas linhas\" → UDF de **row filter** que retorna `BOOLEAN`, anexada com `SET ROW FILTER ... ON (cols)`\n> - `DENY` numa coluna não é a forma como o Unity Catalog mascara dados (e o `DENY` clássico é só Hive metastore)\n> - **ABAC** = `CREATE POLICY` + governed tags no nível de catálogo ou schema, aplicadas de forma consistente a muitas tabelas\n> - Filtros e máscaras não podem ser aplicados a views. Use uma dynamic view\n\n## Pontos-chave\n\n- Row filters e column masks são SQL UDFs anexadas a tabelas e avaliadas em toda consulta\n- `is_account_group_member()` liga a visibilidade a grupos no nível da conta\n- ABAC escala os mesmos controles em catálogos e schemas via governed tags\n- Dynamic views continuam úteis para fatias curadas e compartilháveis\n\n## Tópicos relacionados\n\n- [Controle de acesso e permissões](03-access-control-permissions.md)\n- [Managed e External Tables](02-managed-and-external-tables.md)\n- [Compartilhamento de dados](05-data-sharing.md)\n\n## Documentação oficial\n\n- [Row filters and column masks](https://docs.databricks.com/aws/en/tables/row-and-column-filters)\n- [Unity Catalog attribute-based access control (ABAC)](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/)\n- [Create and manage ABAC policies](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/policies)\n- [ABAC DENY policies (Beta)](https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/deny-policies)\n\n---\n\n**[← Anterior: Controle de acesso e permissões](03-access-control-permissions.md) | [↑ Voltar para Governance and Security](README.md) | [Próximo: Compartilhamento de dados →](05-data-sharing.md)**\n"},{"id":"07-governance-and-security/05-data-sharing","folder":"07-governance-and-security","group":"modulo","order":5,"isIndex":false,"title":"Compartilhamento de Dados","md":"# Compartilhamento de Dados (Delta Sharing / OpenSharing)\n\n## Visão geral\n\nO Delta Sharing é um protocolo aberto e seguro para compartilhar dados entre organizações **sem copiar os dados** e sem distribuir credenciais de storage. Ele permite que provedores compartilhem dados vivos e curados com consumidores dentro e fora da organização.\n\n> [!abstract] Resumo\n>\n> - Delta Sharing (agora chamado **OpenSharing**) compartilha tabelas vivas com outras organizações ou workspaces sem copiar dados\n> - Provedores criam **shares** e **recipients**. Compartilhamento Databricks-to-Databricks usa um *sharing identifier*; o compartilhamento aberto (open sharing) usa tokens/arquivo de credencial\n> - Recipients têm acesso **somente leitura**. Compartilhe views ou tabelas filtradas para limitar o que é exposto\n\n> [!tip] O que a prova cobra\n>\n> - **Não faz parte** do outline da prova de agosto de 2026. Mantenha como contexto para cenários de governança e para a prova Professional\n> - Diferenciar compartilhamento (sem cópia, entre organizações) de Lakehouse Federation (consultar bancos externos no lugar)\n\n> [!note] Atualização da plataforma (out/2026)\n> \"Após o lançamento do OpenSharing open source, o Delta Sharing agora é OpenSharing\" (10/06/2026). Este arquivo mantém o nome Delta Sharing usado em materiais antigos.\n\n---\n\n## Arquitetura\n\n```mermaid\nflowchart LR\n    subgraph Provider[\"Workspace do provedor\"]\n        ProdCatalog[\"Catálogo prod\"]\n        Share[\"Share\"]\n    end\n\n    subgraph Network[\"Canal seguro<br/>Protocolo de sharing (REST/HTTPS)\"]\n        API[\"Servidor de sharing\"]\n    end\n\n    subgraph Consumer[\"Workspace/cliente do consumidor\"]\n        SharedCatalog[\"Catálogo criado a partir do share\"]\n        Query[\"Consulta<br/>somente leitura\"]\n    end\n\n    ProdCatalog --> Share\n    Share --> API\n    API --> SharedCatalog\n    SharedCatalog --> Query\n```\n\n## Vantagens\n\n| Aspecto | Exportação tradicional | Delta Sharing |\n|--------|---|---|\n| **Cópia de dados** | Cópia completa (custo, latência) | Referência viva, sem cópia |\n| **Atualidade** | Snapshot desatualizado | Sempre atual |\n| **Controle de acesso** | Arquivo tudo-ou-nada | Por tabela, partição, view |\n| **Auditoria** | Limitada | Logs de acesso completos |\n| **Credenciais** | Compartilhar credenciais (risco) | Sem compartilhar credenciais de storage |\n| **Plataforma** | Formato do fornecedor | Protocolo aberto (Spark, pandas, Power BI, outros) |\n\n## Do lado do provedor\n\n```sql\n-- 1. Criar o share\nCREATE SHARE sales_data_2025 COMMENT 'Vendas 2025 para o parceiro de marketing';\n\n-- 2. Adicionar objetos (o provedor controla o que é compartilhado)\nALTER SHARE sales_data_2025 ADD TABLE prod.analytics.orders;\nALTER SHARE sales_data_2025 ADD TABLE prod.analytics.revenue;\n-- Também é possível compartilhar views, volumes, modelos e partições específicas\n\n-- 3. Criar o recipient\n--    Databricks-to-Databricks: usa o sharing identifier do metastore do consumidor\nCREATE RECIPIENT partner_dbx USING ID 'aws:us-west-2:<metastore-uuid>';\n--    Open sharing (consumidor fora da Databricks): gera link de ativação/credencial\nCREATE RECIPIENT partner_open COMMENT 'Parceiro externo sem Databricks';\n\n-- 4. Conceder o share ao recipient\nGRANT SELECT ON SHARE sales_data_2025 TO RECIPIENT partner_dbx;\n\nSHOW SHARES;\nSHOW ALL IN SHARE sales_data_2025;\nSHOW GRANTS ON SHARE sales_data_2025;\n```\n\n## Do lado do consumidor\n\n```sql\n-- Databricks-to-Databricks: criar um catálogo (somente leitura) a partir do share\nCREATE CATALOG shared_sales USING SHARE provider_name.sales_data_2025;\n\nSELECT * FROM shared_sales.analytics.orders;\n```\n\nConsumidores fora da Databricks usam o arquivo de credencial (open sharing) com conectores como o cliente Python `delta-sharing`, Spark, pandas ou Power BI.\n\n## Sharing vs Federation vs cópia\n\n| Necessidade | Use |\n| :--- | :--- |\n| Dar a outra organização acesso de leitura a dados vivos, sem copiar | **Delta Sharing / OpenSharing** |\n| Consultar um banco externo (PostgreSQL, Snowflake...) sem ingerir | **Lakehouse Federation** |\n| Ter uma cópia governada e histórica dos dados de outra fonte | **Ingestão** (Lakeflow Connect, Auto Loader, JDBC) |\n\n## Pontos de atenção\n\n- Recipients têm acesso **somente leitura**\n- Tabelas com **row filters / column masks por tabela** não podem ser compartilhadas via Delta Sharing — compartilhe uma view ou uma tabela derivada\n- Use **views** ou **partições** compartilhadas para expor apenas o subconjunto necessário\n- O provedor pode revogar o acesso a qualquer momento com `REVOKE SELECT ON SHARE ... FROM RECIPIENT ...`\n\n## Dicas para a prova\n\n- Delta Sharing = compartilhar **sem copiar**, somente leitura, entre organizações/plataformas\n- Objetos: **share** (o que é compartilhado) + **recipient** (quem recebe)\n- D2D usa sharing identifier; open sharing usa credencial/token\n- Não confunda com Lakehouse Federation, que consulta bancos externos\n\n## Tópicos relacionados\n\n- [Unity Catalog Básico](01-unity-catalog-basics.md)\n- [Controle de acesso e permissões](03-access-control-permissions.md)\n- [Row Filters, Column Masks e ABAC](04-row-filters-column-masks-abac.md)\n\n## Documentação oficial\n\n- [What is Delta Sharing / OpenSharing?](https://docs.databricks.com/aws/en/delta-sharing/)\n- [Create and manage shares](https://docs.databricks.com/aws/en/delta-sharing/create-share)\n- [Create and manage recipients](https://docs.databricks.com/aws/en/delta-sharing/create-recipient)\n\n---\n\n**[← Anterior: Row Filters, Column Masks e ABAC](04-row-filters-column-masks-abac.md) | [↑ Voltar para Governance and Security](README.md)**\n"},{"id":"07-governance-and-security/README","folder":"07-governance-and-security","group":"modulo","order":0,"isIndex":true,"title":"Governance and Security","md":"# Governance and Security (15 % da prova)\n\nO Domínio 7 cobre o Unity Catalog como camada de governança. Você diferencia **managed e external tables** e faz operações básicas com elas: criar, modificar, remover e converter nos dois sentidos. Configura acesso com **GRANT, REVOKE e DENY** para usuários, grupos e service principals no nível certo da hierarquia. Também restringe a visibilidade com **row filters e column masks**, e em escala com **políticas ABAC do Unity Catalog**.\n\n> [!important] DENY no Unity Catalog\n> O exam guide lista **DENY** junto com GRANT e REVOKE. Na documentação atual, o comando SQL clássico `DENY` vale só para o catálogo legado `hive_metastore` e \"não é suportado pelo Unity Catalog\". O mecanismo de negação do Unity Catalog é a **política ABAC DENY (Beta)**, que hoje só consegue negar `MANAGE ACCESS CONTROL`. Veja [03-access-control-permissions.md](03-access-control-permissions.md) para o quadro completo.\n\n## Visão geral dos tópicos\n\n```mermaid\nflowchart TD\n    G[Governança e Segurança] --> UC[Namespace do Unity Catalog]\n    G --> T[Managed vs external tables]\n    G --> P[Privilégios: GRANT / REVOKE / DENY]\n    G --> FG[Acesso granular]\n    FG --> RF[Row filters]\n    FG --> CM[Column masks]\n    FG --> ABAC[Políticas ABAC<br/>governed tags]\n    G --> S[Compartilhamento: OpenSharing]\n```\n\n## Conteúdo da seção\n\n| Arquivo | Tópico | Prioridade |\n| :--- | :--- | :--- |\n| [01-unity-catalog-basics.md](01-unity-catalog-basics.md) | Metastore, namespace de três níveis, catalogs, schemas, volumes, external locations | Alta |\n| [02-managed-and-external-tables.md](02-managed-and-external-tables.md) | Managed vs external, create/alter/drop/UNDROP, `SET MANAGED` / `UNSET MANAGED` | Alta |\n| [03-access-control-permissions.md](03-access-control-permissions.md) | Principals, privilégios, herança, GRANT / REVOKE, DENY, ownership | Alta |\n| [04-row-filters-column-masks-abac.md](04-row-filters-column-masks-abac.md) | Row filters, column masks, `is_account_group_member()`, dynamic views, políticas ABAC | Alta |\n| [05-data-sharing.md](05-data-sharing.md) | Delta Sharing (agora OpenSharing): shares, recipients | Baixa (fora do outline de agosto de 2026) |\n\n## Cobertura das habilidades oficiais (agosto de 2026)\n\n| Habilidade do exam guide (parafraseada) | Onde é coberta |\n| :--- | :--- |\n| Managed vs external tables; criar, modificar, apagar, converter entre elas | [02](02-managed-and-external-tables.md), [01](01-unity-catalog-basics.md) |\n| GRANT, REVOKE e DENY para usuários, grupos e service principals via UI e SQL | [03](03-access-control-permissions.md) |\n| Mascaramento por coluna e segurança por linha conforme o grupo do usuário | [04](04-row-filters-column-masks-abac.md) |\n| Políticas ABAC do Unity Catalog para row filtering e column masking centralizados | [04](04-row-filters-column-masks-abac.md) |\n\n## Conceitos-chave\n\n- **Namespace de três níveis**: `catalog.schema.object`\n- **Privilégios de uso**: `USE CATALOG` + `USE SCHEMA` são necessários para chegar a qualquer objeto, mas sozinhos não dão acesso aos dados\n- **Herança**: um grant em um catálogo ou schema cobre os objetos filhos atuais *e futuros*\n- **Managed tables**: o UC é dono do ciclo de vida e do layout. Após `DROP`, os dados podem ser recuperados com `UNDROP` por 7 dias (padrão)\n- **External tables**: `DROP` remove apenas os metadados; os arquivos continuam no seu storage\n- **Row filter / column mask**: uma SQL UDF anexada com `SET ROW FILTER` ou `SET MASK`, normalmente condicionada a `is_account_group_member()`\n- **ABAC**: `CREATE POLICY ... ROW FILTER | COLUMN MASK ... FOR TABLES` anexada no nível de catálogo, schema ou tabela, e aplicada por governed tags\n\n## Próximos passos\n\nVocê terminou as pastas de conteúdo. Teste-se com as [questões práticas](../../../../../certifications/data-engineer-associate/resources/practice-questions/README.md) e os simulados — de preferência no [site de estudos](../../../../../study-site/index.html).\n\n---\n\n**[← Anterior: Troubleshooting, Monitoring, and Optimization](../06-troubleshooting-monitoring-and-optimization/README.md) | [↑ Voltar à Certificação](../README.md)**\n"},{"id":"README","folder":"","group":"geral","order":0,"isIndex":false,"title":"Data Engineer Associate","md":"# Databricks Certified Data Engineer Associate\n\n> [!important] O que mudou no exam guide de agosto de 2026\n> (prova publicada em 04/05/2026; guia atualizado em 06/08/2026)\n>\n> - **7 domínios com peso oficial**, publicados pela primeira vez desde a reformulação de maio de 2026: Databricks Intelligence Platform 6 %, Data Ingestion and Loading 21 %, Data Transformation and Modeling 22 %, Working with Lakeflow Jobs 16 %, Implementing CI/CD 10 %, Troubleshooting, Monitoring, and Optimization 10 %, Governance and Security 15 %\n> - O guia agora diz explicitamente: **45 questões pontuadas + até 10 itens não pontuados** em 90 minutos. O tempo extra dos itens não pontuados já está incluído\n> - **Recertificação:** faça o *Data Engineer Associate Renewal Exam* ou a prova completa atual\n> - Em CI/CD, os nomes agora são **Declarative Automation Bundles (antigo Databricks Asset Bundles)** e **Databricks Git folders (antigo Databricks Repos)**\n> - A preparação oficial aponta para o **AI Prep Guide** e prática no **Databricks Free Edition**\n> - As questões de exemplo foram atualizadas. A questão de skew agora é uma agregação `groupBy`, em que o tratamento de skew join do AQE não ajuda e você faz salting na chave\n> - Aprovado/reprovado: **a Databricks não publica a nota mínima**\n>\n> As pastas de conteúdo abaixo correspondem **1 : 1 aos 7 domínios oficiais**. O PDF oficial é a fonte da verdade: [exam guide de agosto de 2026 (PDF)](https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Data-Engineer-Associate-Exam-Guide-August-2026.pdf).\n\n> [!note] Atualização da plataforma (out/2026)\n> Alguns nomes de produtos mudaram desde que o guia foi escrito. Este material usa os nomes da prova e indica os nomes atuais onde aparecem:\n>\n> - **Lakeflow Declarative Pipelines** (antigo DLT) foi renomeado para **Lakeflow Spark Declarative Pipelines** em 12/11/2025. A documentação também usa a forma curta \"Lakeflow pipelines\"\n> - **Databricks Asset Bundles** foi renomeado para **Declarative Automation Bundles** em 16/03/2026\n> - **Delta Sharing** agora é **OpenSharing** desde 10/06/2026\n> - O **Community Edition** foi aposentado no fim de 2025. Use o [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition) para praticar\n> - A página da certificação agora chama a plataforma de **Databricks Data + AI Platform**. O domínio 1 da prova continua se chamando \"Databricks Intelligence Platform\"\n\n## Visão geral da prova\n\n| Detalhe | Informação |\n| ------------------- | -------------------------------------------- |\n| **Certificação** | Databricks Certified Data Engineer Associate |\n| **Exam guide** | [Agosto 2026 (PDF)](https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Data-Engineer-Associate-Exam-Guide-August-2026.pdf) |\n| **Questões pontuadas** | 45 de múltipla escolha (+ até 10 não pontuadas) |\n| **Duração** | 90 minutos (inclui o tempo das não pontuadas) |\n| **Resultado** | Aprovado/reprovado (nota mínima não publicada) |\n| **Idiomas** | Inglês, japonês, português (BR), coreano |\n| **Código nos enunciados** | SQL quando possível, senão Python |\n| **Experiência** | 6+ meses de prática com Databricks (recomendado) |\n| **Pré-requisitos** | Nenhum obrigatório; treinamento relacionado é altamente recomendado |\n| **Recertificação** | A cada 2 anos: Renewal Exam ou prova completa atual |\n| **Custo** | US$ 200 (mais impostos) |\n| **Aplicação** | Online com fiscal ou centro de testes |\n| **Material de apoio** | Nenhum permitido |\n\n## Pesos dos domínios (oficial — agosto 2026)\n\n```mermaid\npie title Distribuição da prova (7 domínios)\n    \"Databricks Intelligence Platform\" : 6\n    \"Data Ingestion and Loading\" : 21\n    \"Data Transformation and Modeling\" : 22\n    \"Working with Lakeflow Jobs\" : 16\n    \"Implementing CI/CD\" : 10\n    \"Troubleshooting, Monitoring, and Optimization\" : 10\n    \"Governance and Security\" : 15\n```\n\n| Domínio | Peso | ≈ Questões (de 45) |\n| :--- | :---: | :---: |\n| Databricks Intelligence Platform | 6 % | ~3 |\n| Data Ingestion and Loading | 21 % | ~9 |\n| Data Transformation and Modeling | 22 % | ~10 |\n| Working with Lakeflow Jobs | 16 % | ~7 |\n| Implementing CI/CD | 10 % | ~5 |\n| Troubleshooting, Monitoring, and Optimization | 10 % | ~4 |\n| Governance and Security | 15 % | ~7 |\n\nAs quantidades são estimativas a partir dos pesos. A Databricks publica percentuais, não quantidades por domínio.\n\n## Tópicos de estudo\n\nLeia em ordem. O `README.md` de cada pasta mapeia seus arquivos às habilidades oficiais.\n\n| Seção | Peso | Tópicos |\n| :--- | :---: | :--- |\n| [01 — Databricks Intelligence Platform](01-databricks-intelligence-platform/README.md) | 6 % | Arquitetura, workspace, compute e custos, Delta Lake, time travel |\n| [02 — Data Ingestion and Loading](02-data-ingestion-and-loading/README.md) | 21 % | Padrões de ingestão, Lakeflow Connect (standard e managed), COPY INTO, Auto Loader, JDBC/REST, dados semiestruturados |\n| [03 — Data Transformation and Modeling](03-data-transformation-and-modeling/README.md) | 22 % | Spark SQL, DataFrames, joins, agregações, limpeza, qualidade, objetos Gold, tuning |\n| [04 — Working with Lakeflow Jobs](04-working-with-lakeflow-jobs/README.md) | 16 % | Tasks e DAGs, control flow (retries, If/else, For each), triggers (agendado, file arrival, table update) |\n| [05 — Implementing CI/CD](05-implementing-cicd/README.md) | 10 % | Git folders, Declarative Automation Bundles (variables, targets, deploy), Databricks CLI |\n| [06 — Troubleshooting, Monitoring, and Optimization](06-troubleshooting-monitoring-and-optimization/README.md) | 10 % | Histórico de execuções, status, Spark UI (skew, shuffle, spill), Liquid Clustering, predictive optimization, falhas de compute |\n| [07 — Governance and Security](07-governance-and-security/README.md) | 15 % | Unity Catalog, managed vs external, GRANT / REVOKE / DENY, row filters, column masks, ABAC |\n\n### Prática e recursos\n\n| Recurso | Descrição |\n| :--- | :--- |\n| [Site de estudos](../../../../study-site/index.html) | Aulas + exercícios com correção imediata, caderno de erros, pontos fracos e revisão espaçada |\n| [Questões práticas](../../../../certifications/data-engineer-associate/resources/practice-questions/README.md) | 145 questões agrupadas pelos 7 domínios (em inglês) |\n| [Simulado 1](../../../../certifications/data-engineer-associate/resources/mock-exam/README.md) | Prova completa (45 questões) |\n| [Simulado 2](../../../../certifications/data-engineer-associate/resources/mock-exam-2/README.md) | Prova alternativa (45 questões) |\n| [Dicas para a prova](recursos/dicas-prova.md) | Estratégias e formato da prova |\n| [Revisão final](recursos/revisao-final.md) | Revisão relâmpago para a manhã da prova |\n| [Links oficiais](recursos/links-oficiais.md) | Documentação e inscrição |\n\n## Acompanhamento de progresso\n\n### Fase 1: Plataforma e ingestão\n\n- [ ] 01 — Databricks Intelligence Platform (arquitetura, compute, Delta Lake)\n- [ ] 02 — Data Ingestion and Loading (Lakeflow Connect, COPY INTO, Auto Loader, JDBC/REST)\n\n### Fase 2: Transformação e orquestração\n\n- [ ] 03 — Data Transformation and Modeling (limpeza, joins, objetos Gold, qualidade, tuning)\n- [ ] 04 — Working with Lakeflow Jobs (tasks, control flow, triggers)\n\n### Fase 3: Pronto para produção\n\n- [ ] 05 — Implementing CI/CD (Git folders, Declarative Automation Bundles, Databricks CLI)\n- [ ] 06 — Troubleshooting, Monitoring, and Optimization (histórico, Spark UI, Liquid Clustering)\n- [ ] 07 — Governance and Security (managed vs external, privilégios, máscaras, ABAC)\n\n### Fase 4: Prática\n\n- [ ] Fazer exercícios práticos no [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition)\n- [ ] Completar as questões práticas (meta: 70 %+ por domínio)\n- [ ] Fazer o Simulado 1 (cronometrado)\n- [ ] Revisar os pontos fracos e zerar o caderno de erros\n- [ ] Fazer o Simulado 2\n\n## Recursos oficiais\n\n- [Página da certificação Databricks](https://www.databricks.com/learn/certification/data-engineer-associate)\n- [Exam guide de agosto 2026 (PDF)](https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Data-Engineer-Associate-Exam-Guide-August-2026.pdf)\n- [Documentação Databricks](https://docs.databricks.com/)\n- [Databricks Academy](https://www.databricks.com/learn/training)\n- [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition)\n\n---\n\n**[← Voltar ao início](../../../README.md)**\n"},{"id":"recursos/dicas-prova","folder":"recursos","group":"recursos","order":0,"isIndex":false,"title":"Dicas para a Prova — Data Engineer Associate","md":"# Dicas e Estratégias para a Prova Data Engineer Associate\n\nEstratégias práticas para passar na Databricks Certified Data Engineer Associate na primeira tentativa.\n\n## Formato da prova\n\n| Detalhe | Valor |\n|---|---|\n| Questões pontuadas | 45 de múltipla escolha, mais até 10 itens não pontuados |\n| Duração | 90 minutos (inclui o tempo dos itens não pontuados) |\n| Nota de aprovação | Não publicada. Resultado: aprovado/reprovado |\n| Código nas questões | SQL quando possível, senão Python |\n| Idiomas | Inglês, japonês, **português (BR)**, coreano |\n| Aplicação | Online com fiscal (proctored) ou em centro de testes |\n| Exam guide | [Agosto 2026 (PDF)](https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Data-Engineer-Associate-Exam-Guide-August-2026.pdf), atualizado em 06/08/2026 |\n\n> [!tip] Idioma\n> Mesmo que a prova exista em português, os termos técnicos (Auto Loader, streaming table, Unity Catalog...) aparecem em inglês. Por isso as questões de prática deste repositório estão em inglês — use o tradutor automático só quando travar no enunciado.\n\n## Pesos dos domínios e tempo de estudo\n\n| Domínio | Peso | ≈ Questões | Tempo de estudo sugerido |\n|---|---|---|---|\n| Data Transformation and Modeling | 22 % | ~10 | 8–10 horas |\n| Data Ingestion and Loading | 21 % | ~9 | 7–9 horas |\n| Working with Lakeflow Jobs | 16 % | ~7 | 5–6 horas |\n| Governance and Security | 15 % | ~7 | 5–6 horas |\n| Implementing CI/CD | 10 % | ~5 | 3–4 horas |\n| Troubleshooting, Monitoring, and Optimization | 10 % | ~4 | 3–4 horas |\n| Databricks Intelligence Platform | 6 % | ~3 | 2–3 horas |\n\nIngestão e transformação somam 43 % da prova. Lakeflow Jobs, CI/CD e governança (41 % juntos) são onde o blueprint de 2026 mais difere dos materiais antigos — não pule.\n\n## Gestão do tempo\n\n| Fase | Tempo | Meta |\n|---|---|---|\n| Primeira passada (responder tudo) | 60 min | ~80 s por questão |\n| Revisar as marcadas | 20 min | Voltar às respostas incertas |\n| Revisão final | 10 min | Conferir as puladas |\n\nMarque (flag) qualquer questão em que estiver em dúvida e siga. Não gaste mais de 2 minutos numa questão na primeira passada.\n\n## Tópicos para dominar\n\n### Obrigatório (alta frequência)\n\n- [ ] Idempotência do `COPY INTO` e `force`. Opções `cloudFiles` do Auto Loader: `schemaLocation`, `inferColumnTypes`, `schemaEvolutionMode` (`addNewColumns` / `rescue` / `failOnNewColumns` / `none`), `_rescued_data`\n- [ ] Lakeflow Connect: standard vs managed connectors, e de que é feito um managed connector (connection, gateway para bancos, pipeline, streaming tables)\n- [ ] Limpeza Bronze → Silver: `try_cast`, `coalesce`, `dropna`, `dropDuplicates` vs `ROW_NUMBER()`. Joins (inner, left, broadcast, cross), `union` vs `unionByName`, `explode` / `split`, `approx_count_distinct`\n- [ ] Objetos Gold: table vs view vs materialized view vs streaming table\n- [ ] Expectations: warn (padrão), `ON VIOLATION DROP ROW`, `ON VIOLATION FAIL UPDATE`\n- [ ] Lakeflow Jobs: tipos de task (notebook, SQL, dashboard, pipeline), Run if, retries e timeouts, If/else, For each, task values\n- [ ] Triggers: scheduled (cron Quartz), file arrival, table update, e escolher por tempo vs por dados\n- [ ] Privilégios do UC: `USE CATALOG` + `USE SCHEMA` + `SELECT`, herança, grupos, service principals\n- [ ] Row filters, column masks (`is_account_group_member`) e políticas ABAC\n- [ ] Managed vs external tables, `UNDROP`, `SET MANAGED` / `UNSET MANAGED` (rollback em 14 dias)\n\n### Importante (média frequência)\n\n- [ ] Git folders: criar e trocar branch, Commit & Push, Pull, PR no provedor Git\n- [ ] Declarative Automation Bundles: targets, `${var.x}`, `BUNDLE_VAR_`, precedência de variáveis, modo development vs production, `databricks bundle validate` / `deploy -t` / `run`\n- [ ] Spark UI: skew (max ≫ percentil 75), spill, shuffle. O AQE só trata skew em joins — faça salting em agregações\n- [ ] Parâmetros de tuning: `spark.sql.shuffle.partitions` (200 ou `auto`), `spark.default.parallelism` (RDDs), memória de executor/driver, `spark.sql.autoBroadcastJoinThreshold` (10 MB)\n- [ ] Liquid Clustering (`CLUSTER BY`, `AUTO`, `OPTIMIZE FULL`) e predictive optimization (só managed tables do UC)\n- [ ] Monitoramento de jobs: matrix view, status (Succeeded with failures, Upstream failed, Timed Out), repair runs\n- [ ] Compute: serverless vs classic, tipos de SQL warehouse, falhas de inicialização, precedência de bibliotecas, OOM no driver vs executor\n- [ ] Delta Lake: MERGE, time travel (`VERSION AS OF` / `TIMESTAMP AS OF`), `RESTORE`, `VACUUM` (retenção padrão de 7 dias)\n\n### Bom saber (baixa frequência)\n\n- [ ] Leituras JDBC paralelas (`partitionColumn`, limites, `numPartitions`) e secrets via `dbutils.secrets.get`\n- [ ] Sintaxe de caminho JSON `:` e o tipo `VARIANT`\n- [ ] System tables: `system.lakeflow.*`, `system.access.audit`, `system.billing.usage`\n- [ ] `DENY` clássico é só Hive metastore legado. Políticas ABAC DENY (Beta) negam `MANAGE ACCESS CONTROL`\n- [ ] `%run` vs `dbutils.notebook.run()` em notebooks. Widgets\n\n## Pegadinhas comuns\n\n| Pegadinha | O que a prova testa | Entendimento correto |\n|---|---|---|\n| Retenção do VACUUM | Qualquer valor funciona | O mínimo padrão é **168 horas (7 dias)**. Valores menores exigem desativar a verificação `spark.databricks.delta.retentionDurationCheck.enabled = false` |\n| Schema evolution | Sempre automática na escrita | Precisa ser habilitada explicitamente com `.option(\"mergeSchema\", \"true\")` ou `spark.databricks.delta.schema.autoMerge.enabled` |\n| `availableNow` vs `once` | São iguais? | `availableNow=True` processa todos os dados disponíveis em micro-batches e para. `once=True` (depreciado) processa num único batch. Prefira `availableNow` |\n| Auto Loader vs COPY INTO | Quando usar cada um? | Auto Loader (`cloudFiles`) para a maioria das ingestões: evolução de schema, rastreamento escalável. `COPY INTO` para equipes só SQL, cargas periódicas de conjuntos modestos. Para usuários SQL, a Databricks recomenda streaming tables (que usam Auto Loader) |\n| Checkpoint de streaming | Opcional? | **Obrigatório** para tolerância a falhas e exactly-once. Defina com `checkpointLocation` |\n| Escopo do Unity Catalog | No nível do workspace | **No nível da conta** — abrange vários workspaces |\n| OPTIMIZE vs VACUUM | Fazem a mesma coisa? | Não. `OPTIMIZE` compacta arquivos pequenos. `VACUUM` remove arquivos antigos não referenciados pelo log |\n| MATERIALIZED VIEW vs STREAMING TABLE | Intercambiáveis? | Não. Streaming tables processam linhas novas incrementalmente (append). Materialized views guardam o resultado de uma consulta e o atualizam, incrementalmente quando possível |\n| AQE e skew | O AQE resolve todo skew? | Não. Só divide partições com skew em **joins** sort-merge e shuffle-hash. Faça salting em `groupBy` com skew |\n| DENY no Unity Catalog | `DENY SELECT` bloqueia o usuário? | O `DENY` clássico é só Hive metastore. No UC, revogue ou não conceda, use filtros, máscaras ou ABAC. Políticas ABAC DENY (Beta) negam só `MANAGE ACCESS CONTROL` |\n| Segredos no bundle | Colocar a senha no `databricks.yml`? | Não. Use uma variável definida via `BUNDLE_VAR_<nome>` a partir dos secrets do CI |\n| Task Timed Out | Aumentar retries? | Não. Aumente o **timeout** da task. O warning de duração só alerta |\n\n## Números de referência rápida\n\n| Item | Valor |\n|---|---|\n| Nota de aprovação | Não publicada (aprovado/reprovado) |\n| Retenção padrão do VACUUM | 168 horas (7 dias) |\n| Tamanho alvo de arquivo Delta | ~1 GB (após OPTIMIZE) |\n| Shuffle partitions padrão | 200 |\n| Limite de broadcast join | 10 MB (`spark.sql.autoBroadcastJoinThreshold`). Limite do AQE em runtime: 30 MB |\n| Retenção do transaction log | 30 dias |\n| Comportamento do `availableNow` | Vários micro-batches |\n| Níveis do Unity Catalog | catalog.schema.table |\n| Janela do `UNDROP` | 7 dias (padrão) |\n| Janela do `UNSET MANAGED` | 14 dias |\n| Máximo de chaves no Liquid Clustering | 4 |\n| Histórico de execuções na UI de Jobs | 60 dias |\n\n## Padrões comuns de questão\n\n### Baseadas em cenário\n\n```text\n\"A data engineer needs to ingest JSON files as they arrive in\ncloud storage. The schema may change over time. Which approach\nshould they use?\"\n```\n\n**Estratégia**: identifique os requisitos (incremental, evolução de schema) e associe ao Auto Loader com inferência de schema.\n\n### Boas práticas\n\n```text\n\"What is the recommended approach for ensuring data quality\nin a Lakeflow Declarative Pipelines pipeline?\"\n```\n\n**Estratégia**: conheça as boas práticas oficiais — expectations (`CONSTRAINT ... EXPECT`), não lógica de validação customizada.\n\n### Troubleshooting\n\n```text\n\"A query against a Delta table is returning stale data even\nafter new data was written. What should the engineer check?\"\n```\n\n**Estratégia**: pense em cache (`REFRESH TABLE`), time travel (lendo versão antiga) ou problemas de checkpoint de streaming.\n\n### Configuração\n\n```text\n\"Which option enables Change Data Feed on an existing Delta table?\"\n```\n\n**Estratégia**: memorize os nomes das propriedades — `delta.enableChangeDataFeed = true` via `ALTER TABLE SET TBLPROPERTIES`.\n\n## Glossário de palavras-chave nos enunciados\n\n| Inglês no enunciado | O que significa / aponta para |\n| :--- | :--- |\n| *least operational overhead* / *most managed* | Solução gerenciada: managed connector, Auto Loader, serverless, Lakeflow Jobs |\n| *idempotent* / *re-run safely* | `COPY INTO`, Auto Loader com checkpoint, `MERGE` |\n| *incrementally* / *only new files* | Auto Loader, `COPY INTO`, streaming tables |\n| *unpredictable arrival* | File arrival trigger |\n| *upstream tables owned by another team* | Table update trigger |\n| *must not copy the data* | Lakehouse Federation ou OpenSharing |\n| *only members of group X can see* | Column mask / row filter com `is_account_group_member` |\n| *across many tables / centrally* | Políticas ABAC com governed tags |\n| *one task runs much longer* | Skew |\n| *spill to disk* | Partições grandes demais / pouca memória |\n\n## Véspera da prova\n\n- [ ] Revise a tabela de pesos e priorize Data Transformation and Modeling e Data Ingestion and Loading\n- [ ] Releia as operações do Delta Lake: MERGE, OPTIMIZE, VACUUM, sintaxe de time travel\n- [ ] Revise Auto Loader vs COPY INTO, tipos de conector do Lakeflow Connect e tipos de trigger (scheduled, file arrival, table update)\n- [ ] Releia a hierarquia do Unity Catalog, sintaxe de GRANT/REVOKE, row filters, column masks e ABAC\n- [ ] Releia variables, targets, modos de deploy e comandos `databricks bundle`\n- [ ] Revise triggers de streaming: `processingTime`, `availableNow`, exigência de checkpoint\n- [ ] Faça o **modo Revisão de erros** no site de estudos e zere o caderno de erros\n- [ ] Confirme que o software de fiscalização está instalado e teste sua internet\n- [ ] Durma 8 horas\n\n## Durante a prova\n\n- [ ] Leia a questão inteira antes das alternativas — identifique a restrição-chave\n- [ ] Elimine primeiro as alternativas claramente erradas\n- [ ] Em questões de SQL, cuidado com pegadinhas de sintaxe (ex.: `MERGE INTO` exige `USING`)\n- [ ] Marque as incertas e siga — não fique travado\n- [ ] Atenção a \"BEST\" ou \"recommended\" — a prova costuma ter duas alternativas plausíveis\n- [ ] Em questões de Delta Lake, veja se pergunta sobre leitura ou escrita\n- [ ] Em questões de streaming, note se é processamento contínuo ou disparado (triggered)\n- [ ] Lembre: o Unity Catalog é no nível da conta, não do workspace\n\n## Se não passar\n\n- Revise o relatório de desempenho por seção — identifique o domínio mais fraco\n- Concentre o estudo no domínio com menor pontuação (o painel \"Pontos fracos\" do site ajuda nisso)\n- Aguarde o período exigido para refazer (geralmente 14 dias)\n- Refaça os simulados e revise as respostas erradas\n- Faça de novo com confiança\n\n## Prioridade de recursos de estudo\n\n### Essencial\n\n1. Databricks Academy — trilha Data Engineer Associate\n2. Documentação oficial das suas áreas fracas\n3. Simulados (os dois deste guia)\n4. Prática no [Databricks Free Edition](https://docs.databricks.com/aws/en/getting-started/free-edition) (o Community Edition foi aposentado no fim de 2025)\n5. O **AI Prep Guide** citado no exam guide, que gera um checklist prático adequado ao Free Edition\n\n### Útil (se der tempo)\n\n1. Fóruns da Databricks Community\n2. Tutoriais no YouTube (busque \"Databricks DE Associate\")\n3. Posts de engenheiros certificados\n\n### Pule\n\n- Conteúdo desatualizado (anterior a 2023)\n- Internos profundos do Spark (Tungsten, detalhes do Catalyst)\n- Padrões avançados de streaming (joins stream-stream, sinks customizados)\n\n---\n\n[← Voltar aos Recursos](README.md)\n"},{"id":"recursos/links-oficiais","folder":"recursos","group":"recursos","order":0,"isIndex":false,"title":"Links Oficiais — Data Engineer Associate","md":"# Links oficiais e documentação\n\nLista curada da documentação oficial da Databricks relevante para a prova Data Engineer Associate (a documentação é em inglês).\n\n## Certificação\n\n| Recurso | URL |\n|---|---|\n| Página da certificação DE Associate | <https://www.databricks.com/learn/certification/data-engineer-associate> |\n| Exam guide (agosto 2026, PDF) | <https://www.databricks.com/sites/default/files/2026-10/Databricks-Certified-Data-Engineer-Associate-Exam-Guide-August-2026.pdf> |\n| Visão geral das certificações | <https://www.databricks.com/learn/certification> |\n| Databricks Academy | <https://www.databricks.com/learn/training> |\n| Databricks Free Edition (prática) | <https://docs.databricks.com/aws/en/getting-started/free-edition> |\n| Limitações do Free Edition | <https://docs.databricks.com/aws/en/getting-started/free-edition-limitations> |\n\n## Domínio 1 — Databricks Intelligence Platform\n\n| Recurso | URL |\n|---|---|\n| What is a data lakehouse? | <https://docs.databricks.com/aws/en/lakehouse/> |\n| What is Delta Lake? | <https://docs.databricks.com/aws/en/delta/> |\n| What is Unity Catalog? | <https://docs.databricks.com/aws/en/data-governance/unity-catalog/> |\n| Compute configuration reference | <https://docs.databricks.com/aws/en/compute/configure> |\n| Serverless compute | <https://docs.databricks.com/aws/en/compute/serverless/> |\n| SQL warehouse types | <https://docs.databricks.com/aws/en/compute/sql-warehouse/warehouse-types> |\n| Delta Lake time travel | <https://docs.databricks.com/aws/en/delta/history> |\n\n## Domínio 2 — Data Ingestion and Loading\n\n| Recurso | URL |\n|---|---|\n| What is Lakeflow Connect? | <https://docs.databricks.com/aws/en/ingestion/overview> |\n| Managed connector concepts | <https://docs.databricks.com/aws/en/ingestion/lakeflow-connect/> |\n| Ingest with SQL and Spark APIs (standard connectors) | <https://docs.databricks.com/aws/en/ingestion/> |\n| Get started with COPY INTO | <https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/copy-into/> |\n| COPY INTO reference | <https://docs.databricks.com/aws/en/sql/language-manual/delta-copy-into> |\n| What is Auto Loader? | <https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/> |\n| Auto Loader schema inference and evolution | <https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/schema> |\n| Auto Loader file detection modes | <https://docs.databricks.com/aws/en/ingestion/cloud-object-storage/auto-loader/file-detection-modes> |\n| Query databases using JDBC | <https://docs.databricks.com/aws/en/connect/external-systems/jdbc> |\n| Query variant data | <https://docs.databricks.com/aws/en/semi-structured/variant> |\n| Structured Streaming trigger intervals | <https://docs.databricks.com/aws/en/structured-streaming/triggers> |\n\n## Domínio 3 — Data Transformation and Modeling\n\n| Recurso | URL |\n|---|---|\n| SQL language reference | <https://docs.databricks.com/aws/en/sql/language-manual/> |\n| PySpark DataFrame API | <https://spark.apache.org/docs/latest/api/python/reference/pyspark.sql/dataframe.html> |\n| Standalone materialized views | <https://docs.databricks.com/aws/en/views/materialized> |\n| Standalone streaming tables | <https://docs.databricks.com/aws/en/tables/streaming> |\n| Pipeline expectations (qualidade de dados) | <https://docs.databricks.com/aws/en/ldp/expectations> |\n| Lakeflow pipelines Python reference | <https://docs.databricks.com/aws/en/ldp/developer/python-ref> |\n| Constraints on Databricks | <https://docs.databricks.com/aws/en/tables/constraints> |\n| Adaptive query execution | <https://docs.databricks.com/aws/en/optimizations/aqe> |\n| Set Spark configuration properties | <https://docs.databricks.com/aws/en/spark/conf> |\n\n## Domínio 4 — Working with Lakeflow Jobs\n\n| Recurso | URL |\n|---|---|\n| Lakeflow Jobs | <https://docs.databricks.com/aws/en/jobs/> |\n| Configure and edit tasks | <https://docs.databricks.com/aws/en/jobs/configure-task> |\n| Configure task dependencies (Run if) | <https://docs.databricks.com/aws/en/jobs/conditional-tasks> |\n| If/else task | <https://docs.databricks.com/aws/en/jobs/if-else> |\n| For each task | <https://docs.databricks.com/aws/en/jobs/for-each> |\n| Schedules and triggers | <https://docs.databricks.com/aws/en/jobs/triggers> |\n| File arrival triggers | <https://docs.databricks.com/aws/en/jobs/file-arrival-triggers> |\n| Table update triggers | <https://docs.databricks.com/aws/en/jobs/trigger-table-update> |\n\n## Domínio 5 — Implementing CI/CD\n\n| Recurso | URL |\n|---|---|\n| Databricks Git folders | <https://docs.databricks.com/aws/en/repos/> |\n| Git operations in Git folders | <https://docs.databricks.com/aws/en/repos/git-operations-with-repos> |\n| Declarative Automation Bundles | <https://docs.databricks.com/aws/en/dev-tools/bundles/> |\n| Bundle variables | <https://docs.databricks.com/aws/en/dev-tools/bundles/variables> |\n| Bundle deployment modes | <https://docs.databricks.com/aws/en/dev-tools/bundles/deployment-modes> |\n| `databricks bundle` commands | <https://docs.databricks.com/aws/en/dev-tools/cli/bundle-commands> |\n| Bundles release notes (renomeação, 16/03/2026) | <https://docs.databricks.com/aws/en/release-notes/dev-tools/bundles> |\n\n## Domínio 6 — Troubleshooting, Monitoring, and Optimization\n\n| Recurso | URL |\n|---|---|\n| Monitor Lakeflow Jobs | <https://docs.databricks.com/aws/en/jobs/monitor> |\n| Skew and spill (guia da Spark UI) | <https://docs.databricks.com/aws/en/optimizations/spark-ui-guide/long-spark-stage-page> |\n| Liquid clustering | <https://docs.databricks.com/aws/en/delta/clustering> |\n| Predictive optimization | <https://docs.databricks.com/aws/en/optimizations/predictive-optimization> |\n| Compute termination error codes | <https://docs.databricks.com/aws/en/compute/troubleshooting/cluster-error-codes> |\n| Install libraries | <https://docs.databricks.com/aws/en/libraries/> |\n| System tables | <https://docs.databricks.com/aws/en/admin/system-tables/> |\n\n## Domínio 7 — Governance and Security\n\n| Recurso | URL |\n|---|---|\n| Unity Catalog managed tables | <https://docs.databricks.com/aws/en/tables/managed> |\n| External tables | <https://docs.databricks.com/aws/en/tables/external> |\n| Convert external tables to managed | <https://docs.databricks.com/aws/en/tables/convert-external-managed> |\n| Manage privileges | <https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/> |\n| Privileges reference | <https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges> |\n| Row filters and column masks | <https://docs.databricks.com/aws/en/tables/row-and-column-filters> |\n| ABAC | <https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/> |\n| ABAC DENY policies (Beta) | <https://docs.databricks.com/aws/en/data-governance/unity-catalog/abac/deny-policies> |\n| DENY (Hive metastore legado) | <https://docs.databricks.com/aws/en/sql/language-manual/security-deny> |\n\n## Release notes citadas neste guia\n\n| Mudança | URL |\n|---|---|\n| Lakeflow Declarative Pipelines → Lakeflow Spark Declarative Pipelines (12/11/2025) | <https://docs.databricks.com/aws/en/release-notes/product/2025/november> |\n| Delta Sharing → OpenSharing (10/06/2026) | <https://docs.databricks.com/aws/en/release-notes/product/2026/june> |\n\n## Prática\n\n| Recurso | URL |\n|---|---|\n| Databricks Academy | <https://www.databricks.com/learn/training> |\n| Databricks Free Edition | <https://docs.databricks.com/aws/en/getting-started/free-edition> |\n| Fóruns da Databricks Community | <https://community.databricks.com/> |\n| Delta Lake no GitHub | <https://github.com/delta-io/delta> |\n\n---\n\n[← Voltar aos Recursos](README.md)\n"},{"id":"recursos/README","folder":"recursos","group":"recursos","order":0,"isIndex":false,"title":"Recursos para a prova — Data Engineer Associate","md":"# Recursos para a prova — Data Engineer Associate\n\n| Recurso | Descrição |\n| -------- | ----------- |\n| [Questões práticas](../../../../../certifications/data-engineer-associate/resources/practice-questions/README.md) | 145 questões por domínio (em inglês) |\n| [Simulado 1](../../../../../certifications/data-engineer-associate/resources/mock-exam/README.md) | Prova completa (45 questões / 90 min) |\n| [Simulado 2](../../../../../certifications/data-engineer-associate/resources/mock-exam-2/README.md) | Prova alternativa (45 questões / 90 min) |\n| [Dicas para a prova](dicas-prova.md) | Estratégias, gestão do tempo, pegadinhas, glossário de palavras-chave |\n| [Revisão final](revisao-final.md) | Leitura de 20 minutos para a manhã da prova |\n| [Links oficiais](links-oficiais.md) | Documentação e inscrição |\n| [Site de estudos](../../../../../study-site/index.html) | Estudo + exercícios com correção, caderno de erros e pontos fracos |\n\n---\n\n**[← Voltar à Certificação](../README.md)**\n"},{"id":"recursos/revisao-final","folder":"recursos","group":"recursos","order":0,"isIndex":false,"title":"Revisão Final — Data Engineer Associate","md":"# Revisão Final — DE Associate (leitura de 20 minutos na manhã da prova)\n\n> [!important] Importante\n> **Leia na manhã da prova.** É uma revisão relâmpago, não um guia de estudo. Se algum fato abaixo parecer desconhecido, é um domínio que você deixou passar — anote e revise a pasta do tópico assim que puder.\n\n## Fatos de 2 minutos que mais aparecem\n\n- **Lakeflow Jobs** é o nome atual do que se chamava Workflows. \"Workflows\" só aparece em materiais antigos\n- **Lakeflow Declarative Pipelines** (nome da prova) = o antigo \"Delta Live Tables / DLT\". Desde 12/11/2025 a documentação chama de **Lakeflow Spark Declarative Pipelines**\n- **Declarative Automation Bundles** = o antigo **Databricks Asset Bundles** (DABs). Mesma CLI `databricks bundle`. **Git folders** = o antigo Repos\n- **`COPY INTO` é idempotente**: reexecutar ignora arquivos já carregados. `'force' = 'true'` recarrega\n- **Auto Loader (`cloudFiles`)**: `addNewColumns` (padrão) *para* o stream e evolui no reinício. `rescue` nunca falha e manda o excesso para `_rescued_data`\n- **Managed connectors** (SaaS, bancos) → ingestion pipelines serverless gravando streaming tables. O **ingestion gateway** existe só para bancos\n- **Triggers**: scheduled (por tempo) vs **file arrival** e **table update** (por dados)\n- **Tratamento de skew do AQE = só joins**. Um `groupBy` com skew precisa de **salting**\n- **Liquid Clustering** (`CLUSTER BY`, até 4 chaves, não combina com particionamento nem Z-order). **Predictive optimization** = `OPTIMIZE` / `VACUUM` / `ANALYZE` automáticos em **managed tables do UC**\n- **Acesso no UC** = `USE CATALOG` + `USE SCHEMA` + privilégio no objeto. Grants são herdados por filhos atuais e futuros\n- **DENY**: o comando clássico é **só Hive metastore**. O UC usa REVOKE ou não conceder, filtros, máscaras e ABAC (a política ABAC DENY, em Beta, nega só `MANAGE ACCESS CONTROL`)\n- **External → managed**: `ALTER TABLE ... SET MANAGED`. Desfaça com `UNSET MANAGED` em até 14 dias\n\n## Revisão rápida por domínio (5 minutos)\n\n### 01 — Databricks Intelligence Platform (6 %)\n\n- Lakehouse = uma cópia governada (Delta Lake + Unity Catalog) para BI e IA. Time travel dá rollback e trilha de auditoria\n- Muitos usuários concorrentes de SQL ad hoc → **serverless SQL warehouse** (inicia em ~2–6 s, autoscaling, auto stop)\n- ETL agendado → serverless jobs ou jobs compute. Trabalho interativo → all-purpose ou notebook serverless\n\n### 02 — Data Ingestion and Loading (21 %)\n\n- Comece pela camada **mais gerenciada**: managed connector → Lakeflow pipelines → Structured Streaming / APIs Spark\n- Detecção de arquivos: directory listing (padrão) vs **file notification com file events** (recomendado)\n- JDBC: secrets via `dbutils.secrets.get`. Paralelize com `partitionColumn` / limites / `numPartitions`\n- REST → grave JSON num **volume UC** → Auto Loader → agende os dois num único Lakeflow Job\n\n### 03 — Data Transformation and Modeling (22 %)\n\n- `union` mantém duplicatas e casa por posição. `unionByName` casa por nome. O `UNION` do SQL deduplica\n- \"Linha mais recente por chave\" → `ROW_NUMBER()` / `QUALIFY`, não `dropDuplicates`\n- View (recalculada por consulta) vs **materialized view** (armazenada, atualizada) vs **streaming table** (append incremental) vs table\n- Expectations: warn (padrão) / `DROP ROW` / `FAIL UPDATE`\n- `spark.sql.shuffle.partitions` (200 ou `auto`) para shuffles de DataFrame. `spark.default.parallelism` para RDDs. Broadcast threshold 10 MB\n\n### 04 — Working with Lakeflow Jobs (16 %)\n\n- Tipos de task: notebook, SQL, dashboard, pipeline. **Depends on** monta o DAG\n- **If/else** (ramificação), **For each** (loop, concorrência padrão 1), **retries**, Run if **All done** para limpeza\n- Cron Quartz: `0 0 9 ? * MON-FRI` = dias úteis às 09:00\n\n### 05 — Implementing CI/CD (10 %)\n\n- Git folder: Create Branch → editar → **Commit & Push** → **PR no provedor Git**\n- Precedência de variáveis: `--var` > `BUNDLE_VAR_` > `variable-overrides.json` > `variables` do target > `default`\n- `mode: development` = nomes com prefixo e agendas pausadas. `mode: production` = validações de branch, `run_as` e caminhos\n- `databricks bundle validate` → `deploy -t prod` → `run`\n\n### 06 — Troubleshooting, Monitoring, and Optimization (10 %)\n\n- Tendências de duração → **matrix view** do job. Bloqueios → visão **Graph** (`Upstream failed` aponta para cima)\n- **Timed Out** → aumente o timeout da task. **Succeeded with failures** → as leaf tasks tiveram sucesso\n- Skew: max ≫ percentil 75. Spill: Spill (Disk) > 0 → `auto` / mais partições ou mais memória\n- Falha de inicialização → código de término no event log. Conflito de biblioteca → `%pip` no notebook, versões fixadas. OOM no driver → pare de trazer dados para o driver\n\n### 07 — Governance and Security (15 %)\n\n- Managed: `DROP` apaga após a janela do `UNDROP` (7 dias). External: `DROP` remove só os metadados\n- Column mask com `is_account_group_member('finance_team')`. Row filter = UDF `BOOLEAN` com `SET ROW FILTER ... ON (cols)`\n- **ABAC** = `CREATE POLICY ... FOR TABLES` com governed tags, no nível de catálogo ou schema\n\n## Lembretes de pegadinhas\n\n| Pegadinha | Resposta certa |\n| :--- | :--- |\n| A questão diz \"Workflows\" | Leia como Lakeflow Jobs |\n| A questão diz \"DLT\" ou \"Delta Live Tables\" | Leia como Lakeflow Declarative Pipelines |\n| \"O AQE está ligado, então o skew está resolvido\" num `groupBy` | Não. Faça salting na chave |\n| \"Diminua shuffle partitions para resolver skew\" | Não. Deixa as partições maiores |\n| \"Coloque a senha no `databricks.yml`\" | Não. Use `BUNDLE_VAR_<nome>` dos secrets do CI |\n| \"DENY bloqueia acesso no Unity Catalog\" | O `DENY` clássico é só Hive metastore. Revogue, filtre, mascare ou use ABAC |\n| Desfazer `SET MANAGED` | `UNSET MANAGED` em até 14 dias, não `RESTORE` |\n| Arquivos chegam em horários imprevisíveis | File arrival trigger, não agenda de polling |\n| Compute mais barato para job agendado | Jobs compute ou serverless jobs, não all-purpose |\n\n## Orçamento de tempo — 90 minutos\n\n- **45 questões ÷ 90 minutos = ~2 min/questão** — continue andando\n- **Marque e pule** o que não conseguir responder em 90 segundos — volte no fim\n- **Releia o cenário** antes de reler a pergunta — a maioria das pegadinhas está no cenário\n- **Prefira a opção mais simples** que atende a *todas* as restrições; a Databricks premia respostas \"mais gerenciadas\" (Auto Loader > polling customizado, Lakeflow Jobs > orquestração customizada, UC > local do workspace)\n- **Não mude de ideia** nas marcadas na segunda passada, a menos que encontre informação nova\n\n## Coma. Hidrate-se. Respire.\n\nVocê está preparado. O trabalho está feito. Confie nele. Vá e passe.\n\n---\n\n**[← Voltar aos Recursos](README.md)** | **[↑ Voltar à Certificação](../README.md)**\n"}]};
